LTE_RRC_Message_Struct* init_LTE_RRC_Message_List(int num_elements) {
    LTE_RRC_Message_Struct* list = (LTE_RRC_Message_Struct*)malloc(num_elements * sizeof(LTE_RRC_Message_Struct));

