#include <stdlib.h>
#include <stdio.h>
#include <time.h>

struct record {
    long offset;
    int timestamp;
    int value;
};

void* alloc_and_init_arrays(int size, int min_value, int max_value) {
    struct record** records = (struct record**)malloc(size * sizeof(struct record*));
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));

    if (!records || !offsets || !keys) {
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i] = (struct record*)malloc(sizeof(struct record));
        if (!records[i]) {
            // Handle memory allocation failure
            log_error("Memory allocation failed");
            while (i >= 0) {
                free(records[i]);
                i--;
            }
            free(keys);
            free(offsets);
            free(records);
            return NULL;
        }

        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
        keys[i] = rand() % (max_value - min_value + 1) + min_value;

        records[i]->offset = offsets[i];
        records[i]->timestamp = keys[i];
        records[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}

void free_arrays(void* arr, int size) {
    struct record** records = (struct record**)arr;

    for (int i = 0; i < size; i++) {
        free(records[i]);
    }

    free(records);
    free(((long*)records)[size - 1]);
}
