#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <getopt.h>

#define MAX_LINE_LENGTH 1024
#define BUFFER_SIZE 4096

int main(int argc, char *argv[]) {
    int c;
    int verbose = 0;
    int case_sensitive = 0;
    char *output_file = NULL;
    FILE *fp;

    while ((c = getopt(argc, argv, "cm:o:")) != -1) {
        switch (c) {
            case 'c':
                case_sensitive = 1;
                break;
            case 'm':
                verbose = 1;
                printf("This program counts the number of lines and words in a given file.\n");
                printf("It supports the following options:\n");
                printf("- --manpage: Print comprehensive usage instructions and exit.\n");
                printf("- -cs: Enable case-sensitive word counting; otherwise, treat words as case-insensitive.\n");
                printf("- -o <output_file>: Redirect output to a specified file instead of standard output.\n");
                return 0;
            case 'o':
                output_file = optarg;
                break;
        }
    }

    if (argc <= optind) {
        fprintf(stderr, "Error: No input file provided. Please specify the input file as an argument.\n");
        return 1;
    }

    char *input_file = argv[optind];

    fp = fopen(input_file, "r");
    if (!fp) {
        perror("Error opening input file:");
        return 1;
    }

    int line_count = 0;
    int word_count = 0;
    size_t max_line_length = MAX_LINE_LENGTH;

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    double total_lines = 0;
    int percent_processed = 0;

    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, fp)) > 0) {
        line_count += count_lines(buffer, bytes_read);
        word_count += count_words(buffer, bytes_read, case_sensitive);

        if (ferror(fp) != 0) {
            perror("Error reading file:");
            fclose(fp);
            return 1;
        }

        total_lines++;
        percent_processed = (int)((total_lines / (double)getFileSize(input_file)) * 100);
        if (percent_processed % 10 == 0)
            printf("Processed: %d%%\n", percent_processed);

        if (output_file) {
            fwrite(buffer, 1, bytes_read, fopen(output_file, "w"));
        }
    }

    fclose(fp);

    if (output_file) {
        fprintf(stdout, "Lines: %d\nWords: %d\n", line_count, word_count);
    } else {
        printf("Lines: %d\nWords: %d\n", line_count, word_count);
    }

    return 0;
}

size_t getFileSize(const char *filename) {
    struct stat sb;
    if (stat(filename, &sb) == -1) {
        perror("Error getting file size:");
        return SIZE_MAX;
    }
    return sb.st_size;
}

int count_lines(char *buffer, ssize_t bytes_read) {
    int line_count = 0;

    char *line_start = buffer;
    while ((line_start = strstr(line_start, "\n")) != NULL) {
        line_start += 1; // skip newline
        line_count++;
    }

    return line_count;
}

int count_words(char *buffer, ssize_t bytes_read, int case_sensitive) {
    int word_count = 0;

    char *word_start = buffer;
    while ((word_start = strstr(word_start, " ")) != NULL) {
        word_start += 1; // skip space
        word_count++;
    }

    return word_count;
}
