#include <stdio.h>
#include <stdlib.h>

int* readIntegers(int* count) {
    int* arr = NULL;
    *count = 0;

    for (;;) {
        int num;
        if (scanf("%d", &num) != 1) break;

        if (*count >= 1000) {
            printf("Maximum limit of 1000 integers reached.\n");
            return arr;
        }

        arr = realloc(arr, (*count + 1) * sizeof(int));
        if (!arr) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
        arr[*count++] = num;
    }

    return arr;
}

void printLargest(int* arr, int count) {
    if (count == 0) {
        printf("Array is empty.\n");
    } else {
        int max = arr[0];
        for (int i = 1; i < count; i++) {
            if (arr[i] > max) max = arr[i];
        }
        printf("The largest integer in the array is %d.\n", max);
    }
}

int main() {
    int* arr = NULL;
    int count = 0;

    arr = readIntegers(&count);

    printLargest(arr, count);

    for (int i = 0; i < count; i++) free((void*) &arr[i]);
    free(arr);

    return 0;
}
