import hashlib
from typing import Tuple

def calculate_md5_hash(file_path: str) -> Tuple[str, int]:
    md5 = hashlib.md5()
    with open(file_path, 'rb') as file:
        chunk = file.read(4096)
        while chunk:
            md5.update(chunk)
            chunk = file.read(4096)

    return md5.hexdigest(), len(open(file_path, 'rb').read())

def calculate_md5_hash_resumable(file_path: str, offset: int) -> Tuple[str, int]:
    md5 = hashlib.md5()
    with open(file_path, 'rb') as file:
        file.seek(offset)
        chunk = file.read(4096)
        while chunk:
            md5.update(chunk)
            chunk = file.read(4096)

    return md5.hexdigest(), len(open(file_path, 'rb').read())

def validate_file_integrity(file_path: str) -> bool:
    try:
        with open(file_path, 'rb') as file:
            file_size = len(file.read())
    except FileNotFoundError:
        return False

    return True
