    EVP_CIPHER_CTX *cipher_ctx = NULL;

    switch (mode) {
        case 0: // ECB
            cipher_ctx = EVP_CIPHER_CTX_new();
            EVP_CipherInit_ex(cipher_ctx, EVP_des_ecb(), NULL, NULL, NULL);
            break;
