        case 3: // CFB
            cipher_ctx = EVP_CIPHER_CTX_new();
            EVP_CipherInit_ex(cipher_ctx, EVP_des_cfb64(), NULL, NULL, NULL);
            break;
    }

    return cipher_ctx;
}

int verify_oauth_token(char *json_string) {
    json_object *token_obj = json_object_from_string(json_string);
    if (!token_obj) return 0;

    const char *access_token = json_object_get_string(json_object_object_get(token_obj, "access_token"));
    int expires_in = json_object_get_int(json_object_object_get(token_obj, "expires_in"));
    const char *token_type = json_object_get_string(json_object_object_get(token_obj, "token_type"));

    if (!access_token || !token_type) return 0;

    if (strcmp(token_type, "Bearer") != 0) return 0;

    if (expires_in < 1) return 0;

    // Optional refresh token check
    const char *refresh_token = json_object_get_string(json_object_object_get(token_obj, "refresh_token"));
    if (!refresh_token) {
        // Check any other required fields or conditions here...
    }

    // If all checks pass, return 1 to indicate a valid token
    return 1;
}

