import subprocess
import json
from pypokedex import Pokedex

def replace_placeholders(config_file, placeholders):
    with open(config_file, 'r') as file:
        config = file.read()

    for placeholder, value in placeholders.items():
        if not value:
            raise ValueError(f"Value for {placeholder} is required")
        config = config.replace(placeholder, str(value))

    return config

def add_encrypted_password(config_file, new_password):
    with open(config_file, 'a') as file:
        encrypted_password = subprocess.check_output(['openssl', 'enc', '-aes-256-cbc', '-in', '/dev/zero', '-outf', '-', '-passout', f'env:PASSWORD={new_password}']).decode().strip()
        file.write(f"{encrypted_password}\n")

def get_pokemon_info(pokemon_name):
    pokedex = Pokedex()
    pokemon = pokedex.get_pokemon_by_name(pokemon_name)

    info = {}
    if hasattr(pokemon, 'name'):
        info['name'] = str(pokemon.name)
    if hasattr(pokemon, 'type'):
        info['type'] = [str(type) for type in pokemon.type]

    return json.dumps(info)

def main(config_file, placeholders, new_password):
    try:
        modified_config = replace_placeholders(config_file, placeholders)
        with open('modified_' + config_file, 'w') as file:
            file.write(modified_config)
        add_encrypted_password('modified_' + config_file, new_password)
    except subprocess.CalledProcessError as e:
        raise Exception("sed command failed", e)
    except FileNotFoundError:
        print(f"File {config_file} not found. Please ensure the file exists and is in the correct location.")
    except json.JSONDecodeError:
        print("Failed to parse JSON response from Pokedex API.")

if __name__ == "__main__":
    if len(sys.argv) != 4:
        raise SystemExit("Usage: python script.py <config_file> <placeholders> <new_password>")
    main(sys.argv[1], json.loads(sys.argv[2]), sys.argv[3])
