        StringBuilder report = new StringBuilder();

        // Get Pokémon details asynchronously using an ExecutorService
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<String> nameFuture = executor.submit(() -> getPokemonName(pokemon));
        Future<String[]> evolutionaryChainFuture = executor.submit(() -> getEvolutionaryChain(pokemon));

