void* shared_resource_pool(int num_resources) {
    sem_t *sem = sem_open("/resource_sem", O_CREAT | O_RDWR, 0644, num_resources);
    if (sem == SEM_FAILED) {
        perror("sem_open");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    void* resource_pool();

    void my_thread_function(void* arg) {
        int id = *(int*)arg;
        pthread_mutex_lock(&lock);
        sem_wait(sem);
        // Use the resources
        sem_post(sem);
        pthread_mutex_unlock(&lock);
        free(arg);
    }

    int main() {
        pthread_t threads[10];
        for (int i = 0; i < 10; i++) {
            int* id = malloc(sizeof(int));
            *id = i;
            pthread_create(&threads[i], NULL, my_thread_function, id);
        }
        for (int i = 0; i < 10; i++) {
            pthread_join(threads[i], NULL);
        }

        sem_close(sem);
    }

    void free_resources() {
        sem_destroy(sem);
        pthread_mutex_destroy(&lock);
    }
