using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class DatabaseExecutor
{
    private readonly int _poolSize;
    private readonly object _syncLock = new object();

    public DatabaseExecutor(int poolSize)
    {
        _poolSize = poolSize;
    }

    public async Task<SummaryReport> ExecuteBatchAsync(List<string> sqlCommands, string connectionString, int timeout)
    {
        var report = new SummaryReport();
        using (var connectionPool = new SqlConnectionStringBuilder(connectionString).MultipleActiveResultSets = true)
        {
            connectionPool.Pooling = true;
            connectionPool.MinPoolSize = _poolSize;

            var tasks = new List<Task>();
            foreach (var command in sqlCommands)
            {
                var task = ExecuteAsync(command, connectionString, timeout);
                tasks.Add(task);
            }

            await Task.WhenAll(tasks);

            foreach (var task in tasks)
            {
                try
                {
                    var result = await task;
                    report.SuccessCount++;
                    report.TotalExecutionTime += result.ExecutionTime;
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error executing command: {ex.Message}");
                }
            }

            report.AverageExecutionTime = report.TotalExecutionTime / report.SuccessCount;
        }

        return report;
    }

    private async Task<CommandResult> ExecuteAsync(string command, string connectionString, int timeout)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();

            using (var commandText = new SqlCommand(command, connection))
            {
                try
                {
                    var stopwatch = Stopwatch.StartNew();
                    await commandText.ExecuteNonQueryAsync();
                    stopwatch.Stop();
                    return new CommandResult(true, stopwatch.ElapsedMilliseconds);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error executing command: {ex.Message}");
                    return new CommandResult(false, 0);
                }
            }
        }
    }
}

public class SummaryReport
{
    public int SuccessCount { get; set; } = 0;
    public int TotalExecutionTime { get; set; } = 0;
    public double AverageExecutionTime { get; set; }
}

public class CommandResult
{
    public bool IsSuccessful { get; set; }
    public long ExecutionTime { get; set; }

    public CommandResult(bool isSuccessful, long executionTime)
    {
        IsSuccessful = isSuccessful;
        ExecutionTime = executionTime;
    }
}']

