['```csharp
using System;
using System.IO;
using System.Xml.XInclude;
using System.Xml.XPath;

public class XPathResult
{
    public XElement Element { get; set; }
    public int Index { get; set; }
}

public static XPathResult FindFirstElement(string filePath, string nodeName, dynamic attributes = null)
{
    try
    {
        XPathDocument doc = new XPathDocument(filePath);
        XPathNavigator nav = doc.CreateNavigator();
        XPathExpression expression;

        if (attributes != null)
        {
            foreach (var attribute in attributes)
            {
                expression = nav.Compile($"//{nodeName}[@{attribute.Key}='{attribute.Value}'"];
            }
        }
        else
        {
            expression = nav.Compile($"//{nodeName}");
        }

        XPathNodeIterator iterator = expression.Evaluate();
        XPathResult result = null;

        int index = 0;
        while (iterator.MoveNext())
        {
            if (result == null)
            {
                result = new XPathResult { Element = (XElement)iterator.Current, Index = index };
            }
            index++;
        }

        return result;
    }
    catch (XPathException ex)
    {
        Console.WriteLine($"Error parsing XML: {ex.Message}");
        return null;
    }
    catch (XmlException ex)
    {
        Console.WriteLine($"Error processing XML: {ex.Message}");
        return null;
    }
}']

