import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class StringProcessor {
    public static List<String> processStrings(List<String> strings) {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        List<Future<String>> futures = new ArrayList<>();

        int discardedCount = 0;
        List<String> md5Hashes = new ArrayList<>();

        for (String str : strings) {
            if (str.length() > 1024) {
                ++discardedCount;
                continue;
            }

            Callable<String> task = () -> {
                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    return String.format("%032x", md.digest(str.getBytes()));
                } catch (NoSuchAlgorithmException e) {
                    throw new RuntimeException(e);
                }
            };

            Future<String> future = executor.submit(task);
            futures.add(future);
        }

        for (Future<String> future : futures) {
            try {
                md5Hashes.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                // Handle exceptions and provide meaningful error messages
                throw new RuntimeException("Error processing string", e);
            }
        }

        executor.shutdown();

        return new ArrayList<>(List.concat(md5Hashes, List.of(String.valueOf(discardedCount))));
    }
}
