import java.io.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArraySet;
import java.util.concurrent.atomic.AtomicLong;

public class StateLoader {

    private static final int CACHE_EXPIRATION_MILLIS = 30000; // 30 seconds
    private static final Object LOCK = new Object();
    private static ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();
    private static CopyOnWriteArraySet<String> invalidatedCacheKeys = new CopyOnWriteArraySet<>();
    private static AtomicLong lastAccessedTime = new AtomicLong();

    public static MoSTState loadState(String stateFile) {
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastAccessedTime.get() > CACHE_EXPIRATION_MILLIS) {
            invalidatedCacheKeys.addAll(cache.keySet());
        }
        lastAccessedTime.set(currentTime);

        MoSTState result = cache.putIfAbsent(stateFile, null);
        if (result == null) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(stateFile))) {
                result = (MoSTState) ois.readObject();
                cache.put(stateFile, result);
            } catch (IOException | ClassNotFoundException e) {
                // Handle exceptions
            }
        }

        if (result == null || invalidatedCacheKeys.contains(stateFile)) {
            result = loadFromDisk(stateFile);
        }

        return result;
    }

    private static MoSTState loadFromDisk(String stateFile) {
        MoSTState result = null;
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(stateFile))) {
            result = (MoSTState) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            // Handle exceptions
        }
        return result;
    }
}
