const fs = require('fs').promises;
const path = require('path');

async function readFileAsync(filePath, timeoutMs = 5000) {
  try {
    const fileHandle = await fs.open(filePath, 'r');
    const buffer = Buffer.alloc(0);
    let bytesRead = 0;

    setTimeout(() => {
      throw new Error(`Timeout: File reading took too long (${filePath})`);
    }, timeoutMs);

    while ((await fileHandle.read(buffer, bytesRead, buffer.length - bytesRead)) > 0) {
      bytesRead += await fileHandle.readSome();
    }

    const fileContent = buffer.toString('utf8');
    await fileHandle.close();

    return fileContent;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`File not found: ${filePath}`);
    } else if (err.name === 'TimeoutError') {
      console.error(`Timed out reading file: ${filePath}`);
    } else {
      console.error(`Error reading file: ${filePath}`, err);
    }
  }
}
