const bibleBooks = require('bible-books');
const regExpBookName = /^[A-Za-z]+$/; // regular expression to match book names
const regExpPunctuation = /[^\w\s]/g; // regular expression to remove punctuation and special characters

function analyzeText(text) {
  let result = {};

  // Remove punctuation and special characters
  text = text.replace(regExpPunctuation, '');

  // Split the text into individual words
  const words = text.toLowerCase().split(/\s+/);

  // Define a loop to search for matches in the text
  bibleBooks.forEach(book => {
    if (regExpBookName.test(book)) {
      let count = 0;
      for (let i = 0; i < words.length; i++) {
        if (words[i] === book) {
          count++;
          words.splice(i, 1);
          i--;
        }
      }
      result[book] = count;
    }
  });

  return result;
}

module.exports = analyzeText;
