function insertWidgets(widgets) {
  return Promise.all(widgets.map((widget) => {
    try {
      if (!widget.type || !widget.sourceURL) {
        throw new Error('Widget is missing required fields');
      }

      fetch(widget.sourceURL)
        .then((response) => response.text())
        .then((html) => {
          const $widget = $(`<${widget.type}>`);
          $widget.html(html);

          if (widget.config) {
            Object.keys(widget.config).forEach((key) => {
              $widget.attr(key, widget.config[key]);
            });
          }

          return $widget;
        })
        .then((widgetHTML) => {
          $('body').append(widgetHTML);
        })
        .catch((error) => {
          console.error(`Error inserting widget: ${error}`);
        });
    } catch (error) {
      console.error(`Error processing widget: ${error}`);
    }

    return Promise.resolve({ status: 'success' });
  }));
}"]

