function streamManager() {
  let dataArr = [];
  let pause = false;
  const db = new GraphDatabase();

  function collectData(stream) {
    if (pause) return;

    stream.on('data', (chunk) => {
      dataArr.push(chunk);
    });

    stream.on('end', () => {
      stream.pause();
    });
  }

  function addVerticesAndEdges(numVertices, numEdges) {
    for (let i = 0; i < numVertices; i++) {
      const vertexId = Math.floor(Math.random() * 1000).toString();
      const props = {};
      Object.keys(props) = Array.from({ length: 5 }, () => `prop_${Math.floor(Math.random() * 10)}`);
      db.addVertex(vertexId, props);
    }

    for (let i = 0; i < numEdges; i++) {
      const v1 = Math.floor(Math.random() * numVertices).toString();
      const v2 = Math.floor(Math.random() * numVertices).toString();
      db.addEdge(v1, v2);
    }
  }

  function pauseStream() {
    pause = true;
  }

  function resumeStream() {
    if (!pause) return;

    pause = false;
  }

  function getCollectedData() {
    return dataArr;
  }

  function getGraph() {
    return db.getGraph();
  }

  return {
    collectData,
    addVerticesAndEdges,
    pauseStream,
    resumeStream,
    getCollectedData,
    getGraph,
  };
}
