["```
function copyBytes(chunks, byteCount) {
  if (!Array.isArray(chunks) || !Buffer.isBuffer(chunks[0])) 
    throw new Error('Invalid input: chunks must be an array of Buffer instances');

  if (typeof byteCount !== 'number' || Math.floor(byteCount) !== byteCount)
    throw new Error('Invalid input: byte count must be a non-negative integer');

  let totalBytes = 0;
  for (const chunk of chunks) {
    totalBytes += chunk.length;
  }

  if (byteCount > totalBytes) 
    throw new Error('Not enough bytes available in the provided data');

  const outputBuffer = Buffer.alloc(byteCount);
  let bytesRead = 0;
  let dstPos = 0;

  for (const chunk of chunks) {
    let srcPos = 0;
    while (srcPos < chunk.length && bytesRead < byteCount) {
      const toCopy = Math.min(chunk.length - srcPos, byteCount - bytesRead);
      chunk.copy(outputBuffer, dstPos, srcPos, srcPos + toCopy);
      srcPos += toCopy;
      bytesRead += toCopy;
      dstPos += toCopy;
    }
  }

  return outputBuffer;
}
