function selectElements(cssSelector) {
  const cache = {};

  function traverse(node, path) {
    if (!node) return [];

    let elements = [];
    const selectorParts = cssSelector.split(' ');
    for (let i = 0; i < selectorParts.length; i++) {
      const part = selectorParts[i];
      const parts = part.split(',');

      for (let j = 0; j < parts.length; j++) {
        const part2 = parts[j].trim();

        if (!part2) continue;

        let nodes = node.querySelectorAll(part2);
        if (!nodes.length) return [];

        if (i === selectorParts.length - 1) {
          elements.push(...nodes);
        } else {
          for (let k = 0; k < nodes.length; k++) {
            const childNode = nodes[k];
            const path2 = `${path > '' ? `${path} ` : ''}${part2}`;

            if (!cache[path2]) {
              cache[path2] = traverse(childNode, path2);
            }
            elements.push(...cache[path2]);
          }
        }
      }
    }

    return elements;
  }

  return traverse(document.body, '');
}
