import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class TransactionProcessor {

    public static void processTransactions(String csvFilePath) throws IOException {
        Map<String, String> transactionMap = new HashMap<>();
        Map<String, String> merchantMap = new HashMap<>();

        try (BufferedReader bufferedReader = new BufferedReader(new FileReader(csvFilePath))) {
            String line;
            int totalClusters = 0;

            while ((line = bufferedReader.readLine()) != null) {
                String[] transactionData = line.split(",");
                String transactionId = transactionData[0];
                String merchantId = transactionData[1];

                if (transactionMap.containsKey(transactionId)) {
                    // Handle duplicate transaction IDs
                    System.out.println("Duplicate transaction ID: " + transactionId);
                } else {
                    transactionMap.put(transactionId, merchantId);

                    // Initialize Union-Find data structure for merchant grouping
                    String root = findRoot(merchantId, merchantMap);
                    String newRoot = findRoot(merchantId, merchantMap);

                    if (!root.equals(newRoot)) {
                        union(root, newRoot, merchantMap);
                        totalClusters++;
                    }

                    System.out.println("Processing transaction: " + transactionId);
                }
            }

            // Log time taken for grouping operations
            long endTime = System.currentTimeMillis();
            System.out.println("Time taken for grouping: " + (endTime - startTime) + " milliseconds");

            // Print summary report of total number of clusters formed
            System.out.println("Total number of clusters: " + totalClusters);
        }
    }

    private static String findRoot(String merchantId, Map<String, String> merchantMap) {
        if (!merchantMap.containsKey(merchantId)) {
            // Handle missing or malformed data
            return null;
        }

        if (merchantMap.get(merchantId).equals(merchantId)) {
            return merchantId;
        } else {
            String newRoot = findRoot(merchantMap.get(merchantId), merchantMap);
            merchantMap.put(merchantId, newRoot);
            return newRoot;
        }
    }

    private static void union(String root1, String root2, Map<String, String> merchantMap) {
        if (root1 == null || root2 == null) {
            // Handle missing or malformed data
            return;
        }

        if (!root1.equals(root2)) {
            merchantMap.put(root2, root1);
        }
    }
}
