import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.util.concurrent.ConcurrentHashMap;

public class DataStreamManager {
    private Selector selector;
    private ConcurrentHashMap<Integer, ServerSocketChannel> channels;

    public void start(int numChannels) throws IOException {
        selector = Selector.open();
        channels = new ConcurrentHashMap<>();
        for (int i = 0; i < numChannels; i++) {
            ServerSocketChannel channel = ServerSocketChannel.open();
            channel.bind(new InetSocketAddress(8000 + i));
            channel.configureBlocking(false);
            channel.register(selector, SelectionKey.OP_ACCEPT);
            channels.put(i, channel);
        }
    }

    public void accept() throws IOException {
        while (true) {
            selector.select();
            for (SelectionKey key : selector.selectedKeys()) {
                ServerSocketChannel channel = (ServerSocketChannel) key.channel();
                if (key.isAcceptable()) {
                    channel.accept().configureBlocking(false);
                    channel.register(selector, SelectionKey.OP_READ);
                }
            }
            selector.selectedKeys().clear();
        }
    }

    public void read() throws IOException {
        while (true) {
            selector.select();
            for (SelectionKey key : selector.selectedKeys()) {
                ServerSocketChannel channel = (ServerSocketChannel) key.channel();
                if (key.isReadable()) {
                    // Handle incoming data
                    System.out.println("Received data from channel " + channels.indexOf(channel));
                }
            }
            selector.selectedKeys().clear();
        }
    }

    public void stop() throws IOException {
        for (ServerSocketChannel channel : channels.values()) {
            channel.close();
        }
        selector.close();
    }
}']

