function manageSessionData(sessionToken) {
  const sessionStore = require('session-store');
  const moment = require('moment');

  // Check if session token is expired
  if (moment(sessionToken.expires).isBefore(moment())) {
    invalidateSessionToken();
  }

  function invalidateSessionToken() {
    sessionToken = generateNewToken();
    updateSessionStore(sessionToken);
  }

  function generateNewToken() {
    // Generate a new token using a secure random number generator
    const crypto = require('crypto');
    return crypto.randomBytes(20).toString('hex');
  }

  function updateSessionStore(newToken) {
    sessionStore.set(newToken, { ...sessionToken });
  }

  // Verify user's default locale is set
  if (!sessionToken.locale) {
    determineDefaultLocale();
  }

  function determineDefaultLocale() {
    const ipGeo = require('ip-geolocation');
    const systemSettings = require('system-settings');

    // Determine the user's IP address and use it to determine their default locale
    const ipAddress = getIpAddressFromRequest();
    const userCountryCode = ipGeo.lookup(ipAddress).country_code;
    sessionToken.locale = systemSettings.locales[userCountryCode] || 'en';
  }

  function getIpAddressFromRequest() {
    // Get the IP address from the request object (e.g., express.js's req.ip)
    return '192.168.1.100'; // Replace with actual IP address
  }

  // Validate session cookie
  const validatedSessionToken = validateSessionCookie(sessionToken);

  function validateSessionCookie(token) {
    // Verify the session token is valid and not tampered with
    // This step may involve cryptographic operations or validation against a database
    return token;
  }

  // Update user's session data with latest access timestamp
  const now = moment();
  sessionToken.lastAccessed = now.format('YYYY-MM-DD HH:mm:ss');
  updateSessionStore(sessionToken);

  function updateSessionStore(token) {
    sessionStore.set(token, { ...token });
  }
}

module.exports = manageSessionData;
