                return new EVP_CIPHER(new ECB());
            case "EDE":
                return new EVP_CIPHER(new EDE());
            case "EDE3":
                return new EVP_CIPHER(new EDE3());
            case "CFB":
                return new EVP_CIPHER(new CFB());
            default:
                return null;
        }
