    public static boolean verifyAccessToken(String accessTokenResponse) throws IOException {
        try (JsonReader reader = Json.createReader(Json.createReader(accessTokenResponse).readString())) {
            JsonObject jsonObject = reader.readObject();
            if (!jsonObject.containsKey("access_token") || !jsonObject.containsKey("expires_in") || !jsonObject.containsKey("token_type")) {
                return false;
            }
            String tokenType = jsonObject.getString("token_type");
            int expiresIn = jsonObject.getInt("expires_in");
            if (!tokenType.equals("Bearer") || expiresIn <= 0) {
                return false;
            }
            if (jsonObject.containsKey("refresh_token")) {
                // Optional, do nothing
            } else {
                return false;
            }
        }
        return true;
    }

