use reqwest::blocking::{ClientBuilder, RequestBuilder};
use reqwest::header;
use reqwest::redirect;
use reqwest::Cookie;
use log::{info, warn, error};

async fn create_http_client(url: &str, certificate_validation: bool) -> ClientBuilder {
    let client = ClientBuilder::new()
        .timeout(None)
        .redirect(redirect::follow_all())
        .cookie(Cookie::parse("your-cookie-name", "your-cookie-value").unwrap());

    if certificate_validation {
        client
            .danger_accept_invalid_certs(true)
            .cert(reqwest::pem::crt_file("path/to/your/cert/file"))
            .key(reqwest::pem::rsa_key_file("path/to/your/key/file"));
    }

    client
}

async fn make_request(client: &ClientBuilder, method: &str, url: &str) -> reqwest::blocking::Response {
    let mut request = client.request(method, url);

    // add headers
    request.header(header::ACCEPT_LANGUAGE, "en-US");
    request.header(header::USER_AGENT, "Your-Custom-User-Agent");

    // set query parameters
    if let Some(query_params) = get_query_parameters() {
        for (key, value) in query_params {
            request.query(&[(key.to_string(), value.to_string())]);
        }
    }

    // set body data
    if let Some(body_data) = get_body_data() {
        request.body(body_data);
    }

    request.send().await.unwrap()
}

async fn handle_response(response: &reqwest::blocking::Response) {
    info!("Request sent to {}: {}", response.url(), response.status());

    if let Ok(200..=299) = response.status() {
        // process the response
    } else {
        warn!("Failed request to {}: {}", response.url(), response.status());
        error!("Error processing request: {}", response.error().unwrap());
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let client = create_http_client("https://example.com", true).await;

    // make a GET request
    let response = make_request(&client, "GET", "/path/to/resource").await;
    handle_response(&response).await;

    // make a POST request with query parameters and body data
    let response = make_request(&client, "POST", "/path/to/endpoint")
        .query(&[("param1", "value1"), ("param2", "value2")])
        .body("your-body-data").await;
    handle_response(&response).await;

    // make a PUT request with custom user-agent
    let response = make_request(&client, "PUT", "/path/to/endpoint")
        .header(header::USER_AGENT, "Your-Custom-User-Agent")
        .query(&[("param1", "value1"), ("param2", "value2")])
        .body("your-body-data").await;
    handle_response(&response).await;

    // make a DELETE request with optional certificate validation
    let response = make_request(&client, "DELETE", "/path/to/endpoint")
        .danger_accept_invalid_certs(true)
        .query(&[("param1", "value1"), ("param2", "value2")])
        .body("your-body-data").await;
    handle_response(&response).await;
}
