        runtime.block_on(async {
            // Create a new Tokio task for the compilation
            let (send, receive) = oneshot::channel();
            tokio::spawn(async move {
                compile(&mut send).await.unwrap_or_else(|e| {
                    error!("Compilation failed: {}", e);
                    exit(1)
                });
            });

            // Wait for the compilation task to complete and get its result
            let (result, _) = receive.await;
            if let Err(err) = result {
                error!("Compilation failed: {}", err);
                exit(1);
            }

            info!("Compilation successful");
        });

        loop {
            match rx.recv().await {
                Some((task_id, log)) => {
                    // Process the compilation logs and metrics
                    process_logs(log).await;
                }
                None => break,
            }
        }
    })
}

async fn compile(send: &mut oneshot::Sender Result<(), String>) -> Result<(), String> {
    let start = Instant::now();

    // Install a custom logging hook using SyncLazy module
    sync_lazy::execute(|| {
        // ...
    });

    // Measure the time taken for compilation
    let end = Instant::now();
    let compile_time = end.duration_since(start).unwrap().as_millis();

    // Get the resident set size of the process before and after compilation
    let start_rss = get_resident_set_size();
    // ...

    // Run the Rust compiler with custom logging hook installed
    Command::new("rustc")
        .arg("--crate-type=lib")
        .arg("-o")
        // ...
        .status()
        .unwrap();

    // Install an ice hook using SyncLazy module and catch any errors that occur during compilation
    rustc_driver::catch_with_exit_code(|err| {
        early_error(err);
    });

    send.send(Ok(())).unwrap();
    Ok(())
}

async fn process_logs(log: String) {
    // Send the compilation logs and metrics to an external logging service asynchronously
    async_log_service::log(&log).await;
}
