function updatePatient($patientId)
{
    // Database connection
    $db = new PDO('mysql:host=localhost;dbname=healthcare_db', 'username', 'password');

    // Define tables and columns
    $tables = array('patients', 'contact_info', 'medical_history', 'insurance_info');
    $columns = array(
        'patients' => array('name', 'age'),
        'contact_info' => array('phone_number', 'email'),
        'medical_history' => array('conditions', 'medications'),
        'insurance_info' => array('provider', 'policy_number')
    );

    // Define update queries for each table
    $updates = array();
    foreach ($tables as $table) {
        $updates[] = "UPDATE `$table` SET ";
        foreach ($columns[$table] as $column) {
            $updates[] = "`$column`= :$column, ";
        }
        $updates[] = "WHERE `patient_id` = :patientId";
    }

    // Create prepared statement
    $stmt = $db->prepare(join(' ', $updates));

    // Bind values and execute updates
    $stmt->bindParam(':patientId', $patientId);
    foreach ($columns as $table => $columnArray) {
        foreach ($columnArray as $column) {
            $stmt->bindParam("{$column}", ${"new$column"});  // Note: These variables should be set before calling the function
        }
    }
    $stmt->execute();

    // Log update activity in audit table
    $auditQuery = "INSERT INTO `audits` (`patient_id`, `update_time`, `changes`) VALUES (:patientId, NOW(), :changes)";
    $db->prepare($auditQuery)->execute(array(':patientId' => $patientId, ':changes' => json_encode($updates)));

    // Return success message
    return 'Patient information updated successfully!';
}

