    public DataTable GetEmployeeDetails(int supervisorId, string connectionString)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            try
            {
                connection.Open();

                SqlCommand command = new SqlCommand("sp_GetEmployeeDetails", connection);
                command.CommandType = CommandType.StoredProcedure;
                command.Parameters.AddWithValue("@SupervisorId", supervisorId);

                using (SqlDataAdapter adapter = new SqlDataAdapter(command))
                {
                    DataTable dt = new DataTable();
                    adapter.Fill(dt);

                    return dt;
                }
            }
            catch (SqlException ex)
            {
                // Implement retry logic with exponential backoff
                int retries = 0;
                while (retries < 3)
                {
                    try
                    {
                        connection.Open();

                        SqlCommand command = new SqlCommand("sp_GetEmployeeDetails", connection);
                        command.CommandType = CommandType.StoredProcedure;
                        command.Parameters.AddWithValue("@SupervisorId", supervisorId);

                        using (SqlDataAdapter adapter = new SqlDataAdapter(command))
                        {
                            DataTable dt = new DataTable();
                            adapter.Fill(dt);

                            return dt;
                        }
                    }
                    catch (SqlException ex2)
                    {
                        if (retries >= 3) throw;

                        // Log the error and wait for a short period before retrying
                        System.Diagnostics.Debug.WriteLine($"Error: {ex2.Message}");
                        System.Threading.Thread.Sleep(500);
                        retries++;
                    }
                }

                return null;
            }
        }
    }
}

