<?php
function generateSessionToken($length, $chars) {
    if (!is_numeric($length) || !is_string($chars)) {
        return false;
    }
    if ($length < 1) {
        return false;
    }
    if (empty($chars)) {
        $chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    }

    mt_srand();
    $token = '';
    for ($i = 0; $i < $length; $i++) {
        $token .= $chars[mt_rand(0, strlen($chars) - 1)];
    }
    return $token;
}

function hashAuthenticationToken($token) {
    if (!is_string($token)) {
        return false;
    }
    $hash = hash('sha256', $token);
    return $hash;
}
