    curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($curl, CURLOPT_POST, true);
    curl_setopt($curl, CURLOPT_POSTFIELDS, 'code=' . $code . '&grant_type=authorization_code');
    $response = curl_exec($curl);

    if (empty($response)) {
        return false;
    }

    $json = json_decode($response, true);
    $access_token = $json['access_token'];
    $expires_in = $json['expires_in'];

    $stmt->execute(array(':token' => $access_token, ':expires' => time() + $expires_in));
    $db->commit();

    function get_user_info($access_token) {
        $curl = curl_init($user_info_url);
        curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($curl, CURLOPT_HTTPHEADER, array('Authorization: Bearer ' . $access_token));
        $response = curl_exec($curl);

        if (empty($response)) {
            return false;
        }

        return json_decode($response, true);
    }

    function refresh_access_token() {
        global $client_id, $client_secret, $redirect_uri;

        $curl = curl_init($token_url);
        curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($curl, CURLOPT_POST, true);
        curl_setopt($curl, CURLOPT_POSTFIELDS, 'grant_type=refresh_token&refresh_token=' . $access_token);
        $response = curl_exec($curl);

        if (empty($response)) {
            return false;
        }

        $json = json_decode($response, true);
        $new_access_token = $json['access_token'];
        $expires_in = $json['expires_in'];

        // Update the access token in the database
        $stmt->execute(array(':token' => $new_access_token, ':expires' => time() + $expires_in));
        $db->commit();

        return $new_access_token;
    }

    function rate_limit($access_token) {
        global $rate_limit_window;

        // Check if the access token has been used recently
        $stmt = $db->prepare("SELECT COUNT(*) FROM access_tokens WHERE expires_in > :time AND expires_in < :time + :window");
        $stmt->bindParam(':time', time());
        $stmt->bindParam(':window', $rate_limit_window);
        $count = $stmt->execute()->fetchColumn();

        if ($count >= 5) {
            // Token has been used too many times recently, refresh it
            return refresh_access_token();
        }

        return false;
    }

    function check_token($access_token) {
        global $cache_duration;

        // Check if the access token is expired
        if (time() > ($expires_in + $cache_duration)) {
            // Token has expired, refresh it
            return refresh_access_token();
        }

        return true;
    }
