import re
from datetime import datetime
from heapq import heapify, heappop

def process_log_file(log_file_path):
    log_entries = []
    try:
        with open(log_file_path, 'r') as f:
            for line in f:
                match = re.match(r'(\d{14})\s+([0-9]+)\s+(.*)', line)
                if match:
                    timestamp, sequence_number, data_fields = match.groups()
                    try:
                        entry_timestamp = datetime.strptime(timestamp, '%Y%m%d%H%M%S')
                    except ValueError:
                        continue
                    log_entries.append((entry_timestamp, int(sequence_number), data_fields))
    except IOError as e:
        print(f"Error reading file: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

    # Sort entries by timestamp
    heapify(log_entries)
    sorted_entries = []
    while log_entries:
        _, sequence, _ = heappop(log_entries)
        sorted_entries.append((sequence,))

    # Extract sequence number from last entry
    try:
        last_sequence_number = sorted_entries[-1][0]
    except IndexError:
        print("No entries found in the file")
        return

    print(f"Last sequence number: {last_sequence_number}")
