#include <stdlib.h>
#include <stdio.h>

typedef struct State {
    int id;
    struct State* next;
    struct State* prev;
} State;

State* add_state(State** head, int last_state) {
    if (*head == NULL || last_state != 0) {
        *head = malloc(sizeof(State));
        if (*head == NULL) {
            return NULL; // Out of memory
        }
        (*head)->id = last_state + 1;
        (*head)->next = NULL;
        (*head)->prev = NULL;
    } else {
        State* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        State* new_state = malloc(sizeof(State));
        if (new_state == NULL) {
            return NULL; // Out of memory
        }
        new_state->id = last_state + 1;
        new_state->next = NULL;
        new_state->prev = current;
        current->next = new_state;
    }
    last_state++;
    return *head;
}
