class Node {
public:
    std::shared_ptr<Node> children[8];
    bool isLeaf;
};

std::shared_ptr<Node> initializeOctree(size_t maxDepth, size_t capacity, size_t memoryLimit) {
    if (maxDepth > 0 && memoryLimit < sizeof(Node)) {
        return nullptr; // Error: Insufficient memory
    }

    std::shared_ptr<Node> root = std::make_shared<Node>();
    root->isLeaf = true;

    size_t remainingMemory = memoryLimit;
    for (size_t i = 0; i < maxDepth; ++i) {
        size_t numNodes = (1 << i);
        if (remainingMemory < sizeof(Node) * numNodes) {
            return nullptr; // Error: Insufficient memory
        }

        for (size_t j = 0; j < numNodes; ++j) {
            root->children[j] = std::make_shared<Node>();
            root->children[j]->isLeaf = false;
            remainingMemory -= sizeof(Node);
        }
    }

    return root;
}

int main() {
    size_t maxDepth = 5;
    size_t capacity = 1024;
    size_t memoryLimit = 1048576;

    std::shared_ptr<Node> octree = initializeOctree(maxDepth, capacity, memoryLimit);

    if (!octree) {
        std::cout << "Error: Insufficient memory." << std::endl;
    } else {
        // Use the octree
    }

    return 0;
}
