#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TRANSACTIONS 10000
#define WINDOW_SIZE 10
#define THRESHOLD_ADJUSTMENT 1.05
#define TRANSACTION_ID_LENGTH 32

typedef struct {
    int id;
    double weighted_sum;
    time_t timestamp;
} Transaction;

Transaction transactions[MAX_TRANSACTIONS];
int num_transactions = 0;
int filtered_transactions = 0;
double cumulative_weighted_sum = 0.0;
time_t last_processing_time = time(NULL);

void update_metrics(int transaction_id, double weighted_sum) {
    cumulative_weighted_sum += weighted_sum;
    if (num_transactions < WINDOW_SIZE) {
        transactions[num_transactions].id = transaction_id;
        transactions[num_transactions].weighted_sum = weighted_sum;
        transactions[num_transactions].timestamp = time(NULL);
        num_transactions++;
    } else {
        int i;
        for (i = 0; i < WINDOW_SIZE - 1; i++) {
            transactions[i] = transactions[i + 1];
        }
        transactions[WINDOW_SIZE - 1].id = transaction_id;
        transactions[WINDOW_SIZE - 1].weighted_sum = weighted_sum;
        transactions[WINDOW_SIZE - 1].timestamp = time(NULL);
    }
}

double calculate_threshold() {
    double average_weighted_sums[5] = {0.0};
    int i;
    for (i = 0; i < min(WINDOW_SIZE, num_transactions); i++) {
        average_weighted_sums[i % 5] += transactions[i].weighted_sum;
    }
    return average_weighted_sums[0];
}

int filter_transactions(int transaction_id, double weighted_sum) {
    time_t current_time = time(NULL);
    if (current_time - last_processing_time > 5 || num_transactions == 0) {
        filtered_transactions++;
    } else {
        int i;
        for (i = 0; i < WINDOW_SIZE; i++) {
            if (transactions[i].id == transaction_id && current_time - transactions[i].timestamp > 3) {
                filtered_transactions++;
                break;
            }
        }
    }
    last_processing_time = current_time;
    return 1;
}

int main(int argc, char *argv[]) {
    int max_weighted_sum = 0;
    int max_weighted_sum_id = -1;
    double threshold = calculate_threshold();

    while (/* process transactions */) {
        // filter transactions
        for (int i = 0; i < num_transactions; i++) {
            if (filter_transactions(transactions[i].id, transactions[i].weighted_sum)) {
                if (transactions[i].weighted_sum > threshold) {
                    max_weighted_sum = transactions[i].weighted_sum;
                    max_weighted_sum_id = transactions[i].id;
                    break;
                }
            }
        }
    }

    return 0;
}
