using System;

public class RandomValueGenerator
{
    private Random _random;
    public int MinInt { get; set; }
    public int MaxInt { get; set; }
    public double MinFloat { get; set; }
    public double MaxFloat { get; set; }

    public RandomValueGenerator()
    {
        _random = new Random();
    }

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
    }

    public int GenerateRandomInt(bool isExclusive, bool isValidated = true)
    {
        if (isValidated && (!ValidateRange(MinInt, MaxInt)))
            throw new ArgumentException("Invalid range for integer generation");
        return _random.Next(isExclusive ? 0 : MinInt, isExclusive ? MaxInt + 1 : MaxInt + 1);
    }

    public double GenerateRandomFloat(bool isExclusive, bool isValidated = true)
    {
        if (isValidated && (!ValidateRange(MinFloat, MaxFloat)))
            throw new ArgumentException("Invalid range for float generation");
        return _random.NextDouble() * (isExclusive ? MaxFloat - MinFloat : MaxFloat - MinFloat + 1) + isExclusive ? MinFloat : MinFloat;
    }

    public bool ValidateRange(int min, int max)
    {
        if (min > max)
            return false;
        return true;
    }

    public override string ToString()
    {
        return $"RandomValueGenerator: {MinInt} to {MaxInt} for integers and {MinFloat} to {MaxFloat} for floats";
    }
}
