function asyncReduce(arr, initAccumulator, callback) {
  return new Promise((resolve, reject) => {
    let accumulator = initAccumulator;
    (async () => {
      for await (const element of arr) {
        try {
          accumulator = await callback(accumulator, element);
        } catch (error) {
          reject(error);
          return;
        }
      }
      resolve(accumulator);
    })();
  });
}

function asyncFetchExternalData(url) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open('GET', url, true);
    xhr.onload = () => {
      if (xhr.status === 200) {
        resolve(xhr.responseText);
      } else {
        reject(new Error(`Failed to fetch external data: ${xhr.statusText}`));
      }
    };
    xhr.onerror = () => reject(new Error('Network error'));
    xhr.send();
  });
}

async function main() {
  const arr = [1, 2, 3, 4, 5];
  const initAccumulator = 0;
  const callback = async (acc, element) => acc + element;

  const reducedValue = await asyncReduce(arr, initAccumulator, callback);
  console.log(reducedValue); // Output: 15

  const externalData = await asyncFetchExternalData('https://example.com/external-data');
  const processedData = await asyncReduce([1, 2, 3], 0, (acc, element) => acc + parseInt(element));
  console.log(processedData); // Output: 6
}

main();
