    int csv_len = 0;
    size_t compressed_len = 0;
    void *buffer;

    // Check if the file exists
    struct stat sb;
    if(stat(file_name, &sb) == -1) {
        log_error("File not found");
        return -1;
    }

    // Determine the file format based on the extension
    const char *file_ext = strrchr(file_name, '.');
    if(strncmp(file_ext, ".json", 4) == 0 || strncmp(file_ext, ".JSON", 5) == 0) {
        json_len = read_file(file_name, &buffer);
    } else if(strncmp(file_ext, ".csv", 3) == 0 || strncmp(file_ext, ".CSV", 4) == 0) {
        csv_len = read_csv(file_name, &buffer);
    } else {
        // Assume it's a compressed file
        compressed_len = read_compressed_file(file_name, &buffer);
    }

    if(buffer != NULL) {
        free(buffer);
    }

    return json_len + csv_len;
}

int read_file(const char *file_name, void **buffer) {
    int file_desc = open(file_name, O_RDONLY | O_NONBLOCK);
    if(file_desc == -1) {
        log_error("Failed to open the file");
        return -1;
    }

    struct stat sb;
    fstat(file_desc, &sb);

    *buffer = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, file_desc, 0);
    if(*buffer == MAP_FAILED) {
        log_error("Failed to map the file");
        close(file_desc);
        return -1;
    }

    close(file_desc);
    return (int)sb.st_size;
