    }

    int len = strlen(str);
    if (len >= size_limit) {
        return NULL;
    }

    char* result = (char*)malloc((len + 2)*sizeof(char));
    if (!result) {
        my_log_function("Memory allocation failed");
        return NULL;
    }

    strcpy(result, str);
    if (len < size_limit - 1) {
        strcat(result, "/");
    }

    if (buffer_size >= len + 2) {
        char* temp = result;
        result = buffer;
        buffer = temp;
    } else {
        free(result);
        return NULL;
    }

    return result;
}

int main() {
    char* str1 = "hello";
    int size_limit1 = 5;
    char* buffer1 = (char*)malloc(10*sizeof(char));
    strcpy(buffer1, "test");

    char* res1 = add_slash(str1, size_limit1, buffer1, 10);
    printf("Result: %s\n", res1?res1:"NULL");

    char* str2 = "";
    int size_limit2 = 0;
    char* buffer2 = (char*)malloc(5*sizeof(char));
    strcpy(buffer2, "abc");

    char* res2 = add_slash(str2, size_limit2, buffer2, 5);
    printf("Result: %s\n", res2?res2:"NULL");

    return 0;
}']

