#define MAX_LINE_LENGTH 1024
#define MAX_FIELDS 100

double* process_line(char* line, int* num_fields) {
    // Tokenize the line and count the number of fields
    char* token = strtok(line, " ");
    *num_fields = 0;
    double* fields = (double*)malloc(MAX_FIELDS * sizeof(double));
    while(token != NULL && *num_fields < MAX_FIELDS) {
        if(sscanf(token, "%lf", &fields[*num_fields]) == 1)
            (*num_fields)++;
        token = strtok(NULL, " ");
    }
    // Calculate the average of the last three fields
    double avg = 0;
    for(int i = *num_fields - 3; i < *num_fields; i++)
        avg += fields[i];
    avg /= 3;
    free(fields);
    return &avg;
}

int main() {
    FILE* file = fopen("input.txt", "r");
    if(file == NULL) {
        log_error("Error opening file");
        return 1;
    }

    int num_lines = 0;
    char line[MAX_LINE_LENGTH];
    while(fgets(line, MAX_LINE_LENGTH, file) != NULL) {
        int num_fields;
        double* avg = process_line(line, &num_fields);
        if(num_fields >= 3) {
            printf("%.2f,", *avg);
        }
        free(avg);
    }

    fclose(file);
    return 0;
}

