    FILE* file = fopen(filename, "rb");
    if (!file) {
        free(info);
        return NULL;  // Error: unable to open file
    }

    // Read the TIFF header (16 bytes)
    unsigned char header[16];
    fread(header, 1, 16, file);

    // Check for TIFF format marker
    if (header[0] != 0x49 || header[1] != 0x49 || 
        header[8] != 0x2a || header[9] != 0x20) {
        fclose(file);
        free(info);
        return NULL;  // Error: not a TIFF file
    }

    // Read the image information
    unsigned char* ptr = (unsigned char*)header;
    info->bits_per_sample = (int)*(ptr + 12);
    if (info->bits_per_sample < 1 || info->bits_per_sample > 16) {
        fclose(file);
        free(info);
        return NULL;  // Error: unsupported bits per sample
    }

    ptr += 14;
    int sample_count = *(int*)ptr;
    info->samples_per_pixel = (int)*(ptr + 4);

    // Check for extra samples
    if (sample_count > info->samples_per_pixel) {
        info->extra_samples = sample_count - info->samples_per_pixel;
    } else {
        info->extra_samples = 0;
    }

    fclose(file);

