char* modify_filename_extension(const char* filename) {
    int len = strlen(filename);
    if (len > 255) return "Error: Filename too long";

    int vowel_count = 0;
    for (int i = 0; i < len; i++) {
        if (strchr("aeiouAEIOU", filename[i])) vowel_count++;
    }

    char* new_filename = malloc((len + 10) * sizeof(char));
    strcpy(new_filename, filename);

    if (vowel_count > 0) {
        double seq = (double)vowel_count / len;
        int seq_len = sprintf(NULL, "%.2f", seq);
        char buffer[seq_len];
        sprintf(buffer, "%.2f", seq);
        strcat(new_filename, "_" + buffer);
    }

    for (int i = 0; i < 5; i++) {
        if (strchr(".txt.pdf.docx", filename[len - i - 1])) {
            new_filename[len - i] = 0;
            strcat(new_filename, ".txt");
            break;
        }
    }

    return new_filename;
}

int main() {
    printf("%s\n", modify_filename_extension("example.txt"));
    return 0;
}
