#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/hmac.h>

#define MAX_PASSWORD_LENGTH 32
#define MIN_IV_LENGTH 8
#define MAX_IV_LENGTH 16
#define CBC_MODE 0
#define GCM_MODE 1
#define CTR_MODE 2

typedef struct {
    AES_CTX *aes_ctx;
    unsigned char *derived_key;
    int derived_key_len;
    unsigned char *iv;
    int iv_len;
    int mode;
} CipherContext;

CipherContext* cipher_init(const char* password, const char* salt, int salt_len, int iv_len, int mode) {
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    // Initialize AES context
    ctx->aes_ctx = AES_make_key(password, salt, salt_len);
    if (!ctx->aes_ctx) {
        free(ctx);
        return NULL;
    }

    // Derive the key using a robust KDF (e.g., PBKDF2)
    ctx->derived_key = PBKDF2_HMAC_SHA1(password, salt, salt_len, 32, 1000);
    if (!ctx->derived_key) {
        AES_free(ctx->aes_ctx);
        free(ctx);
        return NULL;
    }

    // Allocate and copy IV
    ctx->iv = malloc(iv_len);
    if (!ctx->iv) {
        AES_free(ctx->aes_ctx);
        free(ctx->derived_key);
        free(ctx);
        return NULL;
    }
    memcpy(ctx->iv, password + strlen(password), iv_len);

    ctx->mode = mode;

    return ctx;
}

int cipher_encrypt(CipherContext* ctx, const unsigned char* plaintext, size_t len, unsigned char** ciphertext) {
    // Encrypt the data using the AES context
    int ret = AES_crypt(ctx->aes_ctx, ctx->iv, plaintext, len, ciphertext);
    if (ret < 0) {
        ERR_error();
        return -1;
    }

    return ret;
}

int cipher_decrypt(CipherContext* ctx, const unsigned char* ciphertext, size_t len, unsigned char** plaintext) {
    // Decrypt the data using the AES context
    int ret = AES_crypt(ctx->aes_ctx, ctx->iv, ciphertext, len, plaintext);
    if (ret < 0) {
        ERR_error();
        return -1;
    }

    return ret;
}

void cipher_cleanup(CipherContext* ctx) {
    // Clean up and free the resources
    AES_free(ctx->aes_ctx);
    free(ctx->derived_key);
    free(ctx->iv);
    free(ctx);
}

int main() {
    CipherContext* ctx = cipher_init("my_password", "my_salt", 16, 12, CBC_MODE);

    if (!ctx) return -1;

    // Use the cipher
    unsigned char plaintext[] = "Hello, World!";
    size_t len = strlen((char*)plaintext);
    unsigned char* ciphertext;
    int ret = cipher_encrypt(ctx, plaintext, len, &ciphertext);

    if (ret < 0) {
        ERR_error();
        return -1;
    }

    // Verify the integrity of the decrypted data
    unsigned char* decrypted;
    ret = cipher_decrypt(ctx, ciphertext, len, &decrypted);

    if (ret < 0) {
        ERR_error();
        return -1;
    }

    // Clean up and disable the cipher
    cipher_cleanup(ctx);

    return 0;
}
