#include <time.h>

int copy_jpg_files(const char *src_dir, const char *tgt_dir) {
    DIR *dir;
    struct dirent *ent;
    struct stat statbuf;
    time_t mod_time;
    int file_size;

    // Create log file
    FILE *log_file = fopen("copy_log.txt", "a+");
    if (!log_file) {
        return 1;
    }

    // Check if target directory exists, create it if not
    if (mkdir(tgt_dir, 0755)) {
        fprintf(log_file, "Error creating target directory: %s\n", tgt_dir);
        fclose(log_file);
        return 1;
    }

    dir = opendir(src_dir);
    if (!dir) {
        fprintf(log_file, "Error opening source directory: %s\n", src_dir);
        fclose(log_file);
        return 1;
    }

    while ((ent = readdir(dir))) {
        char file_path[1024];
        sprintf(file_path, "%s/%s", src_dir, ent->d_name);

        if (stat(file_path, &statbuf) < 0) {
            fprintf(log_file, "Error reading file: %s\n", file_path);
            continue;
        }

        // Check if it's a .jpg file
        if (!strncasecmp(ent->d_name, ".jpg", 4)) {
            char tgt_file_path[1024];
            sprintf(tgt_file_path, "%s/%s", tgt_dir, ent->d_name);

            // Create target directory if not exists
            mkdir(tgt_file_path, 0755);

            if (stat(file_path, &statbuf) < 0) {
                fprintf(log_file, "Error reading file: %s\n", file_path);
                continue;
            }

            mod_time = statbuf.st_mtime;
            file_size = statbuf.st_size;

            // Copy the file
            FILE *file = fopen(tgt_file_path, "wb");
            if (!file) {
                fprintf(log_file, "Error copying file: %s\n", file_path);
                continue;
            }

            FILE *src_file = fopen(file_path, "rb");
            if (!src_file) {
                fclose(file);
                fprintf(log_file, "Error opening source file: %s\n", file_path);
                continue;
            }

            size_t bytes_read;
            char buffer[1024];
            while ((bytes_read = fread(buffer, 1, sizeof(buffer), src_file)) > 0) {
                fwrite(buffer, 1, bytes_read, file);
            }

            fclose(file);
            fclose(src_file);

            // Log the file copy information
            fprintf(log_file, "Copied: %s (Size: %d, Mod Time: %ld)\n", ent->d_name, file_size, mod_time);
        }
    }

    closedir(dir);
    fclose(log_file);

    return 0;
}
