#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <semaphore.h>

#define LOG_FILE "command_log.txt"
#define MAX_CONCURRENT_PROCESSES 10
#define SHUTDOWN_SIGNAL SIGINT

sem_t lock;

void shutdown_handler(int signum) {
    // Shut down all background processes
    sem_wait(&lock);
    printf("Shutting down background processes...\n");
    system("pkill -9 -P 0"); // Send signal to all processes with PID 1
    sem_post(&lock);
}

int execute_command_in_background(char *command, char *log_file) {
    pid_t child_pid;
    int status;

    if (sem_open(&lock, O_CREAT | O_EXCL, 0644, 1) < 0) {
        return -1; // Failed to create semaphore
    }

    if (signal(SHUTDOWN_SIGNAL, shutdown_handler) == SIG_ERR) {
        sem_close(&lock);
        return -2; // Failed to set signal handler
    }

    if (!command || !*command || !log_file || !*log_file) {
        return -3; // Invalid command or log file
    }

    child_pid = fork();

    if (child_pid < 0) {
        sem_close(&lock);
        return -4; // Fork failed
    }

    if (child_pid > 0) {
        waitpid(child_pid, &status, 0); // Wait for child process to finish
        return WEXITSTATUS(status);
    } else {
        // Child process: execute command in background
        char *argv[] = {(char *)command, NULL};
        execvp(command, argv);

        // Handle errors and log execution status
        if (errno) {
            printf("Error executing command '%s': %s\n", command, strerror(errno));
        } else {
            printf("Command '%s' executed successfully.\n", command);
        }

        return 1; // Child process executed successfully
    }
}
