using System;
using System.Diagnostics;
using System.IO;

public class AddWebsiteToDirectory
{
    public static string AddWebsiteToDirectory(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
            return "The specified directory does not exist.";

        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
            return "No web.config file found in the directory. Please ensure it is present to start the website successfully.";

        try
        {
            ProcessStartInfo startInfo = new ProcessStartInfo();
            startInfo.FileName = Path.Combine(directoryPath, siteName + ".exe");
            startInfo.UseShellExecute = false;
            startInfo.CreateNoWindow = true;

            Process process = Process.Start(startInfo);
            process.WaitForExit();

            return "The website was successfully started.";
        }
        catch (Exception ex)
        {
            return $"An error occurred while starting the website: {ex.Message}";
        }
    }
}
