import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class CommandExecutor {
    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY_MILLIS = 1000; // 1 second
    private ExecutorService executorService = Executors.newCachedThreadPool();
    private Logger logger = new Logger();

    public void executeCommand(String command) throws IOException, InterruptedException {
        File targetFile = new File("target_file.txt"); // Replace with actual file path
        if (targetFile.exists()) {
            try {
                targetFile.delete();
            } catch (SecurityException e) {
                logger.error("Failed to delete target file: " + e.getMessage());
            }
        }

        List<Future<String>> futures = new ArrayList<>();
        try {
            for (int retry = 0; retry <= MAX_RETRIES; retry++) {
                CommandRunnable commandRunnable = new CommandRunnable(command);
                Future<String> future = executorService.submit(commandRunnable);
                futures.add(future);

                if (!future.get().equals("Command executed successfully")) {
                    // Command execution failed, wait for a short period before retrying
                    Thread.sleep(RETRY_DELAY_MILLIS);
                } else {
                    break; // Command execution succeeded, no need to retry
                }
            }
        } catch (ExecutionException e) {
            logger.error("Command execution failed: " + e.getMessage());
            // If command execution fails after maximum retries, stop the executor service
            executorService.shutdownNow();
        } finally {
            // Shut down the executor service when command execution is complete
            executorService.shutdown();
        }

        for (Future<String> future : futures) {
            try {
                String result = future.get();
                logger.info(result);
            } catch (InterruptedException | ExecutionException e) {
                logger.error("Failed to get command execution result: " + e.getMessage());
            }
        }
    }

    private class CommandRunnable implements Runnable {
        private final String command;

        public CommandRunnable(String command) {
            this.command = command;
        }

        @Override
        public void run() {
            Process process = null;
            try {
                process = Runtime.getRuntime().exec(new String[]{"/bin/sh", "-c", command});
                BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                // Read standard output
                String line;
                while ((line = stdInput.readLine()) != null) {
                    logger.info(line);
                }

                // Read standard error
                while ((line = stdError.readLine()) != null) {
                    logger.error(line);
                }

                process.waitFor();
                if (process.exitValue() == 0) {
                    logger.info("Command executed successfully");
                } else {
                    logger.error("Command execution failed");
                }
            } catch (IOException | InterruptedException e) {
                // Handle command execution failure
                logger.error("Command execution failed: " + e.getMessage());
            } finally {
                if (process != null) {
                    process.destroy();
                }
            }
        }
    }

    private class Logger {
        public void info(String message) {
            System.out.println("[INFO] " + message);
        }

        public void error(String message) {
            System.out.println("[ERROR] " + message);
        }
    }
}
