#include <json-c/json.h>
#include <stdio.h>

int json_string_to_value(const char *str) {
    json_object *obj;
    obj = json_object_from_json_string(str);

    if(obj == NULL) {
        return 0; // JSON parsing error, return false
    }

    int result = verify_token(obj);

    json_object_put(obj); // Release allocated memory

    return result;
}

int verify_token(json_object *obj) {
    const char *access_token = json_object_get_string(obj, "access_token");
    const char *token_type = json_object_get_string(obj, "token_type");
    const char *refresh_token = json_object_get_string(obj, "refresh_token", NULL);

    int expires_in = (int)json_object_get_int(obj, "expires_in");

    if(access_token == NULL || strlen(access_token) < 16 || strlen(access_token) > 256)
        return 0;
    if(token_type == NULL || strcmp(token_type, "Bearer") != 0)
        return 0;
    if(refresh_token != NULL && strlen(refresh_token) > 1024)
        return 0;

    if(expires_in <= 0)
        return 0;

    // Token type is 'Bearer', and the rest of the fields are valid
    return 1;
}

int main() {
    const char *json_string = "{\"access_token\":\"your_access_token\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    int result = json_string_to_value(json_string);

    if(result) {
        printf("Token is valid\n");
    } else {
        printf("Token is invalid\n");
    }

    return 0;
}
