        _iv = iv;
    }

    public (string[], int) DecryptMessages(params string[] messages)
    {
        var decryptedMessages = new List<string>();
        var discardedCount = 0;

        foreach (var message in messages)
        {
            if (message.Length > 1024)
            {
                ++discardedCount;
                continue;
            }

            try
            {
                var encryptedBytes = Convert.FromBase64String(message);
                using var tripleDes = TripleDES.Create();
                tripleDes.Key = Encoding.ASCII.GetBytes(_key);
                tripleDes.IV = _iv;

                using var ms = new MemoryStream(encryptedBytes);
                using var cs = new CryptoStream(ms, tripleDes.CreateDecryptor(), CryptoStreamMode.Write);

                byte[] decryptedBytes;
                using (var memoryStream = new MemoryStream())
                {
                    cs.CopyTo(memoryStream);
                    memoryStream.Flush();
                    decryptedBytes = memoryStream.ToArray();
                }

                string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);
                decryptedMessages.Add(decryptedMessage);
            }
            catch (CryptographicException ex)
            {
                Console.WriteLine($"Error decrypting message: {ex.Message}");
            }
        }

        return (decryptedMessages.ToArray(), discardedCount);
    }
}
