using System.Security.Cryptography;
using System.Text;

public class LogProcessor
{
    private readonly ILogger _logger;

    public Dictionary<string, string> ProcessLogBatch(List<string> logEntries)
    {
        var idToHash = new Dictionary<string, string>();

        foreach (var entry in logEntries)
        {
            try
            {
                var md5 = MD5(entry);
                idToHash.Add(entry, md5);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
        }

        return idToHash;
    }

    private string MD5(string input)
    {
        using var hashProvider = SHA256.Create();
        var inputBytes = Encoding.ASCII.GetBytes(input);
        var hashedBytes = hashProvider.ComputeHash(inputBytes);
        return BitConverter.ToString(hashedBytes).Replace("-", "").ToLower();
    }
}
