using System;
using System.Security.Cryptography;
using System.Text;

public class Aescbcs decryptor
{
    public static byte[] Decrypt(byte[] cipherText, string encryptionKey, string initializationVector, string paddingScheme)
    {
        try
        {
            using (var aes = Aes.Create())
            {
                aes.Key = Convert.FromBase64String(encryptionKey);
                if (aes.Key.Length != 16 && aes.Key.Length != 24 && aes.Key.Length != 32)
                    throw new ArgumentException("Invalid AES key length. It must be 16, 24 or 32 bytes.");

                aes.IV = Convert.FromBase64String(initializationVector);

                using (var memoryStream = new MemoryStream())
                {
                    using (var cryptoStream = Aes.CreateCryptoStream(memoryStream, aes, CryptoStreamMode.Write))
                    {
                        if (paddingScheme.ToLower() == "pkcs7")
                        {
                            var pkcs7Padding = new PaddingSchemePKCS7();
                            cryptoStream.Write(cipherText, 0, cipherText.Length);
                            cryptoStream.FlushFinalBlock();
                            memoryStream.Position = 0;
                            return memoryStream.ToArray();
                        }
                        else if (paddingScheme.ToLower() == "iso7816-4")
                        {
                            var iso7816Padding = new PaddingSchemeISO7816_4();
                            cryptoStream.Write(cipherText, 0, cipherText.Length);
                            cryptoStream.FlushFinalBlock();
                            memoryStream.Position = 0;
                            return memoryStream.ToArray();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            System.Diagnostics.EventLog.WriteEntry("AESCBCS Decryptor", "Error occurred during decryption: " + ex.Message);
            throw;
        }
    }

    public class PaddingSchemePKCS7
    {
        public static byte[] PKCS7Unpad(byte[] paddedBytes)
        {
            int paddingLength = paddedBytes[paddedBytes.Length - 1];
            if (paddingLength > paddedBytes.Length)
                throw new ArgumentException("Invalid padding length. It must be less than or equal to the ciphertext length.");
            return paddedBytes.Take(paddedBytes.Length - paddingLength).ToArray();
        }
    }

    public class PaddingSchemeISO7816_4
    {
        public static byte[] ISO7816Unpad(byte[] paddedBytes)
        {
            int paddingLength = 0;
            for (int i = paddedBytes.Length - 1; i >= 0; i--)
            {
                if (paddedBytes[i] > paddingLength)
                    throw new ArgumentException("Invalid padding length. It must be less than or equal to the ciphertext length.");
                else
                    paddingLength = paddedBytes[i];
            }
            return paddedBytes.Take(paddedBytes.Length - paddingLength).ToArray();
        }
    }
}
