        }
    }

    public static void executeJavaScriptFiles(Object obj) throws ScriptException, IOException {
        String[] jsFileNames = {"file1.js", "file2.js", "file3.js"}; // list of JavaScript file names
        Invocable invocable;
        try {
            for (String jsFileName : jsFileNames) {
                ScriptEngineManager sem = new ScriptEngineManager();
                ScriptEngine engine = sem.getEngineByName("nashorn");
                engine.eval("load('" + jsFileName + "');");
                invocable = (Invocable) engine;
                invocable.invoke();
            }
        } catch (IOException | ScriptException e) {
            throw new RuntimeException("Error executing JavaScript files: " + e.getMessage());
        }
    }
}
