const childProcess = require('child_process');
const axios = require('axios');

function executeShellCommand(command, apiToken) {
  if (!apiToken) {
    throw new Error('API token is required');
  }

  return async () => {
    try {
      const response = await axios.post(`https://example.com/execute-command`, { command }, {
        headers: {
          'Authorization': `Bearer ${apiToken}`,
          'Content-Type': 'application/json',
        },
        timeout: 30000,
      });

      if (response.status !== 200) {
        throw new Error(`Command execution failed with status code ${response.status}`);
      }

      const { stdout, stderr } = response.data;

      if (stderr) {
        console.error(`Error executing command: ${stderr}`);
      }

      return stdout;
    } catch (error) {
      console.error('Error executing command:', error);
      throw error;
    }
  };
}

function cacheCommandResults({ maxAge, cacheKey }) {
  const cache = {};

  async function getCommandResult(command, apiToken) {
    const key = `${cacheKey}:${command}`;
    if (cache[key]) {
      return cache[key];
    }

    try {
      const result = await executeShellCommand(command, apiToken)();
      cache[key] = { value: result, timestamp: Date.now() };
      return result;
    } catch (error) {
      console.error('Error fetching command result from cache:', error);
      throw error;
    }
  }

  async function setCommandResult(command, apiToken, result) {
    const key = `${cacheKey}:${command}`;
    cache[key] = { value: result, timestamp: Date.now() };
  }

  return { getCommandResult, setCommandResult };
}

const commandCache = cacheCommandResults({
  maxAge: 1000 * 60 * 15, // 15 minutes
  cacheKey: 'my-application',
});

module.exports = {
  executeShellCommand,
  commandCache,
};
