use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use log::{info, warn};

fn create_config_dir() -> Result<(), String> {
    let config_dir_path = env::var("CONFIG_DIR").unwrap_or_else(|_| {
        if !fs::create_dir_all(Path::new(".")).is_ok() {
            return format!("Failed to create project root directory: {}", fs::io_err().unwrap());
        }
        PathBuf::from(".").join("config")
    });

    let current_config_dir_path = env::var("CONFIG_DIR").unwrap_or_default();
    if current_config_dir_path == config_dir_path.to_string_lossy()[0] {
        return Ok(());
    }

    let new_config_dir_path = &config_dir_path;
    info!("Creating config directory at: {}", new_config_dir_path);

    if !fs::create_dir_all(new_config_dir_path).is_ok() {
        warn!("Failed to create config directory: {}", fs::io_err().unwrap());
        return Err("Failed to create config directory".to_string());
    }

    env::set_var("CONFIG_DIR", &new_config_dir_path.to_string_lossy()[0]);

    Ok(())
}
