import json
from abc import ABC, abstractmethod
from collections import defaultdict

class JSONSerializable(ABC):
    @abstractmethod
    def to_json(self) -> dict:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, data: dict) -> 'JSONSerializable':
        pass

class Registry:
    def __init__(self):
        self.factories = defaultdict(dict)

    def register_factory(self, id: str, factory_func):
        self.factories[id] = factory_func

    def get_instance(self, id: str, data: dict) -> JSONSerializable:
        factory_func = self.factories.get(id)
        if not factory_func:
            raise ValueError(f"Invalid ID: {id}")
        return factory_func(data)

class JSONParser:
    def __init__(self):
        self.registry = Registry()

    def parse(self, json_data: str) -> dict:
        try:
            data = json.loads(json_data)
            instance = self.parse_json_object(data)
            return instance.to_json()
        except Exception as e:
            raise ValueError(f"Invalid JSON input: {e}")

    def parse_json_object(self, data: dict) -> JSONSerializable:
        id = data.get('type')
        if not id:
            raise ValueError("Missing type ID")
        factory_func = self.registry.get_instance(id, data)
        return factory_func(data)

class JsonSerializer:
    def __init__(self):
        self.registry = Registry()

    def serialize(self, obj: JSONSerializable) -> str:
        try:
            data = obj.to_json()
            instance = self.serialize_json_object(data)
            return json.dumps(instance)
        except Exception as e:
            raise ValueError(f"Failed to serialize object: {e}")

    def serialize_json_object(self, data: dict) -> dict:
        id = data.get('type')
        if not id:
            raise ValueError("Missing type ID")
        factory_func = self.registry.get_instance(id, data)
        return factory_func(data).to_json()
