#include <stdlib.h>
#include <string.h>
#include <inttypes.h>
#include <pthread.h>

#define MAX_PACKETS 1024
#define BUFFER_SIZE 1024

typedef struct {
    char source_ip[16];
    char dest_ip[16];
    uint8_t protocol;
    size_t payload_len;
} packet_t;

packet_t* allocate_packets(size_t num_packets, const char* ip_range) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    packet_t* packets = (packet_t*)calloc(num_packets, sizeof(packet_t));
    if (!packets) {
        fprintf(stderr, "Error allocating memory for packets\n");
        return NULL;
    }

    for (size_t i = 0; i < num_packets; i++) {
        char source_ip[16], dest_ip[16];
        int protocol;
        size_t payload_len;

        // Generate random IP addresses and protocol
        sprintf(source_ip, "%s.%d", ip_range, rand() % 256);
        sprintf(dest_ip, "%s.%d", ip_range, rand() % 256);
        protocol = rand() % 256;

        // Initialize packet structure
        packets[i].source_ip[0] = '\0';
        packets[i].dest_ip[0] = '\0';
        strcpy(packets[i].source_ip, source_ip);
        strcpy(packets[i].dest_ip, dest_ip);
        packets[i].protocol = (uint8_t)protocol;
        payload_len = rand() % BUFFER_SIZE;

        // Initialize packet payload
        char* payload = (char*)malloc(payload_len);
        if (!payload) {
            fprintf(stderr, "Error allocating memory for packet payload\n");
            free(packets);
            return NULL;
        }
        memset(payload, '\0', payload_len);

        packets[i].payload_len = payload_len;
        // Validate and fill the rest of the structure
    }

    pthread_mutex_unlock(&mutex);
    return packets;
}

void deallocate_packets(packet_t* packets, size_t num_packets) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_packets; i++) {
        free((char*)packets[i].payload);
    }

    free(packets);

    pthread_mutex_unlock(&mutex);
}
