// Function to initialize a linked list of LTE_RRC_Message_Type structures
void init_linked_list(struct LTE_RRC_Message_Type** head_ref, int num_messages) {
    *head_ref = NULL;

    for (int i = 0; i < num_messages; i++) {
        struct LTE_RRC_Message_Type* current = malloc(sizeof(struct LTE_RRC_Message_Type));
        if (current == NULL) {
            printf("Memory allocation failed. Aborting initialization.\n");
            return;
        }

        // Initialize the message structure
        current->type = NAS_MESSAGE_TYPE_1;  // Replace with actual value
        current->sequence_number = i;
        current->transport_format = i % 2;  // Replace with actual value

        if (*head_ref == NULL) {
            *head_ref = current;
        } else {
            struct LTE_RRC_Message_Type* temp = *head_ref;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = current;
        }
    }
}

// Function to free the linked list
void free_linked_list(struct LTE_RRC_Message_Type** head_ref) {
    struct LTE_RRC_Message_Type* current = *head_ref;
    struct LTE_RRC_Message_Type* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head_ref = NULL;
}

int main() {
    int num_messages = 5; // Replace with actual value
    struct LTE_RRC_Message_Type* head = NULL;

    init_linked_list(&head, num_messages);

    // Use the linked list as needed...

    free_linked_list(&head);

    return 0;
}
