import java.io.*;
import java.security.*;
import java.util.*;

public class PacketProcessor {

    private static final int MAX_PAYLOAD_LENGTH = 1024;
    private boolean validatePackets = true;
    private boolean compressPayloads = false;

    public Map<String, Integer> processPacketBatch(List<Packet> packets) {
        Map<String, Integer> md5Hashes = new HashMap<>();
        List<Integer> discardedPackets = new ArrayList<>();

        try (ExecutorService executor = Executors.newCachedThreadPool()) {
            for (Packet packet : packets) {
                if (validatePackets && !packet.isValid()) {
                    System.out.println("Invalid packet: " + packet);
                    continue;
                }

                if (packet.getPayload().length > MAX_PAYLOAD_LENGTH) {
                    discardedPackets.add(1);
                    continue;
                }

                Future<String> future = executor.submit(() -> {
                    String md5Hash = getMd5Hash(packet);
                    return md5Hash;
                });

                try {
                    String result = future.get();
                    if (result != null) {
                        md5Hashes.put(result, 1);
                    }
                } catch (InterruptedException | ExecutionException e) {
                    System.out.println("Error processing packet: " + e.getMessage());
                }
            }

            executor.shutdown();

            return new AbstractMap.SimpleEntry<>(md5Hashes, discardedPackets.size());
        }
    }

    private String getMd5Hash(Packet packet) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = packet.getPayload().getBytes();
        md.update(bytes);
        byte[] hashBytes = md.digest();
        StringBuilder sb = new StringBuilder();

        for (byte b : hashBytes) {
            String hexString = Integer.toHexString(b & 0xFF);
            if (hexString.length() == 1) {
                sb.append('0');
            }
            sb.append(hexString);
        }

        return sb.toString();
    }
}
