    char status[20];
} Transaction;

// Dynamic memory allocation for an array of transactions
Transaction** manage_memory(int num_transactions) {
    // Allocate memory for the array of transactions
    Transaction** transactions = (Transaction**)malloc(num_transactions * sizeof(Transaction*));

    if (!transactions) {
        return NULL;
    }

    // Initialize each transaction structure
    for (int i = 0; i < num_transactions; i++) {
        transactions[i] = (Transaction*)malloc(sizeof(Transaction));

        // Check for memory allocation failure
        if (!transactions[i]) {
            // Handle memory allocation failure and log the error
            printf("Memory allocation failed. Aborting.\n");
            for (int j = 0; j < i; j++) {
                free(transactions[j]);
            }
            free(transactions);
            return NULL;
        }
    }

    // Log a message indicating successful memory allocation
    printf("Memory allocated successfully for %d transactions.\n", num_transactions);

    return transactions;
}

// Example main program to test the function
int main() {
    int num_transactions = 1000;  // Change this value as needed

    Transaction** transactions = manage_memory(num_transactions);

    if (!transactions) {
        printf("Memory allocation failed. Exiting.\n");
        return -1;
    }

    // Use and free the dynamically allocated memory here
    for (int i = 0; i < num_transactions; i++) {
        free(transactions[i]);
    }
    free(transactions);

    return 0;
}
