#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 10000
#define LOG_FILE "log.txt"

typedef struct {
    int customer_id;
    int product_id;
    double purchase_amount;
    time_t purchase_date;
    char status[16];
} Transaction;

void* manage_transactions(void* arg) {
    FILE* file = fopen(LOG_FILE, "a");
    if (!file) return NULL;

    Transaction* transactions = (Transaction*)malloc(MAX_TRANSACTIONS * sizeof(Transaction));
    int num_transactions = 0;

    while (1) {
        printf("Enter number of transactions (-1 to quit): ");
        int n;
        scanf("%d", &n);
        if (n == -1) break;

        transactions = realloc(transactions, (num_transactions + n) * sizeof(Transaction));
        for (int i = num_transactions; i < num_transactions + n; i++) {
            printf("Enter customer ID: ");
            int customer_id;
            scanf("%d", &customer_id);
            printf("Enter product ID: ");
            int product_id;
            scanf("%d", &product_id);
            printf("Enter purchase amount: ");
            double purchase_amount;
            scanf("%lf", &purchase_amount);
            printf("Enter purchase date (HH:MM:SS): ");
            time_t purchase_date;
            scanf("%lu", &purchase_date);
            printf("Enter status (max 15 characters): ");
            fgets(transactions[i].status, sizeof(transactions[i].status), stdin);

            transactions[i].customer_id = customer_id;
            transactions[i].product_id = product_id;
            transactions[i].purchase_amount = purchase_amount;
            transactions[i].purchase_date = purchase_date;
        }
        num_transactions += n;

        int i;
        for (i = 0; i < num_transactions; i++) {
            fprintf(file, "Transaction %d: customer ID=%d, product ID=%d, amount=%.2f, date=%lu, status='%s'\n",
                    i + 1, transactions[i].customer_id, transactions[i].product_id, transactions[i].purchase_amount,
                    transactions[i].purchase_date, transactions[i].status);
        }

        free(transactions);
        transactions = NULL;
    }
    fclose(file);

    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, manage_transactions, NULL);
    pthread_join(thread, NULL);

    FILE* file = fopen(LOG_FILE, "r");
    if (!file) return 1;

    char line[256];
    int sequence_number = 0;
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%*s %d", &sequence_number) == 1)
            break;
    }

    printf("Sequence number: %d\n", sequence_number);

    return 0;
}
