#include <iostream>
#include <fstream>
#include <cmath>

struct Node {
    int featureSize;
    Node* children[8];
};

Node* createOctree(int featureSize) {
    Node* root = new Node();
    root->featureSize = featureSize;

    for (int i = 0; i < 8; i++) {
        root->children[i] = nullptr;
    }

    return root;
}

void initializeOctree(Node** octree, int featureSize, int numLeafNodes) {
    *octree = createOctree(featureSize);

    // calculate the numeric sequence
    double sequence = (featureSize + 1.0) / sqrt(numLeafNodes);
    std::string seqStr = std::to_string(sequence);
    while (seqStr.length() > 2) {
        seqStr = seqStr.substr(0, seqStr.find('.')) + "00";
    }

    // update the capacity of the octree if required
    int capacity = (int)(pow(2, featureSize) * numLeafNodes);
    if (capacity > 255) {
        std::cout << "Error: File name too long!" << std::endl;
        return;
    }

    // allocate memory for prefix leafs and data arrays
    Node* current = *octree;
    while (current != nullptr) {
        for (int i = 0; i < 8; i++) {
            if (current->children[i] == nullptr) {
                current->children[i] = createOctree(current->featureSize - 1);
            }
            current = current->children[i];
        }
    }
}
