#include <stdlib.h>
#include <string.h>

char* truncate_string(const char* str, int size_limit, int trim) {
    int len = strlen(str);
    if (len <= size_limit && !trim) return strdup(str);

    char* result;
    if ((result = malloc(size_limit + 4)) == NULL) return NULL;

    if (trim && len > size_limit) {
        memcpy(result, str, size_limit);
        result[size_limit] = '\0';
    } else if (!trim && len > size_limit) {
        strncpy(result, str, size_limit - 4);
        strcpy(result + size_limit - 4, "... ");
        result[size_limit + 3] = '\0';
    } else {
        strcpy(result, str);
    }

    return result;
}
