    private readonly object _syncLock = new object();
    private readonly MemoryCache _cache;

    public DataLoader()
    {
        _cache = new MemoryCache();
    }

    public void LoadData(string filePath)
    {
        try
        {
            using (FileStream stream = File.OpenRead(filePath))
            {
                using (GZipStream decompressionStream = new GZipStream(stream, CompressionMode.Decompress))
                {
                    BinaryFormatter formatter = new BinaryFormatter();

                    object deserializedObject;
                    using (MemoryStream memoryStream = new MemoryStream())
                    {
                        decompressionStream.CopyTo(memoryStream);
                        memoryStream.Position = 0;

                        deserializedObject = formatter.Deserialize(memoryStream);
                    }

                    ValidateData(deserializedObject);

                    _cache.Add(filePath, deserializedObject);
                }
            }
        }
        catch (Exception ex)
        {
            LogError($"Decompression error: {ex.Message}");
        }
    }

    private void ValidateData(object data)
    {
        // Implement your validation logic here
        if (!IsValid(data))
        {
            throw new InvalidOperationException("Deserialized data is invalid");
        }
    }

    private void LogError(string message)
    {
        Console.WriteLine(message);
    }

    private bool IsValid(object data)
    {
        // Implement your business rules and constraints here
        return true;
    }
}

public class MemoryCache
{
    private readonly Dictionary<string, object> _cache = new Dictionary<string, object>();

    public void Add(string key, object value)
    {
        lock (_syncLock)
        {
            _cache.Add(key, value);
        }
    }

    public object Get(string key)
    {
        lock (_syncLock)
        {
            return _cache.ContainsKey(key) ? _cache[key] : null;
        }
    }
