#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    char src_ip[16];
    char dst_ip[16];
    int protocol;
    int payload_len;
    time_t timestamp;
    void* metadata;
} packet_t;

void* create_packet(int num_packets, int ip_range_start, int ip_range_end, int payload_size_range_min, int payload_size_range_max, int timestamp_range_start, int timestamp_range_end) {
    void* packets = (void*)malloc(num_packets * sizeof(packet_t));
    if (!packets) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_packets; i++) {
        packet_t* p = &((packet_t*)packets)[i];
        p->src_ip[0] = '\0';
        p->dst_ip[0] = '\0';
        p->protocol = rand() % 2 + 1;
        p->payload_len = rand() % (payload_size_range_max - payload_size_range_min) + payload_size_range_min;
        p->timestamp = (time_t)(rand() % (timestamp_range_end - timestamp_range_start) + timestamp_range_start);
        p->metadata = NULL;

        // Initialize IP addresses
        for (int j = 0; j < 4; j++) {
            sprintf(p->src_ip + j * 4, "%d", rand() % (ip_range_end - ip_range_start) + ip_range_start);
            sprintf(p->dst_ip + j * 4, "%d", rand() % (ip_range_end - ip_range_start) + ip_range_start);
        }
    }

    return packets;
}

int free_packet(void* packets) {
    if (!packets) {
        return 0;
    }

    ((packet_t*)packets)[0].metadata = NULL;

    free(packets);

    return 1;
}

void log_packet(packet_t packet, int packet_num) {
    printf("Packet %d: Source IP - %s, Destination IP - %s, Protocol - %d, Payload Length - %d, Timestamp - %ld, Metadata - NULL\n", packet_num, packet.src_ip, packet.dst_ip, packet.protocol, packet.payload_len, (long int)packet.timestamp);
}

int export_packet(void* packets, int num_packets, const char* file_name) {
    FILE* f = fopen(file_name, "wb");
    if (!f) {
        fprintf(stderr, "Error: Unable to open file.\n");
        return -1;
    }

    fwrite(packets, sizeof(packet_t), num_packets, f);

    fclose(f);
    return 0;
}

int main() {
    int num_packets = 10;
    int ip_range_start = 192; // 192.168.1.1
    int ip_range_end = 193;   // 192.168.2.254
    int payload_size_range_min = 64;
    int payload_size_range_max = 1024;
    int timestamp_range_start = 1643723400;
    int timestamp_range_end = 1643820000;

    void* packets = create_packet(num_packets, ip_range_start, ip_range_end, payload_size_range_min, payload_size_range_max, timestamp_range_start, timestamp_range_end);
    if (!packets) {
        return -1;
    }

    for (int i = 0; i < num_packets; i++) {
        packet_t* p = &((packet_t*)packets)[i];
        log_packet(*p, i);
    }

    export_packet(packets, num_packets, "packet_data.bin");

    free_packet(packets);

    return 0;
}
