    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

Packet* allocate_packets(int num_packets, const char* ip_range, int payload_size_range[2], time_t timestamp_range[2]) {
    Packet* packets = (Packet*)malloc_or_die(num_packets * sizeof(Packet));

    for (int i = 0; i < num_packets; i++) {
        Packet* packet = &packets[i];

        // Initialize random IP addresses
        sprintf(packet->src_ip, "%02x:%02x", rand() % 256, rand() % 256);
        sprintf(packet->dst_ip, "%02x:%02x", rand() % 256, rand() % 256);

        // Initialize payload length and timestamp
        packet->payload_len = (unsigned long)rand() % (payload_size_range[1] - payload_size_range[0]) + payload_size_range[0];
        packet->timestamp = (time_t)rand() % (timestamp_range[1] - timestamp_range[0]) + timestamp_range[0];

        // Validate initialized memory
        if (!packet->src_ip || !packet->dst_ip) {
            free(packets);
            return NULL;
        }
    }

    return packets;
}

int main() {
    int num_packets = 10;
    const char* ip_range = "192.168.";
    int payload_size_range[] = {50, 100};
    time_t timestamp_range[] = {(time_t)1623456789, (time_t)1643456789};

    Packet* packets = allocate_packets(num_packets, ip_range, payload_size_range, timestamp_range);

    // Print packet information
    for (int i = 0; i < num_packets; i++) {
