typedef struct {
    char* username;
    int sessionId;
    time_t lastActivity;
    unsigned int timeout;
    bool active;
} Session;

Session** manageSessions(int numSessions, time_t minTimestamp, time_t maxTimestamp, unsigned int minTimeout, unsigned int maxTimeout) {
    // Allocate memory for sessions
    Session** sessions = (Session**)malloc(numSessions * sizeof(Session*));

    // Initialize each session
    for (int i = 0; i < numSessions; i++) {
        sessions[i] = (Session*)malloc(sizeof(Session));
        sessions[i]->username = malloc(strlen("default_username") + 1);
        strcpy(sessions[i]->username, "default_username");
        sessions[i]->sessionId = i;
        sessions[i]->lastActivity = minTimestamp + (rand() % (maxTimestamp - minTimestamp)) * 1000;
        sessions[i]->timeout = rand() % (maxTimeout - minTimeout) + minTimeout;
        sessions[i]->active = true;
    }

    return sessions;
}

int main() {
    int numSessions = 10;
    time_t minTimestamp = time(NULL);
    time_t maxTimestamp = time(NULL) + (60 * 60 * 24); // 1 day
    unsigned int minTimeout = 300; // 5 minutes
    unsigned int maxTimeout = 3600; // 1 hour

    Session** sessions = manageSessions(numSessions, minTimestamp, maxTimestamp, minTimeout, maxTimeout);

    for (int i = 0; i < numSessions; i++) {
        printf("Session %d: username=%s, lastActivity=%lu, timeout=%u, active=%d\n", sessions[i]->sessionId, sessions[i]->username, sessions[i]->lastActivity, sessions[i]->timeout, sessions[i]->active);
    }

    // Clean up memory
    for (int i = 0; i < numSessions; i++) {
        free(sessions[i]->username);
        free(sessions[i]);
    }
    free(sessions);

    return 0;
}
