        inventories[i]->quantity = threshold;
        inventories[i]->price = minPrice + (double)(rand() / (RAND_MAX));
        inventories[i]->available = true;
    }

    // Restock products below the threshold
    for (int i = 0; i < numProducts; i++) {
        if (inventories[i]->quantity <= threshold) {
            inventories[i]->quantity += 10;
        }
    }

    // Log inventory details
    for (int i = 0; i < numProducts; i++) {
        printf("Product %lld: Name=%s, Quantity=%u, Price=%.2f, Available=%d\n", 
               inventories[i]->id, inventories[i]->name, inventories[i]->quantity, 
               inventories[i]->price, (int)inventories[i]->available);
