#include <arpa/inet.h>
#include "logging.h"

int resolve_and_format_hostname(const char* hostname, int size_limit, char* buffer, int log_level) {
    if (!hostname || size_limit <= 0 || !buffer) {
        return -1;
    }

    struct in_addr addr;
    if (gethostbyname(hostname, (char**)&addr) == NULL) {
        LOG(log_level, "Error: DNS resolution failed for hostname %s", hostname);
        return -1;
    }

    char* ip_str = inet_ntop(AF_INET, &addr, buffer, size_limit);
    if (!ip_str || strlen(ip_str) >= size_limit) {
        *buffer = '\0';
        return NULL;
    }

    strcat(buffer, "/");

    if (strlen(buffer) > size_limit - 1) {
        *buffer = '\0';
        return NULL;
    }

    LOG(log_level, "Resolved hostname %s to IP address %s", hostname, buffer);

    return strlen(buffer);
}
