class RandomValueGenerator {
private:
    std::mt19937 generator;
    int minIntValue = 0;
    int maxIntValue = INT_MAX;
    double minFloatValue = 0.0;
    double maxFloatValue = DBL_MAX;

public:
    RandomValueGenerator() {
        generator.seed(std::time(nullptr));
    }

    void SetSeed(long seed) {
        generator.seed(seed);
    }

    void SetIntegerRange(int minValue, int maxValue) {
        if (minValue > maxValue) {
            std::cerr << "Invalid integer range. Minimum value should not be greater than maximum value." << std::endl;
        } else {
            minIntValue = minValue;
            maxIntValue = maxValue;
        }
    }

    void SetFloatRange(double minValue, double maxValue) {
        if (minValue > maxValue) {
            std::cerr << "Invalid float range. Minimum value should not be greater than maximum value." << std::endl;
        } else {
            minFloatValue = minValue;
            maxFloatValue = maxValue;
        }
    }

    int GenerateRandomInteger() {
        std::uniform_int_distribution<int> distribution(minIntValue, maxIntValue);
        return distribution(generator);
    }

    double GenerateRandomFloat() {
        std::uniform_real_distribution<double> distribution(minFloatValue, maxFloatValue);
        return distribution(generator);
    }

    void ValidateRange(int minValue, int maxValue) {
        if (minValue > maxValue) {
            throw std::invalid_argument("Invalid integer range. Minimum value should not be greater than maximum value.");
        }
    }

    void ValidateRange(double minValue, double maxValue) {
        if (minValue > maxValue) {
            throw std::invalid_argument("Invalid float range. Minimum value should not be greater than maximum value.");
        }
    }

    std::string ToString() const {
        return "Current Range Settings: Int[min=" + std::to_string(minIntValue) + ", max=" + std::to_string(maxIntValue) +
               "], Float[min=" + std::to_string(minFloatValue) + ", max=" + std::to_string(maxFloatValue) + "]";
    }

    static void InsertAfter(std::forward_list<std::string>& list, const std::string& searchFor, const std::string& insertAfterThis) {
        auto it = list.begin();
        for (; it != list.end(); ++it) {
            if (*it == searchFor) {
                list.insert_after(it, insertAfterThis);
                return;
            }
        }
        list.insert_after(list.end(), insertAfterThis);
    }
};

