#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/sha.h>

typedef struct {
    unsigned char *hash;
    size_t len;
} hash_data;

hash_data* calculate_sha256_hash(const char *file_path, size_t max_size) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    hash_data* result = (hash_data*)malloc(sizeof(hash_data));
    if (!result) {
        fclose(file);
        return NULL;
    }

    unsigned char *hash = (unsigned char*)malloc(SHA256_DIGEST_LENGTH);
    if (!hash) {
        free(result);
        fclose(file);
        return NULL;
    }

    int chunk_size = 1024 * 1024; // 1MB chunks
    unsigned char buffer[chunk_size];

    size_t offset = 0;
    while (offset < file_size) {
        size_t bytes_to_read = MIN(chunk_size, file_size - offset);
        fread(buffer, 1, bytes_to_read, file);

        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        for (size_t i = 0; i < bytes_to_read; i++) {
            SHA256_Update(&ctx, buffer + i, 1);
        }
        SHA256_Final(hash, &ctx);
    }

    fclose(file);
    result->hash = hash;
    result->len = SHA256_DIGEST_LENGTH;

    return result;
}

int main() {
    hash_data* hash_data = calculate_sha256_hash("path/to/file", 1024 * 1024); // 1MB size limit

    if (!hash_data) {
        printf("Error calculating hash\n");
        return -1;
    }

    char *output_buffer = (char*)malloc(64);
    if (!output_buffer) {
        free(hash_data->hash);
        free(hash_data);
        return -1;
    }

    int bytes_written = sprintf(output_buffer, "%02x", (unsigned char*)hash_data->hash[0]);
    for (int i = 1; i < hash_data->len; i++) {
        bytes_written += sprintf(output_buffer + bytes_written, ":%02x", (unsigned char*)hash_data->hash[i]);
    }
    output_buffer[bytes_written] = '\0';

    printf("SHA-256 Hash: %s\n", output_buffer);

    free(hash_data->hash);
    free(hash_data);
    free(output_buffer);

    return 0;
}
