EVP_CIPHER_CTX* select_cipher_mode(const char* cipher_name) {
    if (strcmp(cipher_name, "ECB") == 0)
        return EVP_des_ecb();
    else if (strcmp(cipher_name, "EDE") == 0)
        return EVP_des_ede();
    else if (strcmp(cipher_name, "EDE3") == 0)
        return EVP_des_ede3();
    else if (strcmp(cipher_name, "CFB") == 0)
        return EVP_des_cfb64();
    else
        return NULL;
}

int verify_oauth_token(const char* json_string) {
    cJSON *root = cJSON_Parse(json_string);
    if (!root)
        return 0;

    cJSON *access_token = cJSON_GetObjectItem(root, "access_token");
    cJSON *expires_in = cJSON_GetObjectItem(root, "expires_in");
    cJSON *token_type = cJSON_GetObjectItem(root, "token_type");
    cJSON *refresh_token = cJSON_GetObjectItem(root, "refresh_token");

    if (!access_token || !expires_in || !token_type) {
        cJSON_Delete(root);
        return 0;
    }

    if (strcmp(token_type->valuestring, "Bearer") != 0) {
        cJSON_Delete(root);
        return 0;
    }

    int expires = atoi(expires_in->valuestring);
    if (expires <= 0) {
        cJSON_Delete(root);
        return 0;
    }

    if (refresh_token && !cJSON_IsUUID(refresh_token)) {
        cJSON_Delete(root);
        return 0;
    }

    int now = time(NULL);
    int expiration_window = 60; // seconds
    if (now > expires_in->valuedouble + expiration_window) {
        // token expired, generate new one
        cJSON *new_refresh_token = cJSON_CreateUUID();
        cJSON_Delete(refresh_token);
        refresh_token = new_refresh_token;
        // update json object
    }

    cJSON_Delete(root);
    return 1;
}
