    // Initialize array elements
    return arr;
}

int serialize_array(NFAPI_CRC_INDICATION_PDU_T* arr, int n, char** data) {
    int len = 0;
    for(int i=0; i<n; i++) {
        len += sizeof(arr[i].rx_ue_info_tag) + sizeof(arr[i].rnti) + strlen(arr[i].crc_ind_rel8_tag) + sizeof(arr[i].crcflag);
    }
    *data = (char*)malloc(len);
    char* p = *data;
    for(int i=0; i<n; i++) {
        memcpy(p, &arr[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        p += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
    return len;
}

int encrypt_data(char* data, int len, char** encrypted) {
    // Initialize AES context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, NULL, NULL, NULL);
    // Set key and IV
    const unsigned char* key = "your_secret_key";
    const unsigned char* iv = "your_secret_IV";
    EVP_EncryptInit_ex(ctx, &key[0], strlen((char*)key), &iv[0], strlen((char*)iv));
    // Encrypt data
    int encrypted_len;
    *encrypted = (char*)malloc(len + AES_BLOCK_SIZE);
    unsigned char* out = *encrypted;
    EVP_EncryptUpdate(ctx, &out[0], &len, &data[0], len);
    EVP_EncryptFinal_ex(ctx, &out[len], &len);
    encrypted_len += len;
    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    return encrypted_len;
}

int send_data(char* data, int len) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080); // Change port number as needed
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr));
    sendall(sockfd, data, len);
    close(sockfd);
}

