    send_data(encrypted_data, encrypted_len);
    free(encrypted_data);
    free(serialized_data);
    return 0;
}

// Polling mechanism
void poll_server(int sockfd) {
    while (1) {
        // Send request to server
        char* req = "your_request";
        int req_len = strlen(req);
        sendall(sockfd, req, req_len);
        // Receive response from server
        char* resp = malloc(1024);
        int resp_len;
        recvall(sockfd, resp, 1024, &resp_len);
        if (strcmp(resp, "confirmation_message") == 0) {
            break; // Confirmation received, exit polling loop
        }
        sleep(5); // Polling interval
    }
    free(resp);
}

int main() {
