#include <tls.h>

// Define the structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int main() {
    // Initialize variables
    int N = 10; // Array size
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for(int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand();
        array[i].CRCFLAG = rand() % 2;
    }

    // Serialize the array into a byte array
    unsigned char *serialized_array = (unsigned char *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T) + N);
    for(int i = 0; i < N; i++) {
        memcpy(serialized_array + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), &array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    serialized_array[N * sizeof(NFAPI_CRC_INDICATION_PDU_T)] = '\0';

    // Compress the byte array
    unsigned char *compressed_array = (unsigned char *)malloc(strlen(serialized_array) / 2 + 1);
    strcpy(compressed_array, serialized_array);

    // Establish a secure TCP connection with TLS encryption
    int sockfd;
    struct sockaddr_in server_addr;
    socklen_t server_len = sizeof(server_addr);
    if ((sockfd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)) == -1) {
        perror("socket");
        exit(1);
    }
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    if (connect(sockfd, (struct sockaddr *)&server_addr, server_len) == -1) {
        perror("connect");
        exit(1);
    }

    // Send the compressed byte array over the secure connection
    int bytes_sent;
    if ((bytes_sent = send(sockfd, compressed_array, strlen(compressed_array), 0)) < 0) {
        perror("send");
        exit(1);
    }

    // Receive and process the response from the remote server
    char buffer[1024];
    int bytes_received;
    if ((bytes_received = recv(sockfd, buffer, sizeof(buffer), 0)) <= 0) {
        perror("recv");
        exit(1);
    }
    printf("%s\n", buffer);

    // Close the connection and free resources
    close(sockfd);
    free(serialized_array);
    free(compressed_array);
    free(array);

    return 0;
}
