// Function to initialize and populate UserSessionConfig array
int populate_user_session_configs(int num_sessions, int bandwidth_limit) {
    // Initialize UserSessionConfig array with requested size
    UserSessionConfig* user_session_configs = (UserSessionConfig*)malloc(num_sessions * sizeof(UserSessionConfig));

    for (int i = 0; i < num_sessions; i++) {
        // Dynamically generate userId and sessionTimeout
        int userId = rand() % 1000;
        int sessionTimeout = rand() % 60 + 1;

        // Initialize NetworkRequest array with requested size
        NetworkRequest* request_queue = (NetworkRequest*)malloc(5 * sizeof(NetworkRequest));

        for (int j = 0; j < 5; j++) {
            // Dynamically generate requestType, priority, and requestSize
            int requestType = rand() % 2;
            int priority = rand() % 3 + 1;
            int requestSize = rand() % 100 + 1;

            NetworkRequest* network_request = (NetworkRequest*)malloc(sizeof(NetworkRequest));
            network_request->requestType = requestType;
            network_request->priority = priority;
            network_request->requestSize = requestSize;
            request_queue[j] = *network_request;
        }

        // Validate total request size and adjust accordingly
        int total_request_size = 0;
        for (int k = 0; k < 5; k++) {
            total_request_size += request_queue[k].requestSize;
        }

        if (total_request_size > bandwidth_limit) {
            // Adjust request sizes to fit within the bandwidth limit
            for (int l = 0; l < 5; l++) {
                request_queue[l].requestSize *= (bandwidth_limit / total_request_size);
            }
        }

        // Initialize UserSessionConfig structure with userId, sessionTimeout, and NetworkRequest array
        user_session_configs[i].userId = userId;
        user_session_configs[i].sessionTimeout = sessionTimeout;
        user_session_configs[i].requestQueue = request_queue;
    }

    return num_sessions;
}

// Function to validate JSON object for OAuth2 access token response
int verify_oauth_token_response(char* json_string) {
    // Initialize valid fields counter
    int valid_fields_count = 0;

    // Check if JSON string contains required fields
    cJSON* root = cJSON_Parse(json_string);
    if (root != NULL) {
        cJSON* access_token = cJSON_GetObjectItem(root, "access_token");
        cJSON* expires_in = cJSON_GetObjectItem(root, "expires_in");
        cJSON* token_type = cJSON_GetObjectItem(root, "token_type");

        // Check for required fields
        if (cJSON_IsString(access_token) && cJSON_IsNumber(expires_in) && cJSON_IsString(token_type)) {
            valid_fields_count++;

            // Check that token type is 'Bearer'
            if (strcmp(token_type->valuestring, "Bearer") == 0) {
                valid_fields_count++;

                // Check that expires_in field is positive
                if (expires_in->valuedouble > 0.0) {
                    valid_fields_count++;
                }
            }
        }

        cJSON_Delete(root);
    }

    return valid_fields_count >= 4;
}
