    int stockLevel;
    struct {
        struct OrderRequest *requests;
        int requestCount;
    } orderRequests;
} ProductInventory;

// Define the OrderRequest structure
typedef struct {
    struct CustomerOrder *order;
    int orderQuantity;
    time_t deliveryDate;
} OrderRequest;

// Define the CustomerOrder structure
typedef struct {
    int orderQuantity;
    int priority;
    time_t deliveryDate;
} CustomerOrder;

// Function to initialize and populate ProductInventory structures
ProductInventory* initProductInventory(int productId, int stockLevel) {
    ProductInventory *product = (ProductInventory*)malloc(sizeof(ProductInventory));
    product->productId = productId;
    product->stockLevel = stockLevel;
    product->orderRequests.requests = NULL;
    product->orderRequests.requestCount = 0;
    return product;
}

// Function to add an OrderRequest to a ProductInventory
void addOrderRequest(ProductInventory *product, int orderQuantity, time_t deliveryDate) {
    // Dynamically allocate memory for the new OrderRequest
    OrderRequest *request = (OrderRequest*)malloc(sizeof(OrderRequest));
    request->order = NULL;
    request->orderQuantity = orderQuantity;
    request->deliveryDate = deliveryDate;

    // Add the new OrderRequest to the product's list of requests
    if (product->orderRequests.requests == NULL) {
        product->orderRequests.requests = request;
        product->orderRequests.requestCount = 1;
    } else {
        OrderRequest *current = product->orderRequests.requests;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = request;
        product->orderRequests.requestCount++;
    }
}

// Function to update the stock level of a ProductInventory
void updateStockLevel(ProductInventory *product, int newStockLevel) {
    // Check if the new stock level is valid
    if (newStockLevel >= 0) {
        product->stockLevel = newStockLevel;
    } else {
        printf("Invalid stock level: %d\n", newStockLevel);
    }
}

// Function to verify an inventory update response JSON object
int isValidInventoryUpdateResponse(char *jsonString) {
    // Parse the JSON string into a ProductInventory structure
    json_t *root = json_loads(jsonString, JSON_DECODE_ANY, NULL);
    if (root == NULL || !json_is_object(root)) {
        return 0; // Invalid JSON format
    }

    // Check for required fields: productId, stockLevel
    int productId = json_integer_value(json_object_get(root, "productId"));
    int stockLevel = json_integer_value(json_object_get(root, "stockLevel"));

    if (json_object_get(root, "refreshToken") != NULL) {
        char *refreshToken = json_string_value(json_object_get(root, "refreshToken"));
        // Check the refreshToken format
        if (strlen(refreshToken) < 32) {
            return 0; // Invalid refreshToken length
        }
    }

    // Check that stockLevel is a positive integer
    if (stockLevel <= 0) {
        return 0; // Invalid stock level
    }

    json_free(root);
    return 1; // Valid inventory update response
}

int main() {
    // Example usage: create and populate a ProductInventory instance
    ProductInventory *product = initProductInventory(123, 100);
    addOrderRequest(product, 50, time(NULL));
    addOrderRequest(product, 25, time(NULL));
    updateStockLevel(product, 75);

    printf("Product ID: %d\n", product->productId);
    printf("Current Stock Level: %d\n", product->stockLevel);
    printf("Number of Order Requests: %d\n", product->orderRequests.requestCount);

