// Function to serialize the array into a byte array
unsigned char* serialize_array(NFAPI_CRC_INDICATION_PDU_T* arr, int N) {
    unsigned char* serialized_data = (unsigned char*)malloc((N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) + 1);
    if (!serialized_data) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    for (int i = 0; i < N; i++) {
        // Serialize each structure
        serialized_data[i * sizeof(NFAPI_CRC_INDICATION_PDU_T)] = arr[i].RX_UE_INFORMATION_TAG;
        serialized_data[(i * sizeof(NFAPI_CRC_INDICATION_PDU_T)) + 1] = (unsigned char)(arr[i].RNTI >> 8);
        serialized_data[(i * sizeof(NFAPI_CRC_INDICATION_PDU_T)) + 2] = (unsigned char)(arr[i].RNTI & 0xFF);
        serialized_data[(i * sizeof(NFAPI_CRC_INDICATION_PDU_T)) + 3] = arr[i].CRC_INDICATION_REL8_TAG;
        serialized_data[(i * sizeof(NFAPI_CRC_INDICATION_PDU_T)) + 4] = (unsigned char)(arr[i].CRCFLAG >> 8);
        serialized_data[(i * sizeof(NFAPI_CRC_INDICATION_PDU_T)) + 5] = (unsigned char)(arr[i].CRCFLAG & 0xFF);
    }
    return serialized_data;
}

// Function to encrypt the byte array using AES
void encrypt_array(unsigned char* data, int N) {
    // Initialize encryption key and IV
    unsigned char key[16], iv[16];
    // Generate random key and IV
    for (int i = 0; i < 16; i++) {
        key[i] = rand() % 256;
        iv[i] = rand() % 256;
    }
    // Encrypt the data
    AES_KEY enc_key;
    AES_set_encrypt_key(key, sizeof(key), &enc_key);
    for (int i = 0; i < N; i++) {
        unsigned char block[16];
        memcpy(block, data + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), 16);
        unsigned char encrypted_block[16];
        AES_cbc_encrypt(block, encrypted_block, 16, &enc_key, iv, AES_ENCRYPT);
        // Copy the encrypted block to the original array
        memcpy(data + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), encrypted_block, 16);
    }
}

// Function to send the encrypted data to a database server using MySQL protocol
void send_data_to_db(unsigned char* data, int N) {
