        if (mysql_errno(conn) != 0) {
            printf("Error sending data to database: %s\n", mysql_error(conn));
            return;
        }
    }
    // Close the MySQL connection
    mysql_close(conn);
}

// Function to detect and handle duplicate transmissions due to retries
void handle_duplicates(int N, unsigned char* data) {
    // Initialize a list of received data
    unsigned char* received_data = (unsigned char*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!received_data) {
        printf("Memory allocation failed.\n");
        return;
