    while (timeout < 30 && !mysql_affected_rows(conn)) {
        // Poll the database server
        mysql_query(conn, "SELECT * FROM table_name");
        if (mysql_errno(conn) != 0) {
            printf("Error polling database: %s\n", mysql_error(conn));
            return;
        }
        // Check for duplicate transmissions
        for (int i = 0; i < N; i++) {
            if (memcmp(received_data, data + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
                printf("Duplicate transmission detected.\n");
                return;
            }
        }
        timeout++;
    }
}

