        }

        // Monitor the system load and adjust resource usage accordingly
        if (sysctlbyname("kern.filesystem.usespace")) {
            printf("System load is high: adjusting resource usage\n");
            struct_count /= 2;
        } else if (sysctlbyname("kern.cpu.usagetotal")) {
