    LTE_RRC_CONNECTION_RECONFIGURATION_PDU_T* structures = (LTE_RRC_CONNECTION_RECONFIGURATION_PDU_T*)malloc(num_structures * sizeof(LTE_RRC_CONNECTION_RECONFIGURATION_PDU_T));

