        *capacity = (size_t)sqrt(*capacity * 2 + 1);
        NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*list, *capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp) {
