#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000
#define ARCHIVE_THRESHOLD 30 // days

// Structure definition
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    int RNTI;
    CRC_INDICATION_REL8_TAG *crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// List management function
void* list_manager(int num_elements) {
    // Initialize list and semaphore
    NFAPI_CRC_INDICATION_PDU_T **list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * num_elements);
    sem_t *semaphore = sem_open("/my_semaphore", O_CREAT | O_EXCL, 0644, 1);

    // Initialize thread-safe background task
    pthread_t background_task;
    pthread_create(&background_task, NULL, reexport_background_task, (void*)list);

    // Main list management loop
    for (int i = 0; i < num_elements; i++) {
        // Insertion and validation mechanism
        if (insert_element(list, semaphore) == -1) {
            printf("Error inserting element!\n");
            break;
        }
    }

    // Export data to file
    export_to_file(list);

    // Archive old files
    archive_old_files();

    return NULL;
}

// Function to insert an element into the list
int insert_element(NFAPI_CRC_INDICATION_PDU_T **list, sem_t *semaphore) {
    int RNTI = rand() % 1000; // Randomly generated RNTI
    NFAPI_CRC_INDINATION_PDU_T *new_element = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    sem_wait(semaphore);
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        if (!list[i]) {
            list[i] = new_element;
            break;
        } else if (list[i]->RNTI == RNTI) {
            printf("Error: Duplicate RNTI!\n");
            return -1;
        }
    }
    sem_post(semaphore);

    return 0;
}

// Function to re-export the list in the background
void* reexport_background_task(void *args) {
    NFAPI_CRC_INDICATION_PDU_T **list = (NFAPI_CRC_INDICATION_PDU_T **)args;

    while (1) {
        // Check for changes to the list
        if (num_elements_changed(list)) {
            // Re-export data to file
            export_to_file(list);
        }
        sleep(10); // Adjust interval as needed
    }

    return NULL;
}

// Function to export the list to a binary file
void export_to_file(NFAPI_CRC_INDICATION_PDU_T **list) {
    // Serialize data using Protocol Buffers
    google::protobuf::Message* message = serialize_data(list);
    FILE *file = fopen("data.bin", "wb");
    fwrite(message->GetArena()->Data(), message->ByteSize(), 1, file);
    fclose(file);

    return;
}

// Function to archive old files
void archive_old_files() {
    // Retrieve list of exported files
    DIR *dir = opendir("data");
    struct dirent *ent = readdir(dir);
    while (ent != NULL) {
        if (stat(ent->d_name, &buf)) {
            printf("Error: Could not stat file %s\n", ent->d_name);
        } else {
            if (buf.st_mtime < (time() - ARCHIVE_THRESHOLD * 24 * 60 * 60)) {
                // Archive file
                rename(ent->d_name, "archived_data/%s", buf.st_ino);
            }
        }
    }

    return;
}

// Function to serialize data using Protocol Buffers
google::protobuf::Message* serialize_data(NFAPI_CRC_INDICATION_PDU_T **list) {
    // Create a Message object for serialization
    NFAPI_CRC_INDICATION_PDU_T_Protobuf message = new NFAPI_CRC_INDICATION_PDU_T_Protobuf();

    // Serialize list data into the Message object
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        if (list[i]) {
            message.add_elements(list[i]->tag, list[i]->RNTI, list[i]->crc_tag);
        }
    }

    return &message;
}

// Function to check for changes in the list
bool num_elements_changed(NFAPI_CRC_INDICATION_PDU_T **list) {
    int new_num_elements = 0;
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        if (list[i]) {
            new_num_elements++;
        }
    }

    return new_num_elements != old_num_elements;
}

// Function to write logs
void log_events(NFAPI_CRC_INDICATION_PDU_T **list) {
    FILE *log_file = fopen("logs.txt", "a");
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        if (list[i]) {
            fprintf(log_file, "%s: Element inserted at index %d.\n", list[i]->tag, i);
        }
    }

    return;
}

// Function to handle errors during export
void export_error_handler(int error_code) {
    switch (error_code) {
        case 0:
            printf("Error while exporting data!\n");
            break;
        case 1:
            printf("Disk full condition encountered.\n");
            break;
        default:
            printf("Unknown error code %d!\n", error_code);
            break;
    }
}

int main() {
    list_manager(MAX_ELEMENTS);

    return 0;
}
