} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** list = NULL;
int list_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&lock);
    if (list_size >= MAX_LIST_SIZE) {
        // List overflow, split the list
        NFAPI_CRC_INDICATION_PDU_T** new_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(2 * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        memcpy(new_list, list, MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        free(list);
        list = new_list;
    }
    list[list_size] = element;
    list_size++;
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(int index) {
    if (index >= list_size) return NULL;
    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU_T* element = list[index];
    pthread_mutex_unlock(&lock);
    return element;
}

void remove_element(RNTI rnti) {
    for (int i = 0; i < list_size; i++) {
        if (list[i]->rnti == rnti) {
            // Remove the element
            free(list[i]->crc_indication_rel8_tag);
            free(list[i]);
            memmove(&list[i], &list[i+1], (list_size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            list_size--;
        }
    }
}

void re_export() {
    pthread_mutex_lock(&lock);
    if (list_size > 0) {
        // Create a new file with a timestamped name
        time_t now = time(NULL);
        char filename[64];
        strftime(filename, sizeof(filename), "export_%Y-%m-%d-%H-%M-%S.bin", localtime(&now));
        FILE* file = fopen(filename, "wb");
        if (file) {
            // Serialize the list to the file
            for (int i = 0; i < list_size; i++) {
                NFAPI_CRC_INDICATION_PDU_T* element = list[i];
                fwrite(&element->valid_rx_ue_tag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
                fwrite(&element->rnti, sizeof(RNTI), 1, file);
                fwrite(element->crc_indication_rel8_tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
            }
            fclose(file);
        } else {
            // Handle error
        }
    }
    pthread_mutex_unlock(&lock);
}

void log_change(char* message) {
    pthread_mutex_lock(&lock);
    FILE* log_file = fopen("log.txt", "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", ctime(&now), message);
        fclose(log_file);
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    // Initialize the list
    list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Background task to monitor the list for changes and trigger re-export
    pthread_t background_task;
    pthread_create(&background_task, NULL, &re_export, NULL);

    // Implement logging mechanism

    return 0;
}

