#include <rand.h>
#include "global_config.h"

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(int N) {
    if (N <= 0) {
        return NULL; // Error: Invalid number of entries
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < N; i++) {
        pdu_array[i].rx_ue_info_tag = RX_UE_INFORMATION_TAG_DEFAULT;
        pdu_array[i].rnti = rand() % RNTI_MAX_VALUE + 1; // Randomly generate RNTI
        pdu_array[i].crc_indication_rel8_tag.crcflag = (rand() % CRCFLAG_MAX_VALUE) | (rand() % 2); // Randomly set CRC flag, avoiding overflow

        if (i == N - 1) {
            pdu_array[i].crc_indication_rel8_tag.crc16 = crc16_calculate(pdu_array, i);
        } else {
            pdu_array[i].crc_indication_rel8_tag.crc16 = 0;
        }
    }

    return pdu_array;
}

uint16_t crc16_calculate(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int N) {
    uint16_t crc = 0xFFFF;
    for (int i = 0; i < N; i++) {
        crc = crc_update(crc, pdu_array[i].rx_ue_info_tag);
        crc = crc_update(crc, pdu_array[i].rnti);
        crc = crc_update(crc, pdu_array[i].crc_indication_rel8_tag.crcflag);
    }
    return crc;
}

uint16_t crc_update(uint16_t crc, uint16_t data) {
    for (int i = 0; i < 8; i++) {
        if ((data & (1 << i)) != 0) {
            crc = (crc >> 1) ^ 0xA001;
        }
    }
    return crc;
}
