void initialize_and_populate_radio_network_nodes(int num_nodes) {
    // Initialize the cache
    size_t cache_size = 128; // Cache size in bytes
    char* cache = (char*)malloc(cache_size);
    if (!cache) {
        printf("Memory allocation failed for cache.\n");
        return NULL;
    }

    RadioNetworkNode* radio_network_nodes = (RadioNetworkNode*)malloc(num_nodes * sizeof(RadioNetworkNode));
    if (!radio_network_nodes) {
        free(cache);
        return NULL;
    }

    // Initialize node IDs and site IDs
    int current_node_id = 1000;
    for (int i = 0; i < num_nodes; i++) {
        radio_network_nodes[i].node_id = current_node_id++;
        radio_network_nodes[i].site_id = i + 1;

        // Dynamically allocate memory for node_info_list
        size_t info_list_size = sizeof(NodeInfo) * 3;
        NodeInfo* node_info_list = (NodeInfo*)malloc(info_list_size);
        if (!node_info_list) {
            printf("Memory allocation failed for node_info_list.\n");
            return NULL;
        }

        // Initialize node information
        srand(time(NULL));
        for (int j = 0; j < 3; j++) {
            NodeInfo* info = &node_info_list[j];
            info->frequency = ((float)rand() / RAND_MAX) * 90.0 + 870.0;
            info->bandwidth = rand() % 11 + 10;
            info->transmission_power = ((float)rand() / RAND_MAX) * 20.0 + 10.0;
        }

        // Set node_info_list
        radio_network_nodes[i].node_info_list = node_info_list;
    }

    return radio_network_nodes;
}

void free_radio_network_nodes(RadioNetworkNode* nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        NodeInfo* info_list = nodes[i].node_info_list;
        if (!info_list)
            continue;

        // Batch deallocation
        size_t total_info_list_size = sizeof(NodeInfo) * 3;
        void* aligned_info_list = (void*)(((size_t)info_list + total_info_list_size - 1) & ~(total_info_list_size - 1));
        free((char*)aligned_info_list);

        // Free the node itself
        nodes[i].node_info_list = NULL; // Prevent accidental writes to freed memory
        free(&nodes[i]);
    }

    // Batch deallocation for cache
    size_t total_cache_size = cache_size;
    void* aligned_cache = (void*)(((size_t)cache + total_cache_size - 1) & ~(total_cache_size - 1));
    free((char*)aligned_cache);
}

int main() {
    int num_nodes = 1000; // Change this to your desired number of nodes
    RadioNetworkNode* radio_network_nodes = initialize_and_populate_radio_network_nodes(num_nodes);

    if (!radio_network_nodes) {
        printf("Initialization failed.\n");
        return -1;
    }

    // Use the populated array...

    free_radio_network_nodes(radio_network_nodes, num_nodes);

    return 0;
}
