        bool is_unique = true;
        for (int j = 0; j < i; j++) {
            if (!strcmp(pdu->rx_ue_info_tag, list[j]->rx_ue_info_tag) && rnti == list[j]->rnti) {
                is_unique = false;
                break;
            }
        }

        if (!is_unique) {
            printf("Error: Duplicate RX_UE_INFORMATION_TAG and RNTI found.\n");
