    for (int i = 0; i < current_size; i++) {
        if (packet_queue[i]->PacketID == /* new PacketID to be added */) {
            printf("Error: Duplicate PacketID found. Aborting operation.\n");
            return -1;
        }
    }
    return 0;
}

void serialize_packet_queue(LTE_PacketQueueElement** packet_queue, int current_size, FILE* file) {
    fwrite(packet_queue, sizeof(LTE_PacketQueueElement*), 1, file);
    for (int i = 0; i < current_size; i++) {
        fwrite(&packet_queue[i]->PacketID, sizeof(int), 1, file);
        fwrite(packet_queue[i]->SourceAddress, sizeof(char), 16, file);
        fwrite(packet_queue[i]->DestinationAddress, sizeof(char), 16, file);
        fwrite(&packet_queue[i]->PayloadSize, sizeof(size_t), 1, file);
    }
}

void deserialize_packet_queue(LTE_PacketQueueElement** packet_queue, int* current_size, FILE* file) {
    *current_size = 0;
    LTE_PacketQueueElement* temp = (LTE_PacketQueueElement*)malloc(sizeof(LTE_PacketQueueElement));
    while (fread(temp, sizeof(LTE_PacketQueueElement), 1, file)) {
        packet_queue[*current_size] = temp;
        (*current_size)++;
    }
}

void destroy_packet_queue(LTE_PacketQueueElement** packet_queue, int current_size) {
    for (int i = 0; i < current_size; i++) {
        free(packet_queue[i]);
    }
    free(packet_queue);
