#include <openssl/evp.h>
#include <json-c/json.h>

EVP_CIPHER_CTX* choose_cipher(const char* json_string) {
    json_object* obj = json_decode(json_string, 0);
    if (obj == NULL || !json_object_is_type(obj, json_type_object)) return NULL;

    const char* token_type = json_object_get_string(obj, "token_type");
    int expires_in = json_object_get_int(obj, "expires_in");
    const char* access_token = json_object_get_string(obj, "access_token");
    const char* refresh_token = json_object_get_string(obj, "refresh_token", NULL);

    if (!strcmp(token_type, "Bearer")) {
        if (expires_in < 0) return NULL;

        EVP_CIPHER_CTX* cipher = EVP_CIPHER_CTX_new();
        switch (json_object_size(obj)) {
            case 3: // only access_token
                EVP_CIPHER_CTX_set_cipher(cipher, EVP_des_ecb());
                break;
            case 4: // access_token and refresh_token
                if (strcmp(refresh_token, "NULL") == 0) {
                    EVP_CIPHER_CTX_set_cipher(cipher, EVP_des_edec());
                } else {
                    EVP_CIPHER_CTX_set_cipher(cipher, EVP_des_ede3_cfb1());
                }
                break;
            default: // access_token and refresh_token present
                if (strcmp(refresh_token, "NULL") == 0) {
                    EVP_CIPHER_CTX_set_cipher(cipher, EVP_des_edec());
                } else {
                    EVP_CIPHER_CTX_set_cipher(cipher, EVP_des_ede3_cfb1());
                }
        }

        json_object* expires = json_object_get(obj, "expires");
        int expiration_window = 300; // adjust this value as needed

        if (json_object_is_type(expires, json_type_number)) {
            int expires_in = json_object_get_int(expires);
            if (expires_in - expires_in > expiration_window) return NULL;
        }

        EVP_CIPHER_CTX_free(cipher);
    } else return NULL;

    return cipher;
}
