EVP_CIPHER_CTX *get_cipher_mode(const char *cipher_name) {
    EVP_CIPHER_CTX *cipher;

    if (strcmp(cipher_name, "ECB") == 0) 
        cipher = EVP_des_ecb();
    else if (strcmp(cipher_name, "EDE") == 0) 
        cipher = EVP_des_ede();
    else if (strcmp(cipher_name, "EDE3") == 0) 
        cipher = EVP_des_ede3();
    else if (strcmp(cipher_name, "CFB") == 0) 
        cipher = EVP_des_cfb64();
    else
        cipher = NULL;

    return cipher;
}

int verify_oauth2_token(const char *token_response) {
    json_t *root, *access_token, *expires_in, *token_type, *refresh_token;
    time_t expires_at, current_time;
    int64_t expires_in_value;
    bool is_valid = true;

    root = json_loadb(token_response, strlen(token_response), JSON_NONE);
    if (!root) 
        return false;

    access_token = json_object_get(root, "access_token");
    if (!access_token || !json_is_string(access_token)) {
        is_valid = false;
        goto error;
    }

    expires_in = json_object_get(root, "expires_in");
    if (!expires_in || !json_is_integer(expires_in)) {
        is_valid = false;
        goto error;
    }

    token_type = json_object_get(root, "token_type");
    if (!token_type || !json_is_string(token_type) || strcmp(json_string_value(token_type), "Bearer") != 0) {
        is_valid = false;
        goto error;
    }

    refresh_token = json_object_get(root, "refresh_token");
    if (refresh_token && !json_is_string(refresh_token)) {
        is_valid = false;
        goto error;
    }

    expires_in_value = json_integer_value(expires_in);
    current_time = time(NULL);

    if (expires_at - current_time > expires_in_value) 
        return false;

    return true;

error:
    json_decref(root);
    return false;
}
