Bluetooth_Device* initialize_and_populate_bluetooth_devices(int num_devices) {
    if (num_devices > MAX_DEVICES) {
        return NULL;
    }

    Bluetooth_Device* devices = (Bluetooth_Device*)malloc(num_devices * sizeof(Bluetooth_Device));
    if (!devices) {
        return NULL;
    }

    for (int i = 0; i < num_devices; i++) {
        char device_id[18] = "00:1A:2B:3C:4D:5E";
        sprintf(device_id + 9, "%02X", i);

        devices[i].device_id = device_id;
        devices[i].mac_address = device_id;

        int num_services = i == 0 ? 1 : i / 2 + 1; // initialize with 1 service for the first device and then 2 services per subsequent device

        Service* service_list = (Service*)malloc(num_services * sizeof(Service));
        if (!service_list) {
            return NULL;
        }

        devices[i].num_services = num_services;

        for (int j = 0; j < num_services; j++) {
            char name[SERVICE_NAME_MAX_LENGTH];
            sprintf(name, "Bluetooth Audio %d", j);

            ServiceType type = i % 3 == 0 ? BT_AUDIO : i % 3 == 1 ? BT_MANH : BT_DATA;

            int status = (i + j) % 2 == 0; // toggle service status

            service_list[j].name = name;
            service_list[j].type = type;
            service_list[j].status = status;
        }

        devices[i].service_list = service_list;
    }

    return devices;
}

void free_bluetooth_devices(Bluetooth_Device* devices, int num_devices) {
    for (int i = 0; i < num_devices; i++) {
        if (devices[i].service_list) {
            free(devices[i].service_list);
        }
    }

    free(devices);
}
