Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void add_to_list(Node** head, Node* new_node) {
    if (*head == NULL || new_node->data.rnti < (*head)->data.rnti) {
        new_node->next = *head;
        if (*head) (*head)->prev = &new_node->data;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && current->next->data.rnti >= new_node->data.rnti)
            current = current->next;
        new_node->next = current->next;
        if (current->next) current->next->prev = &new_node->data;
        current->next = new_node;
        new_node->prev = current;
    }
}

void delete_from_list(Node** head, Node* node_to_delete) {
    if (!node_to_delete) return;
    if (node_to_delete->prev) node_to_delete->prev->next = node_to_delete->next;
    else *head = node_to_delete->next;

    if (node_to_delete->next) node_to_delete->next->prev = node_to_delete->prev;
    free(node_to_delete);
}

