// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the doubly-linked list node structure
typedef struct _doubly_linked_list_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct _doubly_linked_list_node* next;
    struct _doubly_linked_node prev;
} doubly_linked_list_node;

// Function to create and populate the doubly-linked list
NFAPI_CRC_INDICATION_PDU_T** create_and_populate_doubly_linked_list(int N) {
    // Initialize the head of the list
    doubly_linked_list_node* head = NULL;

    // Initialize a pointer to the last node in the list
    doubly_linked_list_node* tail = NULL;

    // Create and populate the list with N entries
    for (int i = 0; i < N; i++) {
        // Allocate memory for a new node
        doubly_linked_list_node* new_node = malloc(sizeof(doubly_linked_list_node));

        // Initialize the data of the new node
        NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        data->rx_ue_info = generate_random_RX_UE_INFORMATION_TAG();
        data->rnti = generate_random_RNTI();
        data->crc_ind_rel_tag = generate_random_CRC_INDICATION_REL8_TAG();
        data->crcflag = rand() % 2;

        // Set the data pointer of the new node
        new_node->data = data;

        // If this is the first node in the list, set it as both the head and tail
        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            // Otherwise, add the new node to the end of the list
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }

    // Return a pointer to the first element in the list
    return (NFAPI_CRC_INDICATION_PDU_T**)head->data;
}

// Function to add an entry by RNTI
void add_entry_by_rnti(NFAPI_CRC_INDICATION_PDU_T** doubly_linked_list, RNTI rnti) {
    // Find the node with the matching RNTI in the list
    doubly_linked_list_node* current = head;
    while (current != NULL) {
        if (current->data->rnti == rnti) {
            // Add or update the entry as necessary
            break;
        }
        current = current->next;
    }
}

// Function to delete an entry by RNTI
void delete_entry_by_rnti(NFAPI_CRC_INDICATION_PDU_T** doubly_linked_list, RNTI rnti) {
    // Find the node with the matching RNTI in the list
    doubly_linked_list_node* current = head;
    while (current != NULL) {
        if (current->data->rnti == rnti) {
            // Remove the entry from the list
            if (current == tail) {
                tail = current->prev;
                tail->next = NULL;
            } else {
                current->prev->next = current->next;
                if (current == head) {
                    head = current->next;
                } else {
                    current->next->prev = current->prev;
                }
            }
            free(current->data);
            free(current);
            break;
        }
        current = current->next;
    }
}

