void ue_sessions_init(UE_Sessions* sessions, size_t initial_capacity) {
    sessions->capacity = initial_capacity;
    sessions->size = 0;
    sessions->sessions = (UE_Session*)malloc(initial_capacity * sizeof(UE_Session));
}

int ue_sessions_add_session(UE_Sessions* sessions, UE_Session new_session) {
    if (sessions->size == sessions->capacity) {
        sessions->capacity *= 2;
        sessions->sessions = (UE_Session*)realloc(sessions->sessions, sessions->capacity * sizeof(UE_Session));
    }
    sessions->sessions[sessions->size] = new_session;
    sessions->size++;
    return 0;
}

