// Function to trim a string to fit within a size limit
char* trimString(char* str, int sizeLimit, int trimFlag) {
    if (!str || !trimFlag) {
        return str;
    }

    // Calculate the maximum length of the trimmed string
    int maxLength = (sizeLimit > strlen(str)) ? strlen(str) : sizeLimit - 1;

    // Trim the string
    char* trimmedStr = (char*)malloc((maxLength + 2) * sizeof(char));
    strncpy(trimmedStr, str, maxLength);
    trimmedStr[maxLength] = '\0';

    return trimmedStr;
}

int main() {
    manageUESessions();
    char* str = "This is a long string that needs to be truncated.";
    int sizeLimit = 20;
    int trimFlag = 1;
    char* trimmedStr = trimString(str, sizeLimit, trimFlag);
    printf("Trimmed string: %s\n", trimmedStr);

    return 0;
}
