#define MAX_SESSIONS 1000
#define MAX_METADATA_SIZE 1024

typedef struct {
    int id;
    char ip_address[16];
    int qos_level;
    long last_active_timestamp;
    char metadata[MAX_METADATA_SIZE];
} UE_Session;

UE_Session *session_list = NULL;
int num_sessions = 0;
pthread_mutex_t session_list_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_session(int id, const char* ip_address, int qos_level, long timestamp) {
    UE_Session* new_session = (UE_Session*)malloc(sizeof(UE_Session));
    if(new_session == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    strcpy(new_session->ip_address, ip_address);
    new_session->id = id;
    new_session->qos_level = qos_level;
    new_session->last_active_timestamp = timestamp;

    pthread_mutex_lock(&session_list_mutex);
    if(num_sessions < MAX_SESSIONS) {
        session_list[num_sessions] = *new_session;
        num_sessions++;
    } else {
        printf("Session list is full!\n");
    }
    pthread_mutex_unlock(&session_list_mutex);

    // Log the new session
    printf("Added UE Session %d with IP Address %s and QoS level %d\n", id, ip_address, qos_level);
}

void remove_session(int id) {
    int i;
    pthread_mutex_lock(&session_list_mutex);
    for(i = 0; i < num_sessions; i++) {
        if(session_list[i].id == id) {
            free(&session_list[i]);
            for(int j = i; j < num_sessions - 1; j++) {
                session_list[j] = session_list[j+1];
            }
            num_sessions--;
            break;
        }
    }
    pthread_mutex_unlock(&session_list_mutex);

    // Log the removed session
    printf("Removed UE Session %d\n", id);
}

void update_qos(int id, int qos_level) {
    int i;
    pthread_mutex_lock(&session_list_mutex);
    for(i = 0; i < num_sessions; i++) {
        if(session_list[i].id == id) {
            session_list[i].qos_level = qos_level;
            break;
        }
    }
    pthread_mutex_unlock(&session_list_mutex);

    // Log the updated QoS
    printf("Updated UE Session %d's QoS level to %d\n", id, qos_level);
}

void clean_up_inactive_sessions() {
    int i;
    pthread_mutex_lock(&session_list_mutex);
    for(i = 0; i < num_sessions; i++) {
        if((time(NULL) - session_list[i].last_active_timestamp) > 300) {
            free(&session_list[i]);
            for(int j = i; j < num_sessions - 1; j++) {
                session_list[j] = session_list[j+1];
            }
            num_sessions--;
        }
    }
    pthread_mutex_unlock(&session_list_mutex);

    // Log the cleaned up inactive sessions
    printf("Cleaned up %d inactive UE Sessions\n", i);
}

void print_session_list() {
    int i;
    pthread_mutex_lock(&session_list_mutex);
    for(i = 0; i < num_sessions; i++) {
        printf("UE Session ID: %d, IP Address: %s, QoS level: %d, Last Active Timestamp: %ld\n", session_list[i].id, session_list[i].ip_address, session_list[i].qos_level, session_list[i].last_active_timestamp);
    }
    pthread_mutex_unlock(&session_list_mutex);
}
