void manage_ue_sessions() {
    // Initialize the head and tail pointers for the linked list
    UE_Session* head = NULL, *tail = NULL;

    // Allocate memory for the first session
    UE_Session* new_session = (UE_Session*)malloc(sizeof(UE_Session));
    if (new_session == NULL) {
