    new_session->cell_info_list = (int*)malloc(num_cell_info_entries * sizeof(int));
    for (int i = 0; i < num_cell_info_entries; i++) {
        new_session->cell_info_list[i] = i;
    }

    // Add the first session to the linked list
    if (head == NULL) {
        head = tail = new_session;
    } else {
        tail->next = new_session;
        tail = new_session;
    }

    while (1) {
        // Update QoS settings based on real-time network load and traffic patterns
        // ...

        // Iterate through the sessions and update their QoS settings
        UE_Session* current = head;
        while (current != NULL) {
            // Update the QoS settings for the current session
            // ...

            current = current->next;
        }
    }
}
