typedef struct DataProcessingUnit {
    int ProcessingTag;
    char* DataID;
    unsigned char* DataBuffer;
} DataProcessingUnit;

DataProcessingUnit* initiateMultiStageProcess(int N, char* url, struct cfg* config) {
    // Create and populate structures
    DataProcessingUnit* units = (DataProcessingUnit*)malloc(N * sizeof(DataProcessingUnit));
    for (int i = 0; i < N; i++) {
        units[i].ProcessingTag = i;
        units[i].DataID = (char*)malloc(10); // dynamically allocate memory for DataID
        sprintf(units[i].DataID, "Data_%d", i);
        units[i].DataBuffer = (unsigned char*)malloc(config->bufferSize * sizeof(unsigned char));
        for (int j = 0; j < config->bufferSize; j++) {
            units[i].DataBuffer[j] = (unsigned char)(rand() % 256); // populate random data
        }
    }

    // Preprocessing Step
    for (int i = 0; i < N; i++) {
        config->preprocessingFunc(&units[i]);
    }

    // Data Validation
    for (int i = 0; i < N; i++) {
        if (!validateData(&units[i], config)) {
            printf("Error: Invalid data detected.\n");
            return NULL;
        }
    }

    // Data Compression
    for (int i = 0; i < N; i++) {
        unsigned char* compressedBuffer = compressData(units[i].DataBuffer, config->bufferSize, config->compressionAlgorithm);
        if (!compressedBuffer) {
            printf("Error: Compression failed.\n");
            return NULL;
        }
        units[i].DataBuffer = compressedBuffer;
    }

    // File Upload
    CURL *curl;
    CURLcode res;
    FILE* file = fopen("output.txt", "wb"); // write binary data to a local file
    for (int i = 0; i < N; i++) {
        fwrite(units[i].DataBuffer, sizeof(unsigned char), config->bufferSize, file);
    }
    fclose(file);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        for (int i = 0; i < N; i++) {
            FILE* file = fopen("output.txt", "rb");
            fseek(file, 0, SEEK_SET);
            curl_easy_setopt(curl, CURLOPT_READDATA, file);
            res = curl_easy_perform(curl);
            fclose(file);
            if(res != CURLE_OK) {
                printf("curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                return NULL;
            }
        }
    }

    // Return the URL of the uploaded file along with a status code
    CURL *curl2;
    CURLcode res2;
    char errorbuf[CURL_ERROR_SIZE];
    FILE* file = fopen("output.txt", "rb");
    curl_easy_setopt(curl, CURLOPT_URL, url);
    res2 = curl_easy_perform(curl);
    if(res2 != CURLE_OK) {
        printf("curl_easy_perform() failed: %s\n", errorbuf);
        return NULL;
    }

    // Free allocated resources
    for (int i = 0; i < N; i++) {
        free(units[i].DataID);
        free(units[i].DataBuffer);
    }
    free(units);

    return NULL;
}
