#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int status_report;
    int status_confirmation;
    void* pdu_data;
} LTE_RLC_PDU_T;

typedef struct {
    LTE_RLC_PDU_T* pdus;
    int size;
    pthread_mutex_t lock;
    int max_size;
} RLC_Channel;

void* rlc_channel_alloc(void* arg) {
    RLC_Channel* channel = (RLC_Channel*)arg;
    void* pdu_data = malloc(1024);
    LTE_RLC_PDU_T* pdu = malloc(sizeof(LTE_RLC_PDU_T));
    pdu->status_report = 0;
    pdu->status_confirmation = 0;
    pdu->pdu_data = pdu_data;
    channel->pdus = realloc(channel->pdus, (channel->size + 1) * sizeof(LTE_RLC_PDU_T));
    channel->pdus[channel->size] = pdu;
    channel->size++;
    return NULL;
}

void rlc_channel_free(void* arg) {
    RLC_Channel* channel = (RLC_Channel*)arg;
    for(int i=0; i<channel->size; i++) {
        free(channel->pdus[i]->pdu_data);
        free(channel->pdus[i]);
    }
    free(channel->pdus);
}

void rlc_channel_resize(void* arg) {
    RLC_Channel* channel = (RLC_Channel*)arg;
    int new_size = 2 * channel->size;
    void** new_pdus = malloc(new_size * sizeof(LTE_RLC_PDU_T*));
    for(int i=0; i<channel->size; i++) {
        new_pdus[i] = channel->pdus[i];
    }
    free(channel->pdus);
    channel->pdus = new_pdus;
    channel->max_size = new_size;
}

int main() {
    RLC_Channel* channel = malloc(sizeof(RLC_Channel));
    pthread_mutex_init(&channel->lock, NULL);
    channel->size = 0;
    channel->max_size = 10;

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, rlc_channel_alloc, channel);
    pthread_create(&thread2, NULL, rlc_channel_alloc, channel);

    sleep(5); // simulate processing time

    for(int i=0; i<channel->size; i++) {
        printf("%p\n", channel->pdus[i]->pdu_data);
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    rlc_channel_free(channel);
    free(channel);

    return 0;
}
