    while (ueState->rachRequestsCount > 0 && ueState->rachRequests[0].accessType == ACCESS_TYPE_EXPIRED) {
        // Remove the expired request and shift the remaining entries
        for (int i = 0; i < --ueState->rachRequestsCount; i++) {
            ueState->rachRequests[i] = ueState->rachRequests[i + 1];
        }
        // Reallocate memory if necessary to avoid fragmentation
