NFAPI_RX_PDU_T* initialize_and_manage_nfaapi_pdu_collection(int num_pdus) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int total_allocated = 0;

    // Dynamically allocate memory for the collection
    NFAPI_RX_PDU_T** pdu_collection = (NFAPI_RX_PDU_T**)malloc(num_pdus * sizeof(NFAPI_RX_PDU_T*));
    if (!pdu_collection) return NULL; // Handle memory allocation failure

    // Populate each PDU structure with unique tag and RNTI values
    for (int i = 0; i < num_pdus; i++) {
        NFAPI_RX_PDU_T* pdu = (NFAPI_RX_PDU_T*)malloc(sizeof(NFAPI_RX_PDU_T));
        if (!pdu) return NULL; // Handle memory allocation failure

        pdu->tag = i;
        pdu->rnti = i;

        pthread_mutex_lock(&lock);
        total_allocated += sizeof(NFAPI_RX_PDU_T) + pdu->data_pdu_tag.size;
        if (total_allocated > QUOTA_THRESHOLD) {
            free(pdu);
            for (int j = 0; j < i; j++) {
                free(pdu_collection[j]->data_pdu_tag);
                free(pdu_collection[j]);
            }
            free(pdu_collection);
            return NULL; // Resource quota exceeded
        }
        pthread_mutex_unlock(&lock);

        pdu_collection[i] = pdu;
    }

    // Helper function to free allocated memory
    void free_nfaapi_pdu_collection(NFAPI_RX_PDU_T** pdu_collection, int num_pdus) {
        for (int i = 0; i < num_pdus; i++) {
            free(pdu_collection[i]->data_pdu_tag);
            free(pdu_collection[i]);
        }
        free(pdu_collection);
    }

    // Serialize the collection to a file
    void serialize_nfaapi_pdu_collection(NFAPI_RX_PDU_T** pdu_collection, int num_pdus) {
        FILE* file = fopen("pdu_collection.bin", "wb");
        if (!file) return; // Handle serialization failure

        for (int i = 0; i < num_pdus; i++) {
            fwrite(&pdu_collection[i]->tag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
            fwrite(&pdu_collection[i]->rnti, sizeof(RNTI), 1, file);
            fwrite(pdu_collection[i]->data_pdu_tag.payload, pdu_collection[i]->data_pdu_tag.size, 1, file);
        }

        fclose(file);
    }

    // ...

    return pdu_collection;
}

