import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class PacketProcessor {
    private static final int MAX_PAYLOAD_LENGTH = 1024;
    private boolean validatePackets;
    private int maxCompressionLevel;
    private int concurrencyLevel;
    private ForkJoinPool forkJoinPool;

    public PacketProcessor(int maxCompressionLevel, int concurrencyLevel) {
        this.maxCompressionLevel = maxCompressionLevel;
        this.concurrencyLevel = concurrencyLevel;
        this.validatePackets = true; // default is validation enabled
    }

    public List<String> processPackets(List<Packet> packets) throws IOException {
        List<String> hashList = new ArrayList<>();
        int discardedPacketsCount = 0;

        forkJoinPool = new ForkJoinPool(concurrencyLevel);

        for (Packet packet : packets) {
            try {
                if (!validatePacket(packet)) continue;
                String hash = processPacket(packet);
                if (hash != null) hashList.add(hash);
            } catch (IOException e) {
                System.out.println("Error processing packet: " + e.getMessage());
            }
        }

        forkJoinPool.shutdown();
        return hashList;
    }

    private boolean validatePacket(Packet packet) throws IOException {
        if (!validatePackets) return true;

        byte[] payload = packet.getPayload();
        if (payload.length > MAX_PAYLOAD_LENGTH) return false;

        String srcIP = packet.getSourceIP();
        if (!isValidIP(srcIP)) return false;

        int protocol = packet.getProtocol();
        if (protocol < 0 || protocol > 255) return false;

        // other validation checks...
        return true;
    }

    private String processPacket(Packet packet) {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream()) {
            byte[] payload = packet.getPayload();
            if (payload.length <= MAX_PAYLOAD_LENGTH) {
                bos.write(payload);
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] hashBytes = md.digest(bos.toByteArray());
                return bytesToHex(hashBytes);
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    // other methods...
}
