const { Redis } = require('ioredis');
const { v4: uuidv4 } = require('uuid');

function KVStore({
  host = 'localhost',
  port = 6379,
  password,
}) {
  const redisConfig = new Redis({
    host,
    port,
    password,
  });

  return async (reqBody) => {
    try {
      const { operation, key, value } = JSON.parse(reqBody);
      if (!operation || !key || !value) return false;

      switch (operation) {
        case 'GET':
          return redisConfig.get(key);

        case 'PUT':
          if (!uuidv4.validate(key)) return false;
          if (!value.length) return false;
          await redisConfig.set(key, value);
          return true;

        case 'DELETE':
          await redisConfig.del(key);
          return true;

        default:
          return false;
      }
    } catch (err) {
      // Handle errors
      return false;
    }
  };
}

class DistributedKVStore {
  constructor({
    clients = [],
  }) {
    this.clients = clients.map((client) => new KVStore(client));
  }

  async handleRequest(reqBody) {
    const client = this.clients[Math.floor(Math.random() * this.clients.length)];
    return await client(reqBody);
  }
}

class DataCollector {
  constructor({
    stream,
    array,
  }) {
    this.stream = stream;
    this.array = array;
    this.paused = false;

    this.collectData = async () => {
      if (this.paused) return;
      for await (const data of this.stream) {
        this.array.push(data);
      }
    };

    this.pause = () => {
      this.paused = true;
    };

    this.resume = () => {
      this.paused = false;
      this.collectData();
    };
  }
}

// Example usage
const distributedKVStore = new DistributedKVStore({
  clients: [
    { host: 'localhost', port: 6379, password: 'password1' },
    { host: 'localhost', port: 6380, password: 'password2' },
  ],
});

const dataCollector = new DataCollector({
  stream: [1, 2, 3, 4, 5].entries(),
  array: [],
});

dataCollector.pause();
// Resume data collection later
dataCollector.resume();

async function main() {
  const reqBody = JSON.stringify({ operation: 'PUT', key: 'uuid-key', value: 'some-value' });
  const response = await distributedKVStore.handleRequest(reqBody);
  console.log(response);
}

main();
