// List of structures, implemented as a linked list
struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node* next;
};
typedef struct Node* NodeList;

void* createNode(void* data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if(newNode == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    newNode->data = (NFAPI_CRC_INDICATION_PDU_T*)data;
    newNode->next = NULL;
    return newNode;
}

int initList(NodeList* list, int maxsize) {
    if(maxsize < 0 || maxsize > MAX_LIST_SIZE) {
        printf("Invalid maximum size\n");
        return -1;
    }
    *list = (NodeList)calloc(1,sizeof(struct Node));
    if(*list == NULL) {
        printf("Memory allocation failed\n");
        return -2;
    }
    (*list)->next = NULL;
    return 0;
}

int addNode(NodeList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    struct Node* newNode = createNode(data);
    if(newNode == NULL)
        return -1;

    pthread_mutex_lock(&lock); // Lock for thread safety
    struct Node* current = *list;
    while(current->next != NULL) {
        current = current->next;
    }
    current->next = newNode;
    pthread_mutex_unlock(&lock);
    return 0;
}

int removeNode(NodeList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&lock); // Lock for thread safety
    struct Node* current = *list;
    struct Node* previous = NULL;
    while(current != NULL) {
        if(current->data == data) {
            if(previous == NULL)
                (*list) = current->next;
            else
                previous->next = current->next;
            free(current);
            pthread_mutex_unlock(&lock);
            return 0;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return -1; // Data not found in the list
}

int querySize(NodeList* list) {
    int size = 0;
    struct Node* current = *list;
    while(current != NULL) {
        size++;
        current = current->next;
    }
    return size;
}
