// Function to manage NFV instances and Bluetooth devices
void* cloud_management_function() {
    // Initialize sample data for NFV instances
    NFV_Instance* nfv_instances = (NFV_Instance*)malloc(sizeof(NFV_Instance) * 10);
    for (int i = 0; i < 10; i++) {
        nfv_instances[i].instance_id = i;
        nfv_instances[i].ip_address = (char*)malloc(20);
        strcpy(nfv_instances[i].ip_address, "192.168.1.");
        itoa(i, (char*)nfv_instances[i].ip_address + strlen("192.168.1."), 10);
        nfv_instances[i].cpu_utilization = i % 2 ? 0.5 : 0.8;
        nfv_instances[i].memory_utilization = i % 3 ? 0.7 : 0.9;
        nfv_instances[i].vnic_config = (char*)malloc(20);
        sprintf(nfv_instances[i].vnic_config, "VNIC-%d", i);
        nfv_instances[i].health_status = i % 4 ? NFV_Healthy : NFV_Unhealthy;
    }

    // Initialize sample data for Bluetooth devices
    Bluetooth_Device* bluetooth_devices = (Bluetooth_Device*)malloc(sizeof(Bluetooth_Device) * 5);
    for (int i = 0; i < 5; i++) {
        bluetooth_devices[i].device_id = i;
        bluetooth_devices[i].mac_address = (char*)malloc(20);
        sprintf(bluetooth_devices[i].mac_address, "00:11:%02X:%02X", i % 256, (i + 1) % 256);
        bluetooth_devices[i].service_count = 2;
        bluetooth_devices[i].device_service_list = (char**)malloc(sizeof(char*) * 2);
        for (int j = 0; j < 2; j++) {
            bluetooth_devices[i].device_service_list[j] = (char*)malloc(20);
            sprintf(bluetooth_devices[i].device_service_list[j], "Service-%d", i * 2 + j);
        }
    }

    // Encrypt sensitive information in NFV instance metadata
    for (int i = 0; i < 10; i++) {
        nfv_instances[i].ip_address = encrypt_string(nfv_instances[i].ip_address, strlen(nfv_instances[i].ip_address));
    }

    // Scan for nearby Bluetooth devices and update device service list
    for (int i = 0; i < 5; i++) {
        bluetooth_devices[i].service_count += scan_for_services(bluetooth_devices[i].mac_address);
        for (int j = 0; j < bluetooth_devices[i].service_count; j++) {
            free(bluetooth_devices[i].device_service_list[j]);
        }
        bluetooth_devices[i].device_service_list = (char**)realloc(bluetooth_devices[i].device_service_list, sizeof(char*) * bluetooth_devices[i].service_count);
    }

    // Deallocate memory when done
    for (int i = 0; i < 10; i++) {
        free(nfv_instances[i].ip_address);
        free(nfv_instances[i].vnic_config);
    }
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < bluetooth_devices[i].service_count; j++) {
            free(bluetooth_devices[i].device_service_list[j]);
        }
        free(bluetooth_devices[i].mac_address);
        free(bluetooth_devices[i].device_service_list);
    }
    free(nfv_instances);
    free(bluetooth_devices);

    return NULL;
}

// Helper function to deallocate all allocated memory
void deallocate_memory(void* ptr) {
    if (ptr != NULL) {
        // Deallocate NFV instances
        NFV_Instance* nfv_instances = (NFV_Instance*)ptr;
        for (int i = 0; i < 10; i++) {
            free(nfv_instances[i].ip_address);
            free(nfv_instances[i].vnic_config);
        }
        free(nfv_instances);

        // Deallocate Bluetooth devices
        Bluetooth_Device* bluetooth_devices = (Bluetooth_Device*)malloc(sizeof(Bluetooth_Device) * 5);
        for (int i = 0; i < 5; i++) {
            for (int j = 0; j < bluetooth_devices[i].service_count; j++) {
                free(bluetooth_devices[i].device_service_list[j]);
            }
            free(bluetooth_devices[i].mac_address);
            free(bluetooth_devices[i].device_service_list);
        }
    }
}

// Function to scan for nearby Bluetooth devices and update device service list
int scan_for_services(char* mac_address) {
    // Simulate scanning for nearby devices
    int services_discovered = 0;
    for (int i = 0; i < 5; i++) {
        if (detect_service(mac_address, i)) {
            services_discovered++;
        }
    }
    return services_discovered;
}

// Function to detect a service using the given MAC address and service ID
int detect_service(char* mac_address, int service_id) {
    // Simulate detecting a service
    printf("Detecting service %d for device %s...\n", service_id, mac_address);
    sleep(1);  // Simulate delay
    return 1;  // Indicate service detected
}

// Function to encrypt sensitive information in NFV instance metadata
char* encrypt_string(char* str, int length) {
    // Simulate encryption using a simple XOR operation with a secret key
    char* encrypted = (char*)malloc(length + 1);
    for (int i = 0; i < length; i++) {
        encrypted[i] = str[i] ^ 0x12;  // Simple XOR operation with a secret key
    }
    encrypted[length] = '\0';
    return encrypted;
}
