        if (!(nodes[i].node_info_list = (char*)malloc(list_size))) {
            perror("Memory allocation failed");
            free_indications();
            return;
        }

        nodes[i].list_size = list_size;
    }

    // Cache node info lists to optimize performance
    pthread_mutex_lock(&indications_mutex);
    for (int i = 0; i < num_nodes; i++) {
