        // Cache frequency, bandwidth, and transmission_power values
        for (int j = 0; j < CACHE_SIZE; j++) {
            cache_index[j] = i % 3 + 1; // Assuming unique values
        }
    }
    pthread_mutex_unlock(&indications_mutex);
}

void free_nfaapi_crc_indications() {
    pthread_mutex_lock(&indications_mutex);

    if (indications) {
        for (int i = 0; i < num_indications; i++) {
            free(indications[i].node_info_list); // Free node_info_list
        }
        free(indications); // Deallocate memory for indications
    }

    pthread_mutex_unlock(&indications_mutex);
}

void free_radio_network_nodes() {
    pthread_mutex_lock(&nodes_mutex);

    if (nodes) {
        for (int i = 0; i < num_nodes; i++) {
            free(nodes[i].node_info_list); // Free node_info_list
        }
        free(nodes); // Deallocate memory for nodes
    }

    pthread_mutex_unlock(&nodes_mutex);
}
