#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum { INFO, WARN, ERROR } LogLevel;
typedef struct {
    unsigned int id;
    time_t timestamp;
    LogLevel level;
    char* message;
    void* stack_trace;
    int config_flag;
} LogEntry;

LogEntry* create_log_entries(int num_entries, int start_time, int end_time, int severity_min, int severity_max);
void log_entry_free(LogEntry* entry);

int main() {
    int num_entries = 10;
    int start_time = time(NULL) - 3600;
    int end_time = time(NULL);
    int severity_min = 1;
    int severity_max = 2;

    LogEntry* log_entries = create_log_entries(num_entries, start_time, end_time, severity_min, severity_max);

    // Use the log entries
    for (int i = 0; i < num_entries; i++) {
        printf("Log Entry %d: \n", i);
        printf("ID: %u\n", log_entries[i].id);
        printf("Timestamp: %ld\n", log_entries[i].timestamp);
        printf("Level: %s\n", log_level_to_string(log_entries[i].level));
        printf("Message: %s\n", log_entries[i].message);
        if (log_entries[i].stack_trace) {
            printf("Stack Trace: ");
            print_stack_trace(log_entries[i].stack_trace);
        }
    }

    for (int i = 0; i < num_entries; i++) {
        log_entry_free(&log_entries[i]);
    }

    free(log_entries);

    return 0;
}

LogEntry* create_log_entries(int num_entries, int start_time, int end_time, int severity_min, int severity_max) {
    LogEntry* entries = (LogEntry*)malloc(num_entries * sizeof(LogEntry));

    if (!entries) {
        printf("Failed to allocate memory for log entries.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        LogEntry* entry = &entries[i];
        entry->id = rand();
        entry->timestamp = start_time + rand() % (end_time - start_time);
        entry->level = (LogLevel)rand() % (severity_max - severity_min + 1) + severity_min;
        char message[256];
        sprintf(message, "Log Message %d", i);
        entry->message = malloc(strlen(message) + 1);
        strcpy(entry->message, message);

        if (!entry->message) {
            printf("Failed to allocate memory for log message.\n");
            free_log_entries(entries, i);
            return NULL;
        }

        entry->stack_trace = malloc(256);
        sprintf(entry->stack_trace, "Stack Trace: %d", i);

        if (!entry->stack_trace) {
            printf("Failed to allocate memory for stack trace.\n");
            free_log_entries(entries, i);
            return NULL;
        }
    }

    // Validate log entries
    for (int i = 0; i < num_entries; i++) {
        LogEntry* entry = &entries[i];
        if (!validate_log_entry(entry)) {
            printf("Invalid log entry: ID %u, Timestamp %ld\n", entry->id, entry->timestamp);
            free_log_entries(entries, i);
            return NULL;
        }
    }

    return entries;
}

void log_entry_free(LogEntry* entry) {
    free(entry->message);
    free(entry->stack_trace);
}

int validate_log_entry(LogEntry* entry) {
    if (entry->timestamp < start_time || entry->timestamp > end_time) {
        return 0; // Invalid timestamp
    }

    if (strlen(entry->message) > 255) {
        return 0; // Message too long
    }

    if (!strcmp(entry->stack_trace, "Stack Trace: ") && strlen(entry->stack_trace) < 10) {
        return 0; // Stack trace not properly formatted
    }

    return 1;
}

int main(int argc, char const *argv[]) {
    // Load logging library
    extern void log(char const*, int);
    log("Log initialized", 1);

    // Process log entries asynchronously
    for (int i = 0; i < num_entries; i++) {
        LogEntry* entry = &entries[i];
        if (entry->config_flag) {
            log(entry->message, 2);
        }
    }

    // Free logging resources
    log("Log terminated", -1);

    return 0;
}

void change_filename_extension(char *filename, int consonant_frequency) {
    char* new_filename = malloc(strlen(filename) + 5);
    sprintf(new_filename, "%s_%d.txt", filename, consonant_frequency);

    if (!new_filename) {
        printf("Failed to allocate memory for new filename.\n");
        return;
    }

    // Check filename constraints
    if (strlen(new_filename) > 255 || contains_invalid_chars(new_filename)) {
        printf("Invalid filename: %s\n", new_filename);
        free(new_filename);
        return;
    }

    // Update the original filename with the new one
    strcpy(filename, new_filename);

    free(new_filename);
}

int contains_invalid_chars(char *filename) {
    int i = 0;
    while (filename[i]) {
        if (!isalnum(filename[i])) {
            return 1; // Contains invalid character
        }
        i++;
    }

    return 0; // Does not contain invalid characters
}
