            // Handle invalid topic filter
        }
    }

    return subscriptions;
}

void free_mqtt_subscriptions(MQTT_Subscription** subscriptions, int num_subscriptions) {
    for(int i=0; i<=num_subscriptions; i++) {
        if(subscriptions[i]->client_id) free(subscriptions[i]->client_id);
        if(subscriptions[i]->topic_filter) free(subscriptions[i]->topic_filter);
        free(subscriptions[i]);
    }
    free(subscriptions);
}

// Add new subscription
void add_subscription(MQTT_Subscription** subscriptions, int num_subscriptions, int QoS) {
    MQTT_Subscription* new_subscription = (MQTT_Subscription*)malloc(sizeof(MQTT_Subscription));

    // Validate client ID for uniqueness
    for(int i=0; i<=num_subscriptions; i++) {
        if(strcmp(subscriptions[i]->client_id, "client_1") == 0) return;
    }

    char client_id[10];
    sprintf(client_id, "client_%d", num_subscriptions+1);
    new_subscription->client_id = (char*)malloc(strlen(client_id)+1);
    strcpy(new_subscription->client_id, client_id);

    // Example topic filter
    char* topic_filter = malloc(MAX_TOPIC_FILTER_LENGTH + 1);
    sprintf(topic_filter, "sensor/%s", QoS ? "device/+/stats" : "topic");
    new_subscription->topic_filter = topic_filter;
    new_subscription->QoS = QoS;
    new_subscription->message_handler = NULL; // placeholder

    subscriptions[num_subscriptions] = new_subscription;
}

// Retrieve subscription by index
MQTT_Subscription* get_subscription(MQTT_Subscription** subscriptions, int num_subscriptions, int index) {
    if(index < 0 || index > num_subscriptions) return NULL;
    return subscriptions[index];
}

// Remove subscription by client ID
void remove_subscription(MQTT_Subscription** subscriptions, int num_subscriptions, char* client_id) {
    for(int i=0; i<=num_subscriptions; i++) {
        if(strncmp(subscriptions[i]->client_id, client_id, strlen(client_id)) == 0) {
            free(subscriptions[i]->client_id);
            free(subscriptions[i]->topic_filter);
            free(subscriptions[i]);
            memmove(&subscriptions[i], &subscriptions[i+1], (num_subscriptions - i)*sizeof(MQTT_Subscription*));
            num_subscriptions--;
            return;
        }
    }
}

// Export subscriptions to JSON file
void export_mqtt_subscriptions_to_json_file(MQTT_Subscription** subscriptions, int num_subscriptions) {
    FILE* file = fopen("subscriptions.json", "w");

    fprintf(file, "[\n");
    for(int i=0; i<num_subscriptions; i++) {
        fprintf(file, "{\"client_id\":\"%s\",\"topic_filter\":\"%s\",\"QoS\":%d},\n", 
                subscriptions[i]->client_id, subscriptions[i]->topic_filter, subscriptions[i]->QoS);
    }

    fprintf(file, "]"); // Close JSON array
    fclose(file);
}

int main() {
    int num_subscriptions = 10; // Initialize with some number of subscriptions

    MQTT_Subscription** subscriptions = initialize_and_manage_mqtt_subscriptions(num_subscriptions);

    // Example usage: Add new subscription
    add_subscription(subscriptions, num_subscriptions, 1);

    // Example usage: Retrieve subscription by index
    MQTT_Subscription* retrieved_subscription = get_subscription(subscriptions, num_subscriptions, 2);

    // Example usage: Remove subscription by client ID
    remove_subscription(subscriptions, num_subscriptions, "client_3");

    // Example usage: Export subscriptions to JSON file
    export_mqtt_subscriptions_to_json_file(subscriptions, num_subscriptions);

    free_mqtt_subscriptions(subscriptions, num_subscriptions);

    return 0;
}

