function countBibleBooks(text) {
    const oldTestamentBooksRegex = /Gen|Exo|Lev|Num|Deu|Jos|Jdg|1Sam|2Sam|1Kgs|2Kgs|Ezra|Neh|Est|Job|Psa|Mic|Hos|Amo|Oba|Jon|Mic|Zep|Hag|Mal/;
    const punctuationRegex = /[^a-zA-Z]/g;
    const bookNames = {};

    text.replace(punctuationRegex, '').toLowerCase().split(/[\s.]+/)
        .forEach(word => {
            if (oldTestamentBooksRegex.test(word)) {
                if (!bookNames[word]) {
                    bookNames[word] = 0;
                }
                bookNames[word]++;
            }
        });

    return bookNames;
}']

