```python
import numpy as np

def analyzeNetworkTraffic(trafficData):
    # Initialize statistical variables
    mean = 0
    std_dev = 0

    # Calculate mean and standard deviation of traffic data
    mean = np.mean(trafficData)
    std_dev = np.std(trafficData)

    # Initialize anomaly detection report
    report = {}

    # Detect unusual bursts or deviations from expected patterns
    for i in range(len(trafficData)):
        if abs(trafficData[i] - mean) > 2 * std_dev:
            # Report potential issue: unusual burst or deviation
            report["anomaly_type"] = "unusual_burst"
            report["time_range"] = f"{i}-{i+1}"
            report["confidence_score"] = 0.8

    return report
