    }

    // Deallocate memory
    for(int i=0; i<size; i++) {
        free(records[i]->string);
        free(records[i]);
    }
    free(strings);
    free(keys);
    free(timestamps);
    free(offsets);
    free(values);

}

int main() {
    int size = 5;
    int key_range = 100;
    int timestamp_range = 60;

