Record* generateRecords(int size, int range, int seedSize, const char** seeds) {
    srand(seed);
    Record* records = (Record*)malloc(size * sizeof(Record));

    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i].offset = rand() % range;
        records[i].val1 = rand() % range;
        records[i].val2 = rand() % range;

        int hash = 0;
        const char *seed = seeds[rand() % seedSize];
        for (int j = 0; j < strlen(seed); j++) {
            hash += (int)seed[j] + (j << 5);
        }
        records[i].str = malloc((strlen("Record_") + itoa(hash, NULL, 16)) + 1);
        strcpy(records[i].str, "Record_");
        strcat(strcat(records[i].str, itoa(hash, NULL, 16)), "\0");

        records[i].prob = (double)rand() / RAND_MAX;
    }

    int* keys = (int*)malloc(size * sizeof(int));
    int* timestamps = (int*)malloc(size * sizeof(int));
    int* values = (int*)malloc(size * sizeof(int));
    char** strings = (char**)malloc(size * sizeof(char*));

    for (int i = 0; i < size; i++) {
        keys[i] = rand() % range;
        timestamps[i] = rand() % range;
        values[i] = rand() % range;

        strings[i] = malloc((strlen(records[i].str) + 1));
        strcpy(strings[i], records[i].str);
    }

    free(records->str);

    return records;
}
