#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int timestamp;
    int value;
} record;

record** manage_memory(int offset_size, int key_size, int record_count) {
    record** records = NULL;
    long* offsets = NULL;
    int* keys = NULL;

    // Handle memory allocation for each array
    records = (record**)malloc(record_count * sizeof(record*));
    if (!records) {
        printf("Memory allocation failed: Record pointer\n");
        return NULL;
    }

    offsets = (long*)malloc(offset_size * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed: Offset array\n");
        free(records);
        records = NULL;
        return NULL;
    }

    keys = (int*)malloc(key_size * sizeof(int));
    if (!keys) {
        printf("Memory allocation failed: Key array\n");
        free(offsets);
        offsets = NULL;
        free(records);
        records = NULL;
        return NULL;
    }

    // Initialize memory for each record
    for (int i = 0; i < record_count; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            printf("Memory allocation failed: Record %d\n", i);
            free(offsets);
            offsets = NULL;
            free(keys);
            keys = NULL;
            for (int j = 0; j < i; j++) {
                free(records[j]);
                records[j] = NULL;
            }
            return NULL;
        }

        // Randomly initialize 'long' and 'int' fields
        records[i]->offset = (long)rand();
        records[i]->timestamp = rand() % 1000;
        records[i]->value = rand() % 10;

        // Validate memory initialization
        if (!records[i]) {
            printf("Memory allocation failed: Record %d\n", i);
            free(offsets);
            offsets = NULL;
            free(keys);
            keys = NULL;
            for (int j = 0; j < i; j++) {
                free(records[j]);
                records[j] = NULL;
            }
            return NULL;
        }
    }

    // Deallocate unnecessary memory
    if (keys) {
        free(keys);
        keys = NULL;
    }

    if (offsets) {
        free(offsets);
        offsets = NULL;
    }

    // Return the initialized records
    return records;
}
