} record_t;

void* allocate_arrays(size_t initial_size) {
    void *ptr = malloc(initial_size);

    if (!ptr) {
        return NULL; // Handle memory allocation failure
    }

    return ptr;
}

void initialize_arrays(void *ptr, size_t initial_size) {
    record_t *records = (record_t*) ptr;

    for (size_t i = 0; i < initial_size; i++) {
        records[i].value = rand();
        records[i].timestamp = rand();
        records[i].key = rand();
    }
}

void resize_arrays(void *ptr, size_t new_size) {
    record_t *records = (record_t*) ptr;

    record_t *new_records = realloc(records, new_size);

    if (!new_records) {
        free(ptr); // Handle memory allocation failure
        return; 
    }

    records = new_records;
}

void deallocate_arrays(void *ptr, size_t initial_size) {
    record_t *records = (record_t*) ptr;

    free(records);
}
