#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    double value;
    char* id;
    float fvalue;
} entry_t;

void manage_memory(int initial_size, int min_size, int max_size) {
    // Initialize arrays with initial size
    double* doubles = (double*)malloc(initial_size * sizeof(double));
    char** strings = (char**)malloc(initial_size * sizeof(char*));
    entry_t* entries = (entry_t*)malloc(initial_size * sizeof(entry_t));

    // Initialize random value range for float fields
    int min_float = 0;
    int max_float = 100;

    // Dynamic resizing logic
    int current_size = initial_size;
    int resize_threshold = current_size / 2;

    while (1) {
        // Resize arrays when threshold is reached
        if (current_size >= max_size) {
            printf("Array full! Resizing...\n");
            current_size *= 2; // Double the size
        } else if (current_size < min_size && current_size * 2 <= max_size) {
            printf("Array too small! Resizing...\n");
            current_size *= 2; // Double the size
        }

        // Reallocate memory for arrays
        doubles = (double*)realloc(doubles, current_size * sizeof(double));
        strings = (char**)realloc(strings, current_size * sizeof(char*));
        entries = (entry_t*)realloc(entries, current_size * sizeof(entry_t));

        // Initialize new elements with random values
        for (int i = initial_size; i < current_size; i++) {
            double value = rand() / (double)RAND_MAX * (max_float - min_float) + min_float;
            char* string = malloc(10); // Arbitrarily allocate 10 bytes for the string
            sprintf(string, "Entry %d", i);
            entries[i].value = value;
            entries[i].id = string;
            entries[i].fvalue = (float)value;

            strings[i] = string; // Store new string in array
        }

        printf("Memory managed! Current size: %d\n", current_size);
    }
}
