#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <md5.h>

typedef struct {
    long offset;
    int timestamp;
    int value;
    char* string;
} record_t;

record_t** manage_memory(long array_size, int key_range) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(array_size * sizeof(long));
    int* keys = (int*)malloc(array_size * sizeof(int));
    record_t** records = (record_t**)malloc(array_size * sizeof(record_t*));
    char** identifiers = (char**)malloc(array_size * sizeof(char*));
    bool* flags = (bool*)malloc(array_size * sizeof(bool));

    // Initialize arrays
    for(long i = 0; i < array_size; i++) {
        offsets[i] = rand() % key_range;
        keys[i] = rand() % key_range;
        records[i] = (record_t*)malloc(sizeof(record_t));
        identifiers[i] = (char*)malloc(16 * sizeof(char));
        flags[i] = false;

        // Initialize record structure
        records[i]->offset = offsets[i];
        records[i]->timestamp = rand() % key_range;
        records[i]->value = rand() % key_range;
        records[i]->string = identifiers[i];

        // Initialize identifier string
        sprintf(identifiers[i], "record_%ld", i);
    }

    // Free memory if an error occurs during initialization
    if (offsets == NULL || keys == NULL || records == NULL || identifiers == NULL) {
        free(offsets);
        free(keys);
        for(long i = 0; i < array_size; i++) {
            free(records[i]);
            free(identifiers[i]);
        }
        free(records);
        free(identifiers);
        return NULL;
    }

    // Return the managed memory
    return records;
}

void deallocate_memory(record_t** records, long array_size) {
    for(long i = 0; i < array_size; i++) {
        if (records[i]->string != NULL) {
            free(records[i]->string);
        }
        free(records[i]);
    }

    // Free memory for arrays
    free((char*)records);
}

MD5Val compute_md5_hash(const char* str) {
    MD5_CTX ctx;
    MD5_Init(&ctx);
    const unsigned char* ptr = (const unsigned char*)str;
    while (*ptr != '\0') {
        MD5_Update(&ctx, ptr, 1);
        ptr++;
    }
    MD5_Final(&ctx);

    return MD5_GetDigest(&ctx);
}

int main() {
    // Example usage
    record_t** records = manage_memory(10, 100);
    if (records == NULL) {
        printf("Error allocating memory\n");
    } else {
        // Perform operations on managed memory
        for(long i = 0; i < 10; i++) {
            printf("Record %ld: Offset=%ld, Key=%d, Timestamp=%d, Value=%d, String=%s\n",
                   i, records[i]->offset, records[i]->key, records[i]->timestamp, records[i]->value,
                   records[i]->string);
        }

        // Deallocate managed memory
        deallocate_memory(records, 10);

        // Compute MD5 hash for a string
        const char* str = "Hello, World!";
        MD5Val hash = compute_md5_hash(str);
        printf("MD5 Hash: %02x%02x%02x%02x%02x%02x\n", 
               (unsigned char)hash[0], (unsigned char)hash[1],
               (unsigned char)hash[2], (unsigned char)hash[3],
               (unsigned char)hash[4], (unsigned char)hash[5]);
    }

    return 0;
}
