#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    char** items;
    int item_count;
} Transaction;

Transaction* create_transaction(int id, time_t timestamp) {
    Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));
    transaction->id = id;
    transaction->timestamp = timestamp;
    transaction->item_count = 0;
    return transaction;
}

int calculate_total_value(Transaction* transaction) {
    int total_value = 0;
    for (int i = 0; i < transaction->item_count; i++) {
        total_value += strlen(transaction->items[i]) * 10; // Simplified example: price is proportional to item name length
    }
    return total_value;
}

void update_transaction(Transaction* transaction, char* new_item) {
    transaction->items = (char**)realloc(transaction->items, (transaction->item_count + 1) * sizeof(char*));
    transaction->items[transaction->item_count] = new_item;
    transaction->item_count++;
}

int validate_timestamp(time_t timestamp) {
    // Simplified validation: check if timestamp is within the last minute
    time_t current_time = time(NULL);
    return (current_time - timestamp) <= 60; // 1 minute in seconds
}

int main() {
    Transaction* transaction = create_transaction(1, time(NULL));

    // Validate timestamp
    if (!validate_timestamp(transaction->timestamp)) {
        printf("Invalid timestamp. Aborting.\n");
        free(transaction);
        return -1;
    }

    char* item1 = "Apple";
    char* item2 = "Banana";

    // Update transaction
    update_transaction(transaction, item1);
    update_transaction(transaction, item2);

    int total_value = calculate_total_value(transaction);
    printf("Transaction ID: %d\n", transaction->id);
    printf("Timestamp: %lu\n", transaction->timestamp);
    printf("Items: ");
    for (int i = 0; i < transaction->item_count; i++) {
        printf("%s ", transaction->items[i]);
    }
    printf("\nTotal value: %d\n", total_value);

    free(transaction);
    return 0;
}

