    Record **temp = (Record **) realloc(records, sizeof(Record *) * new_size);
    if (!temp) {
        printf("Memory allocation failed for records.\n");
        return;
    }
    records = temp;
    for (int i = record_count; i < new_size; i++) {
        records[i] = (Record *) malloc(sizeof(Record));
        if (!records[i]) {
            printf("Memory allocation failed for record %d.\n", i);
            // fallback strategy: return and report the error
            free(temp);
            temp = NULL;
            return;
        }
    }
