int manage_memory_allocation(int initial_record_count, int initial_identifier_count, double min_value, double max_value) {
    resize_records(initial_record_count);

    Record **records = (Record **) malloc(sizeof(Record *) * initial_record_count);
    if (!records) {
        printf("Memory allocation failed for records.\n");
        return -1; // fallback strategy: report error and return
    }
    for (int i = 0; i < initial_record_count; i++) {
        Record *record = (Record *) malloc(sizeof(Record));
        if (!record) {
            printf("Memory allocation failed for record %d.\n", i);
            // fallback strategy: free already allocated memory and return
            for (int j = 0; j < i; j++) {
                free(records[j]);
