void manage_memory(int size, int range_start, int range_end, const char* str) {
    // Allocate arrays
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    record* records = (record*)malloc(size * sizeof(record));
    char** identifiers = (char**)malloc(size * sizeof(char*));
    unsigned char* flags = (unsigned char*)malloc(size * sizeof(unsigned char));

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % range_end;
        keys[i] = rand() % range_end;
        records[i].offset = offsets[i];
        records[i].timestamp = rand() % range_end;
        records[i].value = rand() % range_end;
        char buffer[10];
        sprintf(buffer, "Record %d", i);
        identifiers[i] = (char*)malloc(strlen(buffer) + 1);
        strcpy(identifiers[i], buffer);
        flags[i] = rand() % 2;
    }

    // Validate memory initialization
    for (int i = 0; i < size; i++) {
        if (offsets[i] > range_end || keys[i] > range_end) {
            printf("Invalid offset or key at index %d\n", i);
            return;
        }
    }

