    int metric2 = 0;

    // Return maximum weighted sum and transaction ID
    printf("Maximum weighted sum: %f\n", max_weighted_sum);
    printf("Transaction ID: %d\n", max_transaction_id);

    // Deallocate memory
    for (int i = 0; i < size; i++) {
        free(identifiers[i]);
    }
    free(identifiers);
    free(flags);
    free(keys);
    free(offsets);
    free(records);

    return;
}
