typedef struct {
    int count_exceeding_threshold;
    double average_key_value;
} metadata;

typedef struct {
    int freq[3];
} usageStats;

record *records;
metadata *metadata;
usageStats *usageStats;

void generate_random_string(char **str, char *chars) {
    *str = (char *)malloc(10);
    for(int i = 0; i < 10; i++) {
        (*str)[i] = chars[rand() % strlen(chars)];
    }
    (*str)[9] = '\0';
}

int main(int argc, char **argv) {
    int N = atoi(argv[1]);
    int max_key_value = atoi(argv[2]);
    double threshold = atof(argv[3]);

    records = (record *)malloc(N * sizeof(record));
    metadata = (metadata *)malloc(sizeof(metadata));
    usageStats = (usageStats *)malloc(sizeof(usageStats));

    for(int i = 0; i < N; i++) {
        records[i].offset = rand();
        records[i].x1 = rand() % max_key_value;
        records[i].x2 = rand() % max_key_value;
        generate_random_string(&records[i].str, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789");
        records[i].timestamp = (double)rand() / RAND_MAX;

        if(records[i].timestamp > threshold)
            metadata->count_exceeding_threshold++;
    }

    for(int i = 0; i < N; i++) {
        usageStats->freq[records[i].x1 % 3]++;
    }
    metadata->average_key_value = (double)usageStats->freq[0] + usageStats->freq[1] + usageStats->freq[2];

    free(records);
    free(metadata);
    free(usageStats);

    return 0;
}
