typedef struct {
    int key;
    long offset;
} Record;

Record* create_dataset(int num_records) {
    Record* dataset = (Record*)malloc(num_records * sizeof(Record));
    if (!dataset) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Initialize random number generator

    for (int i = 0; i < num_records; i++) {
        dataset[i].key = rand() % 100; // Generate random integer key within [0, 99]
        dataset[i].offset = (long)rand() * 1000000L; // Generate random long offset
    }

    return dataset;
}

void add_record(Record** dataset, int* num_records) {
    Record* new_dataset = (Record*)realloc(*dataset, (*num_records + 1) * sizeof(Record));
    if (!new_dataset) {
        printf("Error: Memory allocation failed\n");
        return; // Handle memory allocation error
    }

    *dataset = new_dataset;

    for (int i = *num_records; i > 0; i--) {
        (*dataset)[i] = (*dataset)[i - 1]; // Shift existing records
    }

    Record* new_record = &(*dataset)[*num_records];
    new_record->key = rand() % 100;
    new_record->offset = (long)rand() * 1000000L;

    (*num_records)++;
}

void free_dataset(Record** dataset, int* num_records) {
    if (*num_records > 0) {
        free(*dataset);
        *num_records = 0; // Reset the number of records
    }
}

int main() {
    Record* dataset;
    int num_records = 10;

    dataset = create_dataset(num_records);

    add_record(&dataset, &num_records);

    // Test your code here...

    free_dataset(&dataset, &num_records);
    return 0;
}
