    strcpy(btd->mac_address, "00:11:22:33:44:55");
    btd->device_service_list = (struct {
        char *service_name;
        int service_type;
        enum { SERVICE_STATUS_UP = 0, SERVICE_STATUS_DOWN } service_status;
    }*)malloc(sizeof(struct {
        char *service_name;
        int service_type;
        enum { SERVICE_STATUS_UP = 0, SERVICE_STATUS_DOWN } service_status;
    }));
