    btd->device_service_list->service_type = 1;
    btd->device_service_list->service_status = SERVICE_STATUS_UP;
    return btd;
}

// Function to manage dynamic datasets
void manage_datasets() {
    NFV_Instance* nfvi = allocate_nfvi();
    Bluetooth_Device* btd = allocate_btd();

    // Iterate over NFV instances, updating resource allocation based on cloud resource availability and application demand patterns
    for (int i = 0; i < 5; i++) {
        update_nfvi_resource_allocation(nfvi);
    }

    // Scan for nearby Bluetooth devices and update the device_service_list with discovered services
    discover_services(btd);

    // Deallocate memory safely using helper function
    deallocate_memory_safe(nfvi, btd);
}

// Helper function to deallocate memory safely
void deallocate_memory_safe(void* ptr1, void* ptr2) {
    if (ptr1) free(ptr1);
    if (ptr2) {
        free(ptr2);
        if (ptr2->device_service_list)
            free(ptr2->device_service_list);
    }
}

// Function to update NFV instance resource allocation
void update_nfvi_resource_allocation(NFV_Instance* nfvi) {
    // Update resource utilization metrics based on real-time cloud resource availability and application demand patterns
    nfvi->cpu_utilization += 0.1;
    nfvi->memory_utilization -= 0.2;

    // Ensure minimal impact on ongoing operations by integrating with existing orchestration framework for performance metrics
}

// Function to scan for nearby Bluetooth devices and update the device_service_list with discovered services
void discover_services(Bluetooth_Device* btd) {
    // Scan for nearby Bluetooth devices using an API call
    char** discovered_services = get_discovered_services();

    // Update the device_service_list with discovered services
    btd->device_service_list->service_name = discovered_services[0];
    btd->device_service_list->service_type = 2;
    btd->device_service_list->service_status = SERVICE_STATUS_UP;

    // Deallocate memory for discovered services safely using helper function
    deallocate_discovered_services(discovered_services);
}

// Helper function to deallocate memory for discovered services safely
void deallocate_discovered_services(char** ptr) {
    if (ptr) {
        for (int i = 0; i < 5; i++) free(ptr[i]);
        free(ptr);
    }
}
