    int health_status;
} NFV_Instance;

typedef struct {
    char* device_id;
    char* mac_address;
    char* Bluetooth_Device_Profile;
    struct service_list_node* device_service_list;
} Bluetooth_Device;

typedef struct {
    char* service_name;
    char* service_type;
    char* service_status;
    struct service_list_node* next;
} Service_List_Node;

NFV_Instance* create_nfv_instance(char* instance_id, char* ip_address) {
    NFV_Instance* nfv = (NFV_Instance*)malloc(sizeof(NFV_Instance));
    nfv->instance_id = strdup(instance_id);
    nfv->ip_address = strdup(ip_address);
    nfv->cpu_usage = 0.0;
    nfv->memory_usage = 0.0;
    nfv->vnic_count = 0;
    nfv->vnic_config = NULL;
    nfv->health_status = 1;
    return nfv;
}

Bluetooth_Device* create_bluetooth_device(char* device_id, char* mac_address) {
    Bluetooth_Device* device = (Bluetooth_Device*)malloc(sizeof(Bluetooth_Device));
    device->device_id = strdup(device_id);
    device->mac_address = strdup(mac_address);
    device->Bluetooth_Device_Profile = NULL;
    device->device_service_list = NULL;
    return device;
}

void deallocate_nfv_instance(NFV_Instance* nfv) {
    if (nfv != NULL) {
        free(nfv->instance_id);
        free(nfv->ip_address);
        if (nfv->vnic_config != NULL) {
            for (int i = 0; i < nfv->vnic_count; i++) {
                free(nfv->vnic_config[i]);
            }
            free(nfv->vnic_config);
        }
        free(nfv);
    }
}

void deallocate_bluetooth_device(Bluetooth_Device* device) {
    if (device != NULL) {
        free(device->device_id);
        free(device->mac_address);
        if (device->device_service_list != NULL) {
            struct service_list_node* current = device->device_service_list;
            while (current != NULL) {
                struct service_list_node* next = current->next;
                free(current->service_name);
                free(current->service_type);
                free(current->service_status);
                free(current);
                current = next;
            }
        }
        free(device);
    }
}

void update_nfv_instance(NFV_Instance* nfv, char* new_ip_address) {
    if (nfv != NULL) {
        free(nfv->ip_address);
        nfv->ip_address = strdup(new_ip_address);
    }
}

int main() {
    // Initialize data structures
    NFV_Instance* nfv_instances[5];
    Bluetooth_Device* bluetooth_devices[10];

    // Create sample data
    for (int i = 0; i < 5; i++) {
        nfv_instances[i] = create_nfv_instance(strdup("Instance-"), strdup("192.168.1."));
        update_nfv_instance(nfv_instances[i], "192.168.2.");
    }
    for (int j = 0; j < 10; j++) {
        bluetooth_devices[j] = create_bluetooth_device(strdup("Device-"), strdup("00:11:22:33"));
        // Scan for nearby devices and update service list
    }

    // Deallocate memory
    for (int i = 0; i < 5; i++) {
        deallocate_nfv_instance(nfv_instances[i]);
    }
    for (int j = 0; j < 10; j++) {
        deallocate_bluetooth_device(bluetooth_devices[j]);
    }

    return 0;
}
