} record;

void manage_memory(int array_size, int low, int high) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(array_size * sizeof(long));
    int* keys = (int*)malloc(array_size * sizeof(int));
    record* records = (record*)malloc(array_size * sizeof(record));
    char** strings = (char**)malloc(array_size * sizeof(char*));
    int* flags = (int*)malloc(array_size * sizeof(int));

    // Initialize arrays
    for (int i = 0; i < array_size; i++) {
        offsets[i] = rand() % (high - low + 1) + low;
        keys[i] = rand() % (high - low + 1) + low;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].timestamp = time(NULL);
        records[i].value = rand() % (high - low + 1) + low;
        strings[i] = (char*)malloc((strlen("Hello") + 1) * sizeof(char));
        strcpy(strings[i], "Hello");
        flags[i] = 0;
    }

    // Validate memory initialization
    for (int i = 0; i < array_size; i++) {
        if (offsets[i] < low || offsets[i] > high ||
            keys[i] < low || keys[i] > high) {
            printf("Invalid offset or key value.\n");
            exit(1);
        }
    }

    // Free memory
    for (int i = 0; i < array_size; i++) {
        free(strings[i]);
    }
    free(strings);
    free(flags);
    free(records);
    free(keys);
    free(offsets);
}
