typedef struct {
    int id;
    char *name;
    double value;
} Record;

Record **arrayOfRecords = NULL;

void* allocateArray(int size) {
    void* ptr = malloc(size * sizeof(Record *));
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

void resizeArray(int newSize) {
    Record **newPtr = allocateArray(newSize);
    if (newPtr != NULL) {
        int i;
        for (i = 0; i < newSize && i < sizeof(arrayOfRecords) / sizeof(Record *); i++) {
            newPtr[i] = arrayOfRecords[i];
        }
        free(arrayOfRecords);
        arrayOfRecords = newPtr;
    }
}

void addRecord(int id, char* name, double value) {
    Record **newPtr = allocateArray(sizeof(arrayOfRecords));
    if (newPtr != NULL) {
        Record *newRecord = malloc(sizeof(Record));
        newRecord->id = id;
        newRecord->name = name;
        newRecord->value = value;
        int i;
