#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef enum {
    TASK_PENDING,
    TASK_IN_PROGRESS,
    TASK_COMPLETED
} task_status;

typedef struct {
    char* name;
    int priority;
    task_status status;
} task;

void init_task(task* t, int num) {
    t->name = malloc(strlen("Task_") + 3);
    sprintf(t->name, "Task_%03d", num);
    t->priority = 0;
    t->status = TASK_PENDING;
}

task* create_task(int num) {
    task* t = (task*)malloc(sizeof(task));
    init_task(t, num);
    return t;
}

void free_task(task* t) {
    if (t != NULL) {
        if (t->name != NULL) {
            free(t->name);
        }
        free(t);
    }
}

void insert_task(task** tasks, int num_tasks, task* new_task) {
    task* temp = (task*)malloc((num_tasks + 1) * sizeof(task));
    for (int i = 0; i < num_tasks; i++) {
        temp[i] = *(tasks + i);
    }
    free(*tasks);
    *tasks = temp;
    (*tasks)[num_tasks] = *new_task;
}

void remove_task(task** tasks, int* num_tasks) {
    task* temp = (task*)malloc((*num_tasks - 1) * sizeof(task));
    for (int i = 0, j = 0; i < *num_tasks; i++) {
        if (i != (*num_tasks) - 1) {
            temp[j] = *(tasks + i);
            j++;
        }
    }
    free(*tasks);
    *tasks = temp;
    (*num_tasks]--;
}

void sort_tasks(task** tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; i++) {
        for (int j = i + 1; j < num_tasks; j++) {
            if ((*tasks)[i]->priority > (*tasks)[j]->priority) {
                task* temp = *tasks[i];
                *tasks[i] = *tasks[j];
                *tasks[j] = temp;
            }
        }
    }
}

void clear_tasks(task** tasks, int* num_tasks) {
    for (int i = 0; i < *num_tasks; i++) {
        free_task(*(tasks + i));
    }
    free(*tasks);
    *num_tasks = 0;
}
