#include "memory_pool.h"
#include "hash_table.h"

int configure_system(char **file_paths, int *config_levels, int num_configs) {
    if (!file_paths || !config_levels) {
        return -1; // Error: invalid input
    }

    memory_pool_init();

    hash_table_t *configs = hash_table_create(10); // Initial capacity

    for (int i = 0; i < num_configs; i++) {
        char *file_path = file_paths[i];
        int level = config_levels[i];

        if (!file_path || !*file_path) {
            continue; // Skip invalid or empty file path
        }

        if (access(file_path, R_OK)) {
            return -2; // Error: file not readable
        }

        if (hash_table_get(configs, level) != NULL) {
            return -3; // Error: duplicate config level
        }

        hash_table_put(configs, level, file_path);
    }

    memory_pool_free();

    return 0;
}

