#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <unistd.h>
#include <sys/socket.h>

// Define data structures
typedef struct {
    time_t time;
} weather_report;

typedef struct {
    float latitude;
    float longitude;
    int altitude;
} GPS_POSITION_T;

// Function to dynamically allocate memory and initialize data structures
int* weather_station(int size) {
    // Initialize error flag
    int err = 0;

    // Allocate memory for temperatures array
    float* temps = (float*)malloc(size * sizeof(float));
    if (!temps) return NULL;  // Handle allocation failure

    // Initialize temperatures with random values
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        temps[i] = ((float)rand() / RAND_MAX) * 80.0 - 30.0;
    }

    // Calculate symbols array size and allocate memory
    int symbols_size = size / 3;
    char** symbols = (char**)malloc(symbols_size * sizeof(char*));
    if (!symbols) return NULL;  // Handle allocation failure

    for (int i = 0; i < symbols_size; i++) {
        symbols[i] = (char*)malloc(1);
        if (!symbols[i]) return NULL;  // Handle allocation failure
        *(symbols[i]) = (char)(rand() % ('~' - '!' + 1)) + '!';
    }

    // Calculate weather_reports array size and allocate memory
    int reports_size = symbols_size * 4;
    weather_report* reports = (weather_report*)malloc(reports_size * sizeof(weather_report));
    if (!reports) return NULL;  // Handle allocation failure

    for (int i = 0; i < reports_size; i++) {
        reports[i].time = (time_t)(rand() % (60 * 60 * 24 * 365));
    }

    // Calculate GPS positions array size and allocate memory
    int gps_positions_size = size / 2;
    GPS_POSITION_T* gps_positions = (GPS_POSITION_T*)malloc(gps_positions_size * sizeof(GPS_POSITION_T));
    if (!gps_positions) return NULL;  // Handle allocation failure

    for (int i = 0; i < gps_positions_size; i++) {
        gps_positions[i].latitude = ((float)rand() / RAND_MAX) * 180.0 - 90.0;
        gps_positions[i].longitude = ((float)rand() / RAND_MAX) * 360.0 - 180.0;
        gps_positions[i].altitude = rand() % (10000 + 1);
    }

    // Calculate distances array size and allocate memory
    int* distances = (int*)malloc((gps_positions_size - 1) * sizeof(int));
    if (!distances) return NULL;  // Handle allocation failure

    for (int i = 0; i < gps_positions_size - 1; i++) {
        float d = distance(gps_positions[i], gps_positions[i + 1]);
        distances[i] = (int)(d * 1000);  // Convert meters to kilometers
    }

    // Serialize distances array into byte array
    int serialized_size = sizeof(int) * (gps_positions_size - 1);
    uint8_t* serialized_data = (uint8_t*)malloc(serialized_size);
    if (!serialized_data) return NULL;  // Handle allocation failure

    for (int i = 0; i < gps_positions_size - 1; i++) {
        memcpy(&serialized_data[i * sizeof(int)], &distances[i], sizeof(int));
    }

    // Transmit serialized data to remote weather station server
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) return NULL;  // Handle socket creation failure

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

    int retry_count = 0;
    while (retry_count < 5) {
        if (connect(sockfd, (struct sockaddr*)&addr, sizeof(addr)) == 0)
            break;

        close(sockfd);
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) return NULL;  // Handle socket creation failure
        retry_count++;
    }

    if (retry_count >= 5 || send(sockfd, serialized_data, serialized_size, 0) < 0) {
        close(sockfd);
        free(serialized_data);
        err = -1;
    } else {
        close(sockfd);
    }

    // Free previously allocated memory
    for (int i = 0; i < symbols_size; i++) {
        free(symbols[i]);
    }
    free(symbols);
    free(reports);
    free(gps_positions);
    free(distances);

    return err;
}

// Function to calculate distance between two GPS positions
float distance(GPS_POSITION_T p1, GPS_POSITION_T p2) {
    float lat1 = radians(p1.latitude);
    float lon1 = radians(p1.longitude);
    float lat2 = radians(p2.latitude);
    float lon2 = radians(p2.longitude);

    float dlat = lat2 - lat1;
    float dlon = lon2 - lon1;

    float a = sin(dlat / 2) * sin(dlat / 2) + cos(lat1) * cos(lat2) * sin(dlon / 2) * sin(dlon / 2);
    float c = 2 * atan2(sqrt(a), sqrt(1 - a));
    return (float)(6371.0 * c);  // Earth's radius in kilometers
}

// Convert degrees to radians
float radians(float x) {
    return (x * M_PI) / 180;
}
