```java
import javax.xml.bind.DatatypeConverter;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class MD5Hasher {
    public static List<String> processStrings(List<String> strings) throws Exception {
        ExecutorService executor = Executors.newCachedThreadPool();
        List<Callable<String>> tasks = new ArrayList<>();

        int discardedCount = 0;
        for (String s : strings) {
            if (s.length() > 1024) {
                discardedCount++;
                continue;
            }
            tasks.add(new StringHasherTask(s));
        }

        List<String> results = executor.invokeAll(tasks).stream()
                .map(future -> {
                    try {
                        return future.get();
                    } catch (InterruptedException | ExecutionException e) {
                        throw new Exception("Failed to compute MD5 hash", e);
                    }
                })
                .collect(Collectors.toList());

        executor.shutdown();

        return results;
    }

    private static class StringHasherTask implements Callable<String> {
        private final String s;

        public StringHasherTask(String s) {
            this.s = s;
        }

        @Override
        public String call() throws Exception {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] bytes = s.getBytes();
            byte[] hashBytes = md5.digest(bytes);
            return DatatypeConverter.printHexBinary(hashBytes).toLowerCase();
        }
    }
}
