#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>

// Define a structure to represent a record
typedef struct {
    int value;
} Record;

// Define a structure to represent a nested array of records
typedef struct {
    Record **records;
    int size;
    pthread_mutex_t mutex;
} RecordsArray;

// Function to dynamically manage memory for multiple nested data structures
void* nest_records(int primary_size, int secondary_size) {
    // Allocate memory for the primary record array
    RecordsArray *primary = (RecordsArray*)malloc(sizeof(RecordsArray));
    if (!primary) return NULL;  // Handle out-of-memory error
    primary->records = (Record**)calloc(primary_size, sizeof(Record*));
    primary->size = primary_size;
    pthread_mutex_init(&primary->mutex, NULL);

    // Allocate memory for the secondary record array
    RecordsArray *secondary = (RecordsArray*)malloc(sizeof(RecordsArray));
    if (!secondary) return NULL;  // Handle out-of-memory error
    secondary->records = (Record**)calloc(secondary_size, sizeof(Record*));

    // Initialize the primary and secondary record arrays
    for (int i = 0; i < primary_size; i++) {
        Record *record = (Record*)malloc(sizeof(Record));
        if (!record) return NULL;  // Handle out-of-memory error
        record->value = rand() % 100;  // Initialize with a random value
        primary->records[i] = record;
    }
    for (int i = 0; i < secondary_size; i++) {
        Record *record = (Record*)malloc(sizeof(Record));
        if (!record) return NULL;  // Handle out-of-memory error
        record->value = rand() % 100;  // Initialize with a random value
        secondary->records[i] = record;
    }

    // Track total memory usage
    size_t total_memory_usage = sizeof(RecordsArray) + primary_size * sizeof(Record*) + secondary_size * sizeof(Record);

    // Serialize and deserialize the data structure to a file format (e.g., JSON)
    FILE *file = fopen("data.json", "w");
    if (!file) return NULL;  // Handle out-of-memory error
    fwrite(primary, sizeof(RecordsArray), 1, file);
    fwrite(secondary, sizeof(RecordsArray), 1, file);

    // Log memory allocation and deallocation events
    printf("[Memory Usage] Total: %zu bytes\n", total_memory_usage);

    return primary;
}
