#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct HashTable {
    int size;
    struct Bucket **buckets;
} HashTable;

typedef struct Bucket {
    struct Entry *head;
    struct Entry *tail;
} Bucket;

typedef struct Entry {
    char *key;
    int value;
    struct Entry *next;
} Entry;

HashTable* createHashTable(int size) {
    HashTable *hash_table = (HashTable *)malloc(sizeof(HashTable));
    hash_table->size = size;
    hash_table->buckets = (Bucket **)calloc(size, sizeof(Bucket *));
    for (int i = 0; i < size; i++) {
        hash_table->buckets[i] = (Bucket *)malloc(sizeof(Bucket));
        hash_table->buckets[i]->head = NULL;
        hash_table->buckets[i]->tail = NULL;
    }
    return hash_table;
}

void freeHashTable(HashTable *hash_table) {
    for (int i = 0; i < hash_table->size; i++) {
        Bucket *bucket = hash_table->buckets[i];
        while (bucket->head != NULL) {
            Entry *entry = bucket->head;
            bucket->head = entry->next;
            free(entry);
        }
        free(bucket);
    }
    free(hash_table->buckets);
    free(hash_table);
}

int hashFunction(char *key, int size) {
    int hash = 0;
    for (char *p = key; *p != '\0'; p++) {
        hash += *p;
    }
    return hash % size;
}

void insertEntry(HashTable *hash_table, char *key, int value) {
    Bucket *bucket = hash_table->buckets[hashFunction(key, hash_table->size)];
    Entry *entry = (Entry *)malloc(sizeof(Entry));
    entry->key = strdup(key);
    entry->value = value;
    entry->next = NULL;

    if (bucket->head == NULL) {
        bucket->head = entry;
        bucket->tail = entry;
    } else {
        bucket->tail->next = entry;
        bucket->tail = entry;
    }
}

void printHashTable(HashTable *hash_table) {
    for (int i = 0; i < hash_table->size; i++) {
        Bucket *bucket = hash_table->buckets[i];
        printf("Bucket %d:\n", i);
        Entry *entry = bucket->head;
        while (entry != NULL) {
            printf("%s: %d\n", entry->key, entry->value);
            entry = entry->next;
        }
        printf("\n");
    }
}']

