import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class Main {
    public static List<String> processStringsInParallel(String[] strings) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        List<Future<String>> futures = new ArrayList<>();

        for (String s : strings) {
            if (s.length() > 1024) {
                continue; // discard strings with length exceeding 1024 characters
            }

            int hashLength = 32;
            byte[] hashBytes = new byte[hashLength];
            MessageDigest md5 = null;

            try {
                md5 = MessageDigest.getInstance("MD5");
            } catch (NoSuchAlgorithmException e) {
                throw new RuntimeException(e);
            }

            futures.add(executor.submit(() -> {
                try {
                    return bytesToHex(md5.digest(s.getBytes()));
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }));
        }

        executor.shutdown();

        List<String> md5Hashes = new ArrayList<>();
        int discardedCount = 0;

        for (Future<String> future : futures) {
            try {
                String md5 = future.get();
                if (md5 != null) {
                    md5Hashes.add(md5);
                } else {
                    ++discardedCount;
                }
            } catch (CancellationException e) {
                // ignore cancelled tasks
            }
        }

        return new ArrayList<>(md5Hashes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xFF & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        String[] strings = {"Hello", "World!", "This is a test string"};
        List<String> md5Hashes = processStringsInParallel(strings);

        for (String s : md5Hashes) {
            System.out.println(s);
        }

        System.out.println("Discarded count: " + (strings.length - md5Hashes.size()));
    }
}
