['Here is the Java method that processes a batch of strings, computes their MD5 hashes in parallel while handling potential concurrency issues gracefully:

```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class MD5Hasher {

    public static class HashingTask implements Callable<String> {
        private String input;

        public HashingTask(String input) {
            this.input = input;
        }

        @Override
        public String call() throws Exception {
            if (input.length() > 1024) {
                return null; // discard long strings
            }
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] bytes = input.getBytes();
            md5.update(bytes);
            return bytesToHex(md5.digest());
        }

        private String bytesToHex(byte[] bytes) {
            StringBuilder hexString = new StringBuilder();
            for (byte b : bytes) {
                String f = Integer.toHexString(0xff & b);
                if(f.length() == 1){
                    hexString.append('0');
                }
                hexString.append(f);
            }
            return hexString.toString();
        }
    }

    public static class EnvironmentalData {
        private float[] temperatures;
        private char[] symbols;
        private long[][] weatherReports;

        public EnvironmentalData(int size) {
            this.temperatures = new float[size];
            for (int i = 0; i < size; i++) {
                temperatures[i] = (float) Math.random() * 80 - 30.0f;
            }
            this.symbols = new char[(size / 3)];
            for (char c : symbols) {
                symbols[c % 95] = (char) (Math.random() * 95);
            }
            this.weatherReports = new long[size * 4][];
            for (int i = 0; i < size * 4; i++) {
                weatherReports[i] = new long[]{(long) (System.currentTimeMillis() - Math.random() * 31556926),};
            }
        }

        public float[] getTemperatures() {
            return temperatures;
        }

        public char[] getSymbols() {
            return symbols;
        }

        public long[][] getWeatherReports() {
            return weatherReports;
        }
    }

    public static class DistanceCalculator implements Callable<double[]> {
        private float[] temperatures;

        public DistanceCalculator(float[] temperatures) {
            this.temperatures = temperatures;
        }

        @Override
        public double[] call() throws Exception {
            double[] distances = new double[temperatures.length - 1];
            for (int i = 0; i < temperatures.length - 1; i++) {
                double latDiff = Math.toRadians(temperatures[i + 1] - temperatures[i]);
                double lonDiff = Math.toRadians((Math.random() * 360) % 360);
                distances[i] = distance(latDiff, lonDiff);
            }
            return distances;
        }

        private double distance(double latDiff, double lonDiff) {
            // calculate the distance between two points using Haversine formula
            double R = 6371.0; // Earth's radius in kilometers
            double a = Math.sin(latDiff / 2) * Math.sin(latDiff / 2)
                    + Math.cos(Math.toRadians(temperatures[0]))
                    * Math.cos(Math.toRadians(temperatures[i + 1]))
                    * Math.sin(lonDiff / 2) * Math.sin(lonDiff / 2);
            double c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
            return R * c;
        }
    }

    public static class WeatherStation {
        private byte[] data;

        public void send(byte[] data) throws Exception {
            // implement the logic to send data to the remote weather station server
            // handle timeouts, connection failures, etc.
        }
    }

    public static class Result {
        private List<String> md5Hashes;
        private int discardedCount;
        private EnvironmentalData environmentalData;
        private double[] distances;
        private byte[] serializedData;
        private boolean transmissionFailed;

        public Result(List<String> md5Hashes, int discardedCount,
                EnvironmentalData environmentalData, double[] distances, byte[] serializedData, boolean transmissionFailed) {
            this.md5Hashes = md5Hashes;
            this.discardedCount = discardedCount;
            this.environmentalData = environmentalData;
            this.distances = distances;
            this.serializedData = serializedData;
            this.transmissionFailed = transmissionFailed;
        }
    }

    public static Result processBatch(String[] batch) {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        List<Future<String>> futures = new ArrayList<>();
        List<String> md5Hashes = new ArrayList<>();
        int discardedCount = 0;

        for (String input : batch) {
            if (input.length() > 1024) {
                ++discardedCount;
                continue; // discard long strings
            }
            Callable<String> task = new HashingTask(input);
            futures.add(executor.submit(task));
        }

        try {
            for (Future<String> future : futures) {
                md5Hashes.add(future.get());
            }
        } catch (InterruptedException | ExecutionException e) {
            // handle exceptions
            return null;
        } finally {
            executor.shutdown();
        }

        EnvironmentalData environmentalData = new EnvironmentalData(md5Hashes.size());
        DistanceCalculator distanceCalculator = new DistanceCalculator(environmentalData.getTemperatures());

        try {
            Result result = new Result(md5Hashes, discardedCount,
                    environmentalData, distanceCalculator.call(), null, false);
            WeatherStation weatherStation = new WeatherStation();
            byte[] serializedData = serializeDistances(result.distances);
            weatherStation.send(serializedData);

            return result;
        } catch (Exception e) {
            // handle exceptions
            return null;
        }
    }

