void manage_packet_allocation(size_t num_packets) {
    if (num_packets > MAX_PACKETS) {
        printf("Error: Number of packets exceeds maximum limit.\n");
        return;
    }

    // Allocate memory for packet lengths
    uint16_t* packet_lengths = (uint16_t*)malloc(num_packets * sizeof(uint16_t));

    // Initialize buffer array with packet lengths
    char** buffers = (char**)calloc(num_packets, sizeof(char*));
    for (size_t i = 0; i < num_packets; i++) {
        buffers[i] = (char*)malloc(packet_lengths[i] * sizeof(char));
    }

    // Create linked list of packet headers
    packet_header* headers = (packet_header*)malloc(num_packets * sizeof(packet_header));

    // Populate packet headers with data
    for (size_t i = 0; i < num_packets; i++) {
        // Generate random header data to avoid duplicate routing scenarios
        uint32_t source_ip = rand() % 4294967295;
        uint32_t dest_ip = rand() % 4294967295;

