// Define a linked list node structure for frame headers
typedef struct FrameHeader {
    uint8_t codec;
    uint16_t stream_id;
    int32_t timestamp_offset;
    struct FrameHeader* next;
} frame_header;

// Function to manage efficient allocation and population of data structures
frame_header* allocate_and_populate_frames(uint32_t num_frames) {
    // Allocate memory for an array of uint32_t timestamps
    uint32_t* timestamps = (uint32_t*)malloc(num_frames * sizeof(uint32_t));

    // Initialize arrays of char buffers, each sized according to the corresponding frame size
    char** buffers = (char**)calloc(num_frames, sizeof(char*));
    for (int i = 0; i < num_frames; i++) {
        int buffer_size = rand() % 1024 + 1; // Randomly generated buffer size
        buffers[i] = (char*)malloc(buffer_size * sizeof(char));
    }

    // Create a linked list of frame_header structures, each with timestamp offset set to corresponding timestamp value
    frame_header* headers = NULL;
    for (int i = 0; i < num_frames; i++) {
        frame_header* header = (frame_header*)malloc(sizeof(frame_header));
        header->timestamp_offset = timestamps[i];
        header->next = NULL;

        // Populate each frame_header with header-specific data, ensuring no two adjacent headers have the same stream ID
        header->stream_id = i % 256; // Generate a unique stream ID for each frame
        if (i > 0) {
            frame_header* prev = &headers[i - 1];
            while (prev->next != NULL) prev = prev->next;
            prev->next = header;
        } else {
            headers = header;
        }
    }

    // Implement a mechanism to detect and handle malformed frame headers
    for (frame_header* current = headers; current != NULL; current = current->next) {
        if (current->stream_id == 0 || current->timestamp_offset < 0) {
            printf("Malformed frame header detected! Timestamp offset: %d, Stream ID: %u\n", current->timestamp_offset, current->stream_id);
            free(current); // Free the malformed header
            continue; // Skip processing this particular frame
        }
    }

    // Provide a mechanism to free all allocated memory upon function completion
    for (int i = 0; i < num_frames; i++) {
        free(buffers[i]);
    }
    free(buffers);
    free(timestamps);

    return headers;
}
