#define MAX_RECORDS 100
#define RECORD_KEY_RANGE 10
#define THRESHOLD 50

typedef struct {
    int key;
    long offset;
    int value;
} record_t;

record_t* init_records(int count) {
    record_t *records = NULL;
    int i;

    if (count > MAX_RECORDS) {
        printf("Error: Record count exceeds threshold.\n");
        return records;
    }

    for (i = 0; i < count; i++) {
        record_t *new_records = realloc(records, (i + 1) * sizeof(record_t));
        if (!new_records) {
            free(records);
            printf("Error: Memory allocation failed.\n");
            return NULL;
        }
        records = new_records;
    }

    for (i = 0; i < count; i++) {
        srand(time(NULL) + i); // Ensure randomness
        records[i].key = rand() % RECORD_KEY_RANGE;
        records[i].offset = (long)i;
        records[i].value = rand() % RECORD_KEY_RANGE;
    }

    return records;
}

void free_records(record_t *records, int count) {
    if (!records)
        return;

    for (int i = 0; i < count; i++)
        free(&records[i]);

    free(records);
}
