#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define RECORDS_PER_POOL 1000
#define MAX_RECORDS 100000
#define MEMORY_POOL_SIZE (RECORDS_PER_POOL * sizeof(record))

typedef struct {
    int value;
} record;

record* records = NULL;
long* offsets = NULL;
int* keys = NULL;
size_t records_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* memory_pool = NULL;

void init_records(int initial_capacity, int max_capacity) {
    if (initial_capacity > max_capacity)
        initial_capacity = max_capacity;

    records = malloc(initial_capacity * sizeof(record));
    offsets = malloc(initial_capacity * sizeof(long));
    keys = malloc(initial_capacity * sizeof(int));

    memory_pool = malloc(MEMORY_POOL_SIZE);
}

void resize_records(int new_capacity) {
    if (new_capacity <= 0)
        return;

    record* temp_records = realloc(records, new_capacity * sizeof(record));
    long* temp_offsets = realloc(offsets, new_capacity * sizeof(long));
    int* temp_keys = realloc(keys, new_capacity * sizeof(int));

    records = temp_records;
    offsets = temp_offsets;
    keys = temp_keys;
}

void* allocate_record() {
    void* ptr = NULL;

    pthread_mutex_lock(&lock);
    while (records_size >= MAX_RECORDS) {
        pthread_cond_wait(&cond, &lock);
    }

    if (!memory_pool || records_size >= RECORDS_PER_POOL) {
        resize_records(RECORDS_PER_POOL + 1);
        memory_pool = realloc(memory_pool, (RECORDS_PER_POOL + 1) * sizeof(record));
    }

    ptr = malloc(sizeof(record));
    memcpy(ptr, &records[records_size], sizeof(record));
    records_size++;

    pthread_mutex_unlock(&lock);

    return ptr;
}

void free_record(void* record_ptr) {
    if (!record_ptr)
        return;

    pthread_mutex_lock(&lock);
    record_ptr = (record*) record_ptr;
    int idx = 0;
    for (idx = 0; idx < records_size; idx++) {
        if (&records[idx] == record_ptr) {
            break;
        }
    }

    if (idx >= records_size)
        return;

    free(record_ptr);
    for (int i = idx; i < records_size - 1; i++) {
        records[i] = records[i + 1];
        offsets[i] = offsets[i + 1];
        keys[i] = keys[i + 1];
    }
    records_size--;
    pthread_cond_signal(&cond);

    pthread_mutex_unlock(&lock);
}

void* get_record(void* record_ptr) {
    if (!record_ptr)
        return NULL;

    pthread_mutex_lock(&lock);
    record_ptr = (record*) record_ptr;
    int idx = 0;
    for (idx = 0; idx < records_size; idx++) {
        if (&records[idx] == record_ptr) {
            break;
        }
    }

    if (idx >= records_size)
        return NULL;

    pthread_mutex_unlock(&lock);

    return record_ptr;
}

void handle_error(const char* message) {
    // Log error and maintain system stability
    printf("Error: %s\n", message);
}
