#include <stdlib.h>
#include <stdio.h>

#define MAX_RECORDS 1000
#define MIN_CAPACITY 10
#define MEMORY_POOL_SIZE 1024*1024 // 1MB

struct record {
    int value;
};

typedef struct {
    long offset;
    int key;
} record_key;

void* mem_pool = NULL;
size_t current_capacity = 0;
size_t total_memory_used = 0;
int num_records = 0;

record_key* offsets = (record_key*)malloc(MIN_CAPACITY * sizeof(record_key));
record* records = (record*)malloc(MIN_CAPACITY * sizeof(struct record));

void init_record_array(int initial_capacity) {
    if(initial_capacity < MIN_CAPACITY) {
        printf("Invalid initial capacity. Setting to %d.\n", MIN_CAPACITY);
        initial_capacity = MIN_CAPACITY;
    }

    mem_pool = malloc(MEMORY_POOL_SIZE);

    current_capacity = initial_capacity;
    offsets = (record_key*)realloc(offsets, current_capacity * sizeof(record_key));
    records = (record*)realloc(records, current_capacity * sizeof(struct record));

    total_memory_used += MEMORY_POOL_SIZE + current_capacity * sizeof(record_key) + current_capacity * sizeof(struct record);
}

void add_record(int value) {
    if(num_records >= current_capacity) {
        // Dynamically resize the array
        int new_capacity = num_records * 2 + 10;
        if(new_capacity > MAX_RECORDS) {
            printf("Record limit exceeded. Setting to %d.\n", MAX_RECORDS);
            new_capacity = MAX_RECORDS;
        }

        record_key* temp_offsets = (record_key*)realloc(offsets, new_capacity * sizeof(record_key));
        record* temp_records = (record*)realloc(records, new_capacity * sizeof(struct record));

        offsets = temp_offsets;
        records = temp_records;

        current_capacity = new_capacity;
    }

    // Initialize the new record
    record* new_record = (record*)malloc(sizeof(struct record));
    new_record->value = value;

    // Update the offset and key arrays
    offsets[num_records].key = num_records;
    offsets[num_records].offset = total_memory_used + sizeof(record);

    records[num_records] = *new_record;

    free(new_record);
    num_records++;
}

void remove_record(int index) {
    if(index < 0 || index >= num_records) {
        printf("Invalid record index.\n");
        return;
    }

    // Update the offset and key arrays
    for(int i = index; i < num_records - 1; i++) {
        offsets[i] = offsets[i + 1];
        records[i] = records[i + 1];
    }

    free(records[num_records - 1]);
    num_records--;
}

int get_memory_usage() {
    return total_memory_used;
}

void print_record_array() {
    for(int i = 0; i < num_records; i++) {
        printf("Index %d: value = %d, offset = %ld\n", i, records[i]->value, offsets[i].offset);
    }
}

int main() {
    init_record_array(10);

    add_record(1);
    add_record(2);
    add_record(3);

    print_record_array();

    remove_record(1);

    print_record_array();

    return 0;
}
