    }

    // Implement concurrent access and thread safety
    pthread_t threads[num_entries];
    for (int i = 0; i < num_entries; i++) {
        int* arg = &i;
        pthread_create(&threads[i], NULL, thread_safe_function, arg);
    }
    for (int i = 0; i < num_entries; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the allocated memory
    for (int i = 0; i < num_entries; i++) {
        free(entries[i]);
    }
    free(entries);

    return 0;
}
