void* media_streaming_app(int num_frames, pthread_mutex_t* mutex) {
    // Allocate memory for array of timestamps
    uint32_t* timestamps = (uint32_t*)malloc(num_frames * sizeof(uint32_t));

    // Initialize array of char buffers
    char** buffers = (char**)malloc(num_frames * sizeof(char*));
    for (int i = 0; i < num_frames; i++) {
        buffers[i] = (char*)malloc(1024); // Assuming fixed frame size
    }

    // Create linked list of frame headers
    frame_header** frame_headers = (frame_header**)malloc(num_frames * sizeof(frame_header*));
    for (int i = 0; i < num_frames; i++) {
        frame_headers[i] = (frame_header*)malloc(sizeof(frame_header));
    }

    // Initialize and populate each frame header
    for (int i = 0; i < num_frames; i++) {
        // Set codec, stream ID, and timestamp offset
        frame_headers[i]->codec = (uint8_t)i;
        frame_headers[i]->stream_id = (uint16_t)(i * 2);
        frame_headers[i]->timestamp_offset = (int32_t)i;

        // Check for malformed frames
        if (frame_headers[i]->stream_id == (uint16_t)0x1111) {
            printf("Malformed frame detected!\n");
            continue; // Skip processing
        }
    }

    // Free allocated memory upon function completion
    for (int i = 0; i < num_frames; i++) {
        free(buffers[i]);
    }
    free(buffers);
    for (int i = 0; i < num_frames; i++) {
        free((void*)frame_headers[i]);
    }
    free(frame_headers);
    free(timestamps);

    return NULL;
}

// Helper function to detect and handle malformed frames
void check_frame(frame_header* header) {
    if (header->stream_id == (uint16_t)0x1111) {
        printf("Malformed frame detected!\n");
        // Fallback mechanism: reattempt processing after a delay
        sleep(2); // Simulate delay for demonstration purposes only
    }
}

// Helper function to adjust timestamp offset in real-time
void adjust_timestamp(frame_header* header, int latency) {
    header->timestamp_offset += (int32_t)latency;
}
