        nfa_pds[i].RNTI = rand() % 256;
        nfa_pds[i].CRC_INDICATION_REL8_TAG = rand() % 1024;

        // Set CRCFLAG based on pseudo-random number generator
        unsigned int seed = time(NULL) + (int)rand();
        srand(seed);
        nfa_pds[i].CRCFLAG = rand() % 2;
    }

    // Manage tiered pool allocator for records, keys, and alignment headers
    size_t record_size = sizeof(record);
    size_t key_size = sizeof(int);
    size_t alignment_header_size = sizeof(long);

    // Initialize dynamic list of `Task` structures
