        free(nfa_pds);
        free(records);
        free(keys);
        free(offsets);
        return;
    }

    // Integrate with external event-driven system
    // ...
}

int is_prime(int n) {
    if (n <= 1) return 0;

    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return 0;
    }

    return 1;
}
