        switch (c) {
            case 'h':
                printf("Usage: %s [-o output_file] [input_file]\n", argv[0]);
                return 0;
            case 'o':
                printf("Output file specified: %s\n", optarg);
                break;
            default:
                if (optind < argc) {
                    printf("Input file specified: %s\n", argv[optind]);
                    int num_lines = 0;
                    FILE *fp = fopen(argv[optind], "r");
                    if (fp != NULL) {
                        while (fseek(fp, 0, SEEK_END) == 0 && feof(fp)) {
                            num_lines++;
                            fseek(fp, 0, SEEK_SET);
                        }
                        fclose(fp);
                        printf("Number of lines: %d\n", num_lines);
                    } else {
                        printf("Error opening file.\n");
                    }
                } else {
                    printf("No input file provided. Please specify an input file or use the -h option for help.\n");
                }
        }
    }

    return 0;
}
