#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

// Define record structure with padding for cache alignment
typedef struct {
    int value;
    int *key;
} record;

record* allocate_records(int num_records, long min_value, long max_value) {
    // Calculate the total size required for records and keys
    int total_size = (num_records * sizeof(record)) + (3 * num_records * sizeof(int));

    // Check if system has enough memory
    if (total_size > (50LL * 1024LL * 1024LL) && munmap(NULL, total_size) == -1) {
        printf("Error: System does not have enough physical memory.\n");
        return NULL;
    }

    record* records = (record*)malloc(total_size);
    int* keys = (int*)malloc(3 * num_records * sizeof(int));

    // Initialize records and keys
    for (int i = 0; i < num_records; i++) {
        records[i].value = generate_prime_value(min_value, max_value);
        records[i].key = &keys[3 * i];
    }

    return records;
}

// Helper function to check primality of a number
int is_prime(int n) {
    if (n <= 1)
        return 0;

