// Function to populate each record with a unique int value within specified range [min_value, max_value]
void init_records_values(int min_value, int max_value) {
    if (min_value >= max_value) {
        printf("Error: Invalid range for records values.\n");
        return;
    }

    // Calculate the initial size for records array
    int num_records = max_value - min_value + 1;

    // Initialize each record with a unique value within the specified range
    for (int i = min_value; i <= max_value; i++) {
        // Ensure that no two adjacent records have consecutive values
        if (i % 2 == min_value % 2) {
            continue;
        }

        // Populate the record with the unique value and check primality
        int value = find_prime(i);
        if (value != -1) {
