                records[j].value = value;
            }
        } else {
            printf("Error: Unable to populate records with unique values.\n");
            return;
        }
    }

    // Ensure that the sum of all record values is a prime number
    int total_value = 0;
    for (int i = min_value; i <= max_value; i++) {
        total_value += records[i - min_value].value;
    }
    if (!is_prime(total_value)) {
        printf("Error: Sum of record values is not a prime number.\n");
    }
}

// Helper function to check primality
int find_prime(int n) {
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return -1;
        }
    }
    return n;
}

// Helper function to check if a number is prime
int is_prime(int n) {
    if (n < 2) {
        return 0;
    }
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return 0;
        }
    }
    return 1;
}
