void initArraysAndRecords(int* offsets, long* keys, record** records, int* count, int threshold) {
    // Dynamic allocation for arrays
    int offsetsSize = 10;
    *offsets = (long*)malloc(offsetsSize * sizeof(long));
    int keysSize = 10;
    *keys = (int*)malloc(keysSize * sizeof(int));

    // Initialize offset array
    for (int i = 0; i < offsetsSize; i++) {
        (*offsets)[i] = i;
    }

    // Sort key array in ascending order
    for (int i = 0; i < keysSize; i++) {
        for (int j = i + 1; j < keysSize; j++) {
            if ((*keys)[i] > (*keys)[j]) {
                long temp = (*keys)[i];
                (*keys)[i] = (*keys)[j];
                (*keys)[j] = temp;
            }
        }
    }

    // Dynamic allocation for record array
    *records = (record**)malloc(10 * sizeof(record));
    *count = 0;

    // Initialize records and set values within range
    srand(time(NULL));
    int recordsSize = 10;
    while (*count < threshold) {
        if (*count >= recordsSize) {
            recordsSize *= 2;
            *records = (record*)realloc(*records, recordsSize * sizeof(record));
        }
        record newRecord;
        newRecord.value = rand() % 100; // Random value within range
        (*records)[*count] = newRecord;
        (*count)++;
    }

    // Free allocated memory
    free(*offsets);
    free(*keys);
    for (int i = 0; i < *count; i++) {
        free(&((*records)[i]));
    }
    free(*records);
}

