        fwrite(request->certificates, 1, request->size, pemHandle);
        fwrite(request->privateKeys, 1, request->size, pemHandle);
        fclose(pemHandle);
    }

    // Monitor memory usage
    if (request->memUsage > (double)request->availableRAM * 0.6) {
        printf("Memory warning: %f%%\n", request->memUsage / request->availableRAM * 100);
