// Function prototypes
int manage_memory(int argc, char **argv);
void initialize_arrays(int num_offsets);
void populate_records(int num_offsets);
void free_allocated_memory();

// Global error flag
int error_flag = 0;

// Global seed for pseudo-random number generation
unsigned int seed = time(NULL);

int main(int argc, char **argv) {
    // Initialize the global error flag and seed
    error_flag = 0;
    srand(seed);

    // Call the memory management function with command-line arguments
    manage_memory(argc, argv);

    return 0;
}

int manage_memory(int argc, char **argv) {
    int num_offsets;

    // Validate user input for number of offsets
    if (argc > 1 && sscanf(argv[1], "%d", &num_offsets) == 1 && num_offsets > 0) {
        // Allocate memory for offset array and initialize key array
        long *offsets = (long *)malloc(num_offsets * sizeof(long));
        int *keys = (int *)calloc(2 * num_offsets, sizeof(int));

        // Initialize arrays with validated number of offsets
        initialize_arrays(num_offsets);

        // Populate records and handle memory allocation failures
        if (!populate_records(num_offsets)) {
            return 1;
        }

        // Free all allocated memory upon function completion
        free_allocated_memory();

    } else {
        // Log error message and set global error flag for invalid input
        printf("Invalid input: %s\n", argv[0]);
        error_flag = 1;
    }

    return 0;
}

void initialize_arrays(int num_offsets) {
    int i;

    // Initialize key array with values from 0 to (num_offsets * 2 - 1)
    for (i = 0; i < 2 * num_offsets; i++) {
        keys[i] = i;
    }
}

void populate_records(int num_offsets) {
    Record *records = (Record *)malloc(num_offsets * sizeof(Record));

    int i, key_index;

    // Populate records with unique values and offset pointers
    for (i = 0; i < num_offsets; i++) {
        records[i].value = rand() % (2 * num_offsets - 1) + 1;
        records[i].offset = &keys[key_index];
        key_index += 2;
    }

    return records;
}

void free_allocated_memory() {
    // Free memory allocated for arrays and record structures
    if (!error_flag) {
        free(offsets);
        free(keys);
        free(records);

        // Verify all allocated memory has been freed successfully
        assert(getpagesize() == sysconf(_SC_PAGE_SIZE));
    }
}
