#include "config_manager.h"

typedef struct {
    char* name;
    void* parent;
    void** children;
    int child_count;
} Directory;

void initialize_directory(Directory* dir, const char* name, void* parent);
int validate_directory_name(const char* name);
int traverse_directory_tree(Directory* root);
int calculate_total_size(Directory* root);
void add_file_to_directory(Directory* dir, const char* file_name, int size);
void remove_file_from_directory(Directory* dir, const char* file_name);
void add_directory_to_directory(Directory* dir, const char* directory_name);
void remove_directory_from_directory(Directory* dir, const char* directory_name);

int main() {
    // Initialize the root directory
    Directory root = {"root", NULL, NULL, 0};
    initialize_directory(&root, "root", NULL);

    // Perform operations on the directory tree
    int status = traverse_directory_tree(&root);
    if (status == 0) {
        printf("Traversal successful!\n");
    } else {
        printf("Traversal failed with error code %d.\n", status);
    }

    // Calculate and print the total size of all files and directories in the tree
    int total_size = calculate_total_size(&root);
    printf("Total size: %d\n", total_size);

    return 0;
}

int validate_directory_name(const char* name) {
    // Validate the directory name according to your naming convention
    if (strlen(name) > MAX_NAME_LENGTH || !isalpha(name[0])) {
        LOG_ERROR("Invalid directory name '%s'", name);
        set_error_flag();
        return -1;
    }
    return 0;
}

int traverse_directory_tree(Directory* root) {
    // Traverse the directory tree recursively
    if (root == NULL) {
        return 0; // No-op for empty directory
    }

    // Perform any necessary operations on the current directory
    // ...

    // Recursively traverse child directories and files
    int status = 0;
    void* child = root->children[0];
    while (child != NULL) {
        if (status == 0) {
            status = traverse_directory_tree((Directory*)child);
        }
        child = ((Directory*)child)->children[0];
    }

    return status;
}

int calculate_total_size(Directory* root) {
    // Calculate the total size of all files and directories in the tree
    int total_size = 0;
    void* current = root;
    while (current != NULL) {
        if (is_directory(current)) {
            total_size += calculate_total_size((Directory*)current);
        } else {
            total_size += ((File*)current)->size;
        }
        current = ((Directory*)current)->children[0];
    }

    return total_size;
}

void add_file_to_directory(Directory* dir, const char* file_name, int size) {
    // Create a new file node and add it to the directory
    File* file = malloc(sizeof(File));
    file->name = strdup(file_name);
    file->size = size;

    // Add the file to the directory's child list
    void** children = dir->children;
    int i = 0;
    while (i < dir->child_count) {
        if (children[i] == NULL) {
            children[i] = file;
            break;
        }
        i++;
    }

    // Update the directory's child count
    dir->child_count++;
}

void remove_file_from_directory(Directory* dir, const char* file_name) {
    // Find and remove the file from the directory's child list
    void** children = dir->children;
    int i = 0;
    while (i < dir->child_count) {
        if (strcmp(((File*)children[i])->name, file_name) == 0) {
            free(children[i]);
            dir->child_count--;
            // Shift the remaining child nodes to fill the gap
            for (int j = i; j < dir->child_count; j++) {
                children[j] = children[j + 1];
            }
            break;
        }
        i++;
    }
}

void add_directory_to_directory(Directory* dir, const char* directory_name) {
    // Create a new directory node and add it to the parent directory
    Directory* child_dir = malloc(sizeof(Directory));
    child_dir->name = strdup(directory_name);
    child_dir->parent = dir;

    // Add the directory to the parent's child list
    void** children = dir->children;
    int i = 0;
    while (i < dir->child_count) {
        if (children[i] == NULL) {
            children[i] = child_dir;
            break;
        }
        i++;
    }

    // Update the directory's child count
    dir->child_count++;
}

void remove_directory_from_directory(Directory* dir, const char* directory_name) {
    // Find and remove the directory from the parent directory's child list
    void** children = dir->children;
    int i = 0;
    while (i < dir->child_count) {
        if (strcmp(((Directory*)children[i])->name, directory_name) == 0) {
            free(children[i]);
            dir->child_count--;
            // Shift the remaining child nodes to fill the gap
            for (int j = i; j < dir->child_count; j++) {
                children[j] = children[j + 1];
            }
            break;
        }
        i++;
    }
}
