// Function to manage memory allocation and initialization
void* initDynamicRecords(int capacity) {
    // Calculate the total size of records in bytes (assuming sizeof(Record) == 12)
    int totalSize = capacity * sizeof(Record);

    // Allocate memory for dynamic array of records
    void* recordArray = malloc(totalSize);

    if (!recordArray) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize the first record (if any)
    Record* head = (Record*) recordArray;

    return recordArray;
