// Function to add a new record to the dynamic array
void addRecord(void* records, int key, long offset) {
    // Calculate the number of existing records
    int capacity = 0;
    if (records) {
        Record* head = (Record*) records;
        while (head->key != -1) {  // -1 indicates end of array
            capacity++;
            head++;
        }
    }

    // Check for reaching maximum capacity
    if (capacity >= 10000) {
        printf("Maximum capacity reached. Cannot add more records.\n");
        return;
    }

    // Add the new record to the dynamic array
    Record* tail = (Record*) records + capacity;
    tail->key = key;
    tail->offset = offset;

    // Update the last record's key with -1 to indicate end of array
    head->key = -1;
}

// Function to retrieve a record based on its integer key
void getRecord(void* records, int key) {
    Record* head = (Record*) records;
    while (head->key != -1) {
        if (head->key == key) {
            printf("Found record with key %d and offset %ld\n", key, head->offset);
            return;
        }
        head++;
    }

    printf("Record not found.\n");
}

int main() {
    void* records = initDynamicRecords(10000);

    // Example usage
    addRecord(records, 1, 0x12345678L);
    addRecord(records, 2, 0x23456789L);
    getRecord(records, 1);

    return 0;
}
