#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the maximum capacity of records
#define MAX_CAPACITY 10000

// Define the structure for a record
typedef struct {
    int key;
    long offset;
} Record;

// Define the dynamic array to store records
Record *records = NULL;
int record_count = 0;

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to manage memory allocation and initialization
void *init_records() {
    // Allocate memory for the first chunk of records
    int initial_capacity = 100;
    Record *initial_records = (Record *)malloc(initial_capacity * sizeof(Record));
    if (!initial_records) {
        return NULL; // Handle memory allocation error
    }

    return initial_records;
}

// Function to add a new record
void add_record(int key, long offset) {
    pthread_mutex_lock(&mutex);

    // Check if the maximum capacity is reached
    if (record_count >= MAX_CAPACITY) {
        fprintf(stderr, "Error: Maximum capacity of %d records reached\n", MAX_CAPACITY);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Allocate memory for a new record
    Record *new_records = NULL;
    if (record_count + 1 > sizeof(records) / sizeof(Record)) {
        int new_capacity = record_count * 2 + 100;
        free(records);
        records = (Record *)malloc(new_capacity * sizeof(Record));
    }

    // Add the new record
    Record *new_record = &records[record_count++];
    new_record->key = key;
    new_record->offset = offset;

    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a record by its integer key
Record *get_record(int key) {
    pthread_mutex_lock(&mutex);

    // Search for the record with the matching key
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            Record *found_record = &records[i];
            pthread_mutex_unlock(&mutex);
            return found_record;
        }
    }

    pthread_mutex_unlock(&mutex);
