function analyzeSoftwareFrameworks(text) {
  const frameworks = [
    /react|angular|vue\.js/i,
    /node\.js/i,
    // Add more framework patterns here
  ];

  const report = {};

  text.toLowerCase().split(/[^a-z0-9]+/).forEach((word) => {
    if (word.length > 3) { // Ignore short words like "the", etc.
      frameworks.forEach((pattern) => {
        if (new RegExp(pattern).test(word)) {
          const framework = pattern.source.replace(/^\/|\/$/g, '').replace(/_/g, ' ');
          report[framework] = (report[framework] || 0) + 1;
        }
      });
    }
  });

  return report;
}
