#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define BLOCK_SIZE 1024
#define LOG_BUFFER_SIZE 256

typedef struct {
    int key;
    long offset;
} Record;

Record* records = NULL;
int record_count = 0;
int block_size = 0;
int current_block = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = NULL;

void* allocate_record(int key, long offset) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    return new_record;
}

int insert_record(int key, long offset) {
    if (record_count >= MAX_RECORDS) {
        printf("Error: Maximum records reached.\n");
        return -1;
    }

    Record* new_record = allocate_record(key, offset);

    pthread_mutex_lock(&lock);
    if (current_block * BLOCK_SIZE + sizeof(Record) > record_count * sizeof(Record)) {
        block_size += BLOCK_SIZE;
        current_block++;
    }
    memcpy((void*)(((char*)records) + (record_count++) * sizeof(Record)), new_record, sizeof(Record));
    pthread_mutex_unlock(&lock);

    return 0;
}

int log_insertion(int key, long offset) {
    char buffer[LOG_BUFFER_SIZE];
    sprintf(buffer, "Inserted record with key %d and offset %ld at time %f\n", key, offset, (double)time(NULL));
    fwrite(buffer, 1, strlen(buffer), log_file);
    return 0;
}

void* monitor_thread(void* arg) {
    while (1) {
        sleep(60); // Monitor every minute
        int available_memory = (int)(getpagesize() * (block_size - record_count / BLOCK_SIZE));
        printf("Available memory: %d bytes\n", available_memory);

        if (available_memory < 10000) { // Adjust the block size if needed
            block_size -= BLOCK_SIZE;
            current_block--;
        }
    }

    return NULL;
}

int main() {
    records = malloc(MAX_RECORDS * sizeof(Record));
    pthread_create(&monitor_thread_id, NULL, monitor_thread, NULL);

    log_file = fopen("log.txt", "a");

    // Example usage:
    int key = 1;
    long offset = 12345;
    insert_record(key, offset);
    log_insertion(key, offset);

    return 0;
}
