    time_t last_modified;
    int permissions;
    int reference_count;
} file_metadata;

void* manage_directory(int flag) {
    // Allocate memory for arrays
    double* version_timestamps = (double*)malloc(256 * sizeof(double));
    char** file_paths = (char**)calloc(256, sizeof(char*));
    file_info* file_list = (file_info*)malloc(256 * sizeof(file_info));
    file_metadata* metadata_list = (file_metadata*)malloc(256 * sizeof(file_metadata));

    // Initialize arrays
    for (int i = 0; i < 256; i++) {
        version_timestamps[i] = (double)i;
        file_paths[i] = (char*)malloc(257);
        file_paths[i][0] = '\0';  // Null-terminate string
        file_list[i].timestamp = time(NULL);
        file_list[i].size = i * 1024;  // File size in bytes, incremented by 1KB for each subsequent file
        metadata_list[i].last_modified = file_list[i].timestamp;
        metadata_list[i].permissions = 0;  // Default permissions
        metadata_list[i].reference_count = 0;

        pthread_mutex_init(&metadata_list[i].lock, NULL);  // Initialize mutex for each file
    }

    if (flag == 1) {
        // Clear allocated resources when flag is set to 1
        for (int i = 0; i < 256; i++) {
            free(file_paths[i]);
            pthread_mutex_destroy(&metadata_list[i].lock);
        }
        free(version_timestamps);
        free(file_paths);
        free(file_list);
        free(metadata_list);
    }

    return NULL;
}

