        filePathArray = (char**)malloc(NUM_FILES * sizeof(char*));
        fileInfoArray = (file_info**)malloc(NUM_FILES * sizeof(file_info*));
        fileMetadataArray = (file_metadata*)malloc(NUM_FILES * sizeof(file_metadata));

        versionTimestamps = (double*)malloc(NUM_FILES * sizeof(double));

        // Initialize directory structure components
        for (int i = 0; i < numFiles; i++) {
            filePathArray[i] = (char*)malloc(MAX_FILE_PATH_LENGTH * sizeof(char));
