            fileInfoArray[i]->timestamp = i + 1.0;
            fileInfoArray[i]->fileSize = (off_t) i;

            strcpy(filePathArray[i], "/path/to/file");
        }
    }
}

void manageFileAccess(int fileId, int operation) {
    pthread_mutex_lock(&mutex);
    if (operation == 1) { // Open file
        fileMetadataArray[fileId].refCount++;
    } else if (operation == -1) { // Close file
        fileMetadataArray[fileId].refCount--;
        if (fileMetadataArray[fileId].refCount == 0) {
            free((void*) &fileMetadataArray[fileId]);
        }
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    manageDirectory(NUM_FILES, BATCH_UPDATE_SIZE);

    // Perform batch updates
    for (int i = 0; i < NUM_FILES / BATCH_UPDATE_SIZE; i++) {
        pthread_mutex_lock(&mutex);
        for (int j = i * BATCH_UPDATE_SIZE; j < (i + 1) * BATCH_UPDATE_SIZE; j++) {
            fileMetadataArray[j].lastModified += (time(NULL) - versionTimestamps[j]);
            fileInfoArray[j]->timestamp += (double) (j % 2 == 0 ? 1.0 : -1.0);
        }
        pthread_mutex_unlock(&mutex);
    }

    return 0;
}
