// Define a structure to hold process state information
typedef struct {
    pid_t pid;
    time_t start_time;
    double cpu_usage;
    size_t memory_usage;
    int* file_descriptors; // Linked list of associated file descriptors
} process_state;

// Define a structure to represent the linked list node for file descriptors
typedef struct {
    int fd;
    struct {
        struct {
            struct {
                struct {
                    struct {
                        struct {
                            struct {
                                struct {
                                    process_state* next;
                                } next;
                            } next;
                        } next;
                    } next;
                } next;
            } next;
        } next;
    } file_descriptor_node;

// Define a structure to hold the global state information
typedef struct {
    int num_processes;
    double total_cpu_usage;
    size_t total_memory_usage;
    process_state* processes; // Array of all process states
    file_descriptor_node* file_descriptors_list; // Linked list of file descriptors
} system_state;

// Function to initialize and return a new process state structure
process_state* create_process_state(pid_t pid, time_t start_time) {
    process_state* ps = (process_state*)malloc(sizeof(process_state));
    if (!ps) return NULL;
    ps->pid = pid;
    ps->start_time = start_time;
    ps->cpu_usage = 0.0;
    ps->memory_usage = 0;
    ps->file_descriptors = NULL;
    return ps;
}

// Function to update the total CPU and memory usage
void update_total_usage(system_state* sys, process_state* ps) {
    sys->total_cpu_usage += ps->cpu_usage;
    sys->total_memory_usage += ps->memory_usage;
}

// Function to add a new process state structure
int add_process(system_state* sys, pid_t pid, time_t start_time, double cpu_usage, size_t memory_usage, int num_fds) {
    process_state* ps = create_process_state(pid, start_time);
    if (!ps) return -1; // Out of memory

    ps->cpu_usage = cpu_usage;
    ps->memory_usage = memory_usage;

    file_descriptor_node* fd_list = (file_descriptor_node*)malloc((num_fds + 1) * sizeof(file_descriptor_node));
    if (!fd_list) {
        free(ps);
        return -1; // Out of memory
    }
    for (int i = 0; i < num_fds; i++) {
        file_descriptor_node* current = &fd_list[i];
        current->fd = i;
        current->next = &fd_list[i + 1];
    }

    ps->file_descriptors = fd_list;

    sys->num_processes++;
    update_total_usage(sys, ps);
    return 0; // Success
}

// Function to remove a process state structure
int remove_process(system_state* sys, pid_t pid) {
    for (int i = 0; i < sys->num_processes; i++) {
        if (sys->processes[i]->pid == pid) {
            free(sys->processes[i]->file_descriptors);
            free(sys->processes[i]);
            memmove(&sys->processes[i], &sys->processes[i + 1], (sys->num_processes - i - 1) * sizeof(process_state*));
            sys->num_processes--;
            return 0; // Success
        }
    }
    return -1; // Process not found
}

// Function to retrieve the current total CPU and memory usage
void get_total_usage(system_state* sys, double* cpu_usage, size_t* memory_usage) {
    *cpu_usage = sys->total_cpu_usage;
    *memory_usage = sys->total_memory_usage;
}

// Function to periodically collect statistics and update system state
void collect_statistics(system_state* sys, int interval) {
    // Implement periodic collection of statistics here
}

// Function to clear all allocated resources when a special flag is set
int clear_resources(system_state* sys, int flag) {
    if (flag == 1) { // Clear resources
        for (int i = 0; i < sys->num_processes; i++) {
            free(sys->processes[i]->file_descriptors);
            free(sys->processes[i]);
        }
        free(sys->processes);
        free(sys->file_descriptors_list);
    }
    return 0;
}
