} process_state;

process_state** processes = NULL; // global array of process states

void add_process(pid_t pid, time_t start_time) {
    process_state* new_process = malloc(sizeof(process_state));
    if (!new_process) {
        // handle allocation failure
        return;
    }
    new_process->pid = pid;
    new_process->start_time = start_time;
    new_process->cpu_usage = 0.0;
    new_process->memory_usage = 0;
    new_process->file_descriptors = NULL;

    process_state** processes_copy = malloc(sizeof(process_state*) * (processes ? processes : 1));
    if (!processes_copy) {
        // handle allocation failure
        free(new_process);
        return;
    }
    if (processes) {
        processes_copy[0] = processes[0];
        for (int i = 1; i < processes_copy[0]->length; i++) {
            process_state* current = processes[i];
            new_process->file_descriptors = realloc(new_process->file_descriptors, sizeof(int*) * (current->file_descriptors ? current->file_descriptors->length : 1));
            if (!new_process->file_descriptors) {
                // handle allocation failure
                free(current);
                return;
            }
        }
    } else {
        processes_copy[0] = new_process;
    }

    for (int i = 0; i < processes_copy[0]->length; i++) {
        process_state* current = processes_copy[i];
        if (!current) continue;

        if (current->file_descriptors) {
            int* temp = malloc(sizeof(int*) * (current->file_descriptors->length - 1));
            if (!temp) {
                // handle allocation failure
                free(current);
                return;
            }
            int j = 0;
            for (int k = 0; k < current->file_descriptors->length; k++) {
                if (k == i) continue;

                temp[j++] = current->file_descriptors[k];
            }
            temp[j] = NULL;
            free(current->file_descriptors);
            current->file_descriptors = temp;
        }
    }

    processes = processes_copy;
}

void update_process(pid_t pid, double cpu_usage, size_t memory_usage) {
    for (int i = 0; i < processes[0]->length; i++) {
        if (processes[i]->pid == pid) {
