    process_state** new_processes = malloc(sizeof(process_state*) * (processes ? processes->length - 1 : 0));
    if (!new_processes) {
        // handle allocation failure
        return;
    }

    for (i = 0; i < processes[0]->length; i++) {
        if (processes[i]->pid == pid) continue;

        new_processes[i] = processes[i];
    }
    free(processes);
    processes = new_processes;
}

size_t get_total_cpu_usage() {
    size_t total = 0.0;
    for (int i = 0; i < processes[0]->length; i++) {
        total += processes[i]->cpu_usage;
    }
    return total;
}

size_t get_total_memory_usage() {
    size_t total = 0;
    for (int i = 0; i < processes[0]->length; i++) {
