#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <random>

struct record {
    int key;
    long offset;
    int value;
};

void load_csv_to_records(struct record **records, size_t *record_count, FILE *file) {
    char line[1024];
    size_t count = 0;
    const char* sep = ",";

    while (fgets(line, sizeof(line), file)) {
        char* token = strtok(line, sep);
        if (!token) continue; // skip empty lines

        struct record* rec = (*records + count++);
        rec->key = atoi(token);
        token = strtok(NULL, sep);
        if (!token || sscanf(token, "%ld", &rec->offset) != 1) {
            printf("Error: invalid offset value in line '%s'\n", line);
            continue;
        }
    }

    *record_count = count;
}

int main() {
    size_t record_count = 0;
    struct record* records = NULL;

    FILE* file = fopen("data.csv", "r");
    if (!file) {
        printf("Error: failed to open data.csv\n");
        return -1;
    }

    load_csv_to_records(&records, &record_count, file);
    fclose(file);

    if (record_count == 0) {
        printf("Warning: no records loaded from CSV file\n");
    } else {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 100); // adjust range as needed

        for (size_t i = 0; i < record_count; ++i) {
            records[i].value = dis(gen);
        }
    }

    return 0;
}
