#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
    time_t timestamp;
    char status[5];
} Record;

void log_error(const char* message) {
    // Implement logging mechanism here
}

int main() {
    FILE *file = fopen("input.csv", "r");

    if (!file) {
        log_error("Failed to open input file");
        return 1;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    int numRecords = (int)(fileSize / sizeof(char) - 2); // subtract the newline character

    Record **records = (Record **)malloc(numRecords * sizeof(Record *));
    char *lineBuffer = (char *)malloc((numRecords + 1) * sizeof(char));

    int i = 0;
    while (fscanf(file, "%s", lineBuffer) == 1) {
        Record *record = (Record *)malloc(sizeof(Record));
        sscanf(lineBuffer, "%d %ld %ld %4s", &record->value, &record->offset, &record->timestamp, record->status);

        if (!record->offset || !record->timestamp) {
            log_error("Invalid record detected");
            free(record);
            continue;
        }

        records[i++] = record;
    }

    fclose(file);

    // Initialize random number generator
    srand(time(NULL));

    for (int j = 0; j < numRecords; j++) {
        records[j]->value = rand() % 100 + 1;
    }

    qsort(records, numRecords, sizeof(Record*), compare);

    FILE *outputFile = fopen("output.csv", "w");

    if (!outputFile) {
        log_error("Failed to open output file");
        return 2;
    }

    for (int k = 0; k < numRecords; k++) {
        fprintf(outputFile, "%d %ld %ld %4s\n", records[k]->value, records[k]->offset, records[k]->timestamp, records[k]->status);
        free(records[k]);
    }

    fclose(outputFile);
    free(lineBuffer);
    free(records);
    return 0;
}

int compare(const void *a, const void *b) {
    Record* record1 = *(Record**)a;
    Record* record2 = *(Record**)b;
    if (record1->timestamp > record2->timestamp)
        return -1;
    else
        return 1;
}
