#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define constants for temperature range
#define MIN_TEMP 0.0f
#define MAX_TEMP 100.0f

// Function prototypes
void parseLogFile(const char *filename, float **temp_readings, time_t **timestamps);
void scaleTemperatures(float **temperatures, int num_readings, float calibration_factor);
int filterReadings(float **temperatures, time_t **timestamps, int num_readings, float min_temp, float max_temp);
time_t* sortTimestamps(time_t *timestamps, int num_readings);
void exportFilteredReadings(const char *output_filename, float **filtered_temperatures, time_t *filtered_timestamps, int num_filtered_readings);

int main() {
    // Initialize variables
    const char *log_filename = "sensor_log.txt";
    const char *output_filename = "filtered_readings.log";
    float calibration_factor = 1.0f;
    float min_temp = MIN_TEMP;
    float max_temp = MAX_TEMP;

    // Read data from log file and allocate memory for arrays
    int num_readings;
    float **temperatures;
    time_t **timestamps;
    parseLogFile(log_filename, &temperatures, &timestamps);
    printf("Number of readings: %d\n", num_readings);

    // Scale temperatures based on calibration factor
    scaleTemperatures(temperatures, num_readings, calibration_factor);

    // Filter out readings that fall outside the specified temperature range
    int num_filtered_readings = filterReadings(temperatures, timestamps, num_readings, min_temp, max_temp);
    printf("Number of filtered readings: %d\n", num_filtered_readings);

    // Sort filtered readings based on timestamp field
    time_t *sorted_timestamps = sortTimestamps(*timestamps, num_filtered_readings);

    // Export filtered and sorted readings to new log file
    exportFilteredReadings(output_filename, temperatures, &sorted_timestamps, num_filtered_readings);

    return 0;
}

void parseLogFile(const char *filename, float **temp_readings, time_t **timestamps) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    int num_readings = 0;
    while (!feof(file)) {
        // Read line and tokenize it
        char line[1024];
        fgets(line, sizeof(line), file);

        // Extract timestamp and temperature from line
        time_t timestamp;
        float temperature;

        // Handle malformed entries
        if (sscanf(line, "%ld %f", &timestamp, &temperature) != 2) {
            printf("Error parsing log entry: %s\n", line);
            continue;
        }

        // Allocate memory for new arrays
        *temp_readings = realloc(*temp_readings, sizeof(float) * (num_readings + 1));
        *timestamps = realloc(*timestamps, sizeof(time_t) * (num_readings + 1));

        (*temp_readings)[num_readings] = temperature;
        (*timestamps)[num_readings++] = timestamp;

        // Handle memory allocation errors
        if (!*temp_readings || !*timestamps) {
            printf("Error allocating memory for arrays\n");
            break;
        }
    }

    fclose(file);
}

void scaleTemperatures(float **temperatures, int num_readings, float calibration_factor) {
    for (int i = 0; i < num_readings; i++) {
        (*temperatures)[i] *= calibration_factor;
    }
}

int filterReadings(float **temperatures, time_t **timestamps, int num_readings, float min_temp, float max_temp) {
    int num_filtered_readings = 0;
    for (int i = 0; i < num_readings; i++) {
        if ((*temperatures)[i] >= min_temp && (*temperatures)[i] <= max_temp) {
            // Filtered readings are stored in separate arrays
            float *filtered_temperatures = malloc(sizeof(float));
            time_t *filtered_timestamps = malloc(sizeof(time_t));

            filtered_temperatures[0] = (*temperatures)[i];
            filtered_timestamps[0] = (*timestamps)[i];

            // Reallocate memory for filtered arrays
            (*temperatures) = realloc(*temperatures, sizeof(float) * (num_filtered_readings + 1));
            (*timestamps) = realloc(*timestamps, sizeof(time_t) * (num_filtered_readings + 1));

            (*temperatures)[num_filtered_readings] = filtered_temperatures[0];
            (*timestamps)[num_filtered_readings++] = filtered_timestamps[0];

            free(filtered_temperatures);
            free(filtered_timestamps);

            // Handle memory allocation errors
            if (!*temperatures || !*timestamps) {
                printf("Error allocating memory for filtered arrays\n");
                return num_filtered_readings;
            }
        }
    }

    return num_filtered_readings;
}

time_t* sortTimestamps(time_t *timestamps, int num_readings) {
    time_t *sorted_timestamps = malloc(sizeof(time_t) * num_readings);
    for (int i = 0; i < num_readings; i++) {
        sorted_timestamps[i] = timestamps[i];
    }

    qsort(sorted_timestamps, num_readings, sizeof(time_t), time_t_comparator);

    return sorted_timestamps;
}

void exportFilteredReadings(const char *output_filename, float **filtered_temperatures, time_t *filtered_timestamps, int num_filtered_readings) {
    FILE *file = fopen(output_filename, "w");
    if (file == NULL) {
        printf("Error opening output file: %s\n", output_filename);
        return;
    }

    for (int i = 0; i < num_filtered_readings; i++) {
        fprintf(file, "%ld %.2f\n", filtered_timestamps[i], filtered_temperatures[i]);
    }

    fclose(file);
}
