#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    float temperature;
    char* metadata;
} Reading;

int main() {
    // Function implementation
    void processReadings(const char* filename, int calibrationFactor, float minTemp, float maxTemp, const char* metadataFilter) {
        FILE* file = fopen(filename, "r");
        if (!file) {
            printf("Error opening file\n");
            return;
        }

        // Initialize arrays and pointers
        Reading** readings = (Reading**)malloc(sizeof(Reading*) * 10);
        time_t* timestamps = (time_t*)malloc(sizeof(time_t) * 10);
        float* temperatures = (float*)malloc(sizeof(float) * 10);
        char** metadata = (char**)malloc(sizeof(char*) * 10);

        int i = 0;
        while (fscanf(file, "%ld %f %s", &timestamps[i], &temperatures[i], &metadata[i]) == 3) {
            i++;
        }

        fclose(file);

        // Scale temperatures
        for (int j = 0; j < i; j++) {
            temperatures[j] *= calibrationFactor;
        }

        // Filter readings
        int countInRange = 0, countOutRange = 0;
        for (int k = 0; k < i; k++) {
            if (temperatures[k] >= minTemp && temperatures[k] <= maxTemp) {
                if (strlen(metadata[k]) > 0 && !strcasestr(metadata[k], metadataFilter)) continue;
                countInRange++;
            } else {
                countOutRange++;
            }
        }

        // Report to API
        printf("Readings in range: %d, out of range: %d\n", countInRange, countOutRange);

        // Sort readings
        Reading* sortedReadings = (Reading*)malloc(sizeof(Reading) * i);
        for (int l = 0; l < i; l++) {
            sortedReadings[l].timestamp = timestamps[l];
            sortedReadings[l].temperature = temperatures[l];
            sortedReadings[l].metadata = metadata[l];
        }
        qsort(sortedReadings, i, sizeof(Reading), (int (*)(const void*, const void*))compare);

        // Export filtered and sorted readings
        FILE* output = fopen("output.log", "w");
        for (int m = 0; m < i; m++) {
            fprintf(output, "%ld %f %s\n", sortedReadings[m].timestamp, sortedReadings[m].temperature, sortedReadings[m].metadata);
        }
        fclose(output);

        // Archive old readings
        system("mv old.log new.log");
    }

    int compare(const void* a, const void* b) {
        const Reading* readingA = (const Reading*)a;
        const Reading* readingB = (const Reading*)b;

        if (readingA->timestamp < readingB->timestamp)
            return -1;
        else if (readingA->timestamp > readingB->timestamp)
            return 1;

        return 0;
    }
