typedef struct {
    int key;
    long offset;
} Record;

Record* initializeRecords(size_t count) {
    Record* records = malloc(count * sizeof(Record));
    if (!records) return NULL;
    for (size_t i = 0; i < count; ++i) {
        records[i].key = rand() % 1000;
        records[i].offset = rand() % 1000000;
    }
    return records;
}

EVP_CIPHER_CTX* processData(char* inputString, int commandOption) {
    size_t recordsCount = 500;
    Record* records = initializeRecords(recordsCount);
    if (!records) return NULL;

    EVP_CIPHER_CTX* cipherCtx = EVP_CIPHER_CTX_new();
    if (!cipherCtx) {
        free(records);
        return NULL;
    }

    // Perform initialization based on commandOption
    if (commandOption == 1) {
        // Example initialization for encryption
        if (EVP_EncryptInit_ex(cipherCtx, EVP_aes_256_cbc(), NULL, NULL, NULL) != 1) {
            EVP_CIPHER_CTX_free(cipherCtx);
            free(records);
            return NULL;
        }
    } else if (commandOption == 2) {
        // Example initialization for decryption
        if (EVP_DecryptInit_ex(cipherCtx, EVP_aes_256_cbc(), NULL, NULL, NULL) != 1) {
            EVP_CIPHER_CTX_free(cipherCtx);
            free(records);
            return NULL;
        }
    } else {
        EVP_CIPHER_CTX_free(cipherCtx);
        free(records);
        return NULL;
    }

    // Perform operations on inputString using cipherCtx
    if (commandOption == 1) {
        size_t outLen = strlen(inputString) + EVP_MAX_BLOCK_LENGTH;
        unsigned char* output = malloc(outLen);
        unsigned int len = 0;
        if (!EVP_EncryptUpdate(cipherCtx, output, &len, inputString, strlen(inputString))) {
            free(output);
            EVP_CIPHER_CTX_free(cipherCtx);
            free(records);
            return NULL;
        }
        while (1) {
            unsigned char buffer[EVP_MAX_BLOCK_LENGTH];
            len = EVP_EncryptFinal_ex(cipherCtx, buffer, &len);
            if (!len) break;
            output += len;
            memcpy(output, buffer, len);
            output += len;
        }
    } else if (commandOption == 2) {
        size_t outLen = strlen(inputString) + EVP_MAX_BLOCK_LENGTH;
        unsigned char* output = malloc(outLen);
        unsigned int len = 0;
        if (!EVP_DecryptUpdate(cipherCtx, output, &len, inputString, strlen(inputString))) {
            free(output);
            EVP_CIPHER_CTX_free(cipherCtx);
            free(records);
            return NULL;
        }
        while (1) {
            unsigned char buffer[EVP_MAX_BLOCK_LENGTH];
            len = EVP_DecryptFinal_ex(cipherCtx, buffer, &len);
            if (!len) break;
            output += len;
            memcpy(output + len, buffer, len);
            output += len;
        }
    }

    EVP_CIPHER_CTX_free(cipherCtx);
    free(records);
    return cipherCtx;
}
