void close_inactive_connections() {
    for (int i = 0; i < num_connections; i++) {
        if (strlen(connections[i].status) == 0) {
            // Close the socket
            close(connections[i].sock_descriptor);
            free(connections[i]);
            connections[i] = connections[--num_connections];
            i--;
        }
    }
}

void *allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL || num_connections >= MAX_CONNECTIONS) {
        // Handle resource exhaustion
        return NULL;
    }
    return ptr;
}

