        return -1;
    }
    fclose(file);
    return 0;
}

char* randomString(int length, int maxLength) {
    char* result = (char*)malloc((length + 1) * sizeof(char));
    for(int i = 0; i < length; i++) {
        *(result + i) = 'a' + rand() % ('z' - 'a' + 1);
    }
    *(result + length) = '\0';
    return result;
