#define MAX_RECORDS 1024
#define MAX_FILE_NAME 256
#define MAX_DATA_SIZE 256
#define RANDOM_KEY_RANGE 1000

typedef struct {
    char path[MAX_FILE_NAME];
    time_t lastModified;
    mode_t permissions;
} fileMetadata;

typedef struct {
    long offset;
    int key;
    char data[MAX_DATA_SIZE];
    fileMetadata *metadata;
    void *encryptedData;
} record;

record *processData(int numFiles, char **filePaths) {
    srand(time(NULL));

    // Initialize counts
    int successfulOps = 0;
    int unsuccessfulOps = 0;

    // Initialize records
    record *records = (record *)malloc(sizeof(record) * MAX_RECORDS);
    int recordCount = 0;

    // Process each file
    for (int i = 0; i < numFiles; i++) {
        char filePath[MAX_FILE_NAME];
        sprintf(filePath, "%s", filePaths[i]);

        // Initialize record
        record *record = &records[recordCount++];
        record->offset = rand() % RANDOM_KEY_RANGE;
        record->key = rand() % RANDOM_KEY_RANGE;
        memset(record->data, 0, MAX_DATA_SIZE);

        // Read file data
        FILE *file = fopen(filePath, "rb");
        if (file) {
            successfulOps++;
            fseek(file, 0, SEEK_END);
            int fileSize = ftell(file);
            rewind(file);
            fread(record->data, 1, MIN(fileSize, MAX_DATA_SIZE), file);
            fclose(file);
        } else {
            unsuccessfulOps++;
            printf("Failed to read file: %s\n", filePath);
            record->metadata = (fileMetadata *)malloc(sizeof(fileMetadata));
            strcpy(record->metadata->path, filePath);
            time(&record->metadata->lastModified);
            record->metadata->permissions = 0;
        }
    }

    // Initialize structure to return
    record *result = (record *)malloc(sizeof(record) + sizeof(int) * 2);
    result->records = records;
    result->successfulOps = successfulOps;
    result->unsuccessfulOps = unsuccessfulOps;

    // Optional encryption support
    if (/* some condition */) {
        // Encrypt data
        for (int i = 0; i < recordCount; i++) {
            record *record = &records[i];
            record->encryptedData = /* encrypt record data */;
        }
    }

    return result;
}
