    new_p->start_time = time(NULL);
    new_p->cpu_usage = 0.0;
    new_p->mem_usage = 0;
    new_p->file_descs = NULL;

    if (num_processes >= sizeof(*processes) / sizeof(process_state*)) {
        // handle memory allocation failure
        printf("Memory allocation failed!\n");
        return NULL; 
    }

    processes[num_processes++] = new_p;
    add_process_to_log(new_p, "Added");

    return new_p;
}

int update_process(process_state** processes, const process_state* p) {
    int i;
    for (i = 0; i < num_processes; i++) {
        if (processes[i]->pid == p->pid) {
            // update the process state
            processes[i]->cpu_usage += p->cpu_usage;
            processes[i]->mem_usage += p->mem_usage;
            return 1;
        }
    }

    printf("Process not found!\n");
    return -1; 
}

int remove_process(process_state** processes, const pid_t pid) {
    int i;
    for (i = 0; i < num_processes; i++) {
        if (processes[i]->pid == pid) {
            // remove the process
            free(processes[i]->file_descs);
            free(processes[i]);
            return 1;
        }
    }

    printf("Process not found!\n");
    return -1; 
}

double get_total_cpu_usage() {
    double total = 0.0;
    for (int i = 0; i < num_processes; i++) {
        total += processes[i]->cpu_usage;
    }
    return total;
}

size_t get_total_mem_usage() {
    size_t total = 0;
    for (int i = 0; i < num_processes; i++) {
        total += processes[i]->mem_usage;
    }
    return total;
}

void collect_statistics(int interval, double* avg_cpu_usage, size_t* avg_mem_usage) {
    // calculate the average usage
    *avg_cpu_usage = get_total_cpu_usage() / (double)num_processes;
    *avg_mem_usage = get_total_mem_usage() / num_processes;

    printf("Average CPU Usage: %.2f\n", *avg_cpu_usage);
    printf("Average Memory Usage: %zu\n", *avg_mem_usage);

    // schedule the next collection
    sleep(interval);
}

void init_logging(int fd) {
    log_fd = fd;
}

void log_operation(const char* action, const process_state* p, const char* message) {
    if (log_fd != -1) {
        fwrite(message, strlen(message), 1, log_fd);
        fflush(log_fd);
    }
}
