// Initialize the process state collection and logging mechanism
process_state_collection* init_process_state_collection();

// Add a new process to the collection
int add_process(process_state_collection* collection, pid_t pid, time_t start_time, double cpu_usage, size_t memory_usage);

// Update an existing process's state in the collection
int update_process(process_state_collection* collection, pid_t pid, double cpu_usage, size_t memory_usage);

// Remove a process from the collection
int remove_process(process_state_collection* collection, pid_t pid);

// Retrieve the current total CPU and memory usage across all processes
void get_total_usage(process_state_collection* collection, double* total_cpu_usage, size_t* total_memory_usage);

// Periodically collect statistics on average CPU and memory usage over specified intervals
void collect_statistics(process_state_collection* collection, time_t interval);

// Set up the monitoring system for process state collection health and performance
int setup_monitoring_system(process_state_collection* collection);

// Monitor the process state collection for thresholds exceeded and alert accordingly
void monitor_process_state_collection(process_state_collection* collection);

// Define process state collection structure
typedef struct {
    int size;
    process_state** states;
    pthread_mutex_t mutex;
} process_state_collection;

process_state_collection* init_process_state_collection() {
    // Initialize the process state collection with a default size
    process_state_collection* collection = (process_state_collection*)malloc(sizeof(process_state_collection));
    collection->size = 10; // Default size for the collection
    collection->states = (process_state**)calloc(collection->size, sizeof(process_state*));
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

int add_process(process_state_collection* collection, pid_t pid, time_t start_time, double cpu_usage, size_t memory_usage) {
    // Allocate a new process state structure
    process_state* state = (process_state*)malloc(sizeof(process_state));
    state->pid = pid;
    state->start_time = start_time;
    state->cpu_usage = cpu_usage;
    state->memory_usage = memory_usage;
    int file_descriptors_size = 5; // Default size for the linked list of file descriptors
    state->file_descriptors = (int*)malloc(file_descriptors_size * sizeof(int));
    // Add the new process to the collection and update statistics
    if (!collection->states[collection->size - 1]) {
        // Initialize the new process state
        state->file_descriptors[0] = -1; // Mark as not allocated
    } else {
        // Update the last added process's state in the collection
        process_state* prev_state = collection->states[collection->size - 2];
        // Copy file descriptors from previous process to new one
        int i;
        for (i = 0; i < file_descriptors_size; i++) {
            if (!prev_state->file_descriptors[i]) {
                break;
            }
            state->file_descriptors[i] = prev_state->file_descriptors[i];
        }
    }
    collection->states[collection->size - 1] = state;
    pthread_mutex_lock(&collection->mutex);
    // Update total CPU and memory usage
    double total_cpu_usage = 0.0; // Accumulate CPU usage across all processes
    size_t total_memory_usage = 0.0; // Accumulate memory usage across all processes
    for (int i = 0; i < collection->size; i++) {
        process_state* state = collection->states[i];
        if (state) {
            total_cpu_usage += state->cpu_usage;
            total_memory_usage += state->memory_usage;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return 1;
}

int update_process(process_state_collection* collection, pid_t pid, double cpu_usage, size_t memory_usage) {
    // Find the process with matching PID and update its state
    for (int i = 0; i < collection->size; i++) {
        process_state* state = collection->states[i];
        if (state && state->pid == pid) {
            state->cpu_usage = cpu_usage;
            state->memory_usage = memory_usage;
            return 1; // Process found and updated
        }
    }
    return -1; // Process not found
}

int remove_process(process_state_collection* collection, pid_t pid) {
    // Find the process with matching PID and remove it from the collection
    for (int i = 0; i < collection->size; i++) {
        process_state* state = collection->states[i];
        if (state && state->pid == pid) {
            free(state);
            collection->states[i] = NULL;
            return 1; // Process found and removed
        }
    }
    return -1; // Process not found
}

void get_total_usage(process_state_collection* collection, double* total_cpu_usage, size_t* total_memory_usage) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->size; i++) {
        process_state* state = collection->states[i];
        if (state) {
            *total_cpu_usage += state->cpu_usage;
            *total_memory_usage += state->memory_usage;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

