        for (int i = 0; i < MAX_FILES; i++) {
            free(filePaths[i]);
            pthread_mutex_destroy(&fileMetadata[i].lock);
        }
        free(versions);
        free(filePaths);
        free(fileMetadata);
        free(fileInfo);
    }

    va_end(args);
}

