// Custom LRU cache mechanism for efficient data retrieval
#include <list>
#include <unordered_map>

using namespace std;

class LRUCache {
public:
    LRUCache(int capacity) : cap(capacity), size(0) {}

    void set(const string& key, const string& value) {
        if (size >= cap) {
            // Remove the least recently used entry
            auto it = cache.begin();
            cache.erase(it);
            --size;
        }

        // Update or add a new entry
        pair<unordered_map<string, string>::iterator, bool> ret = cache.insert(pair<string, string>(key, value));
        if (!ret.second) {
            // Update the accessed time for this key
            ret.first->second = value;
        }
    }

    string get(const string& key) {
        auto it = cache.find(key);
        if (it != cache.end()) {
            // Mark the entry as recently used
            it->second = "visited";
            return it->first;
        } else {
            return "";
        }
    }

private:
    int cap;
    int size;
    list<pair<string, string>> cache;
};

