#include <string.h>

typedef struct {
    int val;
} record;

int main() {
    FILE *fp = fopen("input.txt", "r");
    if (!fp) {
        printf("Error opening file\n");
        return 1;
    }

    record *records = NULL;
    int total_records = 0;
    char *line = NULL;
    size_t line_len = 0;

    while (getline(&line, &line_len, fp) != -1) {
        int *nums = NULL;
        size_t num_count = 0;
        char *token = strtok(line, " ");
        while (token) {
            nums = realloc(nums, (num_count + 1) * sizeof(int));
            *(nums + num_count++) = atoi(token);
            token = strtok(NULL, " ");
        }
        int last_two_sum = 0;
        for (int i = num_count - 2; i >= 0; i--) {
            last_two_sum += nums[i];
        }
        record *record_ptr = malloc(sizeof(record));
        record_ptr->val = last_two_sum / 2;
        if (!records) {
            records = record_ptr;
            total_records++;
        } else {
            record_ptr->next = NULL;
            record *temp = records;
            while (temp->next) temp = temp->next;
            temp->next = record_ptr;
            total_records++;
        }
        free(nums);
    }

    fclose(fp);

    fp = fopen("output.txt", "w");
    if (!fp) {
        printf("Error opening file\n");
        return 1;
    }

    record *temp = records;
    while (temp) {
        fprintf(fp, "%d,", temp->val);
        free(temp);
        temp = temp->next;
    }
    fclose(fp);

    return 0;
}
