    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int main() {
    FILE *fp = fopen("input.txt", "r");
    if (!fp) return 1;

    record_t *records = NULL;
    int records_len = 0;
    NFAPI_CRC_INDICATION_PDU_T *nfapis = NULL;
    int nfapis_len = 0;

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        // Process the line
        int *ints = malloc(strlen(line) - strlen(line + strlen(line) - 1) + 1);
        char *token = strtok(line, " ");
        int i = 0;
        for (; token; ++token, ++i) {
            ints[i] = atoi(token);
        }
        ints[i] = 0;

        // Compute the average of the last two integers
        int avg = (ints[i-1] + ints[i-2]) / 2;

        record_t *record = malloc(sizeof(record_t));
        record->last_int = ints[i-1];
        records = realloc(records, sizeof(record_t) * ++records_len);
        records[records_len - 1] = *record;
        free(record);

        // Populating NFAPI structures
        NFAPI_CRC_INDICATION_PDU_T *nfa = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfa->RX_UE_INFORMATION_TAG = rand();
        nfa->RNTI = rand();
        for (int i = 0; i < 10; ++i) {
            nfa->CRC_INDICATION_REL8_TAG[i] = 'a' + rand() % 26;
        }
        nfa->CRCFLAG = rand();
        nfapis = realloc(nfapis, sizeof(NFAPI_CRC_INDICATION_PDU_T) * ++nfapis_len);
        nfapis[nfapis_len - 1] = *nfa;
        free(nfa);

        // Free memory allocated for the line
        free(ints);
    }

    fclose(fp);

    // Serialize NFAPI structures to byte array and send it to database server
    uint8_t *byte_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * nfapis_len + 1);
    for (int i = 0; i < nfapis_len; ++i) {
        memcpy(byte_array + sizeof(NFAPI_CRC_INDICATION_PDU_T) * i, &nfapis[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    byte_array[sizeof(NFAPI_CRC_INDICATION_PDU_T) * nfapis_len] = 0;

    // Send the byte array to database server
    FILE *dbfp = fopen("database.txt", "w");
    fwrite(byte_array, sizeof(uint8_t), strlen((char *)byte_array) + 1, dbfp);
    fclose(dbfp);

    free(records);
    free(nfapis);
    free(byte_array);

    return 0;
}
