['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousChannel;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ConnectionHandler {
    private static final int DEFAULT_RETRY_LIMIT = 3;
    private static final long DEFAULT_BACKOFF_DELAY_MILLIS = 1000;

    private AsynchronousChannel channel;
    private InetSocketAddress address;
    private AtomicInteger retryCount = new AtomicInteger(0);
    private Lock lock = new ReentrantLock();
    private LogService logService;

    public void establishConnection(InetSocketAddress address, int retryLimit, long backoffDelayMillis, LogService logService) {
        this.address = address;
        this.retryCount.set(0);
        this.logService = logService;
        connect();
    }

    private void connect() {
        channel = AsynchronousChannel.open();
        channel.connect(address, new ConnectionCallback(), new ExceptionCallback());
    }

    private class ConnectionCallback implements CompletionHandler<Integer, IOException> {
        @Override
        public void completed(Integer result, IOException attachment) {
            if (result == 0) {
                // Connection established successfully
                logService.log("Connected to " + address);
            } else {
                // Connection failed or closed
                int retryLimit = DEFAULT_RETRY_LIMIT;
                long backoffDelayMillis = DEFAULT_BACKOFF_DELAY_MILLIS;
                lock.lock();
                try {
                    if (retryCount.incrementAndGet() <= retryLimit) {
                        // Retry connection with exponential backoff delay
                        logService.log("Connection failure. Retrying in " + backoffDelayMillis + "ms");
                        channel.connect(address, this, new ExceptionCallback());
                        try {
                            Thread.sleep(backoffDelayMillis);
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt();
                        }
                    } else {
                        // Max retries exceeded
                        logService.log("Max retries exceeded. Connection failed.");
                    }
                } finally {
                    lock.unlock();
                }
            }
        }
    }

    private class ExceptionCallback implements CompletionHandler<IOException, Void> {
        @Override
        public void completed(Void result, IOException attachment) {
            // Handle connection exception
            logService.log("Connection error: " + attachment.getMessage());
        }
    }
}
