        fprintf(file, "{\"name\":\"%s\",\"priority\":%d,\"status\":%u}\n",
                tasks[i]->name, tasks[i]->priority, tasks[i]->status);
    }
}

task** deserialize_tasks(FILE* file) {
    task** tasks = NULL;
    size_t count = 0;

    while (fscanf(file, "{\"name\":\"%255s\",\"priority\":%d,\"status\":%u}\n",
                   &tasks[count].name, &tasks[count].priority, &tasks[count].status) == 3) {
        tasks = realloc(tasks, (count + 1) * sizeof(task));
        count++;
    }

    for (size_t i = 0; i < count; i++) {
        free_task(&tasks[i]);
    }
    free(tasks);
    return NULL;
}

