// Function to generate a random integer within a specified range
int random_int(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}

// Initialize the record hash table with initial capacity and populate it with test data
void init_record_hash(int capacity) {
    // Calculate new size based on existing count
    int new_size = record_count ? (record_count * 2 + 1) : capacity;

    // Reallocate memory for the new hash table
    Record* temp = (Record*)realloc(record_hash, sizeof(Record) * new_size);
    if (!temp) {
        printf("Memory allocation failed.\n");
        exit(-1); // Exit with error code
    }

    record_hash = temp;
    max_records = new_size;

    for (int i = 0; i < record_count; i++) {
        record_hash[i].key = random_int(1, 1000);
        record_hash[i].offset = (long)random_int(1, 1000000);
    }
}

// Check if a key already exists in the dataset
int validate_key(int key) {
    for (int i = 0; i < record_count; i++) {
        if (record_hash[i].key == key) {
            return -1; // Key collision detected, return error code
        }
    }
    return 0; // Valid key, no collisions found
}

// Add a new record to the dataset with unique key and offset values
void add_record(int key, long offset) {
    if (record_count >= max_records) {
        init_record_hash(max_records * 2); // Double the capacity when full
    }

    for (int i = 0; i < record_count; i++) {
        if (record_hash[i].key == key) {
            printf("Key collision detected, cannot add duplicate.\n");
            return; // Abort adding new record due to key conflict
        }
    }

    Record* new_record = &record_hash[record_count];
    new_record->key = key;
    new_record->offset = offset;

    record_count++;

    if (record_count > max_records * 0.75) {
        init_record_hash(max_records * 2); // Double the capacity when 75% full
    }
}

// Retrieve a record by its unique key and print it to console
void retrieve_record(int key) {
    for (int i = 0; i < record_count; i++) {
        if (record_hash[i].key == key) {
            printf("Key: %d, Offset: %ld\n", record_hash[i].key, record_hash[i].offset);
            return;
        }
    }
    printf("Record not found.\n");
}

// Clear the entire dataset by freeing memory and resetting counters
void clear_dataset() {
    for (int i = 0; i < record_count; i++) {
        free(&record_hash[i]);
    }
    free(record_hash);
    record_hash = NULL;
    record_count = 0;
}
