['Here is the C function that dynamically manages memory for a dataset of records:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define structure for a record
typedef struct {
    int key;
    long offset;
} Record;

// Define the hash table structure
typedef struct {
    int size;
    Record **records;
} HashTable;

// Function to initialize a new hash table with a specified size
HashTable* init_hash_table(int size) {
    HashTable *hash_table = (HashTable*)malloc(sizeof(HashTable));
    hash_table->size = size;
    hash_table->records = (Record**)calloc(size, sizeof(Record*));
    return hash_table;
}

// Function to insert a new record into the hash table
void insert_record(HashTable *hash_table, int key, long offset) {
    // Calculate the index for the given key using a simple hash function
    int index = key % hash_table->size;

    // Check if the slot is already occupied
    if (hash_table->records[index] != NULL) {
        // If the slot is occupied and the keys are different, resize the table
        if (hash_table->records[index]->key != key) {
            int new_size = 2 * hash_table->size;
            HashTable *new_hash_table = init_hash_table(new_size);
            for (int i = 0; i < hash_table->size; i++) {
                if (hash_table->records[i] != NULL) {
                    insert_record(new_hash_table, hash_table->records[i]->key, hash_table->records[i]->offset);
                }
            }
            free(hash_table);
            hash_table = new_hash_table;
        } else {
            // If the slot is occupied and the keys are the same (collision), simply update the offset
            hash_table->records[index]->offset = offset;
            return;
        }
    }

    // Create a new record with the given key and offset, and insert it into the table
    Record *record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    hash_table->records[index] = record;
}

// Function to retrieve a record from the hash table using its key
Record* get_record(HashTable *hash_table, int key) {
    // Calculate the index for the given key using the same hash function as insertion
    int index = key % hash_table->size;

    // Check if the slot is occupied and contains the desired record
    if (hash_table->records[index] != NULL && hash_table->records[index]->key == key) {
        return hash_table->records[index];
    } else {
        // If the slot is empty or the record does not match, return NULL
        return NULL;
    }
}

// Function to free all memory allocated by the hash table
void free_hash_table(HashTable *hash_table) {
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->records[i] != NULL) {
            free(hash_table->records[i]);
        }
    }
    free(hash_table->records);
    free(hash_table);
}

// Function to clear the entire dataset
void clear_dataset(HashTable *hash_table) {
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->records[i] != NULL) {
            free(hash_table->records[i]);
        }
    }
    free(hash_table->records);
    free(hash_table);
}
