int main(int argc, char** argv) {
    int verbose = 0;
    FILE* output_file = stdout;
    int threshold = 1;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], HELP_OPTION) == 0) {
            print_help();
            return 0;
        } else if (strcmp(argv[i], VERBOSE_OPTION) == 0) {
            verbose = 1;
        } else if (strcmp(argv[i], OUTPUT_FILE_OPTION) == 0 && i + 1 < argc) {
            output_file = fopen(argv[++i], "w");
            if (!output_file) {
                err(1, "Failed to open output file");
            }
        } else if (strcmp(argv[i], THRESHOLD_OPTION) == 0 && i + 1 < argc) {
            threshold = atoi(argv[++i]);
            if (threshold <= 0) {
                errx(1, "Invalid threshold value: %s", argv[i]);
            }
        } else {
            errx(1, "Unknown option: %s", argv[i]);
        }
    }

    DIR* dir = opendir(argv[1]);
    if (!dir) {
        err(1, "Failed to open directory");
    }

    int file_count = 0;
    ErrorMetric* error_metrics = NULL;

    while ((struct dirent*) readdir(dir)) {
        if (strcmp(".", this->d_name) == 0 || strcmp("..", this->d_name) == 0) {
            continue;
        }
        char file_path[1024];
        sprintf(file_path, "%s/%s", argv[1], this->d_name);

        process_directory(argv[1], file_path, threshold, stdout, output_file, verbose);
        file_count++;

        if (file_count % 10 == 0) {
            printf("Processed %d files...   \r", file_count);
        }
    }

    closedir(dir);

    if (error_metrics) {
        free_error_metrics(error_metrics);
    }

    return 0;
}

void process_directory(const char* directory_path, const char* file_path, int threshold, FILE* input_file, FILE* output_file, int verbose) {
