#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <unistd.h>

#define DATASET_LIMIT 1000000
#define FLOAT_RANGE 10.0f

typedef struct {
    float value;
    char identifier;
} data_point;

data_point** processDatasets(int numDatasets, int* datasetSizes) {
    data_point** datasets = NULL;
    unsigned long* timestamps = NULL;
    float* values = NULL;

    int totalDatasetSize = 0;
    for (int i = 0; i < numDatasets; i++) {
        totalDatasetSize += datasetSizes[i];
    }

    if (totalDatasetSize > DATASET_LIMIT) {
        printf("Error: Total dataset size exceeds the limit.\n");
        return NULL;
    }

    datasets = malloc(numDatasets * sizeof(data_point*));
    if (!datasets) {
        perror("Memory allocation failed for datasets.");
        return NULL;
    }

    timestamps = malloc(totalDatasetSize * sizeof(unsigned long));
    values = malloc(totalDatasetSize * sizeof(float));
    if (!(timestamps && values)) {
        free(datasets);
        perror("Memory allocation failed for timestamps and values.");
        return NULL;
    }

    for (int i = 0; i < numDatasets; i++) {
        datasets[i] = malloc(datasetSizes[i] * sizeof(data_point));
        if (!datasets[i]) {
            int j;
            for (j = 0; j < i; j++) {
                free(datasets[j]);
            }
            free(datasets);
            free(timestamps);
            free(values);
            perror("Memory allocation failed for dataset.");
            return NULL;
        }

        for (int j = 0; j < datasetSizes[i]; j++) {
            datasets[i][j].value = (float)(rand() / (RAND_MAX / FLOAT_RANGE));
            timestamps[i * datasetSizes[i] + j] = rand();
