        free(((data_point*)*arr)[i].value); // assuming float values are dynamically allocated
    }
    free(*arr);
    *arr = NULL;
}

int dynamic_array_resize(void** arr, size_t old_size, size_t new_size) {
    if (new_size > old_size) {
        void* new_arr = realloc(*arr, new_size * sizeof(float));
        if (!new_arr) return 1; // memory allocation failed
        *arr = new_arr;
    } else {
        for (size_t i = old_size; i < new_size; i++) {
            ((float*)*arr)[i] = 0.0f; // initialize new elements to zero
        }
    }
