#define BUFFER_SIZE 4096

typedef struct {
    int value;
} Record;

Record* records;
int num_records = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_once_t once = PTHREAD_ONCE_INIT;

void* generate_random_record(void* arg) {
    (void)arg;

    Record record;
    record.value = rand() % 100 + 1; // Random value between 1 and 100
    return &record;
}

int main(int argc, char** argv) {
    int c;
    char* output_file = NULL;
    int suppress_output = 0;
    pthread_t thread;

    static struct option long_options[] = {
        {"manpage", no_argument, 0, 'm'},
        {"cs", no_argument, 0, 'c'},
        {"o:", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    while ((c = getopt_long(argc, argv, "mc:o:", long_options, NULL)) != -1) {
        switch (c) {
            case 'm':
                printf("Documentation available at https://example.com/manpage.html\n");
                break;
            case 'c':
                suppress_output = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                printf("Usage: %s [-m] [-c] [-o <output_file>] [input_file]\n", argv[0]);
                return -1;
        }
    }

    if (argc - optind < 2) {
        printf("Error: Input file not specified.\n");
        return -1;
    }

    char* input_file = argv[optind];

    FILE* f = fopen(input_file, "r");
    if (!f) {
        fprintf(stderr, "Error opening file %s\n", input_file);
        return -1;
    }

    pthread_t thread_id;
    for (int i = 0; i < MAX_RECORDS; i++) {
        Record record;
        int ret = fread(&record.value, sizeof(record.value), 1, f);
        if (!ret) break;

        // Set the value of each record's int field to a random value
        pthread_create(&thread_id, NULL, generate_random_record, NULL);
        pthread_join(thread_id, NULL);

        records[i].value = record.value;
    }

    fclose(f);

    // Print or save the records
    if (output_file) {
        FILE* of = fopen(output_file, "w");
        for (int i = 0; i < num_records; i++) {
            fwrite(&records[i].value, sizeof(records[i].value), 1, of);
        }
        fclose(of);
    } else if (!suppress_output) {
        for (int i = 0; i < num_records; i++) {
            printf("%d\n", records[i].value);
        }
    }

    return 0;
}
