    void *ptr = manage_data_structures(num_arrays, array_size,
                                       num_timestamps, timestamp_size,
                                       num_points, point_size,
                                       num_metadata, metadata_size);

    // Use caching mechanism
    cache_data((float **)error_handler(ptr), array_size,
               (unsigned long *)error_handler(ptr), timestamp_size);

    return 0;
}

