CustomObject **createCollections(int count, size_t size, unsigned long *totalMemoryUsed) {
    CustomObject **collections = (CustomObject **)malloc((count + 1) * sizeof(CustomObject *));
    if (!collections) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for collections.\n");
        return NULL;
    }

    int i;
    for (i = 0; i <= count; i++) {
        CustomObject *collection = (CustomObject *)malloc(size);
        if (!collection) {
            // Handle memory allocation failure
            printf("Error: Failed to allocate memory for collection %d.\n", i);
            freeCollections(collections, i - 1);
            return NULL;
        }

        collections[i] = collection;
    }

    *totalMemoryUsed += (count + 1) * sizeof(CustomObject *) + count * size;
    return collections;
}

void freeCollections(CustomObject **collections, int count) {
    for (int i = 0; i <= count; i++) {
        if (collections[i]) {
            // Free individual collection objects
            CustomObject *collection = collections[i];
            for (int j = 0; j < sizeof(CustomObject); j += size) {
                free(((char *)collection + j));
            }
            free(collection);
        }
    }

    free(collections);
}
