#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *str;
    int num;
    float f1;
    float f2;
} CustomObj;

void* malloc(size_t size) {
    return realloc(NULL, size);
}

void free(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

// Collection struct
typedef struct {
    CustomObj **objs;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} Collection;

Collection* collection_new(int initial_capacity) {
    Collection *coll = malloc(sizeof(Collection));
    coll->size = 0;
    coll->capacity = initial_capacity;
    coll->objs = malloc(initial_capacity * sizeof(CustomObj *));
    pthread_mutex_init(&coll->mutex, NULL);
    return coll;
}

void collection_free(Collection* coll) {
    for (int i = 0; i < coll->size; i++) {
        free(coll->objs[i]->str);
        free(coll->objs[i]);
    }
    free(coll->objs);
    pthread_mutex_destroy(&coll->mutex);
    free(coll);
}

// Add object to collection
void collection_add(Collection* coll, CustomObj* obj) {
    if (coll->size >= coll->capacity) {
        // Dynamic resizing
        int new_capacity = coll->capacity * 2;
        CustomObj **new_objs = realloc(coll->objs, new_capacity * sizeof(CustomObj *));
        pthread_mutex_lock(&coll->mutex);
        for (int i = coll->size; i < new_capacity; i++) {
            new_objs[i] = NULL;
        }
        pthread_mutex_unlock(&coll->mutex);
        free(coll->objs);
        coll->capacity = new_capacity;
        coll->objs = new_objs;
    }
    coll->objs[coll->size++] = obj;
}

// Remove object from collection
void collection_remove(Collection* coll, int index) {
    if (index < 0 || index >= coll->size) {
        // Error handling
        return;
    }
    free(coll->objs[index]->str);
    free(coll->objs[index]);
    memmove(&coll->objs[index], &coll->objs[index + 1], (coll->size - index - 1) * sizeof(CustomObj *));
    coll->size--;
}

// Retrieve object from collection
CustomObj* collection_get(Collection* coll, int index) {
    if (index < 0 || index >= coll->size) {
        // Error handling
        return NULL;
    }
    return coll->objs[index];
}

int main() {
    // Example usage
    Collection *coll = collection_new(10);
    CustomObj *obj1 = malloc(sizeof(CustomObj));
    obj1->str = "Hello";
    obj1->num = 1;
    obj1->f1 = 3.14;
    obj1->f2 = 2.71;

    CustomObj *obj2 = malloc(sizeof(CustomObj));
    obj2->str = "World";
    obj2->num = 2;
    obj2->f1 = 9.82;
    obj2->f2 = 4.23;

    collection_add(coll, obj1);
    collection_add(coll, obj2);

    printf("Collection size: %d\n", coll->size);
    for (int i = 0; i < coll->size; i++) {
