dataset** create_datasets(int num_datasets, size_t memory_limit) {
    dataset** datasets = (dataset**)malloc(sizeof(dataset*) * num_datasets);
    if (!datasets) {
        // Handle error: Memory allocation failed
        printf("Error: Failed to allocate memory for datasets.\n");
        return NULL;
    }

    int i;
    for (i = 0; i < num_datasets; i++) {
        dataset* dataset = (dataset*)malloc(sizeof(dataset));
        if (!dataset) {
            // Handle error: Memory allocation failed
            printf("Error: Failed to allocate memory for dataset %d.\n", i);
            for (; i > 0; i--) {
                free(datasets[i - 1]);
            }
            free(datasets);
            return NULL;
        }

        dataset->timestamp = 0;
        dataset->data_points = (data_point*)malloc(sizeof(data_point) * MAX_DATASET_SIZE);
        if (!dataset->data_points) {
            // Handle error: Memory allocation failed
            printf("Error: Failed to allocate memory for data points in dataset %d.\n", i);
            free(dataset);
            for (; i > 0; i--) {
                free(datasets[i - 1]);
            }
            free(datasets);
            return NULL;
        }

        dataset->size = 0;

        datasets[i] = dataset;
    }

    return datasets;
}

