#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* str;
    int num;
    float* floats;
} custom_object;

custom_object** collections = NULL;
int collection_count = 0;
int max_collection_size = 10000; // adjust this as needed

void init_collection(int size) {
    if (collections == NULL || size > max_collection_size * collection_count) {
        collections = realloc(collections, (collection_count + 1) * sizeof(custom_object*));
        for (int i = 0; i < collection_count; i++) {
            free(collections[i]);
        }
        collection_count++;
    }
}

void add_to_collection(int index, custom_object* obj) {
    if (index >= max_collection_size || index < 0) {
        printf("Error: Out-of-bounds index.\n");
        return;
    }
    init_collection(index + 1);
    collections[index] = obj;
}

custom_object* get_from_collection(int index) {
    if (index >= max_collection_size || index < 0) {
        printf("Error: Out-of-bounds index.\n");
        return NULL;
    }
    return collections[index];
}

void remove_from_collection(int index) {
    if (index >= max_collection_size || index < 0) {
        printf("Error: Out-of-bounds index.\n");
        return;
    }
    init_collection(collection_count - 1);
    for (int i = index; i < collection_count - 1; i++) {
        collections[i] = collections[i + 1];
    }
    free(collections[collection_count - 1]);
    collection_count--;
}

void* create_custom_object(char* str, int num, float f1, float f2) {
    custom_object* obj = (custom_object*)malloc(sizeof(custom_object));
    if (obj == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }
    obj->str = strdup(str);
    obj->num = num;
    obj->floats = (float*)malloc(sizeof(float) * 2);
    obj->floats[0] = f1;
    obj->floats[1] = f2;
    return obj;
}

int main() {
    // Initialize collections
    for (int i = 0; i < max_collection_size; i++) {
        add_to_collection(i, create_custom_object("Obj", i + 1, 0.5f, 1.3f));
    }

    // Example usage:
    custom_object* obj = get_from_collection(5);
    printf("%s %d %.2f %.2f\n", obj->str, obj->num, obj->floats[0], obj->floats[1]);

    remove_from_collection(7);

    return 0;
}
