typedef struct {
    int error_count;
} error_metrics;

typedef struct {
    int system_health;
} system_status;

struct tcp_connection_info {
    record records[MAX_RECORDS];
    metadata metadata;
    usage_stats usage_stats;
    access_log access_log;
    error_metrics error_metrics;
    system_status system_status;
};

void* dynamic_tcp_connection_info_pool(int num_connections) {
    struct tcp_connection_info** connections = (struct tcp_connection_info**)malloc(num_connections * sizeof(struct tcp_connection_info*));
    for (int i = 0; i < num_connections; i++) {
        connections[i] = (struct tcp_connection_info*)malloc(TCP_CONNECTION_INFO_SIZE);
        // Initialize records
        for (int j = 0; j < MAX_RECORDS; j++) {
            record* rec = &(connections[i]->records[j]);
            rec->offset = (long)i;
            rec->key1 = rand() % 100;
            rec->key2 = rand() % 100;
            char unique_string[10];
            sprintf(unique_string, "%d_%d", i, j);
            rec->unique_string = strdup(unique_string);
            rec->timestamp = (double)rand() / RAND_MAX;
            rec->metadata_ptr = &(connections[i]->metadata);
        }
    }
    return connections;
