    // Initialize random seed
    srand(time(NULL));

    // Create memory pool allocator
    void* memory_pool = malloc(size * sizeof(long));
    if (memory_pool == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    // Initialize arrays using the memory pool allocator
    offsets = (int*)malloc((size / 2 + 1) * sizeof(int), memory_pool);
    for (int i = 0; i < size / 2; i++) {
        offsets[i] = rand() % 2001 - 1000;
    }

    keys = (int*)malloc(size / 2 * sizeof(int), memory_pool);
    for (int i = 0; i < size / 2; i++) {
        keys[i] = rand() % 1001 - 500;
    }

    records = (record**)malloc(2 * size / 2 * sizeof(record*), memory_pool);
    for (int i = 0; i < 2 * size / 2; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->integer_field = rand() % 4001 - 2000;
