        temperatures[i] = (float)(rand() % 8001 - 4000) / 10.0;
    }

    symbols = (char*)malloc(size / 12 * sizeof(char), memory_pool);
    for (int i = 0; i < size / 12; i++) {
        symbols[i] = (char)(rand() % 95 + 32);
    }

    reports = (weather_report**)malloc(4 * size / 12 * sizeof(weather_report*), memory_pool);
