        positions[i] = (GPS_POSITION_T*)malloc(sizeof(GPS_POSITION_T));
        positions[i]->latitude = (double)(rand() % 180 + 1) / 90.0;
        positions[i]->longitude = (double)(rand() % 360 + 1) / 180.0;
        positions[i]->altitude = (double)(rand() % 10000);
    }

    // Initialize distance array
    double* distances = (double*)malloc((2 * size / 12 - 1) * sizeof(double), memory_pool);
    for (int i = 0; i < 2 * size / 12 - 1; i++) {
        distances[i] = sqrt(pow(positions[i]->latitude - positions[i + 1]->latitude, 2) +
                             pow(positions[i]->longitude - positions[i + 1]->longitude, 2) +
                             pow(positions[i]->altitude - positions[i + 1]->altitude, 2));
    }

    // Serialize distance array into byte array
    uint8_t* distance_array = (uint8_t*)malloc((2 * size / 12 - 1) * sizeof(double), memory_pool);
    for (int i = 0; i < 2 * size / 12 - 1; i++) {
        memcpy(&distance_array[i], &distances[i], sizeof(double));
    }

    // Send distance array to remote weather station server
    // ...

    // Implement caching strategy with LRU eviction policy
    // ...
}

int main() {
