#include "telemetry_library.h"

typedef struct {
    float metric;
} metricEntry;

void* updateAndMonitorResource(int resourceId, int size, void* requestBody) {
    // Initialize telemetry library
    telemetry_init();

    // Allocate memory for array of metricEntry structures
    void* arr = malloc(size * sizeof(metricEntry));
    if (!arr) {
        global_error_flag = 1;
        return NULL;
    }

    // Initialize random values in the array
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        ((metricEntry*)arr)[i].metric = (float)(rand() / (RAND_MAX + 1.0)) * 1000 - 500;
    }

    // Update resource using HTTP PUT method
    if (resourceId != -1) {
        // Check if resource exists before updating
        if (!resourceExists(resourceId)) {
            free(arr);
            return NULL;
        }
        // Update resource
        updateResource(resourceId, requestBody);
        // Serialize combined data structures into byte array
        void* serializedData = serializeData(arr, size);
        // Compress and send data to monitoring server using specified protocol version
        int result = sendToMonitoringServer(serializedData, size);
        if (result < 0) {
            free(serializedData);
            return NULL;
        }
    }

    // Delete resource using HTTP DELETE method
    else {
        deleteResource(resourceId);
    }

    // Free allocated memory
    free(arr);

    // Log initialization and update/deletion processes, including any errors encountered
    logTelemetry();

    return NULL;
}
