int processData(int argc, char* argv[]) {
    // Parse configuration file
    FILE* config = fopen("config.txt", "r");
    if (config == NULL) {
        LOG_ERROR("Failed to open config file");
        return -1;
    }

    int offset_size, key_size, record_size;
    fscanf(config, "%d %d %d\n", &offset_size, &key_size, &record_size);

    // Initialize arrays
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));
    struct record* records = (struct record*)malloc(record_size * sizeof(struct record));

    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % 2001 - 1000;
    }

    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % 1001 - 500;
    }

    for (int i = 0; i < record_size; i++) {
        records[i].val = rand() % 2001 - 1000;
    }

    // Serialize data
    unsigned char* data = malloc(record_size * sizeof(struct record));
    int j = 0;
    for (int i = 0; i < record_size; i++) {
        memcpy(&data[j], &records[i].val, sizeof(int));
        j += sizeof(int);
    }

    // Send data to database server
    int db_status;
    if ((db_status = send_to_db(data)) != 0) {
        LOG_ERROR("Failed to transmit data to database");
        free(data);
        return -1;
    }

    // Return success
    return 0;
}

int send_to_db(unsigned char* data) {
    // Simulate sending data to database
    int retries = 3;
    while (retries--) {
        if (send_data(data)) {
            LOG_INFO("Data transmitted successfully");
            return 0;
        } else {
            LOG_ERROR("Failed to transmit data; retrying...");
        }
    }

    // Return failure status code
    return -1;
}

int main(int argc, char* argv[]) {
