#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct node {
    char* data;
    struct node* next;
} Node;

typedef struct value {
    int val;
    Node* strings;
} Value;

typedef struct hash_table {
    Value** buckets;
    int size;
    struct hash_table* next;
} HashTable;

HashTable* create_hash_table(int capacity, float load_threshold) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Value**)calloc(capacity, sizeof(Value*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = 0;
    table->next = NULL;

    return table;
}

void resize_hash_table(HashTable** table, int capacity) {
    HashTable* new_table = create_hash_table(capacity, (*table)->load_threshold);
    if (!new_table) return;

    for (int i = 0; i < (*table)->size; i++) {
        Value* value = (*table)->buckets[i];
        while (value) {
            int index = hash_function(value->key, capacity);
            value->next = new_table->buckets[index];
            new_table->buckets[index] = value;
            value = value->next;
        }
    }

    free((*table)->buckets);
    *table = new_table;
}

int hash_function(char* key, int capacity) {
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % capacity;
}
