data_point** process_datasets(float*** datasets, unsigned long num_datasets) {
    int i;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    data_point** result = (data_point**)malloc(num_datasets * sizeof(data_point*));

    for(i = 0; i < num_datasets; i++) {
        unsigned long max_size = 1000000;
        size_t allocated_memory = 0;

        while(1) {
            float* values = (float*)malloc(max_size * sizeof(float));
            unsigned long* timestamps = (unsigned long*)malloc(max_size * sizeof(unsigned long));

            if(!values || !timestamps) {
                fprintf(stderr, "Memory allocation failed for dataset %lu.\n", i);
                return NULL;
            }

            // Initialize data structure
            size_t count = 0;

            while(count < max_size) {
                data_point* dp = (data_point*)malloc(sizeof(data_point));

                if(!dp) {
                    free(values);
                    free(timestamps);
                    fprintf(stderr, "Memory allocation failed for dataset %lu.\n", i);
                    return NULL;
                }

                scanf("%f %lu %c", &dp->value, &dp->timestamp, &dp->identifier);

                values[count] = dp->value;
                timestamps[count] = dp->timestamp;

                count++;

                if(count >= max_size) {
                    break;
                }
            }

            // Store data structure
            result[i] = (data_point*)malloc(sizeof(data_point));

            if(!result[i]) {
                free(values);
                free(timestamps);
                fprintf(stderr, "Memory allocation failed for dataset %lu.\n", i);
                return NULL;
            }

            pthread_mutex_lock(&lock);

            // Process data structure here

            pthread_mutex_unlock(&lock);

            free(values);
            free(timestamps);
        }
    }

    return result;
}

