record* create_records(int num_records, int long_max, int int_max) {
    // Initialize random number generator
    srand(time(NULL));

    // Calculate total memory required for records
    size_t total_size = sizeof(struct record) * num_records;

    // Dynamically allocate memory for records
    struct record* records = (struct record*)malloc(total_size);

    if (!records) {
        return NULL;
    }

    // Initialize each record with random values
    int i;
    for (i = 0; i < num_records; i++) {
        struct record* rec = &records[i];
        switch (rand() % 3) { // Randomly select type
            case RECORD_LONG:
                rec->value = malloc(sizeof(long));
                *(long*)rec->value = (long)(rand() % long_max);
                break;
            case RECORD_INT:
                rec->value = malloc(sizeof(int));
                *(int*)rec->value = (int)(rand() % int_max);
                break;
            case RECORD_DOUBLE:
                rec->value = malloc(sizeof(double));
                *(double*)rec->value = (double)(rand() / (double)RAND_MAX * 1000.0); // Random floating-point number
                break;
        }
        rec->type = rand() % 3; // Randomly select record type
    }

    return records;
}

void free_records(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        struct record* rec = &records[i];
        switch (rec->type) { // Free memory based on record type
            case RECORD_LONG:
                free(rec->value);
                break;
            case RECORD_INT:
                free(rec->value);
                break;
            case RECORD_DOUBLE:
                free(rec->value);
                break;
        }
    }

    free(records);
}

