        struct record* rec = &records[i];
        printf("Allocated record %d: type=%d value=%p\n", i, rec->type, rec->value);
    }
}

void log_deallocation(record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        struct record* rec = &records[i];
        printf("Deallocated record %d: type=%d value=%p\n", i, rec->type, rec->value);
    }
}
