#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef enum {
    RECORD_LONG,
    RECORD_INT,
    RECORD_DOUBLE
} RecordType;

void* record_alloc(int num_records, int max_record_size) {
    void* records = malloc(num_records * sizeof(void*));
    if (records == NULL) {
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        void* record = malloc(max_record_size);
        if (record == NULL) {
            free(records);
            return NULL;
        }
        records += sizeof(void*);
        *reinterpret_cast<void**>(records) = record;
    }

    return records;
}

void record_free(void* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        void* record = *(void**)records + i * sizeof(void*) + sizeof(void*);
        free(record);
    }
    free(records);
}

int main() {
    // Define your parameters here
    int num_records = 1000000;
    int max_record_size = 32;

    void* records = record_alloc(num_records, max_record_size);

    if (records == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        // Initialize each record with random values
        RecordType type = (i % 3);
        void* record = *(void**)records + i * sizeof(void*) + sizeof(void*);
        switch (type) {
            case RECORD_LONG:
                *(long*)record = rand();
                break;
            case RECORD_INT:
                *(int*)record = rand();
                break;
            case RECORD_DOUBLE:
                *(double*)record = (double)rand() / RAND_MAX;
                break;
        }
    }

    record_free(records, num_records);

    return 0;
}
