typedef struct {
    char* key;
    char* value;
} config_item;

// Define a structure to represent a configuration file
typedef struct {
    int num_items;
    config_item** items;
} config_file;

// Function to process multiple configuration files
config_file** manage_config_files(const char* directory_path, size_t max_file_size) {
    // Initialize the array of pointers to configuration files
    config_file** config_files = (config_file**)malloc(1 * sizeof(config_file*));

    // Loop through the configuration files in the specified directory
    DIR* dir;
    struct dirent* ent;
    if ((dir = opendir(directory_path)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            // Check if the file is a configuration file
            char filename[256];
            strcpy(filename, directory_path);
            strcat(filename, "/");
            strcat(filename, ent->d_name);

            config_file* current_file = (config_file*)malloc(sizeof(config_file));
            current_file->num_items = 0;
            current_file->items = NULL;

            FILE* file = fopen(filename, "r");
            if (file != NULL) {
                // Process the configuration file
                process_config_file(file, &current_file);

                fclose(file);
                free(current_file->items);
                free(current_file);
            } else {
                // Handle error: failed to open file
                printf("Error opening file %s\n", filename);
                free(current_file);
            }

            // Add the processed configuration file to the array
            config_files = (config_file**)realloc(config_files, (config_files->len + 1) * sizeof(config_file*));
            config_files[config_files->len++] = current_file;
        }
        closedir(dir);
    } else {
        // Handle error: failed to open directory
        printf("Error opening directory %s\n", directory_path);
    }

    return config_files;
}

// Function to process a single configuration file
void process_config_file(FILE* file, config_file* current_file) {
    // Initialize the number of items in the file
    int num_items = 0;

    // Loop through the sections in the file
    while (fscanf(file, "%s = %s\n", &current_item.key, &current_item.value) == 2) {
        // Add the item to the current file
        config_file* new_item = (config_file*)malloc(sizeof(config_file));
        new_item->key = strdup(current_item.key);
        new_item->value = strdup(current_item.value);

        current_file->num_items++;
        current_file->items = (config_item**)realloc(current_file->items, current_file->num_items * sizeof(config_item*));

        // Add the item to the end of the array
        current_file->items[current_file->num_items - 1] = new_item;
    }

    fclose(file);
}

// Function to free allocated memory
void free_config_files(config_file** config_files, size_t num_files) {
    for (int i = 0; i < num_files; i++) {
        for (int j = 0; j < config_files[i]->num_items; j++) {
            free(config_files[i]->items[j]->key);
            free(config_files[i]->items[j]->value);
        }
        free(config_files[i]->items);
    }
    free(config_files);
}
