#define MAX_RECORDS 1000
#define MAX_SEGMENT_SIZE 1024*1024 // 1MB
#define MAX_DATA_SIZE 512 // 512 bytes

typedef struct {
    long data_size;
    int status;
} record_t;

void manage_memory(int num_records, long *offsets, int *keys, record_t **records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum number of records exceeded\n");
        return;
    }

    offsets = realloc(offsets, sizeof(long) * num_records);
    keys = realloc(keys, sizeof(int) * num_records);
    *records = malloc(sizeof(record_t *) * num_records);

    for (int i = 0; i < num_records; i++) {
        long segment_size = rand() % MAX_SEGMENT_SIZE + 1;
        int status = i;

        offsets[i] = segment_size;
        keys[i] = i;
        (*records)[i] = (record_t){.data_size = segment_size, .status = status};
    }
}

void free_memory(long *offsets, int *keys, record_t **records) {
    if (offsets) {
        free(offsets);
    }
    if (keys) {
        free(keys);
    }
    if (*records) {
        for (int i = 0; i < MAX_RECORDS; i++) {
            free((*records)[i]);
        }
        free(*records);
    }
}

int main() {
    int num_records = 10;
    long *offsets = NULL;
    int *keys = NULL;
    record_t **records = NULL;

    manage_memory(num_records, &offsets, &keys, &records);

    // Use the managed memory here...

    free_memory(offsets, keys, records);

    return 0;
}
