#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Structure representing a task
typedef struct {
    int priority;
    int data_size;
    int execution_time;
    int status;
} Task;

// Custom error codes for memory allocation failures
enum { MEMORY_ALLOCATION_FAILURE = 1, OUT_OF_MEMORY };

// Linked list node structure
typedef struct Node {
    Task *task;
    struct Node* next;
} Node;

// Function to dynamically allocate and initialize task collection
int create_task_collection(int num_tasks, int max_priority, int max_execution_time) {
    // Dynamically allocate memory for tasks, total_memory_usage, and task_ids
    Task **tasks = (Task **)malloc(num_tasks * sizeof(Task *));
    long *total_memory_usage = (long *)malloc((num_tasks + 1) * sizeof(long));
    int *task_ids = (int *)malloc(num_tasks * sizeof(int));

    // Initialize each task with random priority levels and execution times
    srand(time(NULL));
    for (int i = 0; i < num_tasks; i++) {
        tasks[i] = (Task *)malloc(sizeof(Task));
        tasks[i]->priority = rand() % max_priority;
        tasks[i]->data_size = i + 1;
        tasks[i]->execution_time = rand() % max_execution_time;
        tasks[i]->status = 0;

        // Store the unique ID of each task
        task_ids[i] = i;
    }

    return 0; // Successful allocation and initialization
}

// Function to add a new task to the collection
int add_task(Task **tasks, long *total_memory_usage, int *task_ids, Task *new_task) {
    // Find the next available ID for the new task
    int new_id = task_ids[num_tasks - 1] + 1;
    int num_tasks = sizeof(tasks) / sizeof(Task *);

    // Dynamically allocate memory for the new task and update total_memory_usage
    tasks[num_tasks] = (Task *)malloc(sizeof(Task));
    *tasks[num_tasks] = *new_task;
    total_memory_usage[num_tasks] += new_task->data_size;

    // Update task_ids with the unique ID of the new task
    task_ids = (int *)realloc(task_ids, (num_tasks + 1) * sizeof(int));
    task_ids[num_tasks] = new_id;

    return 0; // Successful addition of a new task
}

// Function to remove a task from the collection
int remove_task(Task **tasks, long *total_memory_usage, int *task_ids, int task_id) {
    // Find the index of the task to be removed
    int idx = -1;
    for (int i = 0; i < num_tasks; i++) {
        if (task_ids[i] == task_id) {
            idx = i;
            break;
        }
    }

    // Check if the task exists in the collection
    if (idx == -1) {
        return MEMORY_ALLOCATION_FAILURE; // Task not found
    }

    // Deallocate memory for the removed task and update total_memory_usage
    free(tasks[idx]);
    tasks = (Task **)realloc(tasks, (num_tasks - 1) * sizeof(Task *));
    total_memory_usage = (long *)realloc(total_memory_usage, (num_tasks - 1) * sizeof(long));
    task_ids = (int *)realloc(task_ids, (num_tasks - 1) * sizeof(int));

    return 0; // Successful removal of a task
}

// Function to get the total memory usage
long get_total_memory_usage(Task **tasks, int num_tasks) {
    long total_memory = 0;
    for (int i = 0; i < num_tasks; i++) {
        total_memory += tasks[i]->data_size;
    }
    return total_memory;
}

// Function to free all allocated memory
void free_task_collection(Task **tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; i++) {
        free(tasks[i]);
    }

    free(tasks);
    free(total_memory_usage);
    free(task_ids);
}
