#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int priority;
    size_t data_size;
    int execution_time;
    int status;
    int* dependency_ids;
} task;

task* create_task(int id) {
    task* new_task = (task*) malloc(sizeof(task));
    new_task->id = id;
    new_task->priority = rand() % 100;
    new_task->data_size = rand() % 1024 + 1;
    new_task->execution_time = rand() % 60;
    new_task->status = 0;
    new_task->dependency_ids = (int*) malloc(sizeof(int));
    return new_task;
}

void add_task(task** tasks, int id) {
    task* new_task = create_task(id);
    *tasks = (task*) realloc(*tasks, (++(*tasks)->size)*sizeof(task));
    (*tasks)[id-1] = new_task;
}

void remove_task(task** tasks, int id) {
    free((*tasks)[id-1]->dependency_ids);
    free((*tasks)[id-1]);
    *tasks = (task*) realloc(*tasks, --(*tasks)->size*sizeof(task));
}

long get_total_memory_usage(task* tasks, int size) {
    long total_memory_usage = 0;
    for(int i=0; i<size; i++) {
        total_memory_usage += tasks[i]->data_size + sizeof(task);
    }
    return total_memory_usage;
}

void pause_task(task** tasks, int id) {
    (*tasks)[id-1]->status = 1;
}

void resume_task(task** tasks, int id) {
    (*tasks)[id-1]->status = 0;
}

int main() {
    // Initialize task collection
    task* tasks = NULL;
    int num_tasks = 10;
    for(int i=0; i<num_tasks; i++) {
        add_task(&tasks, i+1);
    }

    // Get total memory usage
    long total_memory_usage = get_total_memory_usage(tasks, num_tasks);
    printf("Total memory usage: %ld bytes\n", total_memory_usage);

    // Pause and resume a task
    pause_task(&tasks, 5);
    printf("Task 5 paused...\n");
    sleep(1); // wait for a second
    resume_task(&tasks, 5);
    printf("Task 5 resumed...\n");

    // Remove a task
    remove_task(&tasks, 3);
    printf("Task 3 removed...\n");

    return 0;
}

