    new_task->data_size = data_size;
    new_task->execution_time = execution_time;
    new_task->status = 0;
    int *dependency_ids = (int*) allocate(data_size);

    if (dependency_ids == NULL) return NULL; // error code

    new_task->dependency_ids = dependency_ids;
    pthread_mutex_lock(&lock);
    tasks = (task**) reallocate(tasks, num_tasks + 1, sizeof(task*));
    task_ids = (int*) realloc(task_ids, (num_tasks + 1) * sizeof(int));

    task_ids[num_tasks] = num_tasks;
    tasks[num_tasks] = new_task;
    num_tasks++;
    pthread_mutex_unlock(&lock);

    return new_task;
}

void remove_task(int task_id) {
    if (task_id < 0 || task_id >= num_tasks) return; // error code

    task *old_task = tasks[task_id];
    for (int i = task_id; i < num_tasks - 1; i++) {
        task_ids[i] = task_ids[i + 1];
        tasks[i] = tasks[i + 1];
    }

    free(old_task->dependency_ids);
    free(old_task);
    num_tasks--;
}

long get_total_memory_usage() {
    long total = 0;
    for (int i = 0; i < num_tasks; i++) {
        total += tasks[i]->data_size;
    }
    return total;
}
