```cpp
#include <iostream>
#include <vector>
#include <string>
#include <random>

class Transaction {
public:
    uint64_t id;
    double timestamp;
    std::string description;
    std::string status;
    std::vector<std::string> tags;

    Transaction() : id(0), timestamp(0.0), description(""), status("pending"), tags({}) {}
};

std::vector<Transaction*> createTransactions(int numTransactions) {
    std::vector<Transaction*> transactions(numTransactions);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> idDist(1, 1000);
    std::uniform_real_distribution<double> timestampDist(1.0, 10000.0);

    for (int i = 0; i < numTransactions; ++i) {
        Transaction* transaction = new Transaction();
        transaction->id = idDist(gen);
        transaction->timestamp = timestampDist(gen);
        std::string description;
        switch (std::rand() % 3) {
            case 0:
                description = "Payment";
                break;
            case 1:
                description = "Deposit";
                break;
            default:
                description = "Transfer";
                break;
        }
        transaction->description = description;
        std::string status;
        switch (std::rand() % 3) {
            case 0:
                status = "pending";
                break;
            case 1:
                status = "completed";
                break;
            default:
                status = "failed";
                break;
        }
        transaction->status = status;
        for (int j = 0; j < std::rand() % 5 + 1; ++j) {
            transaction->tags.push_back(std::to_string(j));
        }
        transactions[i] = transaction;
    }

    return transactions;
}

void destroyTransactions(std::vector<Transaction*> transactions) {
    for (Transaction* transaction : transactions) {
        delete transaction;
    }
}

int main() {
    int numTransactions = 10000;
    std::vector<Transaction*> transactions = createTransactions(numTransactions);

    // Use the transactions...

    destroyTransactions(transactions);

    return 0;
}
