['```
function analyzeSoftwareFrameworks(text) {
  const frameworkList = ["react", "angular", "vuejs", "nodejs", "express", "django", "rubyonrails"];
  const prefixRegex = /\b(version|latest)\b/i;
  const wholeWordRegex = /\b(\w+)\b/gi;

  const frameworkCounts = {};
  let contextCounts = { project: 0, code: 0, doc: 0 };

  text.replace(wholeWordRegex, (match) => {
    const frameworkName = match.toLowerCase();
    if (frameworkList.includes(frameworkName)) {
      frameworkCounts[frameworkName] = (frameworkCounts[frameworkName] || 0) + 1;
      contextCounts[contextCounts.project <= contextCounts.code ? "project" : "code"]++;
    }
  });

  const apiResponse = await fetch("https://api.frameworkversions.com/versions");
  const latestVersions = await apiResponse.json();

  frameworkCounts.latestVersions = latestVersions;

  return { frameworkCounts, contextCounts };
}

async function generateSummary(data) {
  const totalFrameworks = Object.keys(data.frameworkCounts).length;
  const frameworkUsage = [];
  for (const [framework, count] of Object.entries(data.frameworkCounts)) {
    frameworkUsage.push({ name: framework, value: (count / totalFrameworks) * 100 });
  }
  return chartjs.generatePieChart(frameworkUsage);
}

async function main(text) {
  const data = await analyzeSoftwareFrameworks(text);
  const summary = await generateSummary(data);
  console.log(summary);
}
