void init_record(record* record, int offset_range[2], int key_range[2], double value_range[2]) {
    // Initialize the record based on its type
    switch (record->type) {
        case OFFSET:
            record->data = malloc(sizeof(long));
            *(long*)record->data = rand() % (offset_range[1] - offset_range[0]) + offset_range[0];
            break;
        case INT_KEY:
            record->data = malloc(sizeof(int));
            *(int*)record->data = rand() % (key_range[1] - key_range[0]) + key_range[0];
            break;
        case DOUBLE_VALUE:
            record->data = malloc(sizeof(double));
            *(double*)record->data = value_range[0] + (rand() / (RAND_MAX / (value_range[1] - value_range[0])) * (value_range[1] - value_range[0]));
            break;
    }
}
