class Transaction {
public:
    int id;
    std::time_t timestamp;
    std::string description;
    std::string status;
    std::vector<std::string> tags;

    Transaction() : id(0), timestamp(std::time(nullptr)), description(""), status("pending"), tags({}) {}

    ~Transaction() {
        for (auto& tag : tags) {
            delete[] tag.c_str();
        }
    }
};

class TransactionManager {
public:
    static void createTransactions(int numTransactions, int* transactionArray, int maxMemoryUsage) {
        std::vector<Transaction*> transactions;
        std::mutex mtx;

        auto start = std::chrono::high_resolution_clock::now();

        for (int i = 0; i < numTransactions; ++i) {
            Transaction* transaction = new Transaction();
            transaction->id = i;
            transaction->timestamp = std::time(nullptr);
            transaction->description = "Transaction " + std::to_string(i);
            transaction->status = "pending";

            // Generate random tags
            int numTags = rand() % 5 + 1;
            for (int j = 0; j < numTags; ++j) {
                transaction->tags.push_back("Tag " + std::to_string(j));
            }

            transactions.emplace_back(transaction);

            if (transactionArray != nullptr) {
                *transactionArray++ = transaction;
            }
        }

        auto end = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);
        std::cout << "Transactions created in " << duration.count() << " ms." << std::endl;

        // Log memory allocation and deallocation events
        for (auto& transaction : transactions) {
            if (transaction != nullptr) {
                int totalMemoryUsage = sizeof(Transaction) + transaction->tags.size() * 32; // Assume 32 bytes per tag
                if (totalMemoryUsage > maxMemoryUsage) {
                    std::cerr << "Transaction " << transaction->id << " exceeds maximum memory usage." << std::endl;
                } else {
                    std::cout << "Transaction " << transaction->id << " allocated " << totalMemoryUsage << " bytes of memory." << std::endl;
                }
            }
        }

        // Free memory
        for (auto& transaction : transactions) {
            delete transaction;
        }
    }
};

int main() {
    int numTransactions = 10;
    int maxMemoryUsage = 1024 * 1024; // 1MB

    int* transactionArray = nullptr;
    TransactionManager::createTransactions(numTransactions, transactionArray, maxMemoryUsage);

    return 0;
}
