// Define the structure for a single data point
typedef struct {
    float value;
    char identifier;
} data_point;

// Define the structure for a dataset
typedef struct {
    float* values;
    unsigned long* timestamps;
    data_point** points;
    size_t num_points;
} dataset;

// Function to dynamically allocate and initialize multiple datasets
dataset** create_datasets(size_t num_datasets, size_t max_points_per_dataset, size_t total_limit) {
    dataset** datasets = (dataset**)malloc(num_datasets * sizeof(dataset*));
    if (!datasets) return NULL; // Handle memory allocation error

    for (size_t i = 0; i < num_datasets; i++) {
        datasets[i] = (dataset*)malloc(sizeof(dataset));
        if (!datasets[i]) return NULL; // Handle memory allocation error
        datasets[i]->values = (float*)malloc(max_points_per_dataset * sizeof(float));
        if (!datasets[i]->values) return NULL; // Handle memory allocation error
        datasets[i]->timestamps = (unsigned long*)malloc(max_points_per_dataset * sizeof(unsigned long));
        if (!datasets[i]->timestamps) return NULL; // Handle memory allocation error
        datasets[i]->points = (data_point**)malloc(max_points_per_dataset * sizeof(data_point*));
        if (!datasets[i]->points) return NULL; // Handle memory allocation error

        // Initialize the dataset's size to zero
        datasets[i]->num_points = 0;
    }

    // Check for total allocated memory exceeding the specified limit
    size_t total_allocated = 0;
    for (size_t i = 0; i < num_datasets; i++) {
        total_allocated += max_points_per_dataset * sizeof(float) + max_points_per_dataset * sizeof(unsigned long) + max_points_per_dataset * sizeof(data_point*) + sizeof(dataset);
    }
    if (total_allocated > total_limit) {
        // Handle memory allocation error
        for (size_t i = 0; i < num_datasets; i++) free(datasets[i]);
        free(datasets);
        return NULL;
    }

    return datasets;
}

void destroy_datasets(dataset** datasets, size_t num_datasets) {
    for (size_t i = 0; i < num_datasets; i++) {
        if (datasets[i]->values) free(datasets[i]->values);
        if (datasets[i]->timestamps) free(datasets[i]->timestamps);
        for (size_t j = 0; j < datasets[i]->num_points; j++) {
            if (datasets[i]->points[j]) free(datasets[i]->points[j]);
        }
        free(datasets[i]->points);
        free(datasets[i]);
    }
    free(datasets);
}
