        records[i].offset = rand() % (max - min + 1) + min;
        records[i].timestamp = rand() % (max - min + 1) + min;
        records[i].value = rand() % (max - min + 1) + min;
    }

    // Dynamically allocate and initialize 'string' identifiers
    for (int i = 0; i < size; i++) {
        int idLen = strlen("Identifier ") + 10; // default string length
