    }
    return datasets;
}

void free_datasets(dataset** datasets, int num_datasets) {
    for (int i = 0; i < num_datasets; i++) {
        free(datasets[i]->values);
        free(datasets[i]->timestamps);
        free(datasets[i]->points);
        free(datasets[i]);
    }
    free(datasets);
}

void* allocate_and_init_data_point(void) {
    data_point* point = (data_point*)malloc(sizeof(data_point));
    point->value = 0.0;
    point->identifier = '\0';
    return point;
}

int main() {
    int num_datasets = 5;
    int max_points_per_dataset = 10;
    dataset** datasets = allocate_and_init_datasets(num_datasets, max_points_per_dataset);
    // process datasets here
    free_datasets(datasets, num_datasets);
    return 0;
}
