// Define function to allocate and initialize array of structures
data_point **allocate_and_initialize(int num_datasets, int max_depth) {
    // Initialize error flag
    int err = 0;

    // Allocate memory for array of pointers
    data_point **dataset_ptrs = (data_point **)malloc(num_datasets * sizeof(data_point *));
    if (!dataset_ptrs) {
        err = 1;
        goto cleanup;
    }

    // Iterate over datasets
    for (int i = 0; i < num_datasets; i++) {
        // Allocate memory for current dataset
        data_point *current_dataset = (data_point *)malloc(sizeof(data_point));
        if (!current_dataset) {
            err = 1;
            goto cleanup;
        }

        // Set identifier and initialize sub-pointer
        current_dataset->identifier = 'A' + i;
        current_dataset->sub_ptr = NULL;

        // Iterate over depth levels
        for (int j = 0; j < max_depth; j++) {
            // Allocate memory for sub-data point
            sub_data_point *sub_ptr = (sub_data_point *)malloc(sizeof(sub_data_point));
            if (!sub_ptr) {
                err = 1;
                goto cleanup;
            }

            // Initialize sub-pointer and timestamp
            sub_ptr->timestamp = 0.0f;
            sub_ptr->sub_ptr = NULL;

            // Add to current dataset
            current_dataset->sub_ptr = sub_ptr;
        }

        // Update pointer array
        dataset_ptrs[i] = current_dataset;
    }

cleanup:
    if (err) {
        // Free allocated memory and return error
        for (int i = 0; i < num_datasets; i++) {
            free(dataset_ptrs[i]);
        }
        free(dataset_ptrs);
        return NULL;
    } else {
        // Return pointer array
        return dataset_ptrs;
    }
}

// Example usage:
int main() {
    int num_datasets = 3;
    int max_depth = 2;

    data_point **dataset_ptrs = allocate_and_initialize(num_datasets, max_depth);

    // Process datasets...

    // Free allocated memory
    for (int i = 0; i < num_datasets; i++) {
        free(dataset_ptrs[i]);
    }
    free(dataset_ptrs);

    return 0;
}
