typedef struct sub_sub_data_point {
    // nested structure
} sub_sub_data_point;

data_point** manage_memory(int num_datasets, int max_depth, int* total_allocated) {
    data_point** datasets = (data_point**)malloc(num_datasets * sizeof(data_point*));

    for (int i = 0; i < num_datasets; i++) {
        datasets[i] = (data_point*)malloc(sizeof(data_point));
        // initialize dataset
        datasets[i]->value = 0.0;
        datasets[i]->id = 'A';
        datasets[i]->list = NULL;

        int current_depth = 1;
        while (current_depth <= max_depth) {
            // dynamically allocate memory for sub_data_points
            sub_data_point* new_list = (sub_data_point*)malloc(sizeof(sub_data_point));

            // initialize sub_data_point
            new_list->timestamp = 0.0;
            new_list->next = NULL;

            // add to existing list or start a new one if this is the first level
            datasets[i]->list = current_depth == 1 ? new_list : (sub_data_point*)malloc(sizeof(sub_data_point));

            current_depth++;
        }

        *total_allocated += sizeof(data_point) + sizeof(sub_data_point) * (max_depth - 1);
    }

    return datasets;
}
