#include <time.h>

typedef struct {
    int value;
    long* offset_ptr;
    int* key_ptr;
} record;

record* manage_memory(size_t num_offsets, size_t num_keys, size_t num_records, int min_value, int max_value) {
    // Initialize random number generator
    srand(time(NULL));

    // Calculate total memory required for arrays
    size_t total_size = sizeof(long) * num_offsets + sizeof(int) * num_keys + sizeof(record) * num_records;

    // Allocate memory pool using arena allocator (e.g., jemalloc or tcmalloc)
    void* mem_pool = malloc(total_size);
    if (!mem_pool) {
        return NULL;  // Handle allocation failure
    }

    // Initialize offsets and keys arrays
    long* offsets = (long*)(((char*)mem_pool) + sizeof(long) * num_offsets);
    int* keys = (int*)(((char*)mem_pool) + sizeof(long) * num_offsets + sizeof(int) * num_keys);

    // Initialize records array
    record* records = (record*)(((char*)mem_pool) + sizeof(long) * num_offsets + sizeof(int) * num_keys + sizeof(record) * num_records);
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[i];
    }

    // Validate pointers
    for (size_t i = 0; i < num_records; i++) {
        if (!records[i].offset_ptr || !records[i].key_ptr) {
            free(mem_pool);
            return NULL;  // Handle pointer validation failure
        }
    }

    return records;
}
