void init_memory(int num_offsets, int num_keys, int num_records) {
    // Dynamically allocate memory for arrays/structures
    num_offsets = num_offsets > 0 ? num_offsets : 1;
    num_keys = num_keys > 0 ? num_keys : 1;
    num_records = num_records > 0 ? num_records : 1;

    offsets = (long*)malloc(num_offsets * sizeof(long));
    keys = (int*)malloc(num_keys * sizeof(int));

    records = (record*)malloc(num_records * sizeof(record));
    // Initialize arrays with sequentially increasing values starting from 0
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i;
    }

