    nodes = (node**)malloc(num_records * sizeof(node*));
    for (int i = 0; i < num_records; i++) {
        nodes[i] = (node*)malloc(sizeof(node));
        nodes[i]->data = &records[i];
        nodes[i]->used = 1;
        nodes[i]->timestamp = time(NULL);
    }
}

void reclamation(int modified_index) {
    // Reclaim memory for records that have been invalidated due to concurrent modifications
    for (int i = modified_index; i < num_records; i++) {
        if (!records[i].valid) {
            free(nodes[i]);
            nodes[i] = NULL;
        }
