    int* keys = (int*)keys_arena;
    keys_arena += num_keys * sizeof(int);
    void* records_arena = malloc(num_records * sizeof(record));
    record* records = (record*)records_arena;
    records_arena += num_records * sizeof(record);
    void* nodes_arena = malloc(num_nodes * sizeof(node));
    node* nodes = (node*)nodes_arena;

    // Initialize offsets and keys arrays with sequentially increasing values
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i;
    }

