#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <sys/mman.h>
#include <fcntl.h>

#define RECORD_SIZE sizeof(record)
#define OFFSETS_PER_PAGE 1024 // adjust this for your system's page size

typedef struct {
    int key;
    long offset;
} record;

int g_error = 0; // global error flag

void* my_malloc(size_t size) {
    if (size > 0) {
        void* ptr = malloc(size);
        if (!ptr)
            g_error = 1; // set error flag
        return ptr;
    }
    else {
        return NULL;
    }
}

void free_all(void** arr, int len) {
    for (int i = 0; i < len; i++) {
        if (arr[i])
            free(arr[i]);
    }
}

int check_prime(int n) {
    if (n <= 1)
        return 0;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0)
            return 0;
    return 1;
}

void populate_records(record* records, int len, int min_value, int max_value) {
    srand(time(NULL)); // seed random number generator
    for (int i = 0; i < len; i++) {
        records[i].key = i; // initialize keys
        long offset = i;
        records[i].offset = offset;
        int value = rand() % (max_value - min_value + 1) + min_value;
        if ((i > 0 && value == records[i-1].key + 1) || value < min_value || value > max_value)
            value = rand() % (max_value - min_value + 1) + min_value; // retry if adjacent or out-of-range
        records[i].value = value;
    }
}

int main() {
    int num_offsets, min_value, max_value;
    printf("Enter number of offsets: ");
    scanf("%d", &num_offsets);
    printf("Enter minimum value range: ");
    scanf("%d", &min_value);
    printf("Enter maximum value range: ");
    scanf("%d", &max_value);

    if (num_offsets < 1 || min_value >= max_value) {
        g_error = 2; // set error flag
        return -1;
    }

    long* offsets = my_malloc(num_offsets * sizeof(long));
    int* keys = my_malloc(num_offsets * sizeof(int));

    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i; // initialize offsets and keys arrays
        keys[i] = i;
    }

    record* records = my_malloc(num_offsets * RECORD_SIZE);
    if (!records)
        return -1;

    populate_records(records, num_offsets, min_value, max_value);

    int total_value = 0;
    for (int i = 0; i < num_offsets; i++) {
        total_value += records[i].value;
    }

    if (!check_prime(total_value)) { // check prime
        g_error = 3; // set error flag
        free_all((void**)&offsets, num_offsets), free_all((void**)&keys, num_offsets), free_all((void**)&records, num_offsets);
        return -1;
    }

    printf("Allocated memory successfully.\n");

    free_all((void**)&offsets, num_offsets), free_all((void**)&keys, num_offsets), free_all((void**)&records, num_offsets);

    if (g_error) {
        printf("Error occurred: %d\n", g_error);
        return -1;
    }

    printf("Memory freed successfully.\n");
    return 0;
}
