event_record** initializeEventArrays(int size) {
    event_record** arrays = (event_record**)malloc(3 * sizeof(event_record*));

    for(int i=0; i<3; i++) {
        arrays[i] = (event_record*)calloc(size, sizeof(event_record));

        if(i == 0) { // timestamp array
            long timestamps[size];
            for(int j=0; j<size; j++) {
                timestamps[j] = time(NULL);
            }

            for(int j=0; j<size; j++) {
                arrays[i][j].timestamp = timestamps[j];
                arrays[i][j].eventId = rand() % 100;
            }
        } else if(i == 1) { // event ID array
            int events[size];
            for(int j=0; j<size; j++) {
                events[j] = rand() % 100;
            }

            for(int j=0; j<size; j++) {
                arrays[i][j].timestamp = time(NULL);
                arrays[i][j].eventId = events[j];
            }
        } else { // event record array
            char* characters[] = {"Hello", "World", "Testing", "Event", "Record"};
            for(int j=0; j<size; j++) {
                arrays[i][j].timestamp = time(NULL);
                arrays[i][j].eventId = rand() % 100;

                int length = strlen(characters[rand() % 5]);
                char* message = (char*)malloc((length+1)*sizeof(char));
                for(int k=0; k<length; k++) {
                    message[k] = characters[rand() % 5][k];
                }
                message[length] = '\0';

                arrays[i][j].message = message;
            }
        }
    }

    return arrays;
}

void freeEventArrays(event_record** arrays) {
    for(int i=0; i<3; i++) {
        for(int j=0; j<arrays[i]; j++) {
            if(arrays[i][j]->message != NULL) {
                free(arrays[i][j]->message);
            }
        }

        if(arrays[i] != NULL) {
            free(arrays[i]);
        }
    }

    if(arrays != NULL) {
        free(arrays);
    }
}
