    event_record** array = (event_record**)malloc(num_events * sizeof(event_record*));
    for(int i = 0; i < num_events; i++) {
        array[i] = (event_record*)malloc(sizeof(event_record));

        // Initialize timestamp and event ID
        array[i]->timestamp = time(NULL);
        array[i]->event_id = i;

        // Generate random message
        const char* chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890";
        int len = rand() % 20 + 1;
        char* message = (char*)malloc((len+1)*sizeof(char));
        for(int j = 0; j < len; j++) {
            message[j] = chars[rand() % (strlen(chars))];
        }
        message[len] = '\0';
        array[i]->message = message;

        // Error handling
        if(array[i]->message == NULL) {
            free(array[i]);
            for(int k = i - 1; k >= 0; k--) {
                free(array[k]->message);
                free(array[k]);
            }
            free(array);
            return NULL;
        }
    }

    return array;
}

