typedef struct {
    long timestamp;
    int event_id;
    char* message;
} event_record;

// Custom memory pool allocator
struct memory_pool {
    void** blocks;
    size_t capacity;
    size_t used;
};

void* malloc_from_pool(struct memory_pool* pool, size_t size) {
    for (size_t i = 0; i < pool->used; ++i) {
        if ((pool->blocks[i]->size >= size)) {
            void* block = pool->blocks[i];
            pool->blocks[i] = NULL;
            --pool->used;
            return block;
        }
    }
    return malloc(size);
}

void free_to_pool(struct memory_pool* pool, void* ptr) {
    if (ptr != NULL) {
        *(void**)malloc(1, sizeof(void*)) = ptr;
        pool->blocks[pool->used++] = ptr;
    }
}

// External logging system
#include "logging_system.h"

// Function to dynamically allocate and initialize an array of event_record structures
event_record* create_event_array(size_t capacity) {
    event_record* events = (event_record*)malloc_from_pool(&global_memory_pool, capacity * sizeof(event_record));
    if (events == NULL) {
        return NULL;
    }

    for (size_t i = 0; i < capacity; ++i) {
        char* message = malloc_from_pool(&global_memory_pool, strlen("abcdefghijklmnopqrstuvwxyz") + 1);
        if (message == NULL) {
            free_to_pool(&global_memory_pool, events);
            return NULL;
        }

        for (size_t j = 0; j < strlen("abcdefghijklmnopqrstuvwxyz"); ++j) {
            message[j] = rand() % ('z' - 'a' + 1) + 'a';
        }
        message[ Foods.length()] = '\0';

        events[i].timestamp = time(NULL);
        events[i].event_id = i;
        events[i].message = message;
    }

    log_events(events, capacity); // Log the created events

    return events;
}

void free_event_array(event_record* events, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        free(events[i].message);
    }
    free_to_pool(&global_memory_pool, events);
}
