// Custom memory pool allocator structure
typedef struct {
    void* mem;
    size_t size;
} MemoryPool;

// Initialize the custom memory pool
MemoryPool* init_memory_pool(size_t initial_size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->mem = malloc(initial_size);
    mp->size = initial_size;
    return mp;
}

// Reallocate the custom memory pool if necessary
void* reallocate_mp(MemoryPool* mp, size_t new_size) {
    void* temp = realloc(mp->mem, new_size);
    mp->mem = temp;
    mp->size = new_size;
    return temp;
}

// Custom memory pool allocator functions for allocating and freeing memory
void* mp_malloc(MemoryPool* mp, size_t size) {
    if (mp->size < size) {
        mp->mem = reallocate_mp(mp, mp->size + 1024);
    }
    return malloc(size);
}

void mp_free(MemoryPool* mp) {
    free(mp->mem);
    free(mp);
}

