#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MIN_VALUE 1
#define MAX_VALUE 1000
#define PRIME_THRESHOLD 30

// Define the record structure type
typedef struct {
    int value;
    long offset;
    int key;
} record_t;

// Function to check if a number is prime
int is_prime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

// Function to generate a random prime number
int get_prime(int min_value, int max_value) {
    int num = rand() % (max_value - min_value + 1) + min_value;
    while (!is_prime(num)) {
        num++;
        if (num > max_value) return -1; // handle edge case where max_value is less than or equal to min_value
    }
    return num;
}

// Main function to manage memory allocation and initialization for multiple data structures
record_t* init_records(int n, int min_value, int max_value) {
    if (n <= 0 || min_value >= max_value) return NULL; // handle edge cases where n is zero or min_value is greater than or equal to max_value

    // Calculate the total memory required for offsets array
    long offset_memory = sizeof(long) * n;
    // Check if the total memory exceeds 70% of the system's available physical memory
    size_t total_physical_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    size_t max_offset_memory = (total_physical_memory / 7) * 3; // assume 70% of the total physical memory
    if (offset_memory > max_offset_memory) {
        printf("Error: Memory allocation failed due to exceeded system resources.\n");
        return NULL;
    }

    // Initialize offsets array with sequentially increasing values starting from 0
    long* offsets = (long*)malloc(offset_memory);
    for (int i = 0; i < n; i++) {
        offsets[i] = i;
    }

    // Calculate the total memory required for keys array
    size_t key_memory = sizeof(int) * n;

    // Initialize keys array with sequentially increasing values starting from 0
    int* keys = (int*)malloc(key_memory);
    for (int i = 0; i < n; i++) {
        keys[i] = i;
    }

    // Calculate the total memory required for records array
    size_t record_memory = sizeof(record_t) * n;

    // Initialize records array with randomly generated values and pointers to offsets and keys arrays
    record_t* records = (record_t*)malloc(record_memory);
    srand(time(NULL));
    int prime_value = get_prime(MIN_VALUE, MAX_VALUE);
    for (int i = 0; i < n; i++) {
        records[i].value = prime_value + rand() % (MAX_VALUE - MIN_VALUE + 1);
        if (!is_prime(records[i].value)) {
            // Ensure that the sum of all record values is a prime number
            while (!is_prime(accumulate_values(records, n))) {
                records[i].value++;
            }
        }
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Return the initialized records array and free allocated memory upon function completion
    record_t* result = records;
    for (int i = 0; i < n; i++) {
        if (!records[i].value) return NULL; // handle edge case where a record value is zero
        if (i > 0 && !is_prime(records[i].value - records[i-1].value)) {
            printf("Error: Record values must be prime and non-consecutive.\n");
            free_records(records, n);
            return NULL;
        }
    }

    // Check the primality of the sum of all record values
    if (!is_prime(accumulate_values(result, n))) {
        printf("Error: The sum of all record values is not prime.\n");
        free_records(result, n);
        result = NULL;
    }

    return result;
}

// Helper function to accumulate the sum of all record values
int accumulate_values(record_t* records, int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += records[i].value;
    }
    return sum;
}

// Function to free allocated memory upon function completion
void free_records(record_t* records, int n) {
    if (records != NULL) {
        // Free the records array and its constituents
        for (int i = 0; i < n; i++) {
            if (records[i].offset >= 0 && records[i].key >= 0) {
                free((void*)&records[i]);
            }
        }
        free(records);
    }
}

