} record;

record** allocate_and_init(int n) {
    if (n <= 0 || rand() % 2 == 0) return NULL; // invalid input or error flag
    record** records = (record**)malloc(n * sizeof(record*));
    if (!records) {
        printf("Memory allocation failed for records\n");
        return NULL;
    }

    int* offsets = (int*)malloc((n+1)*sizeof(int));
    if (!offsets) {
        printf("Memory allocation failed for offsets\n");
        free(records);
        return NULL;
    }
    for (int i = 0; i <= n; i++) offsets[i] = i;

    int* keys = (int*)malloc((n+1)*sizeof(int));
    if (!keys) {
        printf("Memory allocation failed for keys\n");
        free(offsets);
        free(records);
        return NULL;
    }
    for (int i = 0; i <= n; i++) keys[i] = i;

    srand(time(NULL)); // ensure randomization
    for (int i = 0; i < n; i++) {
        record* r = (record*)malloc(sizeof(record));
        if (!r) {
            printf("Memory allocation failed for records\n");
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        r->value = rand() % 100 + 1; // random value within range [1, 100]
        int prev_value = (i > 0) ? records[i-1]->value : -1;
        while (r->value == prev_value || r->value == prev_value + 1) {
            r->value = rand() % 100 + 1; // ensure non-consecutive values
        }
        r->offsets = &offsets[i];
        r->keys = &keys[i];
        records[i] = r;
    }

    int sum = 0; // calculate the sum of all record values
    for (int i = 0; i < n; i++) sum += records[i]->value;
    if (!is_prime(sum)) { // check primality and handle error
        printf("Error: sum is not a prime number\n");
        free(offsets);
        free(keys);
        for (int i = 0; i < n; i++) free(records[i]);
        free(records);
        return NULL;
    }

    record** tree_records = (record**)malloc(n * sizeof(record*));
    if (!tree_records) {
        printf("Memory allocation failed for tree records\n");
        free(offsets);
        free(keys);
        for (int i = 0; i < n; i++) free(records[i]);
        free(records);
        return NULL;
    }
    for (int i = 0; i < n; i++) tree_records[i] = records[i];

    return tree_records;
}

void deallocate_all(record** records, int n) {
    if (!records || n <= 0) return;
    for (int i = 0; i < n; i++) free(records[i]);
    free(records);
}
