void* custom_malloc(size_t size) {
    static void* pool_start = NULL;
    static size_t pool_size = 0;
    static int initialized = 0;

    if (!initialized) {
        pool_start = malloc(1024 * 1024); // Initialize a 1MB memory pool
        pool_size = 1024 * 1024;
        initialized = 1;
    }

    if (pool_start + size > pool_start + pool_size) {
        // Re-allocate the memory pool if necessary
        pool_size += 1024 * 1024;
        void* new_pool = realloc(pool_start, pool_size);
        if (!new_pool) return NULL; // Handle allocation failure
        pool_start = new_pool;
    }

    return (void*)((char*)pool_start + size - sizeof(size_t));
}

int main() {
    int num_offsets = 1000;
    long min_offset = 1;
    long max_offset = 10000;

    int num_records = 500;
    int min_value = 1;
    int max_value = 1000;

