    if(option > 1) {
        record* newRecords = (record*)malloc((MAX_RECORDS * 2) * sizeof(record));
        memcpy(newRecords, dynamicRecords, MAX_RECORDS * sizeof(record));
        free(dynamicRecords);
        dynamicRecords = newRecords;
    }

    // Implement cryptographic processing and file I/O operations
    if(strcmp(operationType, "encryption") == 0) {
