Array array_init(int initial_capacity) {
    Array arr = (Array)malloc(sizeof(struct));
    arr->records = (Record*)calloc(initial_capacity, sizeof(Record));
    arr->size = 0;
    arr->capacity = initial_capacity;
    return arr;
}

