    free(arr->records);
    free(arr);
}

int array_resize(Array* arr, int new_size) {
    Array temp_arr = *arr;
    arr->records = (Record*)realloc(temp_arr.records, new_size * sizeof(Record));
    arr->size = new_size;
    arr->capacity = new_size;
    return 0;
}

Array nested_array_init(int initial_capacity) {
    // implementation for nested array initialization
    Array arr = array_init(initial_capacity);
    return arr;
}

void nested_array_free(Array* arr) {
    // implementation for freeing nested arrays
    array_free(arr);
}

