// Initialize the hash table with a given size
HashTable* init_hash_table(int size) {
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    hash_table->size = size;
    hash_table->records = (Record**)malloc(size * sizeof(Record*));
    for (int i = 0; i < size; i++) {
        hash_table->records[i] = NULL;
    }
    return hash_table;
}

// Free the memory allocated by the hash table
void free_hash_table(HashTable* hash_table) {
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->records[i] != NULL) {
            free(hash_table->records[i]);
        }
    }
    free(hash_table->records);
    free(hash_table);
}

// Generate a certificate in PEM format
void generate_certificate(OAuthRequest* request, char** certificate) {
    // Initialize the OpenSSL library
    SSL_library_init();

    // Create a new SSL context
    SSL_CTX* ctx = SSL_CTX_new(TLS_server_method());
    SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER, NULL);
    SSL_CTX_load_verify_locations(ctx, "path/to/ca/cert.pem", "path/to/ca/cert.key");

    // Load the client certificate and private key
    X509* client_cert = load_client_certificate(request->client_cert);
    EVP_PKEY* client_key = load_client_private_key(request->client_key);

    // Generate a new certificate for the request
    X509* new_cert = generate_new_certificate(ctx, client_cert, client_key);

    // Convert the certificate to PEM format
    char* pem_cert = NULL;
    int pem_len = i2s_X509(new_cert, &pem_cert);
    *certificate = pem_cert;

    // Free the OpenSSL resources
    SSL_CTX_free(ctx);
    X509_free(client_cert);
    EVP_PKEY_free(client_key);
}

