    }

    // Add the new element to the list
    (*data_list)[*data_count].offset = offset;
    (*data_list)[*data_count].key = key;
    (*data_count)++;
}

data_t* get_element(data_t** data_list, int index) {
    if (index >= *data_count || index < 0) {
        return NULL;
    }
    return &((*data_list)[index]);
}

void remove_element(data_t** data_list, int* data_count, int index) {
    // Check if the list is not empty
    if (*data_count > 0 && index >= 0 && index < *data_count) {
        // Shift elements to fill the gap
        memmove(&((*data_list)[index]), &((*data_list)[index + 1]), (*data_count - index - 1) * sizeof(data_t));
        (*data_count)--;
    }
}

