// Insert a key-value pair into the hash table
void insert_hash_table(hash_table_t* table, int key, void* value) {
    // Calculate the index for the given key using a simple hash function
    int index = key % table->size;

    // Move to the next slot if collision occurs
    while (table->keys[index] != 0 && table->keys[index] != key) {
        index = (index + 1) % table->size;
