        offsets[i] = offset;

        pthread_create(&threads[i], NULL, process_data, (void*)data);
    }

    for (int i = 0; i < num_ds; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < num_ds; i++) {
