import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class PacketProcessor {
    private static final int MAX_PAYLOAD_LENGTH = 1024;
    private boolean validatePackets = true;

    public List<String> processPackets(List<Packet> packets) {
        ForkJoinPool pool = new ForkJoinPool();
        List<Packet> validPackets = pool.invoke(new PacketHasher(packets));
        pool.shutdown();

        int discardedCount = packets.size() - validPackets.size();
        return getMd5Hashes(validPackets);
    }

    private List<String> getMd5Hashes(List<Packet> packets) {
        List<String> md5Hashes = new ArrayList<>();
        for (Packet packet : packets) {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] bytes = md.digest(packet.getPayload().getBytes());
                StringBuilder sb = new StringBuilder();
                for (byte b : bytes) {
                    sb.append(String.format("%02x", b));
                }
                md5Hashes.add(sb.toString());
            } catch (Exception e) {
                // Log error and skip packet
                System.out.println("Error processing packet: " + e.getMessage());
            }
        }
        return md5Hashes;
    }

    private class PacketHasher extends RecursiveTask<List<Packet>> {
        List<Packet> packets;

        public PacketHasher(List<Packet> packets) {
            this.packets = packets;
        }

        @Override
        protected List<Packet> compute() {
            if (packets.size() <= 1) {
                // Process packet directly
                return processSinglePacket(packets.get(0));
            } else {
                int mid = packets.size() / 2;
                List<Packet> leftPackets = new ArrayList<>(packets.subList(0, mid));
                List<Packet> rightPackets = new ArrayList<>(packets.subList(mid, packets.size()));

                // Split work into two parts
                PacketHasher leftTask = new PacketHasher(leftPackets);
                PacketHasher rightTask = new PacketHasher(rightPackets);

                // Fork tasks and get results
                List<Packet> leftResult = leftTask.forkAndJoin();
                List<Packet> rightResult = rightTask.forkAndJoin();

                // Merge results
                return mergeResults(leftResult, rightResult);
            }
        }

        private List<Packet> processSinglePacket(Packet packet) {
            if (packet.getPayload().length > MAX_PAYLOAD_LENGTH) {
                // Discard packets with payload exceeding 1024 characters
                System.out.println("Discarded packet: " + packet.getSource() + " -> " + packet.getDestination());
                return new ArrayList<>();
            } else {
                return new ArrayList<>(Collections.singletonList(packet));
            }
        }

        private List<Packet> mergeResults(List<Packet> left, List<Packet> right) {
            List<Packet> merged = new ArrayList<>(left);
            merged.addAll(right);
            return merged;
        }
    }
}
