using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class DatabaseBatchExecutor
{
    private readonly ILogger _logger;
    private readonly int _maxConcurrentOperations;
    private readonly int _minThreadPoolSize;
    private readonly int _maxThreadPoolSize;
    private readonly TimeSpan _timeout;

    public DatabaseBatchExecutor(ILogger logger, int maxConcurrentOperations, int minThreadPoolSize, int maxThreadPoolSize, TimeSpan timeout)
    {
        _logger = logger;
        _maxConcurrentOperations = maxConcurrentOperations;
        _minThreadPoolSize = minThreadPoolSize;
        _maxThreadPoolSize = maxThreadPoolSize;
        _timeout = timeout;
    }

    public async Task<ExecutionReport> ExecuteBatchAsync(List<string> sqlCommands, string connectionString)
    {
        var executionReports = new List<ExecutionReport>();
        var threadPool = new Threadpool(_minThreadPoolSize, _maxThreadPoolSize);

        foreach (var command in sqlCommands)
        {
            var operationId = Guid.NewGuid();
            var executionReport = await ExecuteOperationAsync(connectionString, command, operationId);
            executionReports.Add(executionReport);
        }

        return new ExecutionReport
        {
            SuccessRate = CalculateSuccessRate(executionReports),
            AverageExecutionTime = CalculateAverageExecutionTime(executionReports),
            PeakConcurrency = threadPool.GetPeakConcurrency(),
            Logs = LogOperationsAsync(executionReports).Result,
        };
    }

    private async Task<ExecutionReport> ExecuteOperationAsync(string connectionString, string command, Guid operationId)
    {
        var connection = await GetConnectionAsync(connectionString);
        try
        {
            await connection.ExecuteAsync(command, _timeout);
        }
        catch (Exception ex)
        {
            // Retry logic goes here based on retry policy
            throw;
        }
        finally
        {
            connection.Dispose();
        }

        return new ExecutionReport
        {
            OperationId = operationId,
            Success = true,
            ExecutionTime = DateTime.Now - DateTimeOffset.Now,
        };
    }

    private async Task<SqlConnection> GetConnectionAsync(string connectionString)
    {
        using (var connection = new SqlConnection(connectionString))
        {
            await connection.OpenAsync();
            return connection;
        }
    }

    private async Task<List<string>> LogOperationsAsync(List<ExecutionReport> executionReports)
    {
        var logs = new List<string>();

        foreach (var report in executionReports)
        {
            var logMessage = $"Operation {report.OperationId} {(report.Success ? "SUCCEEDED" : "FAILED")}";
            if (!report.Success)
            {
                logMessage += $": {report.Exception.Message}";
            }
            logMessage += $" ({report.ExecutionTime.TotalMilliseconds} ms)";
            logs.Add(logMessage);
        }

        return logs;
    }

    private double CalculateSuccessRate(List<ExecutionReport> executionReports) => (double)executionReports.Count(r => r.Success) / executionReports.Count;

    private TimeSpan CalculateAverageExecutionTime(List<ExecutionReport> executionReports) => new TimeSpan(0).AddTicks(executionReports.Sum(r => r.ExecutionTime.Ticks)) / executionReports.Count;
}

public class ExecutionReport
{
    public Guid OperationId { get; set; }
    public bool Success { get; set; }
    public TimeSpan ExecutionTime { get; set; }
}

