    void selectAndExecuteAttack(const std::queue<Attack>& attackQueue, const PaymentProcessor& paymentProcessor) {
        if (attackQueue.empty()) return;

        Attack attack = attackQueue.front();
        attackQueue.pop();

        if (std::chrono::system_clock::now() < attack.cooldownEnd) {
            // Cooldown period not yet over
            std::cout << "Cooldown period not yet over. Skipping attack." << std::endl;
            return;
