        }

        selector.selectAndExecuteAttack(attackQueue, paymentProcessor);

        // Process batched payments every 1 second
        std::this_thread::sleep_for(std::chrono::milliseconds(DeduplicationIntervalMilliseconds));
    }

    return 0;
}
