void selectAndExecuteAttack(std::mt19937& rng) {
    static const std::vector<Attack::Type> attacks = {Attack::FIST, Attack::ELBOW, Attack::KICK};
    static const int cooldownTime = 9; // seconds
    static int currentCooldowns[3] = {0};

    if (currentCooldowns[0] > 0) {
        --currentCooldowns[0];
    }
    if (currentCooldowns[1] > 0) {
        --currentCooldowns[1];
    }
    if (currentCooldowns[2] > 0) {
        --currentCooldowns[2];
    }

    int attackIndex = rng() % 3;
    std::cout << "Selected Attack: " << static_cast<int>(attacks[attackIndex]) << std::endl;

    currentCooldowns[attackIndex] = cooldownTime;

    // Payment processing
    if (paymentProcessingFramework()) {
        // Batching mechanism for network writes
        int batchSize = 100;
        for (int i = 0; i < batchSize && !transactions.empty(); ++i) {
            transactions.pop();
            writeTransactionToServer();
        }
    }

    // Statistical summaries
    static int successfulAttacks = 0;
    if (!isCooldownActive()) {
        ++successfulAttacks;
    }
}

bool isCooldownActive() {
    for (int i = 0; i < 3; ++i) {
        if (currentCooldowns[i] > 0) {
            return true;
        }
    }
    return false;
}

