    record* records = (record*) arena;
    long* offsets = (long*) ((char*) records + num_records * sizeof(record));
    int* keys = (int*) ((char*) records + num_offsets * sizeof(long) + num_keys * sizeof(int));

    // Initialize arrays
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i;
    }

    // Populate records array with random values and pointer assignments
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(min_value, max_value);

    for (int i = 0; i < num_records; i++) {
        record& r = records[i];
        r.value = dis(gen);
        r.offset_ptr = &offsets[dis(gen) % num_offsets];
        r.key_ptr = &keys[dis(gen) % num_keys];
