}

// Function to handle dynamic resizing of RLC PDU pool
void resize_rlc_pdu_pool(LTE_RLC_PDU_T** pool, int* count, int new_count) {
    // Deallocate memory for the old pool
    free(*pool);

    // Allocate memory for the new pool
    *pool = (LTE_RLC_PDU_T*)malloc(new_count * sizeof(LTE_RLC_PDU_T));

    if (!*pool) {
        // Handle memory allocation failure
        printf("Memory allocation failed\n");
        return;
    }

    // Copy data from old pool to new pool
    for (int i = 0; i < *count; i++) {
        (*pool)[i].RLC_AM_STATUS_REPORT = (*pool)[i - 1].RLC_AM_STATUS_REPORT;
        (*pool)[i].RLC_AM_STATUS_REPORT_CONFIRMATION = (*pool)[i - 1].RLC_AM_STATUS_REPORT_CONFIRMATION;
    }

    // Update count and pool pointer
    *count = new_count;
}

