Transaction* manageTransactions(int numTransactions, int numTags, int randomAmountRange) {
    Transaction* transactions = (Transaction*)malloc(numTransactions * sizeof(Transaction));
    if (!transactions) {
        return NULL; // handle memory allocation failure
    }

    for (int i = 0; i < numTransactions; i++) {
        transactions[i].id = i;
        transactions[i].timestamp = time(NULL);
        sprintf(transactions[i].currency, "%c", 'X' + rand() % 26); // random currency code
        transactions[i].amount = (double)rand() / RAND_MAX * randomAmountRange; // random amount
        transactions[i].tags = (char**)malloc((numTags + 1) * sizeof(char*));
        for (int j = 0; j < numTags; j++) {
            transactions[i].tags[j] = (char*)malloc(16 * sizeof(char)); // assuming max tag length of 15
            sprintf(transactions[i].tags[j], "Tag_%d", j); // random tag name
        }
        transactions[i].tags[numTags] = NULL;
    }

    double totalAmount = 0.0;
    int topN = 3; // compute average transaction amount and top N transactions by amount
    for (int i = 0; i < numTransactions; i++) {
        if (transactions[i].amount > 100.0) { // filter transactions based on criteria
            totalAmount += transactions[i].amount;
        } else {
            free(transactions[i].tags);
            transactions[i].tags = NULL; // handle incomplete or invalid data
        }
    }

    printf("Average transaction amount: %.2f\n", totalAmount / (numTransactions - topN));
    int highestWeightedSum = 0;
    int topTransactionId = 0;
    for (int i = 0; i < numTransactions; i++) {
        if (transactions[i].amount > 100.0) { // filter transactions based on criteria
            transactions[i].weightedSum = transactions[i].amount * 2 + rand() % 10; // weighted sum calculation
            if (transactions[i].weightedSum > highestWeightedSum) {
                highestWeightedSum = transactions[i].weightedSum;
                topTransactionId = transactions[i].id;
            }
        } else {
            free(transactions[i].tags);
            transactions[i].tags = NULL; // handle incomplete or invalid data
        }
    }

    printf("Top transaction ID: %d\n", topTransactionId);

    for (int i = 0; i < numTransactions; i++) {
        if (transactions[i].amount > 100.0) { // filter transactions based on criteria
            free(transactions[i].tags);
        } else {
            free(transactions[i].tags); // handle incomplete or invalid data
        }
    }

    free(transactions);

    return NULL;
}
