#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY 1024 * 1024 // 1MB
#define MEMORY_THRESHOLD 0.8 // 80% of max memory usage allowed
#define FLOAT_RANGE -10.0f, 10.0f // Random float value range
#define TIMESTAMP_RANGE 0, 1000000 // Unique timestamp range
#define SENSOR_INDEX_RANGE 0, 100 // Unique sensor index range

typedef struct {
    float data;
    char identifier;
    int timestamp;
} data_point;

data_point* memory_manager(int num_data_points) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    data_point* data_points = NULL;
    size_t total_memory = 0;
    size_t allocated_memory = 0;
    srand(time(NULL));

    for (int i = 0; i < num_data_points; i++) {
        data_point* new_data_point = malloc(sizeof(data_point));
        if (!new_data_point) {
            // Handle memory allocation failure
            printf("Memory allocation failed. Reducing memory usage...\n");
            return NULL;
        }

        new_data_point->data = (float)(rand() * (FLOAT_RANGE.end - FLOAT_RANGE.start)) + FLOAT_RANGE.start;
        new_data_point->identifier = 'A' + i % 26; // ASCII letters
        new_data_point->timestamp = rand() % TIMESTAMP_RANGE.end;

        if (!data_points) {
            data_points = new_data_point;
            allocated_memory += sizeof(data_point);
        } else {
            data_point* prev_data_point = data_points;
            while (prev_data_point->next) {
                prev_data_point = prev_data_point->next;
            }
            prev_data_point->next = new_data_point;
        }

        total_memory += sizeof(data_point);

        if ((double)total_memory / allocated_memory > MEMORY_THRESHOLD) {
            // Handle memory usage threshold exceeded
            printf("Memory usage exceeds %f%% of max. Reducing data points...\n", MEMORY_THRESHOLD * 100);
            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);

    return data_points;
}
