typedef struct {
    int value;
    int* key;
} record;

int min_value = 1; // adjust as needed
int max_value = 1000; // adjust as needed

void* task_manager(void* arg) {
    int num_tasks = *(int*)arg;
    int i, j;
    record** records;

    // allocate memory for records
    records = (record**)malloc(num_tasks * sizeof(record*));
    if (!records) {
        // handle error
        return NULL;
    }

    // initialize each record
    for (i = 0; i < num_tasks; i++) {
        int val = (int)((max_value - min_value) * drand48() + min_value);
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            // handle error
            free(records);
            return NULL;
        }

        records[i]->value = val;
        records[i]->key = (int*)malloc((2*i+1) * sizeof(int));
        if (!records[i]->key) {
            // handle error
            free(records[i]);
            free(records);
            return NULL;
        }
    }

    // initialize dynamic list of Task structures
    struct Task** tasks;
    tasks = (struct Task**)malloc(num_tasks * sizeof(struct Task*));
    if (!tasks) {
        // handle error
        for (i = 0; i < num_tasks; i++) {
            free(records[i]->key);
            free(records[i]);
        }
        free(records);
        return NULL;
    }

    // initialize each task
    for (j = 0; j < num_tasks; j++) {
        tasks[j] = (struct Task*)malloc(sizeof(struct Task));
        if (!tasks[j]) {
            // handle error
            for (i = 0; i <= j; i++) {
                free(records[i]->key);
                free(records[i]);
            }
            free(records);
            return NULL;
        }

        tasks[j]->offsets = records[j]->key;
        tasks[j]->keys = &records[j]->value;
    }

    // deallocate memory
    for (i = 0; i < num_tasks; i++) {
        free(tasks[i]);
    }
    free(tasks);
    for (i = 0; i < num_tasks; i++) {
        free(records[i]->key);
        free(records[i]);
    }
    free(records);

    return NULL;
}

int main() {
    int NFAPI_CRC_INDICATION_PDU_T_SIZE = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_t thread;

    pthread_create(&thread, NULL, task_manager, &num_tasks);

    // handle errors and logging
    if (pthread_join(thread, NULL) == -1)
        perror("pthread_join");

    return 0;
}
