    errorRecordData->timestamp = timestamp;

    systemHealth *systemHealthData = (systemHealth *)malloc(sizeof(systemHealth));
    diskSpace = 80.0f; // default value
    memAvailability = 90.0f; // default value
    processStatus = 1; // default value

    configParamsSem = sem_open("/configParams", O_CREAT, 0600);
    metricsSem = sem_open("/metrics", O_CREAT, 0600);
    requestLogSem = sem_open("/requestLog", O_CREAT, 0600);
    errorRecordsSem = sem_open("/errorRecords", O_CREAT, 0600);
    systemHealthSem = sem_open("/systemHealth", O_CREAT, 0600);

    // incrementally update the metrics and requestLog structures
    pthread_mutex_lock(&mutex);
    pthread_cond_signal(&condition);

    // handle memory allocation failures gracefully
    if (!config || !metricsData || !requestLogData || !errorRecordData || !systemHealthData) {
        // log errors and deallocate memory
        free(config);
        free(metricsData);
        free(requestLogData);
        free(errorRecordData);
        free(systemHealthData);

        // handle transient failures and provide notifications for persistent issues
        pthread_mutex_unlock(&mutex);
    }
}

// function to release the structures and semaphores
void releaseStructures() {
    // decrement the semaphores and wait for the threads to finish
    sem_post(configParamsSem);
    sem_post(metricsSem);
    sem_post(requestLogSem);
    sem_post(errorRecordsSem);
    sem_post(systemHealthSem);

    // deallocate memory for the structures
    free(config);
    free(metricsData);
    free(requestLogData);
    free(errorRecordData);
    free(systemHealthData);

    // close and remove the semaphores
    sem_close(configParamsSem);
    sem_close(metricsSem);
    sem_close(requestLogSem);
    sem_close(errorRecordsSem);
    sem_close(systemHealthSem);
}

int main() {
    initStructures();
    releaseStructures();

    return 0;
}
