    new_entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    pthread_mutex_lock(&dir_lock);
    dir[dir_count] = new_entry;
    dir_count++;
    pthread_mutex_unlock(&dir_lock);
}

NFAPI_CRC_INDICATION_PDU_T* get_from_dir(int RNTI) {
    for (int i = 0; i < dir_count; i++) {
        if (dir[i]->RNTI == RNTI) {
            return dir[i];
        }
    }
    return NULL;
}

void remove_from_dir(int RNTI) {
    pthread_mutex_lock(&dir_lock);
    for (int i = 0; i < dir_count; i++) {
        if (dir[i]->RNTI == RNTI) {
            free(dir[i]);
            memmove(&dir[i], &dir[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (dir_count - i));
            dir_count--;
            break;
