record* init_records(int num_records, int max_offset_value, int max_key_value, size_t max_memory_usage) {
    int i;
    size_t total_memory_needed = sizeof(record) * num_records + sizeof(long) * (num_records / 8) + sizeof(int);

    if (total_memory_needed > max_memory_usage) {
        return NULL; // Insufficient memory
    }

    record* records = (record*) malloc(total_memory_needed);
    long* offsets = (long*)malloc((num_records / 8) * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));

    if (!records || !offsets || !keys) {
        // Free the already allocated memory
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL)); // Initialize random number generator

    for (i = 0; i < num_records; i++) {
        records[i].key = rand() % max_key_value;
        records[i].offset = (long)rand() % max_offset_value;
    }

    free(offsets);
    free(keys);

    return records;
}

void free_records(record* records, int num_records) {
    if (!records) {
        return; // No memory to free
    }

    free(records);
