        keys[i] = rand() % 1000;
    }

    // Track memory usage
    int allocated = num_records * sizeof(record_t) + num_records * sizeof(offset_t) + num_records * sizeof(int);
    int deallocated = 0;

    return records;
}

void free_records(record_t* records, offset_t* offsets, int* keys) {
    if (records) {
        for (int i = 0; i < num_records; i++) {
            record_t* rec = &records[i];
            if (rec->string) {
                free(rec->string);
                deallocated++;
            }
        }
        free(records);
        deallocated += num_records * sizeof(record_t);
    }

    if (offsets) {
        free(offsets);
        deallocated += num_records * sizeof(offset_t);
    }

    if (keys) {
        free(keys);
        deallocated += num_records * sizeof(int);
    }

    printf("Deallocated %d bytes.\n", allocated - deallocated);
}

void* aligned_malloc(size_t size, size_t alignment) {
    int padding = ((long)0) % alignment;
    void* ptr = malloc((size + padding) / alignment * alignment);
    if (ptr)
        return ptr;
    else
        return NULL;
}
