void* config_pool_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) return NULL;
    // Align the allocated block to 64-byte boundary
    size_t alignment = (size_t)(0x3F & ((size_t)ptr - 1));
    ptr = (void*)((size_t)ptr + alignment) - alignment;
    return ptr;
}

void config_pool_free(void* ptr, size_t size) {
    free(ptr);
}

