        audit_rec->action_type = malloc(16); // Allocate memory for a fixed-size string
        sprintf(audit_rec->action_type, "Action_%d", i);
        audit_rec->timestamp = time(NULL);
        audit_rec->user_name = malloc(64); // Allocate memory for a larger string
        sprintf(audit_rec->user_name, "User_%d", i);
    }

    // Periodically flush the audit logs to disk and ensure log integrity
    FILE* audit_log = fopen("audit_log.txt", "w");
    if (audit_log) {
        fwrite(audits, sizeof(audit), num_audits, audit_log);
        fclose(audit_log);
