#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

#define MAX_OFFSETS 1000
#define MAX_RECORDS 2000
#define RANGE_START 1
#define RANGE_END 100

typedef struct {
    int value;
} record;

bool isValidInput(size_t input) {
    return (input > 0 && input <= MAX_OFFSETS);
}

void* allocateMemory(size_t size) {
    void* memory = malloc(size);
    if (!memory) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    return memory;
}

void deallocateMemory(void* memory, size_t size) {
    free(memory);
}

record generateRecord() {
    record r;
    r.value = (rand() % (RANGE_END - RANGE_START + 1)) + RANGE_START;
    return r;
}

int populateRecords(record* records, size_t count) {
    for (size_t i = 0; i < count; i++) {
        while (true) {
            record newRecord = generateRecord();
            if (!isAdjacentToExisting(records[i].value, newRecord.value)) {
                records[i] = newRecord;
                break;
            }
        }
    }
    return 0;
}

bool isAdjacentToExisting(int existingValue, int newValue) {
    return (abs(existingValue - newValue) == 1);
