typedef struct {
    int id;
    char* name;
    double value;
} Record;

typedef struct {
    int size;
    Record** records;
} HashTable;

void initRecord(Record* record, int id) {
    record->id = id;
    record->name = (char*)malloc(strlen("default_name") + 1);
    strcpy(record->name, "default_name");
    record->value = (double)rand() / RAND_MAX;
}

HashTable* initHashTable(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->records = (Record**)calloc(size, sizeof(Record*));
    return table;
}

void resizeHashTable(HashTable* table, int newSize) {
    Record** newRecords = (Record**)realloc(table->records, newSize * sizeof(Record*));
    if (!newRecords) {
        // Handle memory allocation failure
        printf("Failed to resize hash table.\n");
        return;
    }
    table->size = newSize;
    table->records = newRecords;
}

void addRecordToHashTable(HashTable* table, Record* record) {
    int index = rand() % table->size;
    if (table->records[index]) {
        // Handle collision using linear probing
        for (int i = 1; ; i++) {
            int newIndex = (index + i) % table->size;
            if (!table->records[newIndex]) {
                table->records[newIndex] = record;
                return;
            }
        }
    } else {
        table->records[index] = record;
    }
}

Record* getRecordFromHashTable(HashTable* table, int id) {
    for (int i = 0; i < table->size; i++) {
        Record* record = table->records[i];
        if (record && record->id == id) {
            return record;
        }
    }
    return NULL;
}

void freeRecord(Record* record) {
    free(record->name);
    free(record);
}

void freeHashTable(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        Record* record = table->records[i];
        if (record) {
            freeRecord(record);
        }
    }
    free(table->records);
    free(table);
}
