// Define a record structure to hold an int value
typedef struct {
    int value;
} record;

// Global error flag
int error_occurred = 0;

// Function to populate records with unique values
void* generate_unique_values(void* arg) {
    // Get the number of offsets and maximum possible long value
    int num_offsets = *((int*)arg);
    long max_long_value = LONG_MAX;

    // Generate unique record values using a non-linear mapping algorithm
    for (int i = 0; i < num_offsets; i++) {
        record* rec = malloc(sizeof(record));
        if (!rec) {
            error_occurred = 1;
            return NULL;
        }
        long mapped_value = (long)(i * max_long_value / num_offsets);
        rec->value = (int)mapped_value;
        // Store the record in an array
    }

    // Free memory after processing
    free(rec);

    return NULL;
}

// Function to manage memory allocation and initialization for three arrays
void* manage_memory(void* arg) {
    int* offsets;
    int num_offsets;
    int* keys;

    // Allocate memory for the array of long offsets
    if (!(num_offsets = malloc(sizeof(int)))) {
        error_occurred = 1;
        return NULL;
    }
    *num_offsets = 0;

    // Validate and read user input to determine the number of offsets
    scanf("%d", num_offsets);
    while (*num_offsets <= 0 || *num_offsets >= 10000) {
        printf("Invalid input. Please enter a positive integer less than 10,000: ");
        scanf("%d", num_offsets);
    }

    // Allocate memory for the array of int keys
    if (!(keys = malloc(3 * sizeof(int)))) {
        error_occurred = 1;
        return NULL;
    }
    memset(keys, 0, 3 * sizeof(int));

    // Create an array of record structures
    if (!(offsets = malloc(*num_offsets * sizeof(record)))) {
        error_occurred = 1;
        return NULL;
    }
    memset(offsets, 0, *num_offsets * sizeof(record));

    // Initialize and populate each record with unique int values using the generate_unique_values function
    pthread_t thread;
    if (pthread_create(&thread, NULL, generate_unique_values, &num_offsets)) {
        error_occurred = 1;
        return NULL;
    }
    pthread_join(thread, NULL);

    // Free memory upon completion
    free(keys);
    free(offsets);

    // Secondary verification process to confirm all memory has been freed
    if (error_occurred) {
        printf("Memory allocation failed.\n");
    } else {
        printf("Memory allocated successfully.\n");
    }

    return NULL;
}
