data_point** new_dataset(size_t size) {
    pthread_mutex_lock(&mutex);
    void* ptr = malloc((sizeof(data_point*) * (size + 1)));
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed for dataset.\n");
        return NULL;
    }

    data_point** arr = (data_point**)ptr;
    for (int i = 0; i <= size; i++) {
        arr[i] = malloc(sizeof(data_point));
        if (!arr[i]) {
            free(ptr);
            fprintf(stderr, "Memory allocation failed for dataset.\n");
            return NULL;
        }
    }

    total_allocated_memory += sizeof(data_point*) * (size + 1) + sizeof(data_point) * size;
    pthread_mutex_unlock(&mutex);
    return arr;
}

void add_data_point(data_point** dataset, size_t index) {
    dataset[index] = malloc(sizeof(data_point));
    if (!dataset[index]) {
        fprintf(stderr, "Memory allocation failed for data point.\n");
    }
}

void remove_data_point(data_point** dataset, size_t index) {
    free(dataset[index]);
    dataset[index] = NULL;
}

data_point*** init_datasets(size_t num_points_per_dataset, size_t limit) {
    pthread_mutex_lock(&mutex);

    if (total_allocated_memory > limit) {
        fprintf(stderr, "Memory allocation exceeded the specified limit.\n");
        return NULL;
    }

    datasets = malloc(sizeof(data_point**));
    *datasets = NULL;

    for (size_t i = 0; i < num_points_per_dataset; i++) {
        data_point** dataset = new_dataset(i);
        if (!dataset) {
            break;
        }

        add_data_point(dataset, 0);
        //add more data points as needed

        pthread_mutex_unlock(&mutex);

        //process the dataset here
    }

    return datasets;
}
