EVP_CIPHER_CTX* choose_cipher(const char* mode_str) {
    if (strcmp(mode_str, "ECB") == 0) {
        return EVP_aes_256_ecb();
    } else if (strcmp(mode_str, "CBC") == 0) {
        return EVP_aes_256_cbc();
    } else if (strcmp(mode_str, "GCM") == 0) {
        return EVP_aes_256_gcm();
    } else if (strcmp(mode_str, "CTR") == 0) {
        return EVP_aes_256_ctr();
    }
    // Default to null encryption for testing purposes
    return NULL;
}

bool parse_oauth2_token(const char* token_json, TokenStoreEntry** tokens, int* num_tokens) {
    json_object* token_obj = json_object_from_string(token_json);
    if (!token_obj) {
        return false;
    }

    // Verify required fields
    if (!json_object_object_get_ex(token_obj, "access_token", &json_object)) {
        return false;
    }
    if (!json_object_object_get_ex(token_obj, "expires_in", &json_object)) {
        return false;
    }
    int expires_in = json_object_get_int_value(json_object);
    if (expires_in < 0) {
        return false;
    }

    // Update access token if expired
    time_t now = time(NULL);
    if (now > expires_in * 1000 + 50000) { // 50 second buffer
        json_object* new_token_obj = json_object_new();
        json_object_object_add(new_token_obj, "access_token", json_string_create(json_object_get_string_value(json_object)));
        int new_expires_in = now - (expires_in * 1000 - 30000); // 30 seconds before expiration
        json_object_object_add(new_token_obj, "expires_in", json_int_create(new_expires_in));
        json_object_object_add(new_token_obj, "refresh_token", json_string_create(gen_random_uuid()));
        token_json = json_object_to_json_string_ext(new_token_obj, JSON_COMPACT);
    }

    // Parse and store tokens
    *num_tokens = 0;
    char** token_keys = (char**)malloc(sizeof(char*) * json_object_get_length(token_obj));
    for (int i = 0; i < json_object_get_length(token_obj); i++) {
        json_object* token_obj_key = json_object_get_array_item(token_obj, i);
        TokenStoreEntry* entry = malloc(sizeof(TokenStoreEntry));
        entry->user_id = json_object_get_string_value(token_obj_key);
        entry->token = json_object_get_string_value(json_object_object_get_ex(token_obj, "access_token", &json_object));
        token_keys[*num_tokens] = entry->user_id;
        (*num_tokens)++;
    }

    *tokens = (TokenStoreEntry**)malloc(sizeof(TokenStoreEntry*) * (*num_tokens));
    for (int i = 0; i < *num_tokens; i++) {
        (*tokens)[i] = token_keys[i];
    }

    free(token_keys);
    return true;
}

