Record* dataManagementSystem(int max_records) {
    // Initialize the maximum number of records
    static Record* records = NULL;
    if (records == NULL || max_records > 0) {
        // Dynamically allocate memory for the record array
        records = realloc(records, sizeof(Record) * (max_records + 1));
        if (records == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
    }

    // Initialize the top-level record
    Record* current_record = &records[max_records];
    int id = rand() % (1000 - 1) + 1; // Randomly generate an ID within a specified range
    char name[16];
    for (int i = 0; i < 15; i++) {
        name[i] = 'a' + (rand() % 26);
    }
    name[15] = '\0'; // Null-terminate the string
    double value = rand() / (double)RAND_MAX;

    // Dynamically allocate memory for nested records
    int num_nested_records = rand() % 3; // Randomly decide on the number of nested records
    Record* nested_records = NULL;
    if (num_nested_records > 0) {
        nested_records = malloc(sizeof(Record) * num_nested_records);
        if (nested_records == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
    }

    // Initialize the cache mechanism
    int cache_size = 100; // Initialize a small cache size for testing purposes
    Record** cache_entries = malloc(sizeof(Record*) * cache_size);
    if (cache_entries == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    int cache_count = 0;

    // Simulate the media streaming service scenario
    int session_duration = rand() % 3600; // Randomly generate a session duration within a range
    for (int i = 0; i < max_records; i++) {
        // Dynamically allocate memory for each record's playback history and preferences
        int* playback_history = malloc(sizeof(int) * (session_duration + 1));
        if (playback_history == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        char* preference = malloc(16);
        if (preference == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        // Simulate the user's playback history and preferences
        for (int j = 0; j < session_duration; j++) {
            playback_history[j] = rand() % 100; // Randomly generate a playback time within a range
        }
        sprintf(preference, "User Preference"); // Initialize a preference string

        // Store the record in the cache mechanism
        Record* current_entry = malloc(sizeof(Record));
        if (current_entry == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        current_entry->id = id;
        strcpy(current_entry->name, name);
        current_entry->value = value;
        current_entry->nested_records = nested_records;
        cache_entries[cache_count] = current_entry;
        cache_count++;

        // Dynamically deallocate memory for the record and its playback history
        free(playback_history);
    }

    // Simulate a real-world scenario where this data structure is part of a media streaming service
    int user_sessions = rand() % 100; // Randomly generate the number of user sessions within a range
    for (int i = 0; i < user_sessions; i++) {
        // Dynamically allocate memory for each user session's metadata
        Record* current_session = malloc(sizeof(Record));
        if (current_session == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        int playback_history_size = rand() % 100; // Randomly generate the size of the playback history within a range
        char** preferences = malloc(sizeof(char*) * playback_history_size);
        for (int j = 0; j < playback_history_size; j++) {
            preferences[j] = malloc(16); // Dynamically allocate memory for each preference string
            if (preferences[j] == NULL) {
                printf("Memory allocation failed.\n");
                return NULL;
            }
            sprintf(preferences[j], "Preference %d", j); // Initialize a preference string
        }

        // Store the user session metadata in the cache mechanism
        Record* current_entry = malloc(sizeof(Record));
        if (current_entry == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        current_entry->id = id;
        strcpy(current_entry->name, name);
        current_entry->value = value;
        current_entry->nested_records = nested_records;
        cache_entries[cache_count] = current_entry;
        cache_count++;

        // Dynamically deallocate memory for the user session metadata and preferences
        for (int j = 0; j < playback_history_size; j++) {
            free(preferences[j]);
        }
    }

    return &records[max_records - 1];
}
