['Here is the code for the `initialize_and_manage_mqtt_subscriptions` function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct to represent MQTT subscription configurations
typedef struct {
    char* client_id;
    char* topic_filter;
    int qos;
    void (*message_handler)(void*);
} mqtt_subscription_config;

// Define a linked list node for the subscriptions
typedef struct node {
    mqtt_subscription_config config;
    struct node* next;
} subscription_node;

// Define the main data structure to manage MQTT subscriptions
typedef struct {
    int num_subscriptions;
    pthread_mutex_t lock;
    subscription_node* head;
} mqtt_subscriptions;

// Initialize and return a new linked list for managing MQTT subscriptions
mqtt_subscriptions* initialize_mqtt_subscriptions(int num_subscriptions) {
    mqtt_subscriptions* subs = (mqtt_subscriptions*)malloc(sizeof(mqtt_subscriptions));
    subs->num_subscriptions = num_subscriptions;
    pthread_mutex_init(&subs->lock, NULL);
    subs->head = NULL;
    return subs;
}

// Add a new MQTT subscription to the list
void add_mqtt_subscription(mqtt_subscriptions* subs, mqtt_subscription_config config) {
    // Create a new node for the subscription
    subscription_node* node = (subscription_node*)malloc(sizeof(subscription_node));
    node->config = config;

    // If this is the first subscription, set it as the head of the list
    if (!subs->head) {
        subs->head = node;
    } else {
        // Otherwise, add it to the end of the list
        subscription_node* current = subs->head;
        while (current->next) {
            current = current->next;
        }
        current->next = node;
    }

    // Increment the count of subscriptions
    subs->num_subscriptions++;
}

// Remove an MQTT subscription from the list by client ID
void remove_mqtt_subscription(mqtt_subscriptions* subs, char* client_id) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&subs->lock);

    // Find the subscription with the matching client ID
    subscription_node* current = subs->head;
    while (current) {
        if (strcmp(current->config.client_id, client_id) == 0) {
            // Remove this subscription from the list
            if (current == subs->head) {
                subs->head = current->next;
            } else {
                subscription_node* prev = subs->head;
                while (prev->next != current) {
                    prev = prev->next;
                }
                prev->next = current->next;
            }
            free(current);
            break;
        }
        current = current->next;
    }

    // Unlock the list
    pthread_mutex_unlock(&subs->lock);

    // Decrement the count of subscriptions if removed
    subs->num_subscriptions--;
}

// Free all allocated memory for MQTT subscriptions
void free_mqtt_subscriptions(mqtt_subscriptions* subs) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&subs->lock);

    // Release each subscription from the list and free its memory
    subscription_node* current = subs->head;
    while (current) {
        subscription_node* next = current->next;
        free(current);
        current = next;
    }

    // Set the head of the list to NULL and release the lock
    subs->head = NULL;
    pthread_mutex_unlock(&subs->lock);

    // Free the linked list itself
    free(subs);
}

// Export the entire list of MQTT subscriptions to a JSON file
void export_mqtt_subscriptions(mqtt_subscriptions* subs, char* filename) {
    // Open the file for writing
    FILE* file = fopen(filename, "w");
    if (!file) return;

    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&subs->lock);

    // Write each subscription to the file in JSON format
    int i = 0;
    subscription_node* current = subs->head;
    while (current) {
        fprintf(file, "{\"client_id\":\"%s\",\"topic_filter\":\"%s\",\"qos\":%d},\n",
            current->config.client_id,
            current->config.topic_filter,
            current->config.qos);
        current = current->next;
    }

    // Close the file and release the lock
    fclose(file);
    pthread_mutex_unlock(&subs->lock);
}
