        metadata[i].tag = malloc(strlen(buffer) + 1);
        strcpy(metadata[i].tag, buffer);
        metadata[i].attr1 = i;
        metadata[i].attr2 = i * 2;
    }

    // Free dynamically allocated memory
    free(records);
    free(keys);
    for (int i = 0; i < num_offsets; i++)
        free(metadata[i].tag);

    return 0;
}
