        else if (strncmp(argv[i], "-o", 2) == 0)
            ; // Redirect output to a specified file
        else if (strcmp(argv[i], "--manpage") == 0)
            print_usage();
        else
            return 0;
    }

    return 1;
}

void print_usage() {
