// Function to dynamically allocate memory and initialize data structures
void* dynamic_init(size_t num_threads, size_t num_connections) {
    // Calculate the total allowed memory usage (75% of available system memory)
    size_t max_memory = 0.75 * sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);

    // Allocate memory for arrays
    long long* thread_ids = malloc(num_threads * sizeof(long long));
    void** thread_pointers = malloc(num_threads * sizeof(void*));
    thread_info* thread_info_arr = malloc(num_threads * sizeof(thread_info));
    network_connection* connection_arr = malloc(num_connections * sizeof(network_connection));

    // Initialize thread information
    for (size_t i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
        thread_pointers[i] = &thread_info_arr[i];
        thread_info_arr[i].id = thread_ids[i];
        thread_info_arr[i].priority = rand() % 100;
        strcpy(thread_info_arr[i].current_status, "idle");
    }

    // Initialize network connections
    for (size_t i = 0; i < num_connections; i++) {
        connection_arr[i].ip_address[0] = '\0';
        connection_arr[i].port_number = rand() % 65535;
        strcpy(connection_arr[i].connection_state, "established");
    }

    // Return the initialized data structures
    void* result[] = {thread_ids, thread_pointers, thread_info_arr, connection_arr};
    return result;
}
