#define USER_ID_LENGTH 16

typedef struct {
    int transaction_id;
    double amount;
    char currency[4];
    char user_id[USER_ID_LENGTH];
} Transaction;

Transaction* allocate_transactions(int num_transactions) {
    Transaction* transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction));
    if (!transactions) {
        printf("Failed to allocate memory for transactions.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_transactions; i++) {
        transactions[i].transaction_id = i + 1;

        // Random amount within range [10.00, 1000.00]
        transactions[i].amount = (double)(rand() % 991) / 100.0 + 10.0;

        // Random currency symbol from USD, EUR, JPY, and GBP
        const char* currencies[] = {"USD", "EUR", "JPY", "GBP"};
        strcpy(transactions[i].currency, currencies[rand() % 4]);

        // Generate random alphanumeric user ID of length USER_ID_LENGTH
        for (int j = 0; j < USER_ID_LENGTH; j++) {
            transactions[i].user_id[j] = (char)(rand() % 26 + 'a');
            if (j < USER_ID_LENGTH - 1) {
                transactions[i].user_id[j+1] = (char)(rand() % 2 ? '0' : '1');
            }
        }

        transactions[i].user_id[USER_ID_LENGTH] = '\0';
    }

    return transactions;
}

void free_transactions(Transaction* transactions, int num_transactions) {
    if (!transactions) return;

    free(transactions);
}

int main() {
    int num_transactions = 500; // Adjust this value to test different scenarios
    Transaction* transactions = allocate_transactions(num_transactions);

    if (num_transactions > MAX_TRANSACTIONS) {
        printf("Error: Maximum number of transactions exceeded.\n");
        return 1;
    }

    // Use the allocated transactions...

    free_transactions(transactions, num_transactions);
    return 0;
}
