            free(item_ids);
            free(product_names_arr);
            free(products);
            free(stock_levels);
            free(supplier_ids_arr);

            printf("Allocation failed. Maximum products reached.\n");
            return;
        }

        count++;
    }

    // Free allocated memory
    for(int i = 0; i < count; i++) {
        free(stock_levels[i]);
    }
    free(stock_levels);

    for(int i = 0; i < PRODUCT_NAME_COUNT; i++) {
        free(product_names_arr[i]);
    }
    free(product_names_arr);

    for(int i = 0; i < SUPPLIER_ID_LENGTH; i++) {
        free(supplier_ids_arr[i]);
    }
    free(supplier_ids_arr);

    free(item_ids);
    free(products);

    printf("Memory successfully allocated and initialized.\n");
}

