#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PRODUCTS 1000
#define PRODUCT_NAME_LENGTH 50
#define SUPPLIER_ID_LENGTH 10
#define STOCK_LEVEL_MIN 1
#define STOCK_LEVEL_MAX 100
#define ALPHABET_SIZE 52

typedef struct {
    int product_id;
    char name[PRODUCT_NAME_LENGTH];
    int stock_level;
    char supplier_id[SUPPLIER_ID_LENGTH];
} Product;

Product* products = NULL;
int num_products = 0;

void init_random(char *buffer, int length) {
    static int seed = time(NULL);
    srand(seed);

    for (int i = 0; i < length; i++) {
        buffer[i] = (char)(rand() % ALPHABET_SIZE + 'a');
    }
    buffer[length] = '\0';
}

void load_products_from_csv(const char *file_name) {
    FILE *fp = fopen(file_name, "r");
    if (!fp) return;

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        Product product;
        sscanf(line, "%d,%[^,],%d,%[^,\n]", &product.product_id, product.name, &product.stock_level, product.supplier_id);
        if (num_products >= MAX_PRODUCTS) {
            printf("Error: Maximum number of products exceeded.\n");
            break;
        }
        if (strlen(product.name) > PRODUCT_NAME_LENGTH - 1 || strlen(product.supplier_id) > SUPPLIER_ID_LENGTH - 1) {
            printf("Error: Product name or supplier ID exceeds maximum length.\n");
            continue;
        }
        product.stock_level = (rand() % (STOCK_LEVEL_MAX - STOCK_LEVEL_MIN + 1)) + STOCK_LEVEL_MIN;
        init_random(product.supplier_id, SUPPLIER_ID_LENGTH);
        products[num_products++] = &product;
    }

    fclose(fp);
}

void release_resources() {
    for (int i = 0; i < num_products; i++) {
        free(products[i]);
    }
    free(products);
}
