                    product.name = strdup(p);
                    break;
                case 2:
                    product.stock_level = atoi(p);
                    break;
                case 3:
                    product.supplier_id = strdup(p);
                    break;
                case 4:
                    product.category = strdup(p);
                    break;
            }
        }

        // Check for parsing errors
        if (product.product_id == 0 || !product.name || product.stock_level < 1) {
            fprintf(stderr, "Error parsing CSV line: %s\n", line);
            continue;
        }

        if (num_products >= MAX_PRODUCTS) {
            fprintf(stderr, "Maximum number of products exceeded.\n");
            return;
        }

        // Allocate memory for the new product
        if (!(products = realloc(products, sizeof(Product) * ++num_products))) {
            perror("realloc failed");
            exit(1);
        }
        products[num_products - 1] = product;
    }

    fclose(file);
}

void load_product_data_from_api(const char* url) {
    // API loading logic here
}

int load_initial_data() {
    // Load data from CSV file and/or API endpoint
    load_product_data_from_csv("products.csv");
    load_product_data_from_api("https://api.example.com/products");

    return 0;
}

void release_resources() {
    for (int i = 0; i < num_products; i++) {
        free(products[i].name);
        free(products[i].supplier_id);
        free(products[i].category);
    }
    free(products);
}

// Error handling mechanism
void report_allocation_failure(const char* message) {
    perror(message);
    exit(1);
}
