record* initArrays(long maxRecords, int maxValue, long maxOffsetValue) {
    // Calculate the total number of records that can be stored without exceeding the limit.
    long numRecords = (maxRecords * sizeof(record)) / 1024 + 1;

    if(numRecords > maxRecords) {
        printf("Error: Memory allocation exceeds specified limit.\n");
        return NULL;
    }

    record* records = (record*)malloc(numRecords * sizeof(record));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    long* offsets = (long*)malloc(numRecords * sizeof(long));

    if(records == NULL || keys == NULL || offsets == NULL) {
        printf("Error: Memory allocation failed.\n");
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    srand(time(NULL));
    for(int i = 0; i < numRecords; i++) {
        records[i].key = rand() % maxValue;
        records[i].offset = (long)rand() % maxOffsetValue;
    }

