['Here is a C code block that implements a robust, multi-threaded key-value store:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct for each key-value pair
typedef struct {
    char* key;
    void* value;
    time_t expiration;
} kv_pair;

// Define the key-value store data structure
typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t allocated;
    kv_pair** cache;
} kv_store;

// Initialize a new key-value store with a given memory budget
kv_store* kv_init(size_t mem_budget) {
    kv_store* store = (kv_store*)malloc(sizeof(kv_store));
    store->capacity = 0;
    store->allocated = 0;
    store->cache = NULL;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

// Add a new key-value pair to the store
int kv_add(kv_store* store, const char* key, void* value, time_t expiration) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&store->lock);

    // Check if the cache is full
    if (store->allocated >= store->capacity) {
        // Resize the cache if necessary
        kv_store_resize(store);
    }

    // Find a slot in the cache to add the new pair
    size_t i;
    for (i = 0; i < store->allocated; i++) {
        if (store->cache[i]->expiration <= time(NULL)) {
            // Found an expired entry, replace it with the new one
            free(store->cache[i]->key);
            free(store->cache[i]->value);
            free(store->cache[i]);
            store->cache[i] = NULL;
            store->allocated--;
        }
    }

    // Add a new slot in the cache if there's space
    if (i < store->capacity) {
        kv_pair* pair = (kv_pair*)malloc(sizeof(kv_pair));
        pair->key = strdup(key);
        pair->value = value;
        pair->expiration = expiration;
        store->cache[i] = pair;
        store->allocated++;
    }

    // Release the lock
    pthread_mutex_unlock(&store->lock);

    return 0;
}

// Retrieve a key-value pair from the store
void* kv_get(kv_store* store, const char* key) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&store->lock);

    size_t i;
    for (i = 0; i < store->allocated; i++) {
        if (strcmp(store->cache[i]->key, key) == 0) {
            break;
        }
    }

    // Check if the entry was found
    if (i < store->allocated) {
        void* value = store->cache[i]->value;
        pthread_mutex_unlock(&store->lock);
        return value;
    } else {
        // Entry not found, return NULL or throw an error
        pthread_mutex_unlock(&store->lock);
        return NULL;
    }
}

// Remove a key-value pair from the store
int kv_remove(kv_store* store, const char* key) {
    // Acquire the lock for thread safety
    pthread_mutex_lock(&store->lock);

    size_t i;
    for (i = 0; i < store->allocated; i++) {
        if (strcmp(store->cache[i]->key, key) == 0) {
            break;
        }
    }

    // Check if the entry was found
    if (i < store->allocated) {
        free(store->cache[i]->key);
        free(store->cache[i]->value);
        free(store->cache[i]);
        store->cache[i] = NULL;
        store->allocated--;
    }

    pthread_mutex_unlock(&store->lock);

    return 0;
}

// Resize the cache to accommodate more entries
void kv_store_resize(kv_store* store) {
    size_t new_capacity = store->capacity * 2;
    // Allocate a new array of key-value pairs
    kv_pair** new_cache = (kv_pair**)malloc(new_capacity * sizeof(kv_pair*));

    // Copy existing entries to the new cache
    size_t j;
    for (j = 0; j < store->allocated; j++) {
        new_cache[j] = store->cache[j];
    }

    // Release resources from the old cache
    free(store->cache);
    store->capacity = new_capacity;
    store->cache = new_cache;

    pthread_mutex_unlock(&store->lock);
}

// Perform garbage collection to remove expired entries
void kv_gc(kv_store* store) {
    size_t i;
    for (i = 0; i < store->allocated; i++) {
        if (store->cache[i]->expiration <= time(NULL)) {
            // Remove the expired entry from the cache
            free(store->cache[i]->key);
            free(store->cache[i]->value);
            free(store->cache[i]);
            store->cache[i] = NULL;
            store->allocated--;
        }
    }

    pthread_mutex_unlock(&store->lock);
}

// Example usage of the key-value store function
int main() {
    kv_store* store = kv_init(1024); // Initialize a 1KB cache

    // Add some key-value pairs to the store
    kv_add(store, "key1", "value1", time(NULL) + 60);
    kv_add(store, "key2", "value2", time(NULL) + 30);

    // Retrieve and print the value for "key1"
    void* value = kv_get(store, "key1");
    printf("%s: %p\n", "key1", value);

    // Remove the entry with key "key2"
    kv_remove(store, "key2");

    // Perform garbage collection to remove expired entries
    kv_gc(store);

    return 0;
}
```

Note that this is a simplified example code and may not be suitable for production use without additional testing and optimization.']

