#define MAX_SENSORS 1000
#define BUFFER_SIZE 1024

typedef struct {
    int id;
    char location[32];
    time_t last_update;
    float temperature;
} sensor_t;

sensor_t* sensors = NULL;
int num_sensors = 0;

void init_sensors() {
    if (sensors) free(sensors);
    sensors = malloc(MAX_SENSORS * sizeof(sensor_t));
    num_sensors = 0;
}

void add_sensor(int id, const char* location, time_t last_update, float temperature) {
    if (num_sensors >= MAX_SENSORS) {
        printf("Error: Maximum number of sensors reached.\n");
        return;
    }
    sensor_t* new_sensor = &sensors[num_sensors++];
    new_sensor->id = id;
    strcpy(new_sensor->location, location);
    new_sensor->last_update = last_update;
    new_sensor->temperature = temperature;
}

void update_sensors() {
    // Update sensor metadata and readings here
    printf("Updating sensors...\n");
}

void safe_free(void* ptr) {
    if (ptr) free(ptr);
}

void stop_service(int sock) {
    char buffer[BUFFER_SIZE];
    send(sock, "Stopping service...", strlen("Stopping service..."));
    close(sock);
}

int main() {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    bind(sock, (struct sockaddr*)&server_addr, sizeof(server_addr));

    listen(sock, 3);

    while (1) {
        int client_sock = accept(sock, NULL, NULL);
        if (client_sock < 0) {
            perror("accept");
            continue;
        }

        pthread_t thread;
        pthread_create(&thread, NULL, &stop_service, (void*)client_sock);

        sleep(rand() % 5 + 1); // Random delay between starts

        send(client_sock, "Service stopped.", strlen("Service stopped."));
    }
}
