typedef struct {
    int key;
} recordEntry;

typedef struct {
    float value;
} metricEntry;

void processDynamicDataStream(int max_records) {
    // Initialize offset array and validate offsets
    long* offsets = (long*)malloc(10 * sizeof(long));
    for (int i = 0; i < 10; i++) {
        offsets[i] = rand() % 100;
    }

    int* keys = (int*)malloc(10 * sizeof(int));
    for (int i = 0; i < 10; i++) {
        keys[i] = rand() % 100;
    }

    // Initialize recordEntry array
    recordEntry* records = (recordEntry*)malloc(max_records * sizeof(recordEntry));
    for (int i = 0; i < max_records; i++) {
        records[i].key = rand() % 100;
    }

    // Initialize metricEntry array
    metricEntry* metrics = (metricEntry*)malloc(max_records / 2 * sizeof(metricEntry));
    for (int i = 0; i < max_records / 2; i++) {
        metrics[i].value = (float)rand() / RAND_MAX;
    }

    // Serialize data structures
    char buffer[1024];
    int offset = 0;
    int key_count = 0;
    for (int i = 0; i < max_records; i++) {
        recordEntry rec = records[i];
        metricEntry met = metrics[i / 2];
        int size = sizeof(recordEntry) + sizeof(metricEntry);
        memcpy(&buffer[offset], &rec, sizeof(recordEntry));
        offset += sizeof(recordEntry);
        memcpy(&buffer[offset], &met, sizeof(metricEntry));
        offset += sizeof(metricEntry);
        key_count++;
    }

    // Serialize data structures to byte array
    char* serialized_data = (char*)malloc(offset + 1);
    for (int i = 0; i < offset; i++) {
        serialized_data[i] = buffer[i];
    }

    serialized_data[offset] = '\0';
}

int main() {
    processDynamicDataStream(10000);
    return 0;
}
