        instances[i]->memory_utilization = 0.8 - (i % 2) * 0.1;
        instances[i]->network_latency = i * 10.0;
        instances[i]->health_status = 'H';
    }
    // Handle the case where num_instances is larger than max_instances
    if (num_instances > max_instances) {
        for (int i = num_instances; i >= max_instances; i--) {
            free(instances[i]);
        }
