    int key;
    long offset;
} record;

record* manage_memory(int num_records, int** keys, long* offsets) {
    int i;
    record* records = NULL;
    int* random_values = NULL;

    // Allocate memory for arrays
    int* keys_copy = (int*)malloc(num_records * sizeof(int));
    long* offsets_copy = (long*)malloc(num_records * sizeof(long));

    if (!keys_copy || !offsets_copy) {
        free(keys_copy);
        free(offsets_copy);
        return NULL;
    }

    for (i = 0; i < num_records; i++) {
        keys_copy[i] = (*keys)[i];
        offsets_copy[i] = offsets[i];
    }

    // Allocate memory for record structures
    records = (record*)malloc(num_records * sizeof(record));

    if (!records) {
        free(keys_copy);
        free(offsets_copy);
        return NULL;
    }

    random_values = (int*)malloc(num_records * sizeof(int));

    if (!random_values) {
        free(records);
        free(keys_copy);
        free(offsets_copy);
        return NULL;
    }

    // Initialize random number generator
    srand(*keys[0]);

    for (i = 0; i < num_records; i++) {
        records[i].key = (*keys)[i];
        records[i].offset = offsets[i];
        char buffer[257]; // Include space for null-terminator
        sprintf(buffer, "%d-%ld", (*keys)[i], offsets[i]);
        records[i].buffer = (char*)malloc(strlen(buffer) + 1);
        strcpy(records[i].buffer, buffer);

        random_values[i] = rand() % 1000;
        records[i].key = random_values[i];
    }

    free(keys_copy);
    free(offsets_copy);
    free(random_values);

    return records;
}

