#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>

// Structure representing an item in the collection
typedef struct {
    char* buffer;
    int index;
    double value;
} Item;

// Function to generate a unique identifier based on the index, global counter, and current system time
char* generate_unique_id(int index, long* counter) {
    // Generate the timestamp using gettimeofday()
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[32];
    sprintf(timestamp, "%ld.%06ld", tv.tv_sec, tv.tv_usec);

    // Concatenate the index and global counter to form a unique identifier
    char* id = (char*)malloc(strlen(timestamp) + 16);
    sprintf(id, "%d-%s-%ld", index, timestamp, *counter);
    (*counter)++;
    return id;
}

// Function to manage memory for a dynamic collection of items under realistic constraints
Item** manage_collection(int num_items, long* seed) {
    // Allocate memory for an array of char buffers, each holding a maximum string length of 512 characters
    char** buffers = (char**)malloc(num_items * sizeof(char*));
    for (int i = 0; i < num_items; i++) {
        buffers[i] = (char*)malloc(513); // 512 for the string and an extra byte for null termination
    }

    // Dynamically allocate memory for an array of item structures, where each structure contains:
    Item** items = (Item**)malloc(num_items * sizeof(Item*));
    for (int i = 0; i < num_items; i++) {
        items[i] = (Item*)malloc(sizeof(Item));
        items[i]->buffer = buffers[i];
        items[i]->index = i;
        items[i]->value = ((double)rand() / RAND_MAX * 1000.0);
    }

    // Populate each item's buffer with a string derived from its index, unique identifier, and timestamp
    for (int i = 0; i < num_items; i++) {
        sprintf(buffers[i], "Item %d - %s", items[i]->index, generate_unique_id(items[i]->index, seed));
    }

    // Return the array of item structures and the total number of items managed
    return items;
}

// Function to iterate over the collection efficiently
void iterate_collection(Item** items, int num_items) {
    for (int i = 0; i < num_items; i++) {
        printf("Item %d: Buffer - '%s', Index - %d, Value - %.2f\n", items[i]->index, items[i]->buffer, items[i]->index, items[i]->value);
    }
}

// Function to clean up all previously allocated memory and exit gracefully
void cleanup(Item** items, char** buffers, int num_items) {
    for (int i = 0; i < num_items; i++) {
        free(buffers[i]);
        free(items[i]);
    }
    free(buffers);
    free(items);
}
