typedef struct item {
    char* buffer;
    int index;
    double value;
} item;

item** manage_memory(int num_items) {
    // Allocate memory for character buffers
    char** buffers = (char**) malloc(num_items * sizeof(char*));
    if (!buffers) return NULL;  // Handle allocation failure

    for (int i = 0; i < num_items; i++) {
        int length = sprintf(buffer, "Item %d: %x", i, custom_hash(i));
        buffers[i] = (char*) malloc((length + 1) * sizeof(char));
        if (!buffers[i]) { // Handle allocation failure
            for (int j = 0; j < i; j++) free(buffers[j]);
            free(buffers);
            return NULL;
        }
        strcpy(buffers[i], buffer);
    }

    // Allocate memory for item structures
    item** items = (item**) malloc(num_items * sizeof(item*));
    if (!items) {  // Handle allocation failure
        for (int i = 0; i < num_items; i++) free(buffers[i]);
        free(buffers);
        return NULL;
    }

    for (int i = 0; i < num_items; i++) {
        items[i] = (item*) malloc(sizeof(item));
        if (!items[i]) { // Handle allocation failure
            for (int j = 0; j <= i; j++) {
                free(buffers[j]);
                free(items[j]->buffer);
                free((void*) items[j]);
            }
            free(items);
            free(buffers);
            return NULL;
        }
    }

    // Initialize item values
    srand(time(NULL));
    for (int i = 0; i < num_items; i++) {
        items[i]->value = ((double) rand() / RAND_MAX) * 1000.0;
    }

    return items;
}
