#define MAX_ITEM_COUNT 10000
#define UNIQUE_ID_LENGTH 32
#define TIMESTAMP_LENGTH 24
#define BUFFER_LENGTH 512

typedef struct {
    char* buffer;
    int index;
    double value;
} item;

item** manageMemory(int itemCount) {
    if (itemCount > MAX_ITEM_COUNT) {
        printf("Error: Maximum item count exceeded.\n");
        return NULL;
    }

    // Allocate memory for an array of `char` buffers
    char** buffers = malloc(itemCount * sizeof(char*));
    if (!buffers) {
        printf("Error: Memory allocation failed.\n");
        free(buffers);
        return NULL;
    }

    // Dynamically allocate memory for an array of `item` structures
    item** items = malloc(itemCount * sizeof(item*));
    if (!items) {
        printf("Error: Memory allocation failed.\n");
        free(buffers);
        free(items);
        return NULL;
    }

    // Initialize and populate each item's buffer
    for (int i = 0; i < itemCount; i++) {
        char buffer[BUFFER_LENGTH];
        sprintf(buffer, "Item %d: %s-%ld", i, getUniqueIdentifier(i), time(NULL));
        buffers[i] = malloc(strlen(buffer) + 1);
        strcpy(buffers[i], buffer);

        item* item = malloc(sizeof(item));
        item->buffer = buffers[i];
        item->index = i;
        item->value = getRandomValue();

        items[i] = item;
    }

    // Set the value of each item's `double` field
    for (int i = 0; i < itemCount; i++) {
        items[i]->value = getRandomValue();
    }

    return items;
}

char* getUniqueIdentifier(int index) {
    static char uniqueId[UNIQUE_ID_LENGTH];
    srand(index);
    sprintf(uniqueId, "%x%x", rand(), time(NULL));
    return uniqueId;
}

double getRandomValue() {
    static srand(time(NULL));
    double value = (double)rand() / RAND_MAX * 1000.0;
    return value;
}
