        entries[i] = (entry_t*)malloc(sizeof(entry_t));
        entries[i]->timestamp = 0;
        entries[i]->log_message = malloc(strlen("Default Log Message") + 1);
        strcpy(entries[i]->log_message, "Default Log Message");
        entries[i]->identifier = i;

        logging_library_log_formatted("Entry %d created with timestamp 0 and log message 'Default Log Message'", i);
    }

    int total_memory_usage = 0;
    for (i = 0; i < num_entries; i++) {
        total_memory_usage += sizeof(entry_t) + strlen(entries[i]->log_message) + 1;
    }
    logging_library_log_formatted("Total memory usage: %d bytes", total_memory_usage);

    return entries;
}

void update_log_message(entry_t** entries, int entry_index, const char* new_log_message) {
    if (entries[entry_index]->log_message != NULL) {
        free(entries[entry_index]->log_message);
    }
    entries[entry_index]->log_message = malloc(strlen(new_log_message) + 1);
    strcpy(entries[entry_index]->log_message, new_log_message);
}

void print_entries(entry_t** entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        printf("Entry %d: Timestamp - %ld, Log Message - '%s', Identifier - %d\n", i, entries[i]->timestamp, entries[i]->log_message, entries[i]->identifier);
    }
}

void free_entries(entry_t** entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        if (entries[i]->log_message != NULL) {
            free(entries[i]->log_message);
        }
        free(entries[i]);
    }
    free(entries);
}

void dump_entries_to_file(entry_t** entries, int num_entries, const char* filename) {
