#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <sys/wait.h>

typedef struct {
    int* fd_list;
    size_t mem_usage;
} process_state;

typedef struct data_record {
    float val;
    char id[10];
    process_state state;
    struct data* ptr;
} record;

typedef struct data {
    int num;
    double dval;
} data;

record* create_data_record(int idx) {
    record* rec = (record*)malloc(sizeof(record));
    if(rec == NULL) return NULL;

    rec->val = rand() / (float)RAND_MAX;
    sprintf(rec->id, "Record %d", idx);

    rec->state.fd_list = (int*)malloc(10 * sizeof(int));
    rec->state.mem_usage = 0;

    rec->ptr = (data*)malloc(sizeof(data));
    rec->ptr->num = rand();
    rec->ptr->dval = (double)rand() / RAND_MAX;

    return rec;
}

void add_record(record** records, int* total_records, int num_new) {
    for(int i = 0; i < num_new; i++) {
        *total_records += 1;
        record* new_rec = create_data_record(*total_records);
        if(new_rec == NULL) return;

        if(*records == NULL) {
            *records = new_rec;
        } else {
            record* last_rec = *records;
            while(last_rec->ptr != NULL) last_rec = last_rec->ptr;
            last_rec->ptr = new_rec;
        }
    }
}

void update_record(record** records, int idx, double cpu_usage, size_t mem_usage) {
    if(*records == NULL || idx > *total_records) return;

    record* rec = (*records);
    for(int i = 0; i < idx; i++) rec = rec->ptr;

    rec->state.mem_usage += mem_usage;
    rec->state.mem_usage /= 2;

    printf("Updated CPU usage: %f, Memory usage: %zu\n", cpu_usage, rec->state.mem_usage);
}

void remove_record(record** records, int idx) {
    if(*records == NULL || idx > *total_records) return;

    record* rec = (*records);
    for(int i = 0; i < idx - 1; i++) rec = rec->ptr;

    free(rec->ptr);
    rec->ptr = NULL;
}

size_t get_total_cpu_usage(record* records) {
    if(records == NULL) return 0;

    size_t total = 0;
    record* rec = records;
    while(rec != NULL) {
        total += rec->state.mem_usage;
        rec = rec->ptr;
    }

    return total;
}

size_t get_total_mem_usage(record* records) {
    if(records == NULL) return 0;

    size_t total = 0;
    record* rec = records;
    while(rec != NULL) {
        total += rec->state.mem_usage;
        rec = rec->ptr;
    }

    return total;
}

void collect_stats(record* records, int interval, double* avg_cpu, double* avg_mem) {
    if(records == NULL) return;

    size_t total_cpu = get_total_cpu_usage(records);
    size_t total_mem = get_total_mem_usage(records);

    *avg_cpu /= (double)interval;
    *avg_mem /= (double)interval;
}

void clear_resources(record** records, int* total_records) {
    if(*records == NULL) return;

    record* rec = (*records);
    while(rec != NULL) {
        free(rec->ptr);
        rec = rec->ptr;
    }

    free(rec);
    *total_records = 0;
}
