        hash_table->buckets[i]->key = rand() % 100;
        // Simulate nested records up to three levels deep
        int depth = 3;
        while (depth > 0) {
            // Manage circular references gracefully
            if (hash_table->buckets[i]->value != NULL) {
                free(hash_table->buckets[i]->value);
                hash_table->buckets[i]->value = NULL;
            }
            depth--;
        }
    }
}

