typedef struct {
    int value;
} record;

record* allocate_records(int count) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % 100;
    }
    return records;
}

void update_range(record* records, int new_min, int new_max) {
    int* values = (int*)malloc(count * sizeof(int));
    for (int i = 0; i < count; i++) {
        values[i] = (records[i].value - new_min) % (new_max - new_min);
    }
    free(records);
    records = (record*)malloc(count * sizeof(record));
    for (int i = 0; i < count; i++) {
        records[i].value = new_min + values[i];
    }
}

void free_resources(record* records, int count) {
    if (!records) return;
    free(records);
    records = NULL;
}
