        return NULL;
    }

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        int min_value = 1;
        int max_value = 100;
        records[i].value = (rand() % (max_value - min_value + 1)) + min_value;
    }

    return records;
}

void free_random_records(Record* records, int count) {
    if (!records || count <= 0) {
        return;
    }

    free(records);
}

