#define RECORD_STRUCT int
#define MIN_RECORDS 1
#define MAX_RECORDS 1000
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 255

typedef struct {
    RECORD_STRUCT value;
} record_t;

record_t* create_record_array(size_t count);
void init_records(record_t*, size_t);
void free_record_array(record_t*);
int get_random_value(int, int);

// Allocate memory for an array of records
record_t* create_record_array(size_t count) {
    if (count < MIN_RECORDS || count > MAX_RECORDS) {
        // Handle invalid input
        printf("Invalid record count: %zu. Using default value.\n", count);
        count = 100;
    }

    record_t* records = (record_t*)malloc(count * sizeof(record_t));
    if (!records) {
        // Handle memory allocation failure
        printf("Memory allocation failed. Reducing record count to %zu.\n", MIN_RECORDS);
        return create_record_array(MIN_RECORDS);
    }

    return records;
}

// Initialize the int values of each record with random numbers
void init_records(record_t* records, size_t count) {
    srand(time(NULL)); // Re-seed the random number generator

    for (size_t i = 0; i < count; i++) {
        records[i].value = get_random_value(RANDOM_RANGE_MIN, RANDOM_RANGE_MAX);
    }
}

// Generate a random integer value within a specified range
int get_random_value(int min, int max) {
    return rand() % ((max - min) + 1) + min;
}

// Free the memory allocated for the record array
void free_record_array(record_t* records) {
    free(records);
}
