    RECORD_OK,
    MEMORY_ALLOCATION_FAILURE,
    INVALID_RECORD_COUNT,
    OUT_OF_RANGE_INITIAL_VALUE
};

// Function to manage dynamic collection of records
int* recordManager(int recordCount, int minValue, int maxValue) {
    // Check for invalid input
    if (recordCount <= 0 || minValue > maxValue) {
        return nullptr;
    }

    // Allocate memory for array of record structures
    int* records = reinterpret_cast<int*>(malloc(recordCount * sizeof(int)));
    if (!records) {
        return nullptr;  // Handle memory allocation failure
    }

    // Initialize int values of each record to random numbers
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(minValue, maxValue);

    for (int i = 0; i < recordCount; ++i) {
        records[i] = dis(gen);
    }

    return records;
}

// Function to update range of random numbers dynamically
void updateRecordRange(int* records, int oldMinValue, int oldMaxValue,
                       int newMinValue, int newMaxValue) {
    // Check if reallocation is necessary
    if (newMinValue >= oldMinValue && newMaxValue <= oldMaxValue) {
        return;  // No reallocation needed
    }

    // Reallocate memory to accommodate updated range
    int* newRecords = reinterpret_cast<int*>(realloc(records, (newMaxValue - newMinValue + 1) * sizeof(int)));
    if (!newRecords) {
        // Handle memory allocation failure
        return;
    }
    records = newRecords;

    // Initialize int values of each record to random numbers within updated range
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(newMinValue, newMaxValue);

    for (int i = 0; i < oldMaxValue - oldMinValue + 1; ++i) {
        records[i] = dis(gen);
    }
}

// Function to free allocated resources before exiting
void freeRecordResources(int* records) {
    if (!records) {
        return;
    }

    free(records);
}
