        printf("Error: No records to update\n");
        return; // no records to update
    }

    for (int i = 0; i < sizeof(records) / sizeof(record); i++) {
        records[i].value = rand() % (end - start + 1) + start;
    }
}

void freeRecords(record* records, int count) {
    if (!records || count <= 0) {
        printf("Error: No records to free\n");
        return; // no records to free
    }

    free(records);
}

int main() {
    srand(time(NULL)); // seed random number generator

    int count = 0;
    printf("Enter the number of records (max 100): ");
    scanf("%d", &count);

    record* records = createRecords(count);

    if (!records) {
        return -1; // memory allocation failed
    }

    updateRecordRange(records, 0, 99); // update range to [0, 99]

    freeRecords(records, count);

    return 0;
}
