typedef struct {
    long offset;
    int timestamp;
    int value;
} record;

record** initializeArrays(int* numOffsets, int* numRows) {
    srand(time(NULL));

    *numOffsets = 10; // initial number of offsets
    *numRows = 1000; // initial number of rows

    int* offsets = (int*)malloc(*numOffsets * sizeof(long));
    int* keys = (int*)malloc(*numOffsets * sizeof(int));
    record** records = (record**)malloc(*numRows * sizeof(record));

    for (int i = 0; i < *numOffsets; i++) {
        offsets[i] = rand() % 100000;
        keys[i] = rand() % 100;
    }

    for (int i = 0; i < *numRows; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->offset = offsets[rand() % *numOffsets];
        records[i]->timestamp = rand() % 10000;
        records[i]->value = rand() % 10;
    }

    free(offsets);
    free(keys);

    return records;
}

char* getMD5Hash(const char* str) {
    unsigned char hash[16];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, str, strlen(str));
    MD5_Final(hash, &ctx);

    char* result = (char*)malloc(33 * sizeof(char)); // 32-byte hash + '\0'
    sprintf(result, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x", 
            hash[0], hash[1], hash[2], hash[3], hash[4], hash[5], 
            hash[6], hash[7], hash[8], hash[9], hash[10], hash[11],
            hash[12], hash[13], hash[14], hash[15]);
    return result;
}

int main() {
    int numOffsets, numRows;
    record** records = initializeArrays(&numOffsets, &numRows);

    // Use the initialized arrays here...

    for (int i = 0; i < numRows; i++) {
        free(records[i]);
    }
    free(records);
    return 0;
}
