#include <string.h>
#include <md5.h>

typedef struct record {
    long offset;
    int timestamp;
    short value;
} record_t;

record_t** initArrays(long* offsets, int keys[], long totalBytes) {
    int i;
    int records = totalBytes / sizeof(record_t);

    // Initialize arrays
    long* offsetArray = (long*)malloc(records * sizeof(long));
    if (!offsetArray) return NULL; // Error allocation

    int* keyArray = (int*)malloc(records * sizeof(int));
    if (!keyArray) {
        free(offsetArray);
        return NULL;
    }

    record_t** recordArray = (record_t**)malloc(records * sizeof(record_t*));
    if (!recordArray) {
        free(offsetArray);
        free(keyArray);
        return NULL;
    }

    // Initialize arrays based on user-provided parameters
    for (i = 0; i < records; i++) {
        offsetArray[i] = offsets[i];
        keyArray[i] = keys[i];

        recordArray[i] = (record_t*)malloc(sizeof(record_t));
        if (!recordArray[i]) {
            // Error allocation, free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(offsetArray[j]);
                free(keyArray[j]);
                free(recordArray[j]->offset);
                free(recordArray[j]);
            }
            free(offsetArray);
            free(keyArray);
            return NULL;
        }

        // Initialize record structures
        recordArray[i]->offset = offsetArray[i];
        recordArray[i]->timestamp = keyArray[i];
        recordArray[i]->value = 0; // Default value

        // Compute and set MD5 hash for the given string parameter
        char* strParam = "your_string_parameter_here";
        uint8_t md5Bytes[16];
        MD5(strParam, strlen(strParam), md5Bytes);

        // Set record's timestamp to computed MD5 hash
        recordArray[i]->timestamp = *(int*)md5Bytes;
    }

    return recordArray;
}

void freeArrays(record_t** records) {
    int i;
    for (i = 0; records[i]; i++) {
        free(records[i]->offset);
        free(records[i]);
    }
    free(records);
}
