    for (int i = 0; i < log->count; i++) {
        free(log->events[i].metadata);
    }
    free(log->events);
    free(log);
}

event_log_t* initialize_event_log(int count, int metadata_size) {
    event_log_t* log = malloc(sizeof(event_log_t));
    log->events = calloc(count, sizeof(event_t));
    log->count = count;
    for (int i = 0; i < count; i++) {
        log->events[i].metadata = malloc(metadata_size);
    }
    return log;
}

event_log_t* manage_event_log(int max_events, int metadata_size) {
    event_log_t* log = NULL;
    while (1) {
        log = initialize_event_log(max_events, metadata_size);
        if (log != NULL) break;
        max_events /= 2; // resize to half
    }
    return log;
}

int main() {
    // Example usage:
    event_log_t* log = manage_event_log(MAX_EVENTS, MAX_METADATA_SIZE);
    // ...
    free_event_log(log);
    return 0;
