        return -1;
    }

    for (i = 0; i < num_records; i++) {
        records[i].value = rand() % (new_max - new_min + 1) + new_min;
    }

    return 0;
}

int free_records(record *records) {
    if (!records) {
        error Reporting("No records to free");
        return -1;
    }

    free(records);
    return 0;
}
