typedef struct {
    int value;
} record;

record* create_record_array(int num_records) {
    record *records = NULL;
    record *temp = NULL;

    while (num_records > 0) {
        records = realloc(records, (num_records + 1) * sizeof(record));
        temp = records + num_records;
        for (int i = 0; i < num_records; i++) {
            temp[i].value = rand() % 100;
        }
        num_records--;
    }

    return records;
}

void free_record_array(record *records, int num_records) {
    record *temp = records + num_records;
    for (int i = 0; i < num_records; i++) {
        free(temp - i);
    }
    free(records);
}
