        my_free(ptr);
    }

    // Define a custom allocator for audit records
    audit* my_audit_malloc(int count) {
        audit* ptr = (audit*)my_malloc(count * sizeof(audit));
        if (ptr != NULL) {
            for (int i = 0; i < count; i++) {
                ptr[i].action_type = my_strdup("ACTION_TYPE");
                ptr[i].timestamp = time(NULL);
                ptr[i].user_name = my_strdup("USER_NAME");
            }
        }
        return ptr;
    }

    void my_audit_free(audit* ptr, int count) {
        for (int i = 0; i < count; i++) {
            my_free_string(ptr[i].action_type);
            my_free_string(ptr[i].user_name);
        }
        my_free(ptr);
    }

    // Define a custom allocator for configurations
    config* my_config_malloc(int count) {
        config* ptr = (config*)my_malloc(count * sizeof(config));
        if (ptr != NULL) {
            for (int i = 0; i < count; i++) {
                ptr[i].key = my_strdup("KEY");
                ptr[i].value = rand() % 100;
                ptr[i].last_modified = time(NULL);
            }
        }
        return ptr;
    }

    void my_config_free(config* ptr, int count) {
        for (int i = 0; i < count; i++) {
            my_free_string(ptr[i].key);
        }
        my_free(ptr);
    }

    // Define a mechanism to periodically flush the audit logs
    void flush_audit_logs() {
        FILE* file = fopen("audit.log", "w");
        if (file != NULL) {
            for (int i = 0; i < count; i++) {
                fprintf(file, "%s %ld\n", ptr[i].action_type, ptr[i].timestamp);
            }
            fclose(file);
        } else {
            printf("Error opening file\n");
        }
    }

    // Define a mechanism to periodically flush the configuration logs
    void flush_config_logs() {
        FILE* file = fopen("config.log", "w");
        if (file != NULL) {
            for (int i = 0; i < count; i++) {
                fprintf(file, "%s %ld\n", ptr[i].key, ptr[i].value);
            }
            fclose(file);
        } else {
            printf("Error opening file\n");
        }
    }

    // Define a mechanism to periodically flush the record logs
    void flush_record_logs() {
        FILE* file = fopen("record.log", "w");
        if (file != NULL) {
            for (int i = 0; i < count; i++) {
                fprintf(file, "%d\n", ptr[i].value);
            }
            fclose(file);
        } else {
            printf("Error opening file\n");
        }
    }

    int main() {
        int count;
        printf("Enter the number of configurations: ");
        scanf("%d", &count);

        config* configs = my_config_malloc(count);
        if (configs == NULL) return 1;

        audit* audits = my_audit_malloc(count);
        if (audits == NULL) return 1;

        record* records = my_record_malloc();
        if (records == NULL) return 1;

        // Initialize the logs
        for (int i = 0; i < count; i++) {
            configs[i].last_modified = time(NULL);
            audits[i].timestamp = time(NULL);
            records[i].value = rand() % 100;
        }

        // Periodically flush the logs
        while (1) {
            sleep(60); // Flush every minute
            flush_audit_logs();
            flush_config_logs();
            flush_record_logs();
        }

        return 0;
    }
