    pthread_mutex_init(&arr->mutex, NULL);
}

dynamic_array_free(struct dynamic_array* arr) {
    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->frames[i]);
    }
    free(arr->frames);
    pthread_mutex_destroy(&arr->mutex);
}

bool dynamic_array_add_frame_info(struct dynamic_array* arr, LTE_DL_FRAMEINFO* frame_info, bool is_phy_frame_info_valid, bool srb1_pdu_valid, bool drb_pdu_valid) {
    if (arr->size >= arr->capacity) {
        arr->frames = reallocate_frame_info(arr, arr->capacity * 2);
        arr->capacity *= 2;
    }
    if (!frame_info || !is_phy_frame_info_valid || !srb1_pdu_valid || !drb_pdu_valid) {
        return false; // Error handling for invalid input
    }
    arr->frames[arr->size] = frame_info;
    ++arr->size;
    pthread_mutex_unlock(&arr->mutex);
}

void* reallocate_frame_info(struct dynamic_array* arr, size_t new_capacity) {
    LTE_DL_FRAMEINFO** new_frames = (LTE_DL_FRAMEINFO**)realloc(arr->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO*));
    if (!new_frames) {
        return NULL; // Error handling for memory allocation failure
    }
    arr->frames = new_frames;
    return arr->frames;
}

