void init_wlan_packets() {
    wlan_packets = (WLAN_PACKET**)malloc(10 * sizeof(WLAN_PACKET*));
}

void add_packet(WLAN_PACKET* packet) {
    if (packet_count >= 10) {
        // Handle buffer overflow
        printf("Buffer Overflow\n");
        return;
    }
    wlan_packets[packet_count] = packet;
    packet_count++;
}

WLAN_PACKET* get_packet(int index) {
    if (index < 0 || index >= packet_count) {
        return NULL;
    }
    return wlan_packets[index];
}

void free_wlan_packets() {
    for (int i = 0; i < packet_count; i++) {
        free(wlan_packets[i]->payload);
        free(wlan_packets[i]);
    }
    free(wlan_packets);
}

void prioritize_packets() {
    qsort(wlan_packets, packet_count, sizeof(WLAN_PACKET*), qos_comparator);
}

int qos_comparator(const void* a, const void* b) {
    WLAN_PACKET* pa = *(WLAN_PACKET**)a;
    WLAN_PACKET* pb = *(WLAN_PACKET**)b;
    if (pa->qos_level > pb->qos_level) {
        return -1;
    } else if (pa->qos_level < pb->qos_level) {
        return 1;
    }
    return 0;
}
