    Task* tasks = (Task*)malloc(num_tasks * sizeof(Task));

    if (!tasks) {
        return NULL;
    }

    for (int i = 0; i < num_tasks; i++) {
        char buffer[128];
        sprintf(buffer, "Task %d: Deadline - %s", i, ctime(&i));

        tasks[i].description = strdup(buffer);
        if (!tasks[i].description) {
            return NULL;
        }

        tasks[i].priority = rand() % 10 + 1;
        tasks[i].deadline = time(NULL) + (rand() % 60 * 60); // random deadline in the future
        tasks[i].duration = (double)(rand() % 1000 / 100.0); // random estimated duration

        if (!tasks[i].description || !tasks[i].deadline || isnan(tasks[i].duration)) {
            free_tasks(tasks, i);
            return NULL;
        }
    }

    for (int i = 0; i < num_tasks - 1; i++) {
        for (int j = i + 1; j < num_tasks; j++) {
            if (tasks[i].priority > tasks[j].priority) {
                Task temp = tasks[i];
                tasks[i] = tasks[j];
                tasks[j] = temp;
            } else if (tasks[i].priority == tasks[j].priority && tasks[i].duration > tasks[j].duration) {
                Task temp = tasks[i];
                tasks[i] = tasks[j];
                tasks[j] = temp;
            }
        }
    }

    return tasks;
}

void free_tasks(Task* tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i].description) {
            free(tasks[i].description);
        }
    }
    free(tasks);
}

