#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "logging.h"

// Define the maximum number of tasks
#define MAX_TASKS 100

typedef struct {
    char* description;
    int priority;
    time_t deadline;
    double duration;
} task;

task* manage_tasks(int num_tasks, int seed) {
    // Initialize random number generator with specified seed
    srand(seed);

    task* tasks = (task*)malloc(sizeof(task) * num_tasks);
    if (!tasks) {
        LOG_ERROR("Failed to allocate memory for tasks");
        return NULL;
    }

    for (int i = 0; i < num_tasks; i++) {
        // Allocate memory for task description
        char* desc = (char*)malloc(129); // 128 characters + null terminator
        if (!desc) {
            LOG_ERROR("Failed to allocate memory for task description");
            free(tasks);
            return NULL;
        }

        // Set default priority and generate unique random value
        int priority = rand() % 10 + 1;

        // Set deadline timestamp
        time_t deadline = time(NULL) + (rand() % 3600); // within the next hour

        // Initialize estimated duration with current time required to complete task
        double duration = 5.0; // in seconds, adjust as needed

        tasks[i].description = desc;
        tasks[i].priority = priority;
        tasks[i].deadline = deadline;
        tasks[i].duration = duration;

        // Format task string and log it
        char task_str[256];
        sprintf(task_str, "Task %d: '%s' due by %s (Priority: %d, Duration: %.2f)", i + 1, desc, ctime(&deadline), priority, duration);
        LOG_INFO(task_str);

        // Populate buffer with formatted string
        strcpy(desc, task_str);
    }

    return tasks;
}

int main() {
    int num_tasks = 10; // adjust as needed
    int seed = time(NULL); // generate a random seed

    task* tasks = manage_tasks(num_tasks, seed);
    if (!tasks) {
        LOG_ERROR("Failed to manage tasks");
        return -1;
    }

    // Sort the list of tasks based on priority and estimated duration
    qsort(tasks, num_tasks, sizeof(task), compare_tasks);

    // Print the sorted task list
    for (int i = 0; i < num_tasks; i++) {
        LOG_INFO("Task %d: '%s' due by %s (Priority: %d, Duration: %.2f)", i + 1, tasks[i].description, ctime(&tasks[i].deadline), tasks[i].priority, tasks[i].duration);
    }

    free(tasks);

    return 0;
}

int compare_tasks(const void* a, const void* b) {
    task* ta = (task*)a;
    task* tb = (task*)b;

    if (ta->priority > tb->priority)
        return -1;
    else if (ta->priority < tb->priority)
        return 1;
    else {
        if (ta->duration < tb->duration)
            return -1;
        else
            return 1;
    }
}
