    dir_entry *entry = (dir_entry*)malloc(sizeof(dir_entry));
    entry->name = name;
    entry->file_list = NULL;
    entry->num_files = 0;
    if (type == 1)
        entry->timestamps.created = time(NULL);
    return entry;
}

// Function to create a new file
file_entry* create_file(char *name) {
    file_entry *file = (file_entry*)malloc(sizeof(file_entry));
    file->name = name;
    file->type = 1;
    file->permissions = 0;
    file->timestamps.created = time(NULL);
    return file;
}

// Function to list all files in a directory
