int count_words(char *line, int case_sensitive) {
    int word_count = 0;
    char *token = strtok(line, " \t");
    while (token) {
        if (case_sensitive) {
            // Treat words as case-sensitive
            word_count++;
        } else {
            // Treat words as case-insensitive
            int is_word = 1;
            for (char *c = token; *c; c++) {
                if (!isalpha(*c)) {
                    is_word = 0;
                    break;
                }
            }
            if (is_word) {
                word_count++;
            }
        }
        token = strtok(NULL, " \t");
    }
    return word_count;
}

