        if (std::string(argv[i]) == "-v" || std::string(argv[i]) == "--verbose") {
            verbose_mode = true;
        } else if (std::string(argv[i]) == "-t" || std::string(argv[i]) == "--time-filter") {
            time_filtered = true;
        } else if (std::string(argv[i]) == "-o" || std::string(argv[i]) == "--output-file") {
            output_file = argv[++i];
        } else if (std::string(argv[i]) == "--stats") {
            // TODO: Implement statistics generation
        } else if (std::string(argv[i]) == "--top-n") {
            top_n = std::stoi(argv[++i]);
        }
    }

    processSensorData(argc > 1 ? argv[1] : "input.txt", output_file, verbose_mode, time_filtered, top_n);

    return 0;
}

void processSensorData(const std::string& input_file, const std::string& output_file,
                         bool verbose_mode, bool time_filtered, int top_n) {
    // Open the input file
    std::ifstream input(input_file);

    if (!input.is_open()) {
        std::cerr << "Error opening input file: " << input_file << std::endl;
        return;
    }

    // Initialize output stream and error handling
    std::ofstream output(output_file);
    bool error_occurred = false;

    // Parse command-line arguments
    int start_timestamp = 0;
    int end_timestamp = 0;

    for (int i = 1; i < input.rdbuf()->in_avail(); ++i) {
        char c = input.get();
        if (c == '-') {
            std::string token;
            while ((c = input.get()) != ' ') {
                token += c;
            }
            if (token == "v" || token == "verbose") {
                verbose_mode = true;
            } else if (token == "t" || token == "time-filter") {
                time_filtered = true;
                start_timestamp = 0; // Set start timestamp
                end_timestamp = 0; // Set end timestamp
                while ((c = input.get()) != ' ') {
                    if (isdigit(c)) {
                        start_timestamp *= 10;
                        start_timestamp += c - '0';
                    }
                }
                while ((c = input.get()) != ' ') {
                    if (isdigit(c)) {
                        end_timestamp *= 10;
                        end_timestamp += c - '0';
                    }
                }
            } else if (token == "o" || token == "output-file") {
                output_file = input.str();
            } else if (token == "stats") {
                // TODO: Implement statistics generation
            } else if (token == "--top-n") {
                top_n = std::stoi(input.str());
            }
        }
    }

    if (!time_filtered) {
        start_timestamp = 0;
        end_timestamp = 0;
    }

    // Process sensor data line by line
    int current_timestamp = 0;
    double average_reading = 0.0;
    int total_readings = 0;

    for (std::string line; std::getline(input, line);) {
        if (!time_filtered || (start_timestamp <= current_timestamp && current_timestamp <= end_timestamp)) {
            // Process sensor data entry
            int anomaly_score = 0;
            double reading = analyzeSensorReading(line);

            if (reading > average_reading) {
                total_readings++;
                average_reading += reading / top_n;

                // Generate statistics
                std::cout << "Average reading: " << average_reading << std::endl;
                std::cout << "Total readings: " << total_readings << std::endl;
            }

            current_timestamp = 0; // Reset timestamp

            if (verbose_mode) {
                std::cout << line << std::endl;
            }
        }
    }

    input.close();
    output.close();

    return;
}

