// Compression algorithm with checksums
void compress_data(unsigned char* data, int bytes, unsigned char** compressed_data) {
    // Compress the data and store it in compressed_data
    int total_bytes = bytes + 4; // Add 4 bytes for checksum
    *compressed_data = (unsigned char*)malloc(total_bytes);
    memcpy(*compressed_data, data, bytes);
    uint32_t checksum = calculate_checksum(data, bytes);
    *(uint32_t*)((*compressed_data) + bytes) = checksum;
}

int decompress_data(unsigned char* compressed_data, int total_bytes) {
    // Decompress the data and verify the checksum
    int bytes = total_bytes - 4; // Subtract 4 bytes for checksum
    unsigned char* data = (unsigned char*)malloc(bytes);
    memcpy(data, compressed_data, bytes);
    uint32_t checksum = *(uint32_t*)(compressed_data + bytes);
    if (checksum != calculate_checksum(data, bytes)) {
        return -1; // Invalid checksum
    }
    return 0; // Valid decompression
}
