#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int packetID;
    time_t timestamp;
    unsigned char* payload;
    size_t payloadSize;
} DataPacket;

DataPacket** initializePackets(int numPackets) {
    DataPacket** packets = (DataPacket**)malloc(numPackets * sizeof(DataPacket*));

    if (!packets) {
        printf("Error: Memory allocation failed for packets.\n");
        return NULL;
    }

    int packetCount = 0;
    for (int i = 0; i < numPackets; i++) {
        DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));

        if (!packet) {
            printf("Error: Memory allocation failed for packet %d.\n", i);
            // Free previously allocated packets to avoid memory leak
            for (int j = 0; j < i; j++) {
                free(packets[j]);
            }
            return NULL;
        }

        packet->packetID = i;
        packet->timestamp = time(NULL);

        int payloadSize = rand() % 100 + 1; // Random payload size between 1 and 100 bytes
        packet->payload = (unsigned char*)malloc(payloadSize);

        if (!packet->payload) {
            printf("Error: Memory allocation failed for packet %d's payload.\n", i);
            free(packet); // Free the packet to avoid memory leak
            return NULL;
        }

        // Initialize random payload bytes
        for (int j = 0; j < payloadSize; j++) {
            packet->payload[j] = rand() % 256;
        }

        packet->payloadSize = payloadSize;
        packets[i] = packet;
        packetCount++;
    }

    printf("Packets processed: %d\n", packetCount);

    return packets;
}
