} DataPacket;

void* allocate_data_packet(int size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        return NULL;
    }
    return ptr;
}

DataPacket* create_data_packet(int id, double time, int payload_size) {
    DataPacket* packet = (DataPacket*)allocate_data_packet(sizeof(DataPacket));
    if (packet != NULL) {
        packet->packetID = id;
        packet->timestamp = time;
        packet->Payload = (char*)malloc(payload_size);
        if (packet->Payload == NULL) {
            free(packet);
            return NULL;
        }
    }
    return packet;
}

void log_packet_error(int id, char* message) {
    // Log the error
}

int main() {
    int packet_count = 10;
    DataPacket** packets = (DataPacket**)malloc(sizeof(DataPacket*) * packet_count);
    if (packets == NULL) {
        return -1;
    }

    for (int i = 0; i < packet_count; i++) {
        DataPacket* packet = create_data_packet(i, (double)i, 10);
        if (packet == NULL) {
            log_packet_error(i, "Memory allocation failed");
        } else {
            packets[i] = packet;
        }
    }

    for (int i = 0; i < packet_count; i++) {
        free(packets[i]->Payload);
        free(packets[i]);
    }
    free(packets);

    return 0;
}
