typedef struct {
    int pci;
    float rsrp;
    float sinr;
} LTE_RRC_Cell_Content;

void initialize_and_populate_network_components(int num_packets, int num_cells);

void free_network_components(UdpPacketHeader** packet_headers, LTE_RRC_Cell** cells);

#define set_checksum(packet) ((packet)->checksum = rand())

UdpPacketHeader* allocate_packet() {
    UdpPacketHeader* packet = (UdpPacketHeader*)malloc(sizeof(UdpPacketHeader));
    if (!packet) return NULL;
    return packet;
}

LTE_RRC_Cell* allocate_cell() {
    LTE_RRC_Cell* cell = (LTE_RRC_Cell*)malloc(sizeof(LTE_RRC_Cell));
    if (!cell) return NULL;
    return cell;
}

void initialize_and_populate_network_components(int num_packets, int num_cells) {
    UdpPacketHeader** packet_headers = (UdpPacketHeader**)calloc(num_packets, sizeof(UdpPacketHeader*));
    LTE_RRC_Cell** cells = (LTE_RRC_Cell**)calloc(num_cells, sizeof(LTE_RRC_Cell*));

    for (int i = 0; i < num_packets; ++i) {
        packet_headers[i] = allocate_packet();
        if (!packet_headers[i]) {
            // Handle memory allocation failure
            return;
        }
        ((UdpPacketHeader*)packet_headers[i])->source_port = rand() % 65535;
        ((UdpPacketHeader*)packet_headers[i])->destination_port = rand() % 65535;
        ((UdpPacketHeader*)packet_headers[i])->ip_address = htonl(INADDR_LOOPBACK);
        set_checksum((UdpPacketHeader*)packet_headers[i]);
    }

    for (int i = 0; i < num_cells; ++i) {
        cells[i] = allocate_cell();
        if (!cells[i]) {
            // Handle memory allocation failure
            return;
        }
        cells[i]->cell_id = 1000 + i;
        cells[i]->tac = 1000 + i;
        LTE_RRC_Cell_Content* cell_info = (LTE_RRC_Cell_Content*)calloc(1, sizeof(LTE_RRC_Cell_Content));
        if (!cell_info) {
            // Handle memory allocation failure
            return;
        }
        cell_info->pci = rand() % 500 + 1;
        cell_info->rsrp = (float)(-140.0 - ((rand() % 10000) / 100.0));
        cell_info->sinr = (float)(-3.0 + ((rand() % 2000) / 100.0));
        cells[i]->cell_info_list = cell_info;
    }

    // Free allocated memory
    free_network_components(packet_headers, cells);
}

void free_network_components(UdpPacketHeader** packet_headers, LTE_RRC_Cell** cells) {
    for (int i = 0; i < MAX_PACKETS && packet_headers[i]; ++i) {
        free(packet_headers[i]);
    }
    for (int i = 0; i < MAX_CELLS && cells[i]; ++i) {
        free(cells[i]->cell_info_list);
        free(cells[i]);
    }
}
