void initialize_and_populate_network_components(int num_packets, int num_cells) {
    UdpPacketHeader *udp_packet_headers = malloc(num_packets * sizeof(UdpPacketHeader));
    if (udp_packet_headers == NULL) {
        // Handle memory allocation failure
        return;
    }

    LTE_RRC_Cell *lte_rrc_cells = malloc(num_cells * sizeof(LTE_RRC_Cell));
    if (lte_rrc_cells == NULL) {
        free(udp_packet_headers);
        return;
    }

    for (int i = 0; i < num_packets; i++) {
        udp_packet_headers[i].source_port = i + 1;
        udp_packet_headers[i].dest_port = i + 2;
        strcpy(udp_packet_headers[i].ip_address, "192.168.");
        sprintf(&udp_packet_headers[i].ip_address[12], "%d", i % 255);
        udp_packet_headers[i].checksum = 0; // Initialize checksum
    }

    for (int i = 0; i < num_cells; i++) {
        lte_rrc_cells[i].cell_id = 1000 + i;
        lte_rrc_cells[i].tac = 1000 + i;

        lte_rrc_cells[i].cell_info_list = malloc(sizeof(struct {
            int pci;
            float rsrp;
            float sinr;
        }));
        if (lte_rrc_cells[i].cell_info_list == NULL) {
            free(udp_packet_headers);
            free(lte_rrc_cells);
            return;
        }

        lte_rrc_cells[i].cell_info_list->pci = rand() % 500 + 1;
        lte_rrc_cells[i].cell_info_list->rsrp = (float)(-140.0 - (rand() % 101) / 10.0);
        lte_rrc_cells[i].cell_info_list->sinr = (float)(-3.0 + (rand() % 21) / 10.0);
    }

    // Helper function to free all allocated memory
    void free_network_components(UdpPacketHeader *udp_packet_headers, LTE_RRC_Cell *lte_rrc_cells) {
        for (int i = 0; i < num_packets; i++) {
            free(udp_packet_headers[i].cell_info_list);
        }
        free(udp_packet_headers);

        for (int i = 0; i < num_cells; i++) {
            free(lte_rrc_cells[i].cell_info_list);
        }
        free(lte_rrc_cells);
    }

    // Deallocate all memory
    free_network_components(udp_packet_headers, lte_rrc_cells);
}

int main() {
    initialize_and_populate_network_components(UDP_PACKETS, LTE_RRC_CELLS);
    return 0;
}
