#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LOG_ENTRY_SIZE 1024
#define MAX_MESSAGES 1000

typedef struct {
    int timestamp;
    char message[LOG_ENTRY_SIZE];
    char level[10]; // possible levels: "DEBUG", "INFO", "WARNING", "ERROR"
} LOG_ENTRY;

typedef struct node {
    LOG_ENTRY log_entry;
    struct node* next;
} NODE;

void compress_list(NODE** head_ref, int M) {
    if (*head_ref == NULL || (*head_ref)->next == NULL)
        return;

    NODE* current = *head_ref;
    NODE* previous = NULL;

    // Traverse the list and remove entries older than 'M'
    while (current != NULL && current->log_entry.timestamp < M) {
        previous = current;
        current = current->next;
    }

    if (previous == NULL)
        *head_ref = current;
    else
        previous->next = current;

    // Update the statistics
    int retained_entries = 0, discarded_entries = 0;
    NODE* temp = *head_ref;
    while (temp != NULL) {
        if (temp->log_entry.timestamp >= M)
            retained_entries++;
        else
            discarded_entries++;
        temp = temp->next;
    }

    printf("Retained entries: %d\n", retained_entries);
    printf("Discarded entries: %d\n", discarded_entries);
}

void insert_log_entry(NODE** head_ref, LOG_ENTRY log_entry) {
    NODE* new_node = (NODE*)malloc(sizeof(NODE));
    if (*head_ref == NULL || (*head_ref)->log_entry.timestamp < log_entry.timestamp) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    } else {
        NODE* current = *head_ref;
        while (current->next != NULL && current->next->log_entry.timestamp >= log_entry.timestamp)
            current = current->next;
        new_node->next = current->next;
        current->next = new_node;
    }
}

void print_log_entries(NODE* head) {
    NODE* temp = head;
    while (temp != NULL) {
        printf("%d - %s [%s]\n", temp->log_entry.timestamp, temp->log_entry.message, temp->log_entry.level);
        temp = temp->next;
    }
}

void filter_log_entries(NODE* head, char* level) {
    NODE* temp = head;
    while (temp != NULL) {
        if (strcmp(temp->log_entry.level, level) == 0)
            printf("%d - %s [%s]\n", temp->log_entry.timestamp, temp->log_entry.message, temp->log_entry.level);
        temp = temp->next;
    }
}

int main() {
    // Initialize the head of the list
    NODE* head = NULL;

    // Insert log entries
    LOG_ENTRY log_entries[] = {
        {1643723400, "Something happened", "INFO"},
        {1643723410, "Another thing occurred", "WARNING"},
        {1643723420, "Yet another event", "DEBUG"},
        ...
    };
    for (int i = 0; i < sizeof(log_entries) / sizeof(log_entries[0]); i++) {
        insert_log_entry(&head, log_entries[i]);
    }

    // Compress the list
    compress_list(&head, M);

    // Print all log entries
    print_log_entries(head);

    // Filter log entries by level
    filter_log_entries(head, "WARNING");

    return 0;
}
