// Function to manage dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
void* crc_indication_pdu_array_manager(void* ptr) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    int nfaapi_crc_indication_pdu_array_size = 10; // Initial size of the array

    NFAPI_CRC_INDICATION_PDU_T** nfaapi_crc_indication_pdu_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * nfaapi_crc_indication_pdu_array_size);

    for(int i=0; i<nfaapi_crc_indication_pdu_array_size; i++) {
        nfaapi_crc_indication_pdu_array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Initialize the CRCFLAG as 1 or 0 randomly
        nfaapi_crc_indication_pdu_array[i]->valid = 1;
        nfaapi_crc_indication_pdu_array[i]->rnti = i; // Assign a unique RNTI to each UE
        if(rand() % 2) {
            nfaapi_crc_indication_pdu_array[i]->crcflag = 1;
        } else {
            nfaapi_crc_indication_pdu_array[i]->crcflag = 0;
        }
    }

    // Main loop for adding new elements to the array
    while(1) {
        pthread_mutex_lock(&mutex);
        printf("Enter RNTI value (-1 to exit): ");
        int rnti_value;
        scanf("%d", &rnti_value);

        if(rnti_value == -1) {
            break;
        }

        // Check for array fullness
        if(nfaapi_crc_indication_pdu_array_size <= 0) {
            printf("Array is full. Please delete some elements before adding new ones.\n");
            continue;
        }

        nfaapi_crc_indication_pdu_array[nfaapi_crc_indication_pdu_array_size]->valid = 1; // Assuming RNTI is valid
        nfaapi_crc_indication_pdu_array[nfaapi_crc_indication_pdu_array_size]->rnti = rnti_value; // Assign the entered RNTI to the new UE
        if(rand() % 2) {
            nfaapi_crc_indication_pdu_array[nfaapi_crc_indication_pdu_array_size]->crcflag = 1;
        } else {
            nfaapi_crc_indication_pdu_array[nfaapi_crc_indication_pdu_array_size]->crcflag = 0;
        }

        nfaapi_crc_indication_pdu_array_size++;
        // If array is full, double its size
        if(nfaapi_crc_indication_pdu_array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*) > 10*1024*1024) {
            NFAPI_CRC_INDICATION_PDU_T** new_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * nfaapi_crc_indication_pdu_array_size * 2);
            for(int i=0; i<nfaapi_crc_indication_pdu_array_size; i++) {
                new_array[i] = nfaapi_crc_indication_pdu_array[i];
            }
            free(nfaapi_crc_indication_pdu_array);
            nfaapi_crc_indication_pdu_array = new_array;
        }

        pthread_mutex_unlock(&mutex);

        printf("New UE added. Array size: %d\n", nfaapi_crc_indication_pdu_array_size);
    }

    // Deallocate array and its elements
    for(int i=0; i<nfaapi_crc_indication_pdu_array_size; i++) {
        free(nfaapi_crc_indication_pdu_array[i]);
    }
    free(nfaapi_crc_indication_pdu_array);

    return NULL;
}
