    size_t capacity;
    size_t size;
    PHY_STATISTICS_T* data;
    pthread_mutex_t mutex;
} phy_statistics_array_t;

void* phy_statistics_array_init(size_t initial_capacity) {
    phy_statistics_array_t* array = (phy_statistics_array_t*)malloc(sizeof(phy_statistics_array_t));
    array->capacity = initial_capacity;
    array->size = 0;
    array->data = (PHY_STATISTICS_T*)calloc(initial_capacity, sizeof(PHY_STATISTICS_T));
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void phy_statistics_array_free(phy_statistics_array_t* array) {
    if (!array) return;
    free(array->data);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int phy_statistics_array_add_element(phy_statistics_array_t* array, PHY_STATISTICS_T element) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->data = (PHY_STATISTICS_T*)realloc(array->data, array->capacity * sizeof(PHY_STATISTICS_T));
    }

    array->data[array->size++] = element;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

