    DataPacket** packets = my_malloc(packet_count * sizeof(DataPacket*));
    if (packets == NULL) return NULL;

    for (int i = 0; i < packet_count; i++) {
        packets[i] = my_malloc(sizeof(DataPacket));
        if (packets[i] == NULL) {
            free_all(packets, i);
            return NULL;
        }
        packets[i]->packetID = rand() % 1000;
        time_t timestamp = time(NULL);
        char* Payload = my_malloc(rand() % 10 + 1);
        strcpy(Payload, "Random payload");
        packets[i]->timestamp = timestamp;
        packets[i]->Payload = Payload;
    }

    return (void*)packets;
}

