    for(int i = 0; i < numStreams; i++) {
        StreamConfiguration* stream = (StreamConfiguration*)malloc(sizeof(StreamConfiguration));
        int id = rand();
        size_t bufferSize = rand() % 1024 + 1;
        char buffer[bufferSize];
        for(size_t j = 0; j < bufferSize; j++)
