        stream->id = id;
        stream->bufferSize = bufferSize;
        stream->buffer = malloc(bufferSize);

        // Initialize file info and metadata
        fileInfoArr[i].timestamp = time(NULL) + i;
        fileInfoArr[i].fileSize = rand() % 1024 + 1;

        fileMetadataArr[i].fileDescriptor = open("/path/to/file", O_RDONLY);
