            printf("Error opening file: %s\n", strerror(-fileMetadataArr[i].fileDescriptor));

        // Add to arrays
        streams[i] = stream;
        floats[i] = rand();
        filePaths[i] = malloc(257); // Ensure enough space for null-terminator
        strncpy(filePaths[i], "/path/to/file", 256);
        filePaths[i][256] = '\0';
    }

    // Return number of successfully configured streams
    int success = 0;
    for(int i = 0; i < numStreams; i++) {
        if(streams[i]->buffer && filePaths[i]) {
            printf("Stream %d initialized successfully.\n", i);
            success++;
        } else {
            printf("Error initializing stream %d: %s\n", i, strerror(errno));
        }
    }

    return (StreamConfiguration*)streams;
}

int main() {
    size_t numStreams = 10000;
    StreamConfiguration* streams = configureStreams(numStreams);
    // Perform stream operations here...
    free(streams);
    return 0;
}
