typedef struct {
    time_t timestamp;
    off_t fileSize;
    char* filePath;
    int refCount;
    pthread_mutex_t lock;
} FileInfo;

typedef struct {
    time_t lastModified;
    mode_t perms;
    int refCount;
} FileMetadata;

int initDir(int N) {
    DirEntry** dirEntries = (DirEntry**)calloc(N, sizeof(DirEntry*));
    if (!dirEntries) return -1; // out-of-memory

    char** filePaths = (char**)malloc(N * sizeof(char*) + 256);
    if (!filePaths) return -2; // out-of-memory

    FileInfo** fileInfos = (FileInfo*)calloc(N, sizeof(FileInfo));
    if (!fileInfos) return -3; // out-of-memory

    for (int i = 0; i < N; i++) {
        dirEntries[i] = (DirEntry*)malloc(sizeof(DirEntry));
        if (!dirEntries[i]) return -4; // out-of-memory

        filePaths[i] = malloc(257); // +1 for null-terminator
        if (!filePaths[i]) return -5; // out-of-memory

        fileInfos[i].timestamp = time(NULL);
        fileInfos[i].fileSize = 0;
        fileInfos[i].filePath = filePaths[i];
        fileInfos[i].refCount = 0;

        pthread_mutex_init(&fileInfos[i].lock, NULL);

        dirEntries[i]->RX_UE_INFORMATION_TAG = rand() % 256;
        dirEntries[i]->RNTI = rand() % 65536;
        dirEntries[i]->CRC_INDICATION_REL8_TAG = rand();
        dirEntries[i]->CRCFLAG = rand() % 2;

    }

    // Initialize persistent storage
    int db_fd = open("directory.db", O_RDWR | O_CREAT, 0644);
    if (db_fd < 0) return -6; // error opening database

    // Store directory information in database
    for (int i = 0; i < N; i++) {
        DIR* dir = opendir("path/to/directory");
        if (!dir) continue;

        struct dirent* entry = readdir(dir);
        while (entry) {
            if (strcmp(entry->d_name, filePaths[i])) {
                // Store file metadata in database
                FileMetadata fileMeta;
                fileMeta.lastModified = fileInfos[i].timestamp;
                fileMeta.perms = 0755;
                fileMeta.refCount = 1;

                db_entry dbEntry;
                dbEntry.filePath = filePaths[i];
                dbEntry.fileInfo = &fileInfos[i];

                // Store directory entry in database
                dir_entries[i]->filePath = filePaths[i];
                dir_entries[i]->fileInfo = &fileInfos[i];

                insert_db(db_fd, &dbEntry);

            }
            entry = readdir(dir);
        }

    }

    return 0;
}

int main() {
    int N = 1000; // example value
    initDir(N);
    return 0;
}
