#define MAX_LINE_LENGTH 1024
#define DEFAULT_OUTPUT_FILE "output.txt"
#define HELP_TEXT "Usage: word_counter [options] input_file\n" \
                 "Options:\n" \
                 "  --help     Print this help message and exit.\n" \
                 "  -cs        Enable case-sensitive word counting.\n" \
                 "  -o <file>  Redirect output to the specified file instead of standard output.\n"

int main(int argc, char **argv) {
    int c;
    while ((c = getopt(argc, argv, "+:ho:c")) != -1) {
        switch (c) {
            case 'h':
                printf(HELP_TEXT);
                return 0;
            case 'o':
                strcpy(DEFAULT_OUTPUT_FILE, optarg);
                break;
            case 'c':
                // case-sensitive word counting
                break;
            default:
                if (c == '?') {
                    fprintf(stderr, "Unknown option: %s\n", argv[optind - 1]);
                }
                else {
                    fprintf(stderr, "Invalid command line argument.\n");
                }
                return 1;
        }
    }

    if (argc <= optind) {
        printf("Error: No input file specified. Please provide the input file as an argument.\n");
        printf(HELP_TEXT);
        return 0;
    }

    char *input_file = argv[optind];

    FILE *fp = fopen(input_file, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Unable to open file '%s' for reading. Please ensure the file exists and is readable.\n", input_file);
        return 1;
    }

    int lines_counted = 0;
    int words_counted = 0;

    char line[MAX_LINE_LENGTH];
    size_t chunk_size = 1024 * 16; // 16KB
    char *chunk = malloc(chunk_size);

    if (chunk == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for file processing.\n");
        fclose(fp);
        return 1;
    }

    int64_t total_words = 0;

    while (fgets(line, sizeof line, fp)) {
        lines_counted++;

        char *word = strtok(line, " ");
        while (word != NULL) {
            words_counted++;
            word = strtok(NULL, " ");
        }
    }

    fclose(fp);

    printf("Lines: %d\n", lines_counted);
    printf("Words: %d\n", words_counted);

    return 0;
}
