#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Structure representing a connection pool entry
typedef struct {
    int clientId;
    void* connection; // Connection object
    char query[1024]; // Query command (default: empty string)
    int timeout; // Timeout value (default: 0)
    bool idle; // Flag indicating whether the connection is idle (default: true)
} ConnectionPoolEntry;

// Structure managing a database connection pool
typedef struct {
    ConnectionPoolEntry* entries;
    size_t numEntries;
    size_t capacity;
    pthread_mutex_t mutex; // Mutex for thread-safe access
    FILE* logFile; // File handle for logging
} ConnectionPoolManager;

// Initialize and manage a database connection pool
void* connectionPoolManagerInit(size_t initialCapacity, size_t maxCapacity) {
    ConnectionPoolManager* manager = (ConnectionPoolManager*) malloc(sizeof(ConnectionPoolManager));
    if (!manager) return NULL;

    manager->numEntries = 0;
    manager->capacity = initialCapacity;

    // Allocate memory for connection pool entries
    manager->entries = (ConnectionPoolEntry*) calloc(manager->capacity, sizeof(ConnectionPoolEntry));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL); // Initialize mutex

    // Open log file for logging
    manager->logFile = fopen("connection_pool.log", "a+");
    if (!manager->logFile) {
        fclose(manager->logFile);
        free(manager->entries);
        free(manager);
        return NULL;
    }

    return manager;
}

// Add a new client connection to the pool (thread-safe)
void connectionPoolAddEntry(ConnectionPoolManager* manager, int clientId, void* connection) {
    pthread_mutex_lock(&manager->mutex); // Lock mutex for thread safety

    if (manager->numEntries >= manager->capacity) {
        // Reallocate memory if necessary
        manager->entries = (ConnectionPoolEntry*) realloc(manager->entries, sizeof(ConnectionPoolEntry) * (manager->capacity * 2));
        manager->capacity *= 2;
    }

    ConnectionPoolEntry* newEntry = &manager->entries[manager->numEntries++];
    newEntry->clientId = clientId;
    newEntry->connection = connection;
    strcpy(newEntry->query, ""); // Initialize query command
    newEntry->timeout = 0; // Initialize timeout value
    newEntry->idle = true; // Initialize idle flag

    pthread_mutex_unlock(&manager->mutex); // Unlock mutex
}

// Remove a client connection from the pool (thread-safe)
void connectionPoolRemoveEntry(ConnectionPoolManager* manager, int clientId) {
    pthread_mutex_lock(&manager->mutex); // Lock mutex for thread safety

    for (size_t i = 0; i < manager->numEntries; i++) {
        if (manager->entries[i].clientId == clientId) {
            // Find and remove the corresponding entry
            ConnectionPoolEntry* oldEntry = &manager->entries[i];
            for (size_t j = i + 1; j < manager->numEntries; j++) {
                manager->entries[j - 1] = manager->entries[j]; // Shift entries
            }
            manager->numEntries--;
            free(oldEntry); // Free memory

            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex); // Unlock mutex
}

// Log connection pool operations (thread-safe)
void connectionPoolLogOperation(ConnectionPoolManager* manager, const char* operation) {
    pthread_mutex_lock(&manager->mutex); // Lock mutex for thread safety

    fprintf(manager->logFile, "%s: %d client connections in the pool\n", operation, manager->numEntries);

    pthread_mutex_unlock(&manager->mutex); // Unlock mutex
}

// Deallocate memory and close log file when done
void connectionPoolManagerFree(ConnectionPoolManager* manager) {
    if (!manager) return;

    free(manager->entries); // Free connection pool entries
    fclose(manager->logFile); // Close log file
    pthread_mutex_destroy(&manager->mutex); // Destroy mutex

    free(manager); // Deallocate memory
}
