#include <arpa/inet.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>

#define MAX_IP_ADDRESSES 100
#define MAX_PORT_NUMBER 65535
#define TIMEOUT_SECONDS 10
#define HANDSHAKE_BUFFER_SIZE 1024

typedef struct {
    int socket;
    char buffer[HANDSHAKE_BUFFER_SIZE];
    time_t timestamp;
    int error_code;
} SocketStruct;

SocketStruct *manage_connections(int num_connections, char **ip_addresses, int *port_numbers) {
    int i;
    SocketStruct *sockets = (SocketStruct *)malloc(num_connections * sizeof(SocketStruct));

    for (i = 0; i < num_connections; i++) {
        // Establish connection and handle errors
        int socket_fd = -1;
        if ((socket_fd = establish_connection(ip_addresses[i], port_numbers[i])) == -1) {
            // Handle failed connections
            freesockets(sockets, i);
            return NULL;
        }

        // Set up handshake and receive response
        if (!send_handshake(socket_fd)) {
            close_socket(socket_fd);
            freesockets(sockets, i);
            return NULL;
        }
    }

    return sockets;
}

int establish_connection(char *ip_address, int port_number) {
    int socket_fd = -1;

    // Create socket and set up for connection
    if ((socket_fd = socket(AF_INET, SOCK_STREAM, 0)) == -1)
        return -1;

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port_number);
    inet_pton(AF_INET, ip_address, &server_addr.sin_addr);

    // Set up timeout
    if (setsockopt(socket_fd, SOL_SOCKET, SO_RCVTIMEO, &TIMEOUT_SECONDS, sizeof(int)) == -1)
        return -1;

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        close(socket_fd);
        return -1;
    }

    return socket_fd;
}

void freesockets(SocketStruct *sockets, int i) {
    for (int j = 0; j < i; j++) {
        close_socket(sockets[j].socket);
        // Clean up other fields
    }
    free(sockets);
}

