        std::ifstream file(inputFile);
        if (!file.is_open()) {
            logger_.log(LogLevel::ERROR, "Failed to open input file: " + inputFile);
            return;
        }

        // Initialize variables and data structures
        std::vector<std::string> sensorData;
        size_t totalMemoryUsage = 0;

        // Read and process the sensor data line by line
