    int** ints = NULL;
    char*** chars = NULL;
    record* records = NULL;

    if (argc > 1 && strcmp(argv[1], "--manpage") == 0)
        printf("Your manual page content\n");
    else if (argc > 1 && strcmp(argv[1], "-cs") == 0) {
        int len = 10;
        *ints = (int*)malloc(len * sizeof(int));
        *chars = (char**)malloc(len * sizeof(char*));

        for (int i = 0; i < len; i++) {
            (*chars)[i] = (char*)malloc(10 * sizeof(char));
        }
    } else if (argc > 1 && strcmp(argv[1], "-o") == 0) {
        char* output_file = argv[2];
        FILE* file = fopen(output_file, "w");

        if (!file)
            return -1;

        for (int i = 0; i < len; i++) {
            fprintf(file, "%s\n", (*chars)[i]);
        }

        fclose(file);
    } else if (argc > 1) {
        parse_args(&argc, &argv, &ints);

        record* records = mem_mgr(ints, chars);

        printf("%zu\n", sizeof(record));

        for (int i = 0; i < len; i++) {
            free((*chars)[i]);
        }

        free(*chars);
    } else
        fprintf(stderr, "Usage: -cs <file> or -o <output_file>\n");

    if (*ints)
        free(*ints);

    return 0;
}

record* mem_mgr(int** ints, char*** chars) {
    int len = 10;
    *chars = (char**)malloc(len * sizeof(char*));
    record* records = (record*)malloc(len * sizeof(record));

    for (int i = 0; i < len; i++) {
        (*chars)[i] = (char*)malloc(10 * sizeof(char));

        time_t timestamp = time(NULL);
        struct tm* info = localtime(&timestamp);
        int year = info->tm_year;
        int month = info->tm_mon;
        int day = info->tm_mday;
        double value = 0.5 + (double)i / 10.0;

        records[i].timestamp = ((year - 1970) * 365 + day) * 24 * 60 * 60 + month * 30 * 24 * 60 * 60;
        records[i].value = value;
    }

    return records;
}

void parse_args(int* argc, char*** argv, char*** chars) {
    int len = 10;
    *chars = (char**)malloc(len * sizeof(char*));

    for (int i = 0; i < len; i++) {
        (*chars)[i] = (char*)malloc(10 * sizeof(char));

        strcpy((*chars)[i], argv[1]);

        printf("%s\n", (*chars)[i]);
    }
}
