int main(int argc, char **argv) {
    Args args = {NULL, 0, NULL, 1};
    if (!parse_args(argc, argv)) {
        print_usage();
        return 1;
    }

    // Start timing
    clock_t start_time = clock();

    pthread_t threads[args.parallel_processes];
    for (int i = 0; i < args.parallel_processes; i++) {
        char *filename = strtok(args.input_file, ",");
        process_input_file(filename);
    }

    // Wait for all threads to finish
    for (int i = 0; i < args.parallel_processes; i++) {
        pthread_join(threads[i], NULL);
    }

    // End timing
    clock_t end_time = clock();
    int total_time = (end_time - start_time) / (double)CLOCKS_PER_SEC;

    log_info(start_time, end_time, total_time);
    return 0;
}

