        free(new_record);
        return; // Handle allocation failure
    }

    // Add record to list and update total CPU and memory usage
    new_record->next = NULL;
    if (!data_records) {
        data_records = new_record;
    } else {
        data_record* current = data_records;
        while (current->next) {
            current = current->next;
        }
        current->next = new_record;
    }

    num_data_records++;
}

void update_record(float precision_value, char* identifier, double cpu_usage, size_t memory_usage) {
    // Find record to update
    data_record* current = data_records;
    while (current) {
        if (strcmp(current->identifier, identifier) == 0) {
            break;
        }
        current = current->next;
    }
    if (!current) return; // Record not found

    // Update record fields
    current->precision_value = precision_value;

    // Update process state
    current->process_state.cpu_usage = cpu_usage;
    current->process_state.memory_usage = memory_usage;

    // Update total CPU and memory usage
    if (current_total_cpu_memory_usage) {
        current_total_cpu_memory_usage->cpu_usage += cpu_usage;
        current_total_cpu_memory_usage->memory_usage += memory_usage;
    } else {
        current_total_cpu_memory_usage = &current->process_state;
    }
}

void remove_record(char* identifier) {
    // Find record to remove
    data_record* current = data_records;
    data_record* previous = NULL;
    while (current) {
        if (strcmp(current->identifier, identifier) == 0) {
            break;
        }
        previous = current;
        current = current->next;
    }
    if (!current) return; // Record not found

    // Remove record from list and update total CPU and memory usage
    if (previous) {
        previous->next = current->next;
    } else {
        data_records = current->next;
    }

    // Free record resources
    free(current);
    num_data_records--;
}

void get_current_total_cpu_memory_usage(double* cpu_usage, size_t* memory_usage) {
    *cpu_usage = current_total_cpu_memory_usage->cpu_usage;
    *memory_usage = current_total_cpu_memory_usage->memory_usage;
}

void collect_statistics(int interval) {
    // Collect statistics
    double total_cpu_usage = 0.0;
    size_t total_memory_usage = 0;
    data_record* current = data_records;
    while (current) {
        total_cpu_usage += current->process_state.cpu_usage;
        total_memory_usage += current->process_state.memory_usage;
        current = current->next;
    }

    // Update statistics
    current_total_cpu_memory_usage->cpu_usage = total_cpu_usage / num_data_records;
    current_total_cpu_memory_usage->memory_usage = total_memory_usage / num_data_records;

    // Periodically export statistics to log file (optional)
}

void clear_all_resources(int flag) {
    if (!flag) return; // Do not clear resources

    // Free record and process state structures
    data_record* current = data_records;
    while (current) {
        free(current);
        current = current->next;
    }
    num_data_records = 0;

    // Close or unlink file descriptors
    if (current_total_cpu_memory_usage && current_total_cpu_memory_usage->file_descriptors) {
        for (int i = 0; i < current_total_cpu_memory_usage->memory_usage; i++) {
            close(current_total_cpu_memory_usage->file_descriptors[i]);
        }
    }

    // Reset total CPU and memory usage
    current_total_cpu_memory_usage = NULL;
}

// Function to periodically export statistics to log file (optional)
