#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int session_id;
    char client_ip[16];
    int server_port;
    int protocol_type; // 0 - TCP, 1 - UDP
    char* buffer;
} SessionStruct;

SessionStruct** setup_and_manage_application_sessions(int num_sessions) {
    SessionStruct** sessions = NULL;
    size_t session_size = sizeof(SessionStruct);

    // Allocate memory for the array of session structures
    sessions = (SessionStruct**)malloc(num_sessions * sizeof(SessionStruct*));

    if (!sessions) {
        return NULL;
    }

    // Initialize the hash table for unique session IDs
    int** id_table = (int**)calloc(1024, sizeof(int*));
    int id_table_size = 1024;

    // Populate each session with a unique session ID, client IP address, server port, and protocol type
    for (int i = 0; i < num_sessions; i++) {
        SessionStruct* session = (SessionStruct*)malloc(session_size);

        if (!session) {
            free(sessions);
            return NULL;
        }

        // Initialize the session ID using a hashing mechanism
        int id = rand() % 1000000;
        int hash_value = id % id_table_size;

        while (id_table[hash_value]) {
            id = rand() % 1000000;
            hash_value = id % id_table_size;
        }

        session->session_id = id;
        strcpy(session->client_ip, "192.168.1.");
        session->server_port = 8080; // Default port
        session->protocol_type = (rand() % 2) ? 1 : 0;

        // Initialize the dynamic buffer for incoming and outgoing message data
        int buffer_size = 1024;
        session->buffer = malloc(buffer_size);

        if (!session->buffer) {
            free(sessions);
            return NULL;
        }

        // Validate the server port range for both TCP and UDP
        if (session->server_port < 0 || session->server_port > 65535) {
            free(session->buffer);
            free(session);
            continue;
        }

        sessions[i] = session;
    }

    // Release allocated memory when done using it
    void release_sessions(SessionStruct** sessions, int num_sessions) {
        for (int i = 0; i < num_sessions; i++) {
            SessionStruct* session = sessions[i];
            free(session->buffer);
            free(session);
        }

        free(sessions);
    }
}
