void validateReadings(SensorReading* readings, int num_readings) {
    // Validate timestamps within valid range
    for (int i = 0; i < num_readings; i++) {
        if (readings[i].timestamp < 0 || readings[i].timestamp > time(NULL)) {
            printf("Invalid timestamp in reading %d\n", i);
        }

        // Validate value and quality factor limits
