void* create_population_list(int num_structures) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc((num_structures + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for(int i = 0; i < num_structures; i++) {
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand() % 65535;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu->CRCFLAG = rand() % 2;

        list[i] = pdu;
        pthread_mutex_unlock(&mutex);
    }

    return (void*)list;
}

void free_population_list(void* population_list) {
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)population_list;
    for(int i = 0; i < num_structures; i++) {
        pthread_mutex_lock(&mutex);
        free(list[i]);
        pthread_mutex_unlock(&mutex);
    }
