#include <time.h>

#define MAX_UE_INFO_TAG_SIZE 256
#define MAX_RNTI_SIZE 10
#define MAX_CRC_IND_TAG_SIZE 32

typedef struct {
    char RX_UE_INFORMATION_TAG[MAX_UE_INFO_TAG_SIZE];
    int RNTI;
} NFAPI_RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_REL8_TAG;

typedef struct {
    NFAPI_RX_UE_INFORMATION_TAG rx_ue_info_tag;
    NFAPI_CRC_INDICATION_REL8_TAG crc_ind_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int n, int** list) {
    *list = (NFAPI_CRC_INDICATION_PDU_T**)malloc((n+1)*sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pdu) {
            printf("Memory allocation failed!\n");
            return NULL;
        }

        srand(time(NULL));
        sprintf(pdu->rx_ue_info_tag.RX_UE_INFORMATION_TAG, "RX_UE_INFO_TAG_%d", i);
        pdu->rx_ue_info_tag.RNTI = rand() % 1000000;

        pdu->crc_ind_tag.CRCFLAG = (rand() % 2) ? 1 : 0;

        if (!validate_pdu(pdu)) {
            free(pdu);
            return NULL;
        }

        (*list)[i] = pdu;
    }

    (*list)[n] = NULL; // mark the end of the list

    return *list;
}

int validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (strlen(pdu->rx_ue_info_tag.RX_UE_INFORMATION_TAG) > MAX_UE_INFO_TAG_SIZE
        || strlen(pdu->rx_ue_info_tag.RX_UE_INFORMATION_TAG) < 1) {
        return 0;
    }

    if (pdu->rx_ue_info_tag.RNTI <= 0 || pdu->rx_ue_info_tag.RNTI >= 1000000) {
        return 0;
    }

    if (pdu->crc_ind_tag.CRCFLAG != 0 && pdu->crc_ind_tag.CRCFLAG != 1) {
        return 0;
    }

    return 1;
}

void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T** list, int n) {
    for (int i = 0; i < n; i++) {
        if ((*list)[i]) {
            free((*list)[i]);
        }
    }

    free(*list);
}
