typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* createNFAPIListAndUpload(int N, char* url) {
    NFAPI_CRC_INDICATION_PDU_T** nfaList = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for(int i = 0; i < N; i++) {
        nfaList[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfaList[i]->RX_UE_INFORMATION_TAG = rand() % 100;
        nfaList[i]->RNTI = rand() % 100;
        nfaList[i]->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        pthread_mutex_lock(&lock);
        if(nfaList[i]->RX_UE_INFORMATION_TAG + nfaList[i]->RNTI != nfaList[i]->CRCFLAG) {
            printf("Error: Structure integrity failed.\n");
            free(nfaList[i]);
            i--;
            continue;
        }
        pthread_mutex_unlock(&lock);
    }

    // File upload using Bluebird library
    FILE* file = fopen("file.txt", "w+");
    fwrite(url, strlen(url), 1, file);
    fclose(file);

    // Uploading the list of structures to the URL
    // Assuming that a chosen library (e.g., Bluebird) is used for this process
    char uploadUrl[1024];
    sprintf(uploadUrl, "%s/list.txt", url);
    FILE* uploadedFile = fopen(uploadedUrl, "w+");
    for(int i = 0; i < N; i++) {
        fwrite(&nfaList[i]->RX_UE_INFORMATION_TAG, sizeof(int), 1, uploadedFile);
        fwrite(&nfaList[i]->RNTI, sizeof(int), 1, uploadedFile);
        fwrite(&nfaList[i]->CRCFLAG, sizeof(int), 1, uploadedFile);
    }
    fclose(uploadedFile);

    free(nfaList);
    return uploadUrl;
}
