#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct list_node* next;
};

typedef struct {
    pthread_mutex_t lock;
    struct list_node* head;
    size_t capacity;
    size_t threshold;
} NFAPI_CRC_INDICATION_LIST;

NFAPI_CRC_INDICATION_LIST* create_crc_list(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_LIST* list = (NFAPI_CRC_INDICATION_LIST*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->capacity = initial_capacity;
    list->threshold = list->capacity / 2;
    return list;
}

void crc_list_add(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL || list->head->data != data) {
        struct list_node* new_node = (struct list_node*)malloc(sizeof(struct list_node));
        new_node->data = data;
        new_node->next = list->head;
        list->head = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* crc_list_get(NFAPI_CRC_INDICATION_LIST* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    struct list_node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    if (current == NULL || current->data == NULL) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    pthread_mutex_unlock(&list->lock);
    return current->data;
}

void crc_list_remove(NFAPI_CRC_INDICATION_LIST* list, unsigned short RNTI) {
    pthread_mutex_lock(&list->lock);
    struct list_node** node = &list->head;
    while (*node != NULL && (*node)->data->RNTI != RNTI) {
        node = &((*node)->next);
    }
    if (*node == NULL || (*node)->data == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    *node = (*node)->next;
    free((*node)->data);
    free(*node);
    pthread_mutex_unlock(&list->lock);
}

int crc_list_export(NFAPI_CRC_INDICATION_LIST* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return -1;
    }
    struct list_node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
    return 0;
}

void crc_list_compress(NFAPI_CRC_INDICATION_LIST* list) {
    // Compression logic goes here
}

NFAPI_CRC_INDICATION_LIST* crc_list_split(NFAPI_CRC_INDICATION_LIST* list) {
    NFAPI_CRC_INDICATION_LIST* new_list = create_crc_list(list->capacity / 2);
    pthread_mutex_lock(&list->lock);
    struct list_node* current = list->head;
    while (current != NULL) {
        if (rand() % 2 == 0) {
            crc_list_add(new_list, current->data);
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return new_list;
}

void crc_list_destroy(NFAPI_CRC_INDICATION_LIST* list) {
    struct list_node* current = list->head;
    while (current != NULL) {
        free(current->data);
        free(current);
        current = current->next;
    }
    free(list);
}
