int list_size = 0;
NFAPI_CRC_INDICATION_PDU_T* pdulist = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int valid_count = 0;
int invalid_count = 0;
int error_count = 0;

void* create_pdu(struct timespec* ts) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Initialize fields...
    pdu->RX_UE_INFORMATION_TAG = rand() % 256;
    pdu->RNTI = rand();
    pdu->CRC_INDICATION_REL8_TAG = rand() % 65536;
    pdu->CRCFLAG = (rand() & 1) ? 0 : 1;

    pthread_mutex_lock(&lock);
    pdulist[list_size++] = *pdu;
    pthread_mutex_unlock(&lock);

    // Logging
    if (*ts < 1000) {
        printf("Valid PDU processed: %u\n", list_size);
    }

    free(pdu);
}

void compaction() {
    int i, j = 0;
    for (i = 0; i < list_size; ++i) {
        if (pdulist[i].RX_UE_INFORMATION_TAG != 0) {
            pdulist[j++] = pdulist[i];
        }
    }

    pthread_mutex_lock(&lock);
    list_size = j;
    free(pdulist);
    pdulist = NULL;
    pthread_mutex_unlock(&lock);
}

void* backpressure(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        if (list_size > MAX_CONCURRENT_CONNECTIONS - 100) {
            // Limit the rate of data ingestion
            printf("System is overwhelmed, limiting data ingestion\n");
            pthread_cond_wait(&cond, &lock);
        }
        pthread_mutex_unlock(&lock);

        // Periodic compaction
        if (list_size % LIST_COMPACTION_INTERVAL == 0 && list_size > 0) {
            compaction();
        }

        usleep(10000); // Simulate some processing time
    }
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, backpressure, NULL);

    while (1) {
        create_pdu(NULL);
        // Simulate data ingestion from external source...
        usleep(1000000); // Simulate 1 second of processing time
    }

    return 0;
}
