NFAPI_CRC_INDICATION_PDU_T* pdu_list = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int pdu_count = 0;

void create_and_populate_pdu_list(int num_puds) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_puds; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            printf("Error allocating memory for PDU.\n");
            exit(1);
        }
        strcpy(pdu->RX_UE_INFORMATION_TAG, "valid_tag");
        pdu->RNTI = (rand() % 1000) + 1;
        sprintf(pdu->CRC_INDICATION_REL8_TAG, "%x", rand());
        pdu->CRCFLAG = (unsigned int)(rand() % 2);
        pdu_list[i] = *pdu;
    }
    pthread_mutex_unlock(&lock);
}

void compaction() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_PDU_STRUCTURES; i++) {
        if (!pdu_list[i].RNTI) {
            free(pdu_list[i]);
            pdu_count--;
        }
    }
    pthread_mutex_unlock(&lock);
}

void log_valid_and_invalid_pdu(int num_valid, int num_invalid) {
    printf("Valid PDUs: %d\n", num_valid);
    printf("Invalid PDUs: %d\n", num_invalid);
}

int main() {
    pthread_t thread;
    srand(time(NULL));
    create_and_populate_pdu_list(MAX_PDU_STRUCTURES);
    for (int i = 0; i < MAX_CONCURRENT_CONNECTIONS; i++) {
        if (pthread_create(&thread, NULL, &create_and_populate_pdu_list, (void*)MAX_PDU_STRUCTURES)) {
            printf("Error creating thread.\n");
            exit(1);
        }
    }
    for (int i = 0; i < MAX_CONCURRENT_CONNECTIONS; i++) {
        pthread_join(thread, NULL);
    }
    compaction();
    log_valid_and_invalid_pdu(pdu_count, 0);
    return 0;
}
