#define MAX_PACKETS 1000
#define IP_ADDRESS_LENGTH 16
#define PAYLOAD_SIZE_RANGE 1, 1024

typedef struct {
    char src_ip[IP_ADDRESS_LENGTH];
    char dst_ip[IP_ADDRESS_LENGTH];
    int payload_size;
    double latency;
    int sequence_number;
} Packet;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_all_memory(void** memory_blocks, int count) {
    for (int i = 0; i < count; ++i) {
        free(memory_blocks[i]);
    }
}

Packet* create_packets(int max_packs, size_t ip_addresses_size, char** packet_identifiers, double* latencies, int* sequence_numbers) {
    Packet* packets = allocate_memory(sizeof(Packet) * max_packs);
    if (!packets) return NULL;

    for (int i = 0; i < max_packs; ++i) {
        time_t timestamp = time(NULL);
        char packet_identifier[IP_ADDRESS_LENGTH];
        sprintf(packet_identifier, "%ld", timestamp);

        int payload_size = rand() % (PAYLOAD_SIZE_RANGE.second - PAYLOAD_SIZE_RANGE.first + 1) + PAYLOAD_SIZE_RANGE.first;
        double latency = (double)rand() / RAND_MAX * (10.0 - 0.1) + 0.1;
        int sequence_number = i;

        packets[i].src_ip[IP_ADDRESS_LENGTH - 1] = '\0';
        strcpy(packets[i].src_ip, "192.168.");
        char src_ip_digits[4];
        sprintf(src_ip_digits, "%d.%d.%d.%d", (i / 256) % 256, (i / 16) % 256, (i / 2) % 256, i % 256);
        strcat(packets[i].src_ip, src_ip_digits);

        strcpy(packets[i].dst_ip, "192.168.");
        sprintf(src_ip_digits, "%d.%d.%d.%d", ((i + 1) / 256) % 256, ((i + 1) / 16) % 256, ((i + 1) / 2) % 256, (i + 1) % 256);
        strcat(packets[i].dst_ip, src_ip_digits);

        strcpy(packet_identifiers[i], packet_identifier);
        latencies[i] = latency;
        sequence_numbers[i] = sequence_number;

        packets[i].payload_size = payload_size;
    }

    return packets;
}
