#define MAX_TEMP_READINGS 1000
#define MAX_DESCRIPTION_LENGTH 256
#define SMOOTHING_WINDOW_SIZE 3
#define LOGGING_SERVICE_API "my_logging_service"

typedef struct {
    double temperature;
    char description[MAX_DESCRIPTION_LENGTH];
} TemperatureReading;

void* my_malloc(size_t size) {
    // custom memory pool allocation logic here
}

int process_json_file(const char* file_path, int max_length, json_object* smoothing_output) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        printf("Error opening file\n");
        return 1;
    }

    json_object* root = json_object_from_file(file);
    fclose(file);

    if (!root) {
        printf("Error parsing JSON\n");
        return 2;
    }

    int num_readings = 0;
    TemperatureReading** readings = (TemperatureReading**)my_malloc(MAX_TEMP_READINGS * sizeof(TemperatureReading*));
    char** descriptions = (char**)my_malloc(MAX_TEMP_READINGS * MAX_DESCRIPTION_LENGTH);
    int* description_lengths = (int*)malloc(MAX_TEMP_READINGS * sizeof(int));

    json_object_iter* iter;
    for (iter = json_object_iter_begin(root); iter; json_object_iter_next(iter)) {
        const char* key = json_object_get_string(iter->key);
        if (!strcmp(key, "temperature")) {
            double temperature = json_object_get_double(iter->value);
            // handle missing or malformed entries
            if (isnan(temperature)) {
                printf("Error: invalid temperature value\n");
                continue;
            }
            readings[num_readings]->temperature = temperature;
        } else if (!strcmp(key, "description")) {
            const char* description_str = json_object_get_string(iter->value);
            // handle missing or malformed entries
            if (strlen(description_str) > max_length) {
                printf("Error: description exceeds maximum allowed length\n");
                continue;
            }
            strcpy(readings[num_readings]->description, description_str);
        } else {
            printf("Unknown key: %s\n", key);
        }

        num_readings++;
    }

    // smoothing algorithm
    for (int i = 0; i < num_readings; i++) {
        double sum = 0.0;
        int count = 0;
        for (int j = 0; j <= SMOOTHING_WINDOW_SIZE && i + j < num_readings; j++) {
            sum += readings[i + j]->temperature;
            count++;
        }
        if (count > 0) {
            readings[i]->temperature = sum / count;
        } else {
            // handle edge case where window does not fully overlap
            readings[i]->temperature = readings[i]->temperature;
        }
    }

    // filter out entries with descriptions exceeding maximum length
    int filtered_count = 0;
    for (int i = 0; i < num_readings; i++) {
        if (strlen(readings[i]->description) <= max_length) {
            // reusing memory block where possible
            char* description_ptr = my_malloc(strlen(readings[i]->description) + 1);
            strcpy(description_ptr, readings[i]->description);
            descriptions[filtered_count] = description_ptr;
            filtered_count++;
        } else {
            printf("Error: skipping entry with excessive description\n");
        }
    }

    // logging service integration
    int error_entries = num_readings - filtered_count;
    printf("Successfully processed %d entries, with %d errors\n", filtered_count, error_entries);

    json_object* output = json_object_new_object();
    for (int i = 0; i < filtered_count; i++) {
        json_object_set_new(output, "temperature", json_real(readings[i]->temperature));
        json_object_set_new(output, "description", json_string(descriptions[i]));
    }

    // export smoothed and filtered temperature data to new JSON file
    FILE* output_file = fopen("output.json", "w");
    json_object_to_file(output, output_file);
    fclose(output_file);

    return 0;
}

int main() {
    process_json_file("input.json", MAX_DESCRIPTION_LENGTH, NULL);
    return 0;
}
