#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <csv.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define RACH_REQUEST_MAX 10000
#define PROBABILITY_OF_REQUEST .5

typedef struct {
    int ueIdentifier;
    char rrcConnectionStatus;
    struct {
        int requestType;
        int priority;
    } *rachRequests;
} UEState;

UEState* ueStates = NULL;
int ueStateCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populateUeStatesFromCsv(const char* filePath) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filePath);
        return;
    }

    csv_reader* reader = csv_init(file);
    if (reader == NULL) {
        printf("Error initializing CSV reader.\n");
        fclose(file);
        return;
    }

    int i = 0;
    while (csv_next_row(reader)) {
        UEState* ueState = malloc(sizeof(UEState));
        ueState->ueIdentifier = i++;
        ueState->rrcConnectionStatus = csv_get_cell(reader, 1)[0];
        ueState->rachRequests = NULL;

        // Add RACHRequest entries based on the probabilistic model
        int requestCount = (int) (PROBABILITY_OF_REQUEST * RACH_REQUEST_MAX);
        for (int j = 0; j < requestCount; j++) {
            UEState* rachRequest = malloc(sizeof(UEState));
            // Set random value within a specified range
            rachRequest->requestType = rand() % 2;
            rachRequest->priority = rand() % 3;

            // Add to the list of RACHRequests for this UEState
            if (ueState->rachRequests == NULL) {
                ueState->rachRequests = malloc(sizeof(struct {
                    int requestType;
                    int priority;
                }));
                ueState->rachRequests[0] = rachRequest;
            } else {
                UEState* temp = ueState->rachRequests;
                while (temp->next != NULL) {
                    temp = temp->next;
                }
                temp->next = malloc(sizeof(struct {
                    int requestType;
                    int priority;
                }));
                temp->next = rachRequest;
            }
        }

        // Add the UEState to the dynamic array
        if (ueStates == NULL || ueStateCount >= MAX_RECORDS) {
            // Resize the array as needed
            int newSize = ueStateCount + 1 + RACH_REQUEST_MAX;
            UEState* newArray = realloc(ueStates, sizeof(UEState) * newSize);
            if (newArray != NULL) {
                ueStates = newArray;
            } else {
                printf("Error allocating memory for UEStates.\n");
                return;
            }
        }

        // Log errors without termination
        if (csv_error(reader)) {
            printf("Error reading CSV file: %s\n", csv_strerror(csv_error(reader)));
            fclose(file);
            return;
        }

        // Add the UEState to the dynamic array
        ueStates[ueStateCount++] = ueState;
    }

    csv_close(reader);
    fclose(file);
}

void periodicClearExpiredEntries() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < ueStateCount; i++) {
        if (ueStates[i].rachRequests != NULL) {
            // Clear expired RACHRequest entries
            UEState* temp = ueStates[i].rachRequests;
            while (temp->next != NULL) {
                temp = temp->next;
                free(temp->next);
            }
        }
    }
    pthread_mutex_unlock(&mutex);
}

void seedRandomNumberGenerator() {
    // Seed the random number generator correctly
    srand(time(NULL));
}

int main() {
    // Initialize resources for managing user equipment states
    ueStates = malloc(sizeof(UEState) * MAX_RECORDS);

    // Read data from an external CSV file and populate UEStates
    populateUeStatesFromCsv("user_equipment_states.csv");

    // Seed the random number generator correctly to set the value of each record's int field
    seedRandomNumberGenerator();

    // Periodically clear expired RACHRequest entries
    pthread_t thread;
    pthread_create(&thread, NULL, periodicClearExpiredEntries, NULL);

    // Handle concurrent access by multiple threads using a thread-safe data structure
    pthread_mutex_lock(&mutex);
    // ...
    pthread_mutex_unlock(&mutex);

    return 0;
}

