Record* initialize_records(int numRecords, int minRange, int maxRange);
void save_records(Record*, int);
Record* load_records(const char*);

int main() {
    // Example usage:
    Record* records = initialize_records(1000, 1, 100);
    save_records(records, 10); // Save the first 10 records
