Record* initialize_records(int numRecords, int minRange, int maxRange) {
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    srand(time(NULL)); // Randomize the seed

    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % 100; // Generate a random key
        records[i].offset = rand() % 100; // Generate a random offset
        records[i].value = rand() % (maxRange - minRange) + minRange; // Randomly generated value within the range
    }
    return records;
}

void save_records(Record* records, int numRecordsToSave) {
    FILE* file = fopen("records.dat", "wb");
    if (!file) {
        perror("Error opening file for writing");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < numRecordsToSave; i++) {
        fwrite(&records[i], sizeof(Record), 1, file); // Write the record to the file
    }
    fclose(file);
}

Record* load_records(const char* filename) {
    Record* records = NULL;
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file for reading");
        return NULL; // Return failure indicator
    }

    fseek(file, 0, SEEK_END); // Move to the end of the file
    int fileSize = ftell(file);
    rewind(file);

    records = (Record*)malloc((int)ceil((double)fileSize / sizeof(Record)));
    fread(records, sizeof(Record), (int)fileSize / sizeof(Record), file);
    fclose(file);
    return records;
}
