        for (int j = 0; j < numKeysPerRecord; j++) {
            strValues[j] = (char*)malloc((strlen("string") + 10) * sizeof(char));
            strcpy(strValues[j], "string");
        }

        // Initialize nested records within the record
        int* nestedNumRecords = malloc(sizeof(int));
        if (!nestedNumRecords) {
            printf("Memory allocation failed. Aborting.\n");
            free(values);
            free(strValues);
            free(record->id);
            free(record);
            return NULL;
