        *nestedNumRecords = 3; // Assume three levels of nested records

        Record*** nestedRecords = malloc(*nestedNumRecords * sizeof(Record**));
        if (!nestedRecords) {
            printf("Memory allocation failed. Aborting.\n");
            free(nestedNumRecords);
            free(values);
            free(strValues);
            free(record->id);
            free(record);
            return NULL;
        }

        for (int k = 0; k < *nestedNumRecords; k++) {
            nestedRecords[k] = dataManagementSystem(*nestedNumRecords, numKeysPerRecord);
            if (!nestedRecords[k]) {
                printf("Memory allocation failed. Aborting.\n");
                free(nestedNumRecords);
                free(values);
                free(strValues);
                free(record->id);
                free(record);
                return NULL;
            }
        }

        // Copy data into the final structure
        for (int i = 0; i < numRecords; i++) {
            records[i] = record;
            record = NULL;
        }

        // Free temporary arrays and structures
        for (int j = 0; j < numKeysPerRecord; j++) {
            free(strValues[j]);
        }
        free(strValues);
        free(values);

        return records;
    }
}
