#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>
#include <sqlite3.h>

// Define structure for records
typedef struct {
    int key;
    int offset;
    int value;
} Record;

// Define structure for record cache
typedef struct {
    pthread_mutex_t mutex;
    Record** cache;
    size_t capacity;
    size_t count;
} Cache;

// Initialize records function
void initialize_records(int num_records, int* keys, int* offsets, int min_value, int max_value) {
    // Initialize data structures
    sqlite3_open("records.db", NULL);
    json_object* root = json_object_new_object();

    // Create cache with default size and eviction policy
    Cache cache;
    cache.capacity = 1000;
    cache.count = 0;
    pthread_mutex_init(&cache.mutex, NULL);
    cache.cache = (Record**)malloc(sizeof(Record*) * cache.capacity);

    // Initialize records and values
    Record* records = (Record*)malloc(sizeof(Record) * num_records);
    for(int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        // Insert record into SQLite database
        char query[1024];
        sprintf(query, "INSERT INTO records VALUES (%d, %d, %d)", keys[i], offsets[i], records[i].value);
        sqlite3_exec("records.db", query, NULL, NULL, NULL);

        // Serialize and store record in JSON file
        json_object* record_json = json_object_new_object();
        json_object_object_add(record_json, "key", json_integer(keys[i]));
        json_object_object_add(record_json, "offset", json_integer(offsets[i]));
        json_object_object_add(record_json, "value", json_integer(records[i].value));
        json_object_object_add(root, "record", record_json);

        // Add record to cache
        if(cache.count < cache.capacity) {
            cache.cache[cache.count] = &records[i];
            cache.count++;
        }
    }

    // Close database and JSON file
    sqlite3_close("records.db");
    json_object_free(root);

    // Start caching thread
    pthread_t caching_thread;
    pthread_create(&caching_thread, NULL, (void*)cache_records, &cache);
}

// Cache records function
void cache_records(Cache* cache) {
    while(1) {
        // Evict least recently used record from cache
        if(cache->count > 0) {
            for(int i = 0; i < cache->count - 1; i++) {
                cache->cache[i] = cache->cache[i + 1];
            }
            free(cache->cache[cache->count - 1]);
            cache->count--;
        }

        // Sleep and repeat
        sleep(10);
    }
}

