#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

typedef struct {
    int key;
    int offset;
    int value;
} Record;

Record* initialize_records(int num_records) {
    // Initialize the records array with malloc
    Record* records = (Record*)malloc(num_records * sizeof(Record));

    // Initialize the record values randomly within a specified range
    for (int i = 0; i < num_records; i++) {
        int value = rand() % 100;
        records[i].key = rand();
        records[i].offset = rand();
        records[i].value = value;
    }

    return records;
}

void save_to_file(Record* records, int num_records, char* filename) {
    // Open the file in binary write mode
    int fd = open(filename, O_CREAT | O_RDWR, 0644);

    // Write the record data to the file
    for (int i = 0; i < num_records; i++) {
        Record record = records[i];
        fwrite(&record, sizeof(Record), 1, fd);
    }

    // Close the file
    close(fd);
}

void load_from_file(Record* records, int num_records, char* filename) {
    // Open the file in binary read mode
    int fd = open(filename, O_RDONLY);

    // Read the record data from the file
    for (int i = 0; i < num_records; i++) {
        Record record;
        fread(&record, sizeof(Record), 1, fd);
        records[i] = record;
    }

    // Close the file
    close(fd);
}

void save_to_json_file(Record* records, int num_records, char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        Record record = records[i];
        fprintf(file, "{\"key\": %d, \"offset\": %d, \"value\": %d}\n", record.key, record.offset, record.value);
    }

    fclose(file);
}

void load_from_json_file(Record* records, int num_records, char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        Record record;
        fscanf(file, "{\"key\": %d, \"offset\": %d, \"value\": %d}\n", &record.key, &record.offset, &record.value);
        records[i] = record;
    }

    fclose(file);
}

int main() {
    int num_records = 1000;
    Record* records = initialize_records(num_records);

    char filename[20];
    sprintf(filename, "records.bin");
    save_to_file(records, num_records, filename);

    // Load the records from the binary file
    load_from_file(records, num_records, filename);

    sprintf(filename, "records.json");
    save_to_json_file(records, num_records, filename);

    // Load the records from the JSON file
    load_from_json_file(records, num_records, filename);

    return 0;
}
