#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <chrono>
#include <thread>
#include <random>
#include <iomanip>
#include <algorithm>

// Function to process weather data
void processWeatherData(size_t tempSize, size_t pressureSize, size_t humiditySize, size_t windSize) {
    // Initialize random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<float> tempDist(-40.0f, 60.0f);
    std::uniform_real_distribution<float> pressureDist(800.0f, 1100.0f);
    std::uniform_real_distribution<float> humidityDist(0.0f, 100.0f);
    std::uniform_real_distribution<float> windDist(0.0f, 50.0f);

    // Initialize time_t field
    auto now = std::chrono::system_clock::now();
    auto start = now - (std::chrono::hours(24) * 2);
    std::time_t startTime = std::chrono::system_clock::to_time_t(start);

    // Initialize arrays for temperature, pressure, humidity, and wind speed readings
    float* temps = new float[tempSize];
    float* pressures = new float[pressureSize];
    float* humidities = new float[humiditySize];
    float* winds = new float[windSize];

    // Generate random data for each array
    for (size_t i = 0; i < tempSize; ++i) {
        temps[i] = tempDist(gen);
    }
    for (size_t i = 0; i < pressureSize; ++i) {
        pressures[i] = pressureDist(gen);
    }
    for (size_t i = 0; i < humiditySize; ++i) {
        humidities[i] = humidityDist(gen);
    }
    for (size_t i = 0; i < windSize; ++i) {
        winds[i] = windDist(gen);
    }

    // Initialize array of time_t values
    time_t* times = new time_t[humiditySize * 2];

    // Fill in time array with random start times
    for (size_t i = 0; i < humiditySize * 2; ++i) {
        times[i] = startTime + (std::chrono::hours(24) * std::rand() % (int)(2 * 24));
    }

    // Initialize strings for weather metrics
    char** metricStrings = new char*[tempSize];
    for (size_t i = 0; i < tempSize; ++i) {
        metricStrings[i] = new char[1024];

        std::strftime(metricStrings[i], 1024, "Temperature: %f°C\n", nullptr);
        metricStrings[i][std::strlen(metricStrings[i]) - 1] = '\0';

        // Check for overflow
        if (std::strlen(metricStrings[i]) >= 1023) {
            delete[] metricStrings[i];
            continue;
        }
    }

    // Calculate SHA-256 hashes of weather metrics in parallel
    std::vector<std::string> hashes;
    int discarded = 0;

    #pragma omp parallel num_threads(4)
    {
        int id = omp_get_thread_num();
        size_t start = id * tempSize / 4, end = (id + 1) * tempSize / 4;
        if (id == 3) {
            end = tempSize;
        }

        for (size_t i = start; i < end; ++i) {
            std::string hash;

            // Check for overflow
            if (std::strlen(metricStrings[i]) >= 1023) {
                ++discarded;
                continue;
            }

            SHA256_CTX ctx;
            SHA256_Init(&ctx);
            SHA256_Update(&ctx, metricStrings[i], strlen(metricStrings[i]));
            SHA256_Final(std::array<char, SHA256_DIGEST_LENGTH>(), &ctx);

            // Convert hash to hexadecimal string
            for (int j = 0; j < SHA256_DIGEST_LENGTH; ++j) {
                char buffer[3];
                sprintf(buffer, "%02x", ctx.hash[j]);
                hash += std::string(buffer);
            }

            #pragma omp critical
            {
                hashes.push_back(hash);
            }
        }
    }

    // Calculate moving average of temperature readings over a sliding window of 24 hours
    float* tempAverages = new float[humiditySize * 2];
    for (size_t i = 0; i < humiditySize * 2; ++i) {
        float sum = 0;
        size_t j = i % 24;

        while (j--) {
            sum += temps[j % tempSize];
        }

        tempAverages[i] = sum / (float)(std::min(24, tempSize));
    }

    // Serialize moving averages into binary format
    std::ofstream file("weather_data.bin", std::ios::binary);
    file.write((char*)tempAverages, sizeof(float) * humiditySize * 2);

    // Free allocated memory
    delete[] temps;
    delete[] pressures;
    delete[] humidities;
    delete[] winds;
    delete[] times;
    for (size_t i = 0; i < tempSize; ++i) {
        delete[] metricStrings[i];
    }
    delete[] metricStrings;

    std::cout << "Discarded strings: " << discarded << std::endl;
}

int main() {
    processWeatherData(100, 25, 50, 33);
    return 0;
}
