#include <pthread.h>

typedef struct {
    int ue_id;
    int rrc_status;
    int num_rach_requests;
    struct RACHRequest* rach_requests;
} UEState;

typedef struct {
    int access_type;
    int priority;
} RACHRequest;

void* ue_state_array = NULL;
int array_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

UEState* get_ue_state(int idx) {
    pthread_mutex_lock(&mutex);
    UEState* state = (UEState*)malloc(sizeof(UEState));
    state->ue_id = rand() % 1000 + 1;
    state->rrc_status = rand() % 2; // 0 or 1
    int num_requests = rand() % 5 + 1;
    state->num_rach_requests = num_requests;
    state->rach_requests = (RACHRequest*)malloc(num_requests * sizeof(RACHRequest));
    for (int i = 0; i < num_requests; i++) {
        RACHRequest request;
        request.access_type = rand() % 2; // 0 or 1
        request.priority = rand() % 3 + 1; // 1, 2 or 3
        state->rach_requests[i] = request;
    }
    pthread_mutex_unlock(&mutex);
    return state;
}

void free_ue_state_array(int size) {
    UEState* state = ue_state_array;
    for (int i = 0; i < size; i++) {
        if (state[i].num_rach_requests > 0) {
            for (int j = 0; j < state[i].num_rach_requests; j++) {
                free(&state[i].rach_requests[j]);
            }
        }
    }
    free(ue_state_array);
}

void* ue_state_init(int num_ue_states, int max_num_rach_requests) {
    pthread_mutex_lock(&mutex);
    array_size = num_ue_states;
    ue_state_array = (UEState*)malloc(array_size * sizeof(UEState));
    for (int i = 0; i < num_ue_states; i++) {
        UEState* state = get_ue_state(i);
        ue_state_array[i] = *state;
    }
    pthread_mutex_unlock(&mutex);
}

void ue_state_destroy() {
    free_ue_state_array(array_size);
}
