        int key;
        long offset;

        if (fscanf(file, "%d %ld", &key, &offset) != 2) {
            printf("Error reading data file.\n");
            break;
        }

        records[num_records]->key = key;
        records[num_records]->offset = offset;

        num_records++;
        if (num_records >= max_limit) {
            break;
        }
    }

    fclose(file);

    record_t** temp_records = (record_t**)malloc((num_records + 1) * sizeof(record_t*));
    for (int i = 0; i <= num_records; i++) {
        temp_records[i] = records[i];
    }

    free(records);
    return temp_records;
}

