    int max_limit = 10000;
    record_t** records = allocate_and_init_records(max_limit);
    for (int i = 0; i < max_limit && i < num_records; i++) {
        printf("%d %ld\n", records[i]->key, records[i]->offset);
    }
    return 0;
}
